insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قال: "انْتَدَبَ اللهُ لِمَنْ خَرَجَ فِي سَبِيلِهِ لَا يُخْرِجُهُ إِلَّا إِيمَانٌ بِي وَتَصْدِيقٌ بِرُسُلِي أَنْ أُرْجِعَهُ بِمَا نَالَ مِنْ أَجْرٍ أَوْ غَنِيمَةٍ أَوْ أُدْخِلَهُ الْجَنَّةَ، وَلَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي مَا قَعَدْتُ خَلْفَ سَرِيَّةٍ وَلَوَدِدْتُ أَنِّي أُقْتَلُ فِي سَبِيلِ اللهِ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ ثُمَّ أُحْيَا ثُمَّ أُقْتَلُ". (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ (സമരത്തിന്) പുറപ്പെടുന്നു. അല്ലാഹുവിലും അവന്റെ ദൂതന്മാരിലുമുള്ള വിശ്വാസം കാരണത്താൽ മാത്രമാണ് അവൻ അതിന് പുറപ്പെട്ടത്. അങ്ങനെയുള്ള ഒരുത്തനെ തന്റെ അടുക്കൽ നിന്നുള്ള പ്രതിഫലമോ, യുദ്ധാർജ്ജിത സ്വത്തോ, സ്വർഗ്ഗ പ്രവേശമോ നൽകാതെ തിരിച്ചയക്കുകയില്ലെന്ന് അല്ലാഹു ഉത്തരവാദിത്തമായി ഏറ്റെടുത്തിരിക്കുന്നു. എന്റെ സമുദായത്തിന് ക്ലേശമാകുമെന്ന് ഞാൻ കരുതിയിരുന്നില്ലെങ്കിൽ യുദ്ധത്തിനയക്കുന്ന ഒരു സൈന്യത്തിൽ നിന്നും ഞാൻ ഒഴിവാകുകയില്ലായിരുന്നു, അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെട്ട് പിന്നെയും ജീവിച്ച് വീണ്ടും കൊല്ലപ്പെടാനും പിന്നെ ജീവിച്ച് പിന്നെയും കൊല്ലപ്പെടാനും ഞാൻ ആഗ്രഹിക്കുമായിരുന്നു". (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لَا يُلْدَغُ الْمُؤْمِنُ مِنْ جُحْرٍ وَاحِدٍ مَرَّتَيْنِ". (ق,د,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സത്യവിശ്വാസിക്ക് ഒരു മാളത്തിൽ നിന്ന് രണ്ട് പ്രാവശ്യം കടിയേൽക്കുകയില്ല". (ബു,മു,ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ بِشْرِ بْنِ سُحَيْمٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُ أَنْ يُنَادِيَ أَيَّامَ التَّشْرِيقِ أَنَّهُ "لَا يَدْخُلُ الْجَنَّةَ إِلَّا مُؤْمِنٌ، وَهِيَ أَيَّامُ أَكْلٍ وَشُرْبٍ". (ق,ت,ن)', 'ബിശ്റുബ്നു സുഹൈം(റ): അയ്യാമുത്തശ്രീഖിൽ (ദുൽഹിജ്ജ 11,12,13) "വിശ്വാസിയല്ലാതെ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല, അവ തീറ്റയുടെയും കുടിയുടെയും ദിവസങ്ങളാണ്" എന്ന് വിളിച്ചുപറയാൻ നബി(സ) അദ്ദേഹത്തോട് കൽപിച്ചു. (ബു,മു,തു,ന)', 'بِشْرِ بْنِ سُحَيْمٍ', 'ബിശ്റുബ്നു സുഹൈം(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 81, 81, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ أَبِي هريرة رَضِيَ اللهُ عَنْهُ قال: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : "قَالَ اللهُ عَزَّ وَجَلَّ: إِذَا تَحَدَّثَ عَبْدِي بِأَنْ يَعْمَلَ حَسَنَةً فَأَنَا أَكْتُبُهَا لَهُ حَسَنَةً مَا لَمْ يَعْمَلْ، فَإِذَا عَمِلَهَا فَأَنَا أَكْتُبُهَا بِعَشْرِ أَمْثَالِهَا، وَإِذَا تَحَدَّثَ بِأَنْ يَعْمَلَ سَيِّئَةً فَأَنَا أَغْفِرُهَا لَهُ مَا لَمْ يَعْمَلْهَا، فَإِذَا عَمِلَهَا فَأَنَا أَكْتُبُهَا لَهُ بِمِثْلِهَا، وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: قَالَتِ الْمَلَائِكَةُ: رَبِّ ذَاكَ عَبْدُكَ يُرِيدُ أَنْ يَعْمَلَ سَيِّئَةً – وَهُوَ أَبْصَرُ بِهِ – فَقَالَ: ارْقُبُوهُ، فَإِنْ عَمِلَهَا فَاكْتُبُوهَا لَهُ بِمِثْلِهَا، وَإِنْ تَرَكَهَا فَاكْتُبُوهَا لَهُ حَسَنَةً، إِنَّمَا تَرَكَهَا مِنْ جَرَّايَ. وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَحْسَنَ أَحَدُكُمْ إِسْلَامَهُ فَكُلُّ حَسَنَةٍ يَعْمَلُهَا تُكْتَبُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ، وَكُلُّ سَيِّئَةٍ يَعْمَلُهَا تُكْتَبُ بِمِثْلِهَا حَتَّى يَلْقَى اللهَ". (ق,ت)', 'അബൂഹുറൈറ(റ): അല്ലാഹു പറഞ്ഞതായി നബി(സ) പറഞ്ഞു: "എന്റെ അടിമ ഒരു നന്മ ചെയ്യാൻ ഉദ്ദേശിച്ച് അത് ചെയ്തില്ലെങ്കിലും അവന്ന് അതൊരു നന്മയായി ഞാൻ എഴുതും. ഇനി അത് ചെയ്താൽ അതിന്റെ പത്തിരട്ടിയായി ഞാനതെഴുതും. അവന് ഒരു തെറ്റ് ചെയ്യാൻ തോന്നി - അവൻ അത് ചെയ്തില്ല എങ്കിൽ - അവന് ഞാൻ അത് പൊറുത്തുകൊടുക്കും. ആ തെറ്റ് ചെയ്താൽ അതിന് തുല്യമായത് (ശിക്ഷ) മാത്രം അവന് ഞാൻ എഴുതും." നബി(സ) തുടർന്നു: "മലക്കുകൾ പറയും. നാഥാ! അതാ നിന്റെ അടിമ! അവൻ ഒരു തെറ്റു ചെയ്യാൻ ഉദ്ദേശിക്കുന്നു. - നാഥൻ അത് കൃത്യമായും വ്യക്തമായും കാണുന്നുണ്ട് - അല്ലാഹു മലക്കുകളോട് പറയും. നിങ്ങൾ അവനെ നിരീക്ഷിക്കുക. അവൻ ആ തെറ്റ് ചെയ്യുന്നുവെങ്കിൽ അതിന് തുല്യമായത് എഴുതുക. അവനതുപേക്ഷിച്ചാൽ അതൊരു നന്മയായി അവന് എഴുതുക. കാരണം; എന്റെ കാരണത്താൽ മാത്രമാണ് അവൻ അത് ഒഴിവാക്കിയത്." നബി(സ) പറഞ്ഞു: "നിങ്ങളിലൊരാൾ നേരാംവണ്ണം ഇസ്ലാം ആശ്ലേഷിച്ചാൽ മരിക്കുന്നതുവരെ അയാൾ ചെയ്യുന്ന ഓരോ നന്മക്കും പത്തു മുതൽ എഴുനൂറ് ഇരട്ടി വരെയും ഓരോ തിന്മക്കും അവക്ക് തുല്യമായതും എഴുതപ്പെടും." (ബു,മു,തു)', 'أَبِي هريرة', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 81, 82, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عن أَبِي هُرَيْرَةَ وَأَبِي ذَرٍّ رضي اللهُ عَنْهُمَا قَالَا:كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَجْلِسُ بَيْنَ ظَهْرَانَيْ أصحابه فَيَجِيءُ الْغَرِيبُ، فَلَا يَدْرِي أَيُّهُمْ هُوَ حَتَّى يَسْأَل، فَطَلَبْنَا إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَجْعَلَ لَهُ مَجْلِسًا يَعْرِفُهُ الْغَرِيبُ إِذَا أَتَاهُ، فَبَنَيْنَا لَهُ دُكَّانًا مِنْ طين كَانَ يَجْلِسُ عَلَيْهِ، وَإِنَّا لَجُلُوسٌ وَرَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي مَجْلِسه، إِذْ أَقْبَلَ رَجُلٌ أَحْسَنُ النَّاسِ وَجْهًا وَأَطْيَبُ النَّاسِ رِيحًا، كَأَنَّ ثِيَابَهُ لَمْ يَمَسَّهَا دَنَسٌ حَتَّى سَلَّمَ فِي طَرَفِ الْبِسَاطِ، فَقَالَ: السَّلَامُ عَلَيْكَ يَا مُحَمَّدُ! فَرَدَّ عَلَيْهِ السَّلَامَ، قَالَ: أَدْنُو يَا مُحَمَّدُ؟ قَالَ: "ادْنُهْ"، فَمَا زَالَ يَقُولُ: "أَدْنُو" مِرَارًا وَيَقُولُ لَهُ "ادْنُ" حَتَّى وَضَعَ يَدَهُ عَلَى رُكْبَتَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: يَا مُحَمَّدُ! أَخْبِرْنِي مَا الْإِسْلَامُ؟ قَالَ: "الإِسْلَامُ أَنْ تَعْبُدَ اللهَ وَلَا تُشْرِكَ بِهِ شَيْئًا، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَحُجَّ الْبَيْتَ، وَتَصُومَ رَمَضَانَ". قَالَ: إِذَا فَعَلْتُ ذَلِكَ فَقَدْ أَسْلَمْتُ؟ قَالَ: "نعم" قَالَ: صدقت، فَلَمَّا سَمِعْنَا قَوْلَ الرَّجُلِ ''صدقت'' أَنْكَرْنَاهُ، قَالَ: يَا مُحَمَّدُ! أَخْبِرْنِي مَا الْإِيمَانُ؟ قَالَ: "الْإِيمَانُ بِاللهِ، وَمَلَائِكَتِهِ، وَالْكِتَابِ، وَالنَّبِيِّينَ، وَتُؤْمِنُ بِالْقَدَرِ" قَالَ: فَإِذَا فَعَلْتُ ذَلِكَ فَقَدْ آمَنْتُ؟ قَالَ رَسُولُ اللهِ: "نعم" قَالَ: صدقت، قَالَ: يَا مُحَمَّدُ! أَخْبِرْنِي مَا الْإِحْسَانُ؟ قَالَ: "أَنْ تَعْبُدَ اللهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ" قَالَ: صدقت، قَالَ: يَا مُحَمَّدُ! أَخْبِرْنِي مَتَى السَّاعَةُ؟ فَنَكَسَ فَلَمْ يُجِبْهُ شَيْئًا، ثُمَّ أَعَادَ فَلَمْ يُجِبْهُ شَيْئًا، وَرَفَعَ رَأْسَهُ فَقَالَ: "مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ، وَلَكِنْ لَهَا عَلَامَاتٌ تُعْرَفُ بِهَا؛ إِذَا رَأَيْتَ الرِّعَاءَ الْبُهُمَ يَتَطَاوَلُونَ فِي الْبُنْيَانِ، وَرَأَيْتَ الْحُفَاةَ الْعُرَاةَ مُلُوكَ الْأَرْضِ، وَرَأَيْتَ الْمَرْأَةَ تَلِدُ رَبَّهَا خَمْسٌ لَا يَعْلَمُهَا إِلَّا اللهُ: {إِنَّ اللهَ عِنْدَهُ عِلْمُ السَّاعَةِ} إِلَى قَوْلِهِ: {إِنَّ اللهَ عَلِيمٌ خَبِيرٌ} ثُمَّ قَالَ: "لَا وَالَّذِي بَعَثَ مُحَمَّدًا بِالْحَقِّ هُدًى وَبَشِيرًا مَا كُنْتُ بِأَعْلَمَ بِهِ مِنْ رَجُلٍ مِنْكُمْ، وَإِنَّهُ لَجِبْرِيلُ عَلَيْهِ السَّلَامُ نَزَلَ فِي صُورَةِ دِحْيَةَ الْكَلْبِيِّ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ), അബൂദർറ്(റ): നബി(സ) തന്റെ അനുചരന്മാർക്കിടയിൽ ഇരിക്കുമ്പോൾ ഒരു അപരിചിതൻ കടന്നു വരികയാണെങ്കിൽ ''ആരാണ് നബി'' എന്നു ചോദിച്ചറിയും വരെ അയാൾക്ക് നബി(സ)യെ കൂട്ടത്തിൽനിന്ന് വേർതിരിച്ചു മനസ്സിലാക്കാൻ സാധിക്കില്ലായിരുന്നു. അതിനാൽ, അപരിചിതർ വന്നാൽ അവർക്ക് നബിയെ തിരിച്ചറിയുംവിധം ഒരു ഇരിപ്പിടം ഒരുക്കാൻ ഞങ്ങൾ നബി(സ)യോട് ആവശ്യപ്പെട്ടു. അങ്ങനെ നബി(സ)ക്ക് ഇരിക്കാൻ ഞങ്ങൾ മണ്ണുകൊണ്ട് ഒരു പീഠം നിർമിച്ചു. പ്രവാചകൻ സ്വന്തം ഇരിപ്പിടത്തിലും ഞങ്ങൾ ചുറ്റും ഇരിക്കുമ്പോൾ ജനങ്ങളിൽ അതീവ സുന്ദരനും ഏറ്റവും സുഗന്ധമുള്ളവനുമായ ഒരാൾ കടന്നുവന്നു. അദ്ദേഹത്തിന്റെ വസ്ത്രം തീരെ അഴുക്ക് പുരളാത്ത പോലെയുണ്ട്. അദ്ദേഹം സദസ്സിന്റെ അറ്റത്ത് നിന്ന് നബി(സ)യോട് അസ്സലാമുഅലൈക യാ മുഹമ്മദ് എന്ന് സലാം ചൊല്ലുകയും നബി(സ) സലാം മടക്കുകയും ചെയ്തു. അദ്ദേഹം ചോദിച്ചു. മുഹമ്മദ്! ഞാൻ അടുത്ത് വരട്ടെയോ? നബി(സ) പറഞ്ഞു: "അടുത്തു വരൂ." ഞാൻ അടുത്ത് വരട്ടയോ? എന്നദ്ദേഹം പലതവണ ആവർത്തിച്ചപ്പോൾ നബി(സ)അദ്ദേഹത്തോട് അടുത്ത് വരൂ എന്നു പറഞ്ഞു കൊണ്ടേയിരുന്നു. അങ്ങനെ തന്റെ കൈ പ്രവാചകർ(സ)യുടെ കാൽ മുട്ടുകളിൽ വെച്ച് ഇരുന്ന ശേഷം അദ്ദേഹം ചോദിച്ചു. ഓ മുഹമ്മദ്! എന്താണ് ഇസ്ലാം എന്ന് പറഞ്ഞുതന്നാലും. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിനെ ആരാധിക്കലും അവനോട് ഒന്നിനേയും പങ്ക് ചേർക്കാതിരിക്കലും നിസ്കാരം നിലനിർത്തലും സകാത്ത് നൽകലും ഹജ്ജ് നിർവ്വഹിക്കലും റമളാനിൽ വ്രതമനുഷ്ഠിക്കലുമാണ് ഇസ്ലാം." ആഗതൻ ചോദിച്ചു: ഇത് ചെയ്താൽ ഞാൻ മുസ്ലിമാകുമോ? നബി(സ)പറഞ്ഞു: "അതെ." ആഗതൻ: താങ്കൾ പറഞ്ഞത് ശരിയാണ്. (താങ്കൾ പറഞ്ഞത് ശരിയെന്ന ആഗതന്റെ വാക്കുകേട്ടപ്പോൾ ഞങ്ങൾക്കദ്ദേഹത്തോട് നീരസം തോന്നി.) അദ്ദേഹം തുടർന്നു: ഓ മുഹമ്മദ്! ഈമാൻ എന്താണെന്ന് എന്നെ അറിയിച്ചാലും. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അവന്റെ മലക്കുകളിലും വേദങ്ങളിലും നബിമാരിലും വിധിയിലും വിശ്വസിക്കൽ." ആഗതൻ: ഇതംഗീകരിച്ചാൽ ഞാൻ വിശ്വാസിയാകുമോ? നബി(സ) പറഞ്ഞു: "അതെ." ആഗതൻ: താങ്കൾ പറഞ്ഞത് ശരിയാണ്. ഓ മുഹമ്മദ്, എന്താണ് ഇഹ്സാൻ എന്ന് എനിക്കറിയിച്ച് തന്നാലും. നബി(സ): "നീ അല്ലാഹുവിനെ കാണുന്നുണ്ട് എന്നപോലെ അവന് ഇബാദത്ത് ചെയ്യുക. നിശ്ചയം, നീ അവനെ കാണുന്നില്ലെങ്കിലും അവൻ നിന്നെ കാണുന്നുണ്ട്." ആഗതൻ: താങ്കൾ പറഞ്ഞത് ശരിയാണ്. ഓ മുഹമ്മദ്! അന്ത്യദിനം എപ്പോഴാണെന്ന് എനിക്ക് പറഞ്ഞുതന്നാലും. അപ്പോൾ നബി(സ) തലതാഴ്ത്തി മൗനം ദീക്ഷിച്ചു. അദ്ദേഹം ചോദ്യം ആവർത്തിച്ചു. അപ്പോഴും നബി(സ) ഒന്നും പറഞ്ഞില്ല. വീണ്ടും അദ്ദേഹം ചോദ്യം ആവർത്തിച്ചപ്പോഴും അതിന് മറുപടിയൊന്നും പറഞ്ഞില്ല. ശേഷം തലയുയർത്തി നബി(സ) പറഞ്ഞു. "ചോദിക്കപ്പെട്ടവൻ അതേക്കുറിച്ച് ചോദ്യകർത്താവിനേക്കാൾ അറിയുന്നവനല്ല. എന്നാൽ അന്ത്യദിനത്തെ തിരിച്ചറിയാവുന്ന ചില അടയാളങ്ങളുണ്ട്; കറുത്ത ഒട്ടകത്തെ മേക്കുന്ന ഇടയന്മാരായ ജനത കെട്ടിട നിർമ്മാണത്തിൽ കിടമത്സരം നടത്തുന്നതും, വസ്ത്രവും ചെരിപ്പും ധരിക്കാനില്ലാത്തവർ ഭൂമിയിൽ രാജാക്കന്മാരാകുന്നതും, പെണ്ണ് തന്റെ യജമാനനെ പ്രസവിക്കുന്നതും നീ കാണാനിടവരിക. അന്ത്യനാളിനെക്കുറിച്ചുള്ള അറിവ് അല്ലാഹു മാത്രം അറിയുന്ന അഞ്ച് കാര്യങ്ങളിൽപെട്ടതാണ്. "അല്ലാഹുവിങ്കലാണ് അന്ത്യദിനത്തിന്റെ അറിവ്" എന്ന ഖുർആൻ വചനം "അല്ലാഹു അറിയുന്നവനും സൂക്ഷ്മജ്ഞാനിയുമാണ്" എന്നഭാഗം വരെ ഓതിയിട്ട് പറഞ്ഞു. സുവിശേഷകനായും സന്മാർഗ്ഗവും സത്യവുമായി മുഹമ്മദി(സ)നെ നിയോഗിച്ചവനാണെ, നിങ്ങളേക്കാൾ കൂടുതൽ എനിക്കത് അറിയുമായിരുന്നില്ല. തീർച്ചയായും അത് ജിബ്രീലാണ്. അദ്ദേഹം ദിഹ്‌യത്തുൽ കൽബി(റ)യുടെ രൂപത്തിൽ ഇറങ്ങിവന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ وَأَبِي ذَرٍّ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 82, 83, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ أَبِي سعيد الخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ أُنَاسًا مِنْ عبد القيس قدموا علي رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا نَبِيَّ اللهِ! إِنَّا حَيٌّ مِنْ رَبِيعَةَ، وَبَيْنَنَا وَبَيْنَكَ كُفَّارُ مُضَرَ، وَلَا نَقْدِرُ عَلَيْكَ إِلَّا فِي أَشْهُرِ الحُرُمِ، فَمُرْنَا بِأَمْرٍ نَأْمُرْ بِهِ مَنْ وَرَاءَنَا وَنَدْخُلْ بِهِ الْجَنَّةَ إِذَا نَحْنُ أَخَذْنَا بِهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "آمُرُكُمْ بِأَرْبَعٍ، وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: اعْبُدُوا اللهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَأَقِيمُوا الصَّلَاةَ، وَآتُوا الزَّكَاةَ، وَصُومُوا رَمَضَانَ، وَأَعْطُوا الخُمُسَ مِنَ الْغَنَائِمِ. وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: عَنِ الدُّبَّاءِ، وَالْحَنْتَمِ، وَالْمُزَفَّتِ، وَالنَّقِيرِ". قَالُوا: يَا نَبِيَّ اللهِ! مَا علمك بِالنَّقِيرِ؟ قَالَ: "بَلِي! جذعٌ تنقرونه فتقذفون فيه مِنَ الْقُطَيْعَاءِ – قَالَ سَعِيدٌ أَوْ قَالَ مِنَ التَّمْرِ – ثُمَّ تَصُبُّونَ فِيهِ مِنَ الْمَاءِ، حَتَّى إِذَا سَكَنَ غَلَيَانُهُ شَرِبْتُمُوهُ حَتَّى إِنَّ أَحَدَكُمْ – أَوْ إِنَّ أَحَدَهُمْ – لَيَضْرِبُ ابْنَ عَمِّهِ بِالسَّيْفِ". قَالَ: وَفِي الْقَوْمِ رَجُلٌ أصابتْهُ جِرَاحَةٌ كَذَلِكَ، قَالَ: وَكُنْتُ أَخْبَؤُهَا حَيَاءً مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: فَفِيمَ نَشْرَبُ يَا رَسُولَ اللهِ؟ قَالَ: "فِي أَسْقِيَةِ الْأَدَمِ الَّتِي يُلَاثُ عَلِي أَفْوَاهِهَا". قَالُوا: يَا رَسُولَ اللهِ! إِنَّ أَرْضَنَا كَثِيرَةُ الْجِرْذَانِ، وَلَا تَبْقَى بِهَا أَسْقِيَةُ الْأَدَمِ، فَقَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَإِنْ أَكَلَتْهَا الْجِرْذَانُ، وَإِنْ أَكَلَتْهَا الْجِرْذَانُ، وَإِنْ أَكَلَتْهَا الْجِرْذَانُ". قَالَ: وَقَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِأَشَجِّ عَبْدِ الْقَيْسِ: "إِنَّ فِيكَ لَخَصْلَتَيْنِ يُحِبُّهُمَا اللهُ: الْحِلْمُ وَالْأَنَاةُ". (ق,د,ت,ن)', 'അബൂസഈദിൽഖുദ്‌രി(റ): അബ്ദുൽ ഖൈസ് വംശത്തിലെ കുറച്ചാളുകൾ നബിയുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രവാചകരേ! ഞങ്ങൾ റബീഅ: ഗോത്രക്കാരാണ്. നമുക്കിടയിൽ മുളർ ഗോത്രത്തിലെ സത്യനിഷേധികൾ ഉള്ളതിനാൽ പവിത്ര (യുദ്ധം നിഷിദ്ധമായ) മാസങ്ങളിലല്ലാതെ ഞങ്ങൾക്ക് അങ്ങയുടെ അടുത്ത് വരാൻ കഴിയുന്നില്ല. അതിനാൽ അനുഷ്ഠിച്ചാൽ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുന്നതും ഞങ്ങളുടെ ജനതയോട് കൽപിക്കാവുന്നതുമായ കാര്യങ്ങൾ ഞങ്ങളോട് കൽപ്പിച്ചാലും!. നബി(സ) പറഞ്ഞു: "ഞാൻ നാല് കാര്യങ്ങൾ നിങ്ങളോട് കൽപിക്കുകയും നാല് കാര്യങ്ങൾ നിങ്ങൾക്ക് വിലക്കുകയും ചെയ്യുന്നു: നിങ്ങൾ അല്ലാഹുവിനെ ആരാധിക്കുകയും അവനോട് ഒന്നിനെയും പങ്ക് ചേർക്കാതിരിക്കുകയും ചെയ്യുക, നിസ്കാരം നിലനിർത്തുക, സകാത്ത് നൽകുക, റമളാനിൽ നോമ്പനുഷ്ഠിക്കുക, സമരാർജ്ജിത സ്വത്തിന്റെ അഞ്ചിൽ ഒന്ന് (ബൈതുൽമാലിലേക്ക്) നൽകുക. (എന്നും ഞാൻ കൽപിക്കുന്നു). ഞാൻ നിങ്ങൾക്ക് നാല് കാര്യങ്ങൾ എന്നിവ വിലക്കുന്നു. അഥവാ; ചുരങ്ങാതൊണ്ട്, പച്ചച്ചായം പൂശിയ പാത്രം, ടാർ പൂശിയ പാത്രം, മരപ്പാത്രം." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരെ! മരപ്പാത്രമെന്നാൽ എന്താണ് അങ്ങ് അർത്ഥമാക്കുന്നത്? നബി(സ) പറഞ്ഞു: "അതെ! നിങ്ങൾ തുരന്നുണ്ടാക്കുന്ന മരത്തടിയാണത്. പിന്നെ നിങ്ങൾ അതിൽ കാരക്കാ നുറുക്കുകളിട്ട് (സഈദ്(റ) പറയുന്നു: അല്ലെങ്കിൽ അവിടുന്ന് പറഞ്ഞത് ''കാരക്കകൾ'' എന്നാണ്) വെള്ളമൊഴിക്കുന്നു. എന്നിട്ട് അതിന്റെ പത അടങ്ങിയാൽ നിങ്ങൾ അത് കുടിക്കുകയും (ബോധരഹിതനായി) തങ്ങളിൽ ഒരുത്തൻ സ്വന്തം പിതൃവ്യപുത്രനെ വാളുകൊണ്ട് വെട്ടുകയും ചെയ്യുന്നു." നിവേദകൻ പറയുന്നു: ഇത്തരത്തിൽ മുറിവ് പറ്റിയ ഒരാൾ അക്കൂട്ടത്തിലുണ്ടായിരുന്നു. അയാൾ പറഞ്ഞു: ലജ്ജ കാരണം ഞാനത് റസൂലിൽ നിന്നും മറച്ച് വെച്ചു. ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ! പിന്നെ ഏത് പാത്രത്തിൽ നിന്നാണ് ഞങ്ങൾ കുടിക്കുക? പ്രവാചകൻ(സ) പറഞ്ഞു: "വായ് ചുറ്റികെട്ടിയ, തോൽ കൊണ്ടുള്ള ജലപാത്രത്തിൽ നിന്ന്." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ! ഞങ്ങളുടെ പ്രദേശം എലികൾ നിറഞ്ഞതാണ്. തോൽജലപ്പാത്രം അവിടെ നിലനിൽക്കില്ല. നബി(സ) പറഞ്ഞു: "അത് എലികൾ ഭക്ഷിച്ചാലും ശരി, അത് എലികൾ ഭക്ഷിച്ചാലും ശരി, അത് എലികൾ ഭക്ഷിച്ചാലും ശരി." നിവേദകൻ പറയുന്നു: നബി(സ) അബ്ദുൽ ഖൈസിലെ മുറിവ് പറ്റിയവനോട് പറഞ്ഞു: "നിന്നിൽ അല്ലാഹു ഇഷ്ടപ്പെടുന്ന രണ്ട് ഗുണങ്ങളുണ്ട്: വിവേകവും അവധാനതയും". (ബു,മു,ദ,തു,ന)', 'أَبِي سعيد الخُدْرِيِّ', 'അബൂസഈദിൽഖുദ്‌രി(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 83, 84, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ طَلْحَةَ بْنِ عُبَيْدِ اللهِ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ أَهْلِ نَجْدٍ ثَائِرُ الرَّأْسِ، نَسْمَعُ دَوِيَّ صَوْتِهِ وَلَا نَفْقَهُ مَا يَقُولُ حَتَّى دَنَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عليه وسلم، فَإِذَا هُوَ يَسْأَلُ عَنِ الْإِسْلَامِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَمْسُ صَلَوَاتٍ فِي الْيَوْمِ وَاللَّيْلَةِ". فَقَالَ: هَلْ عَلَيَّ غَيْرُهُنَّ؟ قَالَ: "لَا، إِلَّا أَنْ تَطَّوَّعَ، وَصِيَامُ شَهْرِ رَمَضَانَ". فَقَالَ: هَلْ عَلَيَّ غَيْرُهُ؟ فَقَالَ: "لَا، إِلَّا أَنْ تَطَّوَّعَ" وَذَكَرَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الزَّكَاةَ فَقَالَ: هَلْ عَلَيَّ غَيْرُهَا؟ قَالَ: "لَا، إِلَّا أَنْ تَطَّوَّعَ" قَالَ: فَأَدْبَرَ الرَّجُلُ وَهُوَ يَقُولُ: وَاللهِ لَا أَزِيدُ عَلَى هَذَا وَلَا أَنْقُصُ مِنْهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَفْلَحَ إِنْ صَدَقَ". (ق,د,ن)', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ): നജ്ദ് നിവാസികളിൽപ്പെട്ട മുടി ചിന്നിച്ചിതറിയ ഒരാൾ തിരുമേനി(സ)യുടെ അടുക്കൽ വന്നു. അയാളുടെ ശബ്ദത്തിന്റെ മൂളക്കം (നേരിയ ശബ്ദം) കേൾക്കാമായിരുന്നുവെങ്കിലും റസൂലിന്റെ അടുത്തെത്തുന്നതുവരെ അയാൾ പറയുന്നതെന്താണെന്ന് ഞങ്ങൾക്ക് മനസ്സിലായില്ല. അപ്പോൾ അയാൾ ഇസ്ലാമിനെക്കുറിച്ച് അന്വേഷിക്കുകയാണ്. നബി(സ) പറഞ്ഞു: "രാത്രിയും പകലുമായി അഞ്ച് നിസ്കാരം." ഇതല്ലാതെ മറ്റുവല്ലതും എന്റെ ബാധ്യതയായിട്ടുണ്ടോയെന്ന് അയാൾ ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇല്ല, നീ ഐച്ഛികമായി ചെയ്യുന്നതൊഴികെ." ശേഷം നബി(സ) പറഞ്ഞു: "റമദാൻ മാസത്തിലെ വ്രതം." അദ്ദേഹം ചോദിച്ചു: അതല്ലാതെ മറ്റുവല്ല ബാധ്യതയും എനിക്കുണ്ടോ? നബി(സ) അരുളി: "ഇല്ല, നീ ഐച്ഛികമായി ചെയ്യുന്നതൊഴികെ." ശേഷം പ്രവാചകൻ(സ) അദ്ദേഹത്തോടു സകാത്തിനെ സംബന്ധിച്ച് പറഞ്ഞു. അദ്ദേഹം ചോദിച്ചു. അതല്ലാതെ മറ്റു വല്ല ബാധ്യതയും എനിക്കുണ്ടോ? നബി(സ) അരുളി: "ഇല്ല. ഐച്ഛികമായി നീ ചെയ്യുന്നതൊഴികെ." തിരിച്ചുപോകുമ്പോൾ അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ, ഞാൻ ഇതിൽ കൂട്ടുകയോ കുറക്കുകയോ ചെയ്യില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാൾ പറഞ്ഞത് സത്യമാണെങ്കിൽ അയാൾ വിജയിച്ചു." (ബു,മു,ദ,ന)', 'طَلْحَةَ بْنِ عُبَيْدِ اللهِ', 'ത്വൽഹതുബ്നു ഉബൈദില്ല(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 84, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ : "بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ، شَهَادَة أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَحَجِّ الْبَيْتِ، وَصَوْمِ رَمَضَانَ ". (ق,ت,ن)', 'അബ്ദുല്ലാഹിബ്നുഉമർ(റ): പ്രവാചകർ(സ) പറഞ്ഞു: "ഇസ്ലാം സഥാപിക്കപ്പെട്ടത് അഞ്ച് കാര്യങ്ങളുടെ മേലിലാണ്; അല്ലാഹുവല്ലാതെ ഇലാഹില്ലെന്നും, നിശ്ചയം മുഹമ്മദ് അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമാണെന്നും സാക്ഷ്യപ്പെടുത്തുക, നിസ്കാരം നിലനിർത്തുക, സകാത്ത് നൽകുക, ഹജ്ജ് ചെയ്യുക, റമദാനിൽ വ്രതമനുഷ്ഠിക്കുക." (ബു,മു,തു,ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നുഉമർ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَنْفَقَ الرَّجُلُ عَلَى أَهْلِهِ يَحْتَسِبُهَا فَهُوَ لَهُ صَدَقَة". (خ)', 'അബൂമസ്ഊദ്(റ): പ്രവാചകർ(സ) പറഞ്ഞു: അല്ലാഹുവിന്റെ പ്രീതി പ്രതീക്ഷിച്ചുകൊണ്ട് ഒരാൾ തന്റെ ഭാര്യ(ആശ്രിതർ)ക്കു വേണ്ടി ചെലവു ചെയ്താൽ അത് അവനെ സംബന്ധിച്ചേടത്തോളം പുണ്യാർഹമായ ദാനമാണ്. (ബു)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 85, 85, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ أَوَّلَ مَا قَدِمَ الْمَدِينَةَ نَزَلَ عَلَى أَجْدَاده مِنَ الْأَنْصَارِ وَأَنَّهُ صَلَّى قِبَلَ بَيْتِ الْمَقْدِسِ سِتَّةَ عَشَرَ شَهْرًا أَوْ سَبْعَةَ عَشَرَ شَهْرًا وَكَانَ يُعْجِبُهُ أَنْ تَكُونَ قِبْلَتُهُ قِبَلَ الْبَيْتِ وَأَنَّهُ صَلَّى أَوَّلَ صَلَاةٍ صَلَّاهَا صَلَاةَ الْعَصْرِ، وَصَلَّى مَعَهُ قَوْمٌ، فَخَرَجَ رَجُلٌ مِمَّنْ صَلَّى مَعَهُ فَمَرَّ عَلَى أَهْلِ مَسْجِدٍ وَهُمْ رَاكِعُونَ فَقَالَ أَشْهَدُ بالله لَقَدْ صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قِبَلَ مَكَّةَ، فَدَارُوا كَمَا هُمْ قِبَلَ الْبَيْتِ، وَكَانَتِ الْيَهُودُ قَدْ أَعْجَبَهُمْ إِذْ كَانَ يُصَلِّي قِبَلَ بَيْتِ الْمَقْدِسِ وَأَهْلُ الْكِتَابِ فَلَمَّا وَلَّى وَجْهَهُ قِبَلَ الْبَيْتِ أَنْكَرُوا ذَلِكَ. (خ)', 'ബറാഅ്(റ): അദ്ദേഹം പറയുന്നു: പ്രവാചകർ(സ) മദീനയിലേക്കു ചെന്ന ആദ്യഘട്ടത്തിൽ അൻസാരികളിൽപെട്ട തന്റെ പിതൃകുടുംബങ്ങളുടെ അതിഥിയായിട്ടാണ് താമസിച്ചത്. നബി(സ) ബൈത്തുൽ മുഖദ്ദസിന്റെ നേരെ തിരിഞ്ഞു നിന്നുകൊണ്ട് പതിനാറോ പതിനേഴോ മാസം നിസ്കരിച്ചു. എന്നാൽ തിരിഞ്ഞു നിസ്കരിക്കുന്നത് കഅ്ബയിലേക്കാവുന്നതായിരുന്നു പ്രവാചകന് പ്രിയം. തിരുമേനി(സ) പ്രഥമമായി കഅബയിലേക്കു തിരിഞ്ഞു നിർവ്വഹിച്ച നിസ്കാരം അസ്‌റാണ്. തിരുമേനിയുടെ കൂടെ ഒരു സംഘം ആളുകളും നിസ്കരിച്ചു. നിസ്കരിച്ച സംഘത്തിപ്പെട്ട ഒരാൾ തിരിച്ചു പോകുമ്പോൾ ഒരു സംഘം ആളുകൾ പള്ളിയിൽ വെച്ച് നിസ്കരിക്കുകയാണ്. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ സത്യം, നിശ്ചയം റസൂലി(സ)ന്റെ കൂടെ ഞാൻ മക്കയുടെ നേരെ തിരിഞ്ഞാണ് നിസ്കരിച്ചത്. ഇതുകേട്ടപ്പോൾ കഅ്ബക്കു നേരെ തിരിഞ്ഞു. അവർ റുകൂഇലായിരുന്നു. പ്രവാചകർ(സ) ബൈത്തുൽ മുഖദ്ദിസിന് നേരെ തിരിഞ്ഞുകൊണ്ട് നിസകരിക്കുന്നത് ജൂതന്മാക്ക് ഏറ്റവും പ്രിയങ്കരമായിരുന്നു. എന്നാൽ തിരുമേനി കഅ്ബയുടെ നേരെ തിരിഞ്ഞു നിസ്കരിക്കാൻ തുടങ്ങിയപ്പോൾ അവരതിനെ വെറുക്കുകയാണുണ്ടായത്. (ബു)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 85, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ: شَهَادَة أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَإِقَامِ الصَّلَاةِ، وَإِيتَاءِ الزَّكَاةِ، وَصَوْمِ رَمَضَانَ، وَحَجِّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا". حَسَنٌ صَحِيحٌ. (ق,ت,ن)', 'ഇബ്നുഉമർ(റ): പ്രവാചൻ(സ) പറഞ്ഞു: അല്ലാഹു അല്ലാതെ ആരാധനക്കർഹനായി മറ്റാരുമില്ലെന്നും മുഹമ്മദ് അല്ലാഹുവിന്റെ ദൂതനുമാണെന്ന് സാക്ഷ്യം വഹിക്കുക. നിസ്കാരം അതിന്റെ മുറപ്രകാരം നിർവ്വഹിക്കുക. നിർബ്ബന്ധദാനം (സകാത്ത്) നൽകുക, റമദാനിൽ നോമ്പനുഷ്ടിക്കുക, കഴിയുമെങ്കിൽ കഅ്ബയുടെ അടുക്കൽ ചെന്ന് ഹജ്ജ്കർമ്മം നിർവ്വഹിക്കുക, എന്നീ അഞ്ചു കാര്യങ്ങളിന്മേലായി ഇസ്ലാം പടുത്തുയർത്തപ്പെട്ടിരിക്കുന്നു. (ഹദീസ് ഹസനും സ്വഹിഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,തു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ جَرِيرِ بْنِ عَبْدِاللهِ قَالَ: إِنِّي أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: أُبَايِعُكَ عَلَى الْإِسْلَامِ، فَشَرَطَ عَلَيَّ: وَالنُّصْحِ لِكُلِّ مُسْلِمٍ، فَبَايَعْتُهُ عَلَى هَذَا. (خ)', 'ജരീറുബിൻ അബ്ദില്ല(റ): അദ്ദേഹം പറയുന്നു: ഞാൻ പ്രവാചകർ(സ)യുടെ അടുക്കൽ ചെന്നു പറഞ്ഞു: ''ഇസ്ലാം മതമനുസരിച്ചു ജീവിക്കാമെന്ന് പ്രതിജ്ഞയെടുക്കാൻ ഞാൻ തയ്യാറാണ്.'' അപ്പോൾ ''എല്ലാ മുസ്ലിംകളോടും ഗുണകാംക്ഷയോടെ ജീവിക്കണമെന്ന്'' പ്രവാചകർ(സ) എന്നോട് വ്യവസ്ഥ ചെയ്തു. അങ്ങനെ ഈ വ്യവസ്ഥ പ്രകാരം തന്നെ ഞാൻ നബി(സ)യോട് പ്രതിജ്ഞചെയ്തു. (ബു)', 'جَرِيرِ بْنِ عَبْدِاللهِ قَالَ', 'ജരീറുബിൻ അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أمرت أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، وَيُقِيمُوا الصَّلَاةَ، وَيُؤْتُوا الزَّكَاةَ، فَإِذَا فَعَلُوا ذَلِكَ عَصَمُوا مِنِّي دِمَاءَهُمْ وَأَمْوَالَهُمْ إِلَّا بِحَقِّ الْإِسْلَامِ، وَحِسَابُهُمْ عَلَى اللهِ". (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും നിശ്ചയം മുഹമ്മദ് അല്ലാഹുവിന്റെ ദൂതനാണെന്നും സാക്ഷ്യപ്പെടുത്തുകയും നിസ്കാരം മുറപ്രകാരം നിലനിർത്തുകയും സകാത്ത് നൽകുകയും ചെയ്യുന്നതുവരെ ജനങ്ങളോട് സമരം ചെയ്യുവാൻ ഞാൻ കൽപിക്കപ്പെട്ടു. അവർ അത് നിർവഹിച്ചാൽ ഇസ്ലാമിന്റെ പേരിലുള്ള ബാധ്യതകളൊഴികെ എന്നിൽനിന്ന് അവരുടെ രക്തവും ധനവും അവർ സംരക്ഷിച്ചു. അവരുടെ വിചാരണ അല്ലാഹുവിൽ നിക്ഷിപ്തമാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 86, 86, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا تُوُفِّيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاسْتُخْلِفَ أَبُو بَكْرٍ بَعْدَهُ، وَكَفَرَ مَنْ كَفَرَ مِنَ الْعَرَبِ، قَالَ عُمَرُ بْنُ الْخَطَّابِ لِأَبِي بَكْرٍ: كَيْفَ تُقَاتِلُ النَّاسَ؟ وَقَدْ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أمرت أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَقُولُوا لَا إِلَهَ إِلَّا اللهُ، فَمَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ، فَقَدْ عَصَمَ مِنِّي مَالَهُ وَنَفْسَهُ إِلَّا بِحَقِّهِ، وَحِسَابُهُ عَلَى اللهِ". فَقَالَ أَبُوبَكْرٍ: وَاللهِ! لَأُقَاتِلَنَّ مَنْ فَرَّقَ بَيْنَ الصَّلَاةِ وَالزَّكَاةِ، فَإِنَّ الزَّكَاةَ حَقُّ الْمَالِ، وَاللهِ لَوْ مَنَعُونِي عِقَالًا كَانُوا يُؤَدُّونَهُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَقَاتَلْتُهُمْ عَلَى مَنْعِهِ، فَقَالَ عُمَرُ بْنُ الْخَطَّابِ: فَوَاللهِ! مَا هُوَ إِلَّا أَنْ رَأَيْتُ اللهَ عَزَّ وَجَلَّ قَدْ شَرَحَ صدر أبي بكر لِلْقِتَالِ فَعَرَفْتُ أَنَّهُ الْحَقُّ. (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകർ(സ) വഫാതാവുകയും അബൂബക്കർ(റ) ഖിലാഫത്ത് ഏൽപിക്കപ്പെടുകയും അറബികളിൽ ചിലർ സത്യനിഷേധികളാകുകയും ചെയ്ത സന്ദർഭത്തിൽ ഉമർ(റ) അബൂബക്കറി (റ)നോട് ചോദിച്ചു: ലാഇലാഹ ഇല്ലല്ലാഹ് എന്നു പറയുന്നതുവരെ മാത്രമാണ് യുദ്ധം ചെയ്യാനാണ് ഞാൻ കൽപിക്കപ്പെട്ടത്. കാരണം, ലാഇലാഹ ഇല്ലല്ലാഹ് എന്നു പറഞ്ഞവൻ, ന്യായമായ അവകാശങ്ങളൊഴികെ തന്റെ ശരീരവും ധനവും സുരക്ഷിതമാക്കിയിരിക്കുന്നു. അവന്റെ വിചാരണയാകട്ടെ അല്ലാഹുവിൽ നിക്ഷിപ്തമാണ്." എന്ന് പ്രവാചകൻ(സ) പറഞ്ഞിരിക്കെ താങ്കൾ എങ്ങിനെയാണ് ഈ ജനങ്ങളോട് യുദ്ധം ചെയ്യുക? അപ്പോൾ അബൂബക്കർ(റ) പറഞ്ഞു: അല്ലാഹുവാണെ, നിസ്കാരവും സകാത്തും തമ്മിൽ വ്യത്യാസം കൽപിക്കുന്നവരോട് ഞാൻ യുദ്ധം ചെയ്യുകതന്നെ ചെയ്യും. കാരണം സകാത് ധനത്തിന്റെ ന്യായമായ അവകാശമാണ്. അല്ലാഹുവാണ്, പ്രവാചകന് അവർ നൽകിയിരുന്ന ഒരൊട്ടകക്കയർ എനിക്ക് നിഷേധിച്ചാൽ അത് തടഞ്ഞതിന്റെ പേരിലും ഞാനവരോട് യുദ്ധം ചെയ്യും. ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവാണെ, അബൂബക്കറിന്റെ ഹൃദയം യുദ്ധത്തിന് വിശാലമാക്കിയത് (യുദ്ധം പ്രഖ്യപിക്കാൻ തോന്നിച്ചത്) അല്ലാഹു തന്നെയാണെന്ന് എനിക്ക് തോന്നി. അപ്പോൾ അതാണ് സത്യമെന്ന് ഞാൻ മനസ്സിലാക്കി. (ബു,മു,ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 86, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أمرت أَنْ أُقَاتِلَ النَّاسَ حَتَّى يَشْهَدُوا أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَأَنْ يَسْتَقْبِلُوا قِبْلَتَنَا، وَيَأْكُلُوا ذَبِيحَتَنَا، وَأَنْ يُصَلُّوا صَلَاتَنَا، فَإِذَا فَعَلُوا ذَلِكَ حُرِّمَتْ عَلَيْنَا دِمَاؤُهُمْ وَأَمْوَالُهُمْ إِلَّا بِحَقِّهَا، لَهُمْ مَا لِلْمُسْلِمِينَ وَعَلَيْهِمْ مَا عَلَى الْمُسْلِمِينَ". (خ,د,ت,ن)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ഇലാഹില്ലെന്നും, മുഹമ്മദ്(സ) അവന്റെ അടിമയും ദൂതനുമാണെന്നും സാക്ഷ്യം വഹിക്കുകയും, നമ്മുടെ ഖിബ്‌ലയെ അഭിമുഖീകരിക്കുകയും, നാം അറുത്തത് ഭക്ഷിക്കുകയും, നമ്മുടെ നിസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്യുന്നതുവരെ ജനങ്ങളോട് യുദ്ധം ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടു. അവർ അത് പ്രവർത്തിച്ചാൽ ന്യായമായ അവകാശ ബാധ്യതകളൊഴികെ അവരുടെ രക്തവും ധനവും നമ്മുടെമേൽ നിഷിദ്ധമാക്കപ്പെട്ടിരിക്കുന്നു. മുസ്ലിംകളുടെ അവകാശ ബാധ്യതകൾ അവരുടെയും അവകാശ ബാധ്യതകളായിരിക്കും". (ബു,ദ,തു,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ جَرِيرِ بْنِ عَبْدِاللهِ الْبَجَلِي رَضِيَ اللهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَالنُّصْحِ لِكُلِّ مُسْلِمٍ. (ق,ن)', 'ജരീറുബ്നുഅബ്ദില്ലാഹിൽ ബജലി(റ): നിസ്കാരം നില നിർത്തുമെന്നും സകാത്ത് കൊടുക്കുമെന്നും എല്ലാ മുസ്ലിമിനോടും ഗുണകാംക്ഷ പുലർത്തുമെന്നും ഞാൻ നബി(സ)യോട് കരാർ ചെയ്തു. (ബു,മു,ന)', 'جَرِيرِ بْنِ عَبْدِاللهِ الْبَجَلِي', 'ജരീറുബ്നുഅബ്ദില്ലാഹിൽ ബജലി(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 87, 87, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عن عُبَادَةَ بْنِ الصَّامِتِ – وَكَانَ شَهِدَ بَدْرًا وَهُوَ أَحَدُ النُّقَبَاءِ لَيْلَةَ الْعَقَبَةِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ، وَحَوْلَهُ عِصَابَةٌ مِنْ أَصْحَابِه: "بايعوني عَلَى أَنْ لَا تُشْرِكُوا بالله شيئا، وَلَا تَسْرِقُوا، وَلَا تَزْنُوا، وَلَا تَقْتُلُوا أَوْلَادَكُمْ، وَلَا تَأْتُوا بِبُهْتَانٍ تَفْتَرُونَهُ بَيْنَ أَيْدِيكُمْ وَأَرْجُلِكُمْ، وَلَا تَعْصُوا فِي مَعْرُوفٍ، فَمَنْ وَفَى مِنْكُمْ فَأَجْرُهُ عَلَى اللهِ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا فَعُوقِبَ فِي الدُّنْيَا فَهُوَ كَفَّارَةٌ لَهُ، وَمَنْ أَصَابَ مِنْ ذَلِكَ شَيْئًا ثُمَّ سَتَرَهُ اللهُ فَهُوَ إِلَى اللهِ، إِنْ شَاءَ عَفَا عَنْهُ وَإِنْ شَاءَ عَاقَبَهُ". فَبَايَعْنَاهُ عَلَى ذَلِكَ. (ق,ت,ن)', 'അഖബ ഉടമ്പടിയിലെ പ്രതിനിധികളിലൊരാളും ബദ്റിൽ പങ്കെടുത്ത വ്യക്തിയുമായ ഉബ്വാദത്ബിനു സ്വാമിത്ത്(റ): നബി(സ) പറഞ്ഞു: "കൂടെ ഒരു സംഘം ആളുകളുമുണ്ട്: അല്ലാഹുവോട് ഒന്നിനെയും പങ്ക് ചേർക്കില്ലെന്നും മോഷണം ചെയ്യുകയില്ലെന്നും, വ്യഭിചരിക്കുകയില്ലെന്നും, കുഞ്ഞുങ്ങളെ കൊല്ലുകയില്ലെന്നും നിങ്ങൾക്കിടയിൽ വ്യാജാരോപണങ്ങൾ കെട്ടിച്ചമക്കുകയില്ലെന്നും നന്മക്കെതിരു നിൽക്കുകയില്ലെന്നും എന്നോട് നിങ്ങൾ കരാർ ചെയ്യുക. നിങ്ങളിൽ വല്ലവനും കരാർ പൂർത്തിയാക്കിയാൽ അവന്റെ പ്രതിഫലം അല്ലാഹുവിലാണ്. നിഷിദ്ധമായത് പ്രവർത്തിക്കുകയും ദുൻയാവിൽ വെച്ചുതന്നെ ശിക്ഷിക്കപ്പെടുകയും ചെയ്താൽ അതവന് പ്രായശ്ചിത്തമായിരിക്കും. വല്ലവനും നിഷിദ്ധമായത് ചെയ്യുകയും അല്ലാഹു അത് ഗോപ്യമാക്കി വെക്കുകയും ചെയ്താൽ അക്കാര്യം അല്ലാഹുവിലേക്കാണ്. അല്ലാഹു ഉദ്ദേശിച്ചാൽ അവന്ന് പൊറുത്തുകൊടുക്കുകയോ ശിക്ഷിക്കുകയോ ചെയ്യും." അപ്പോൾ ഞങ്ങൾ അപ്രകാരം നബി(സ)യോട് കരാർ ചെയ്തു. (ബു,മു,തു,ന)', 'عُبَادَةَ بْنِ الصَّامِتِ – وَكَانَ شَهِدَ بَدْرًا وَهُوَ أَحَدُ النُّقَبَاءِ لَيْلَةَ الْعَقَبَةِ', null, null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 87, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "الْحَلَالُ بَيِّنٌ وَالْحَرَامُ بَيِّنٌ، وَبَيْنَهُمَا مُشَبَّهَاتٌ لَا يَعْلَمُهَا كَثِيرٌ مِنَ النَّاسِ، فَمَنِ اتَّقَى الْمُشَبَّهَاتِ اسْتَبْرَأَ لِدِينِهِ وَعِرْضِهِ، وَمَنْ وَقَعَ فِي الشُّبُهَاتِ كَرَاعٍ يَرْعَى حَوْلَ الْحِمَى يُوشِكُ أَنْ يُوَاقِعَهُ، أَلَا وَإِنَّ لِكُلِّ مَلِكٍ حِمًى، أَلَا إِنَّ حِمَى اللهِ فِي أَرْضِهِ مَحَارِمُهُ، أَلَا وَإِنَّ فِي الْجَسَدِ مُضْغَةً إِذَا صَلَحَتْ صَلَحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ". (ق,ت,جه)', 'നുഅ്മാനുബ്നുബശീർ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അനുവദിക്കപ്പെട്ടത് വ്യക്തമാണ്. നിഷിദ്ധമായതും വ്യക്തംതന്നെ. അവയ്ക്കിടയിൽ അവ്യക്തമായ ചില സംഗതികളുണ്ട്. അധികമാളുകളും അവയുടെ നിജസ്ഥിതി അറിയുന്നില്ല. അപ്പോൾ ആരെങ്കിലും അവ്യക്തമായ കാര്യങ്ങളെ സൂക്ഷിച്ചാൽ അവൻ അവന്റെ ദീനിനെയും അഭിമാനത്തെയും തെറ്റിൽ നിന്ന് മുക്തമാക്കി. ഇത്തരം അവ്യക്തതകളിൽ കുടുങ്ങിപ്പോയവൻ, സംരക്ഷിതമേഖലക്ക് ചുറ്റും ആടുമേക്കുന്ന ഇടയനെപ്പോലെയാണ്. അവൻ അതിൽ അകപ്പെടാറായിരിക്കുന്നു. അറിയുക! ഓരോ രാജാവിനും ഓരോ സുരക്ഷിത മേഖലയുണ്ട്. തന്റെ ഭൂമിയിൽ അല്ലാഹുവിന്റെ സുരക്ഷിതമേഖല അവൻ നിഷിദ്ധമാക്കിയ കാര്യങ്ങളത്രെ. അറിയുക! മനുഷ്യ ശരീരത്തിൽ ഒരു മാംസക്കഷ്ണമുണ്ട്, തീർച്ച. അതു നന്നായാൽ ശരീരം മുഴുവനും നന്നായി. അതു ചീത്തയായാൽ ശരീരം മുഴുവൻ ചീത്തയായി. അറിയുക! അതത്രെ ഹൃദയം." (ബു,മു,തു,ജ)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നുബശീർ(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 88, 88, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عن سَعِيدِ بْنِ الْمُسَيَّبِ رَضِيَ اللهُ عَنْهُ، عَنْ أبيه قَالَ: لَمَّا حَضَرَتْ أَبَا طَالِبٍ الْوَفَاةُ جَاءَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَوَجَدَ عِنْدَهُ أَبَا جَهْلٍ وَعَبْدَ اللهِ بْنَ أَبِي أُمَيَّةَ بْنِ الْمُغِيرَةِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَمِّ! قُلْ لَا إِلَهَ إِلَّا اللهُ، كَلِمَةً أَشْهَدُ لَكَ بِهَا عِنْدَ اللهِ". فَقَالَ أَبُو جَهْلٍ وَعَبْدُ اللهِ بْنُ أَبِي أُمَيَّةَ: يَا أَبَا طَالِبٍ! أَتَرْغَبُ عَنْ مِلَّةِ عَبْدِ الْمُطَّلِبِ؟ فَلَمْ يَزَلْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْرِضُهَا عَلَيْهِ وَيُعِيدُ لَهُ تِلْكَ الْمَقَالَةَ حَتَّى قَالَ أَبُوطَالِبٍ آخِرَ مَا كَلَّمَهُمْ هُوَ عَلَى مِلَّةِ عَبْدِ الْمُطَّلِبِ، وَأَبَى أَنْ يَقُولَ لَا إِلَهَ إِلَّا اللهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَا وَاللهِ! لَأَسْتَغْفِرَنَّ لَكَ مَا لَمْ أُنْهَ عَنْكَ" فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ {مَا كَانَ لِلنَّبِيِّ وَالَّذِينَ آمَنُوا أَنْ يَسْتَغْفِرُوا لِلْمُشْرِكِينَ وَلَوْ كَانُوا أُولِي قُرْبَى مِنْ بَعْدِ مَا تَبَيَّنَ لَهُمْ أَنَّهُمْ أَصْحَابُ الْجَحِيمِ} وَأُنْزِلَ اللهُ تَعَالَى فِي أَبِي طَالِبٍ، فَقَالَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ {إِنَّكَ لَا تَهْدِي مَنْ أَحْبَبْتَ وَلَكِنَّ اللهَ يَهْدِي مَنْ يَشَاءُ وَهُوَ أَعْلَمُ بِالْمُهْتَدِينَ} [القصص:٥٦] (ق,ن)', 'സഈദ്ബ്നുൽ മുസയ്യബ്(റ) തന്റെ പിതാവിൽനിന്ന്: അബൂത്വാലിബ് മരണാസന്നനായിരിക്കെ നബി(സ) അദ്ദേഹത്തിന്റെ അടുത്തുവന്നു. അബ്ദുല്ലാഹിബ്നു അബീ ഉമയ്യത്തുബ്നിൽ മുഗീറയും അബൂജഹ്ലും അവിടെയുണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "ഓ പിതൃവ്യാ! നിങ്ങൾ ''ലാഇലാഹഇല്ലല്ലാഹ്'' (അല്ലാഹു അല്ലാതെ ആരാധ്യനില്ല) എന്ന് പറയുക. ആ വാക്യം മുഖേന അല്ലാഹുവിങ്കൽ നിങ്ങൾക്ക് വേണ്ടി ഞാൻ സാക്ഷി നിൽക്കാം." ആ സമയം അബൂജഹ്ലും അബ്ദുല്ലാഹിബ്നു അബീഉമയ്യയും ചേർന്ന് ചോദിച്ചു: അബൂതാലിബ്! താങ്കൾ അബ്ദുൽ മുത്തലിബിന്റെ പാത വെടിയുകയാണോ? അല്ലാഹുവിന്റെ ദൂതനാകട്ടെ ആ വാക്യം ആവർത്തിച്ചു പറഞ്ഞു കൊടുത്തു കൊണ്ടേയിരുന്നു. അങ്ങനെ അവസാനമായി അബൂതാലിബ് അവരോട് പറഞ്ഞത് ''ഞാൻ അബ്ദുൽ മുത്വലിബിന്റെ മാർഗ്ഗത്തിലാണ്'' എന്നത്രെ, അദ്ദേഹം ലാഇലാഹ ഇല്ലല്ലാഹ് എന്നുച്ചരിക്കാൻ വിസമ്മതിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "വിലക്കപ്പെടാത്തിടത്തോളം കാലം താങ്കൾക്കുവേണ്ടി ഞാൻ പാപമോചനത്തിനഭ്യർത്ഥിക്കും." അപ്പോൾ "ബഹുദൈവ വിശ്വാസികൾ ജ്വലിക്കുന്ന നരകാഗ്നിയുടെ അവകാശികളാണെന്ന് വ്യക്തമായതിന് ശേഷവും അവർക്ക് വേണ്ടി പാപമോചനം തേടൽ പ്രവാചകനും വിശ്വാസികൾക്കും ഭൂഷണമല്ല." (തൗബ: 113) എന്ന വചനം അല്ലാഹു അവതരിപ്പിച്ചു. അബൂത്വാലിബിന്റെ വിഷയത്തിൽ (ഈ സൂക്തം) അവതരിപ്പിച്ചു: "താങ്കൾ ഇഛിക്കുന്നവരെ സന്മാർഗ്ഗത്തിലാക്കാൻ താങ്കൾക്കാകില്ല. എന്നാൽ അല്ലാഹു താനുദ്ദേശിക്കുന്നവരെ നേർമാർഗ്ഗത്തിലാക്കുന്നു. സന്മാർഗ്ഗം പ്രാപിക്കുന്നവരെ അവൻ നന്നായി അറിയുന്നതാണ്." (ഖസസ്: 56) (ബു,മു,ന)', 'سَعِيدِ بْنِ الْمُسَيَّبِ', 'സഈദ്ബ്നുൽ മുസയ്യബ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], 'القصص:٥٦', null, 88, 89, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا قُعُودًا حَوْلَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَعَنَا أَبُو بَكْرٍ وَ عُمَرُ فِي نَفَرٍ، فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ بَيْنِ أَظْهُرِنَا، فَأَبْطَأَ عَلَيْنَا، وَخَشِينَا أَنْ يُقْتَطَعَ دُونَنَا وَفَزِعْنَا، فَقُمْنَا فَكُنْتُ أَوَّلَ مَنْ فَزِعَ، فَخَرَجْتُ أَبْتَغِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَتَّى أَتَيْتُ حَائِطًا لِلْأَنْصَارِ لِبَنِي النَّجَّارِ، فَدُرْتُ بِهِ هَلْ أَجِدُ لَهُ بَابًا، فَلَمْ أَجِدْ، فَإِذَا رَبِيعٌ يَدْخُلُ فِي جَوْفِ حَائِطٍ مِنْ بِئْرٍ خَارِجَةٍ، وَالرَّبِيعُ الْجَدْوَلُ، فَاحْتَفَزْتُ كَمَا يَحْتَفِزُ الثَّعْلَبُ، فَدَخَلْتُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَبُو هُرَيْرَةَ؟" فَقُلْتُ؟ نعم يَا رَسُولَ اللهِ! قَالَ: "مَا شَأْنُكَ" قُلْتُ: كُنْتَ بَيْنَ أَظْهُرِنَا، فَقُمْتَ فَأَبْطَأْتَ عَلَيْنَا، فَخَشِينَا أَنْ تُقْتَطَعَ دُونَنَا فَفَزِعْنَا، فَكُنْتُ أَوَّلَ مَنْ فَزِعَ، فَأَتَيْتُ هَذَا الْحَائِطَ فَاحْتَفَزْتُ كَمَا يَحْتَفِزُ الثَّعْلَبُ، وَهَؤُلَاءِ النَّاسُ وَرَائِي، فَقَالَ: "يَا أَبَا هُرَيْرَةَ! – وَأَعْطَانِي نَعْلَيْهِ، قَالَ – اذْهَبْ بِنَعْلَيَّ هَاتَيْنِ، فَمَنْ لَقِيتَ مِنْ وَرَاءِ هَذَا الْحَائِطِ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ مُسْتَيْقِنًا بِهَا قَلْبُهُ فَبَشِّرْهُ بِالْجَنَّةِ" فَكَانَ أَوَّلَ مَنْ لَقِيتُ عُمَرُ، فَقَالَ: مَا هَاتَانِ النَّعْلَانِ يَا أَبَا هُرَيْرَةَ؟ فَقُلْتُ: هَاتَانِ نَعْلَا رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، بَعَثَنِي بِهِمَا مَنْ لَقِيتُ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ مُسْتَيْقِنًا بِهَا قَلْبُهُ بَشَّرْتُهُ بِالْجَنَّةِ، فَضَرَبَ عُمَرُ بِيَدِهِ بَيْنَ ثَدْيَيَّ، فَخَرَرْتُ لِاسْتِي، فَقَالَ: ارْجِعْ يَا أَبَا هُرَيْرَةَ!، فَرَجَعْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَجْهَشْتُ بُكَاءً، وَرَكِبَنِي عُمَرُ فَإِذَا هُوَ عَلَى أَثَرِي، فَقَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا لَكَ يَا أَبَا هُرَيْرَةَ؟! قُلْتُ: لَقِيتُ عُمَرَ فَأَخْبَرْتُهُ بِالَّذِي بَعَثْتَنِي بِهِ، فَضَرَبَ بَيْنَ ثَدْيَيَّ ضَرْبَةً خَرَرْتُ لِاسْتِي، قَالَ ارْجِعْ، فَقَالَ لَهُ رَسُولُ اللهِ: "يَا عُمَرُ! مَا حَمَلَكَ عَلَى مَا فَعَلْتَ؟" قَالَ: يَا رَسُولَ اللهِ! بِأَبِي أَنْتَ وَأُمِّي! أَبَعَثْتَ أَبَا هُرَيْرَةَ بِنَعْلَيْكَ مَنْ لَقِيَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ مُسْتَيْقِنًا بِهَا قَلْبُهُ بَشَّرَهُ بِالْجَنَّةِ؟ قَالَ: "نعم" قَالَ: فَلَا تَفْعَلْ، فَإِنِّي أَخْشَى أَنْ يَتَّكِلَ النَّاسُ عَلَيْهَا، فَخَلِّهِمْ يَعْمَلُونَ، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَخَلِّهِمْ". (م)', 'അബൂഹുറൈറ(റ): ഒരിക്കൽ ഞങ്ങൾ അബൂബക്കർ, ഉമർ(റ) തുടങ്ങിയവരെല്ലാം ഉൾകൊള്ളുന്ന ഒരുസംഘം നബി(സ)യുടെ അടുത്ത് ഇരിക്കുകയായിരുന്നു. തദവസരത്തിൽ നബി(സ) ഞങ്ങളുടെ ഇടയിൽ നിന്നെഴുന്നേറ്റു പോവുകയും (തിരിച്ചുവരാൻ) വളരെ വൈകുകയും ചെയ്തു. അപ്പോൾ വല്ല വിപത്തും സംഭവിച്ചതാണെന്ന് ഞങ്ങൾ ഭയപ്പെടുകയും അസ്വസ്ഥരാവുകയും ചെയ്തു. അങ്ങനെ ഞങ്ങൾ എഴുന്നേറ്റു. ആ കൂട്ടത്തിൽ ആദ്യം ഭയമനുഭവപ്പെട്ട വ്യക്തി ഞാനായിരുന്നു. തന്നിമിത്തം പ്രവാചകനെ അന്വേഷിച്ച് ഞാൻ പുറപ്പെടുകയും നജ്ജാർ ഗോത്രക്കാരനായ ഒരു അൻസാരിയുടെ തോട്ടത്തിനരികിൽ എത്തിച്ചേരുകയും ചെയ്തു. അനന്തരം അതിനു വല്ല പ്രവേശന കവാടവുമുണ്ടോ എന്നന്വേഷിച്ച് ഞാനതിന്റെ ചുറ്റും നടന്നുനോക്കി. എന്നാൽ ഞാനൊരു കവാടവും കണ്ടില്ല. അപ്പോഴതാ പുറത്തുള്ള ഒരു കിണറിൽ നിന്നും ചെറിയ കൈതോട് തോട്ടത്തിന്റെ ഉള്ളിലേക്കു പോകുന്നു. കുറുക്കൻ പ്രവേശിക്കുന്നതു പോലെ ഞാനതിലൂടെ പ്രവാചകന്റ അടുത്തേക്കു ചെന്നു. (എന്നെ കണ്ട) ഉടൻ പ്രവാചകൻ ചോദിച്ചു. "അബൂഹുറൈറയോ?" ഞാൻ മറുപടി പറഞ്ഞു: അതെ തിരുദൂതരേ! നബി(സ) ചോദിച്ചു: "എന്താണ് നിന്റെ അവസ്ഥ?" ഞാൻ പറഞ്ഞു: താങ്കൾ ഞങ്ങളുടെ ഇടയിൽ നിന്ന് എഴുന്നേറ്റുപോയി വളരെ വൈകിയിട്ടും തിരിച്ചുവരാതിരുന്നതിനാൽ വല്ല വിപത്തും സംഭവിച്ചോയെന്ന് ഞങ്ങൾ ഭയപ്പെടുകയും അസ്വസ്ഥരാവുകയും ചെയ്തു. ആദ്യമായി വളരെ അസ്വസ്ഥത അനുഭവപ്പെട്ടത് എനിക്കായിരുന്നു. അതിനാൽ ഞാനീ തോട്ടത്തിന്റെ അരികിൽ വരികയും കുറുക്കൻ പ്രവേശിക്കുന്നതുപോലെ ഞാനിതിൽ പ്രവേശിക്കുകയും ചെയ്തു. മറ്റുള്ളവരെല്ലാം എന്റെ പിന്നിലുണ്ട്. (അവിടെ പ്രവാചകനെ കണ്ടു) തൽസമയം പ്രവാചകൻ(സ) തന്റെ രണ്ട് ചെരിപ്പുകൾ എനിക്ക് നൽകിയിട്ട് പറഞ്ഞു. "ഹേ, അബൂഹുറൈറൊ! നീ എന്റെ ഈ രണ്ട് ചെരിപ്പ് കൊണ്ട് പോവുകയും, അനന്തരം അല്ലാഹു അല്ലാതെ ഒരാരാധ്യനുമില്ലെന്ന് ദൃഢവിശ്വാസം പ്രഖ്യാപിക്കുന്ന ആരെയാണോ ഈ തോട്ടത്തിന്റെ പിന്നിൽ കാണുന്നത് അവനെ സ്വർഗ്ഗം കൊണ്ട് സന്തോഷവാർത്ത അറിയിക്കുകയും ചെയ്യുക." ഞാൻ ആദ്യമായി കണ്ടത് ഉമറി(റ)നെയായിരുന്നു. അപ്പോൾ അദ്ദേഹം ചോദിച്ചു: ഇതെന്താണ് അബൂഹുറൈറൊ, രണ്ട് ചെരിപ്പ്? ഞാൻ പറഞ്ഞു: ഇത് നബി(സ)യുടെ രണ്ട് ചെരിപ്പാണ്. ''അല്ലാഹുവല്ലാതെ യാതൊരു ആരാധ്യനുമില്ല'' എന്ന് ഹൃദയത്തിലുറപ്പിച്ച് സാക്ഷ്യപ്പെടുത്തുന്ന ഏതൊരാളെ കാണുന്നുവോ അവനെ സ്വർഗ്ഗം കൊണ്ട് സന്തോഷവാർത്ത അറിയിക്കുക എന്ന വ്യവസ്ഥയിൽ ഈ ചെരുപ്പ് ഏൽപിച്ചുകൊണ്ട് എന്നെ അയച്ചതാണ്. അപ്പോൾ ഉമർ(റ) തന്റെ കൈകൊണ്ട് എന്റെ നെഞ്ചിന് അടിച്ചു. ഉടനെ ഞാൻ ആസനം കുത്തിവീണു. അദ്ദേഹം പറഞ്ഞു: അബൂഹുറൈറൊ! തിരിച്ചുപോകൂ! ഞാൻ കരഞ്ഞുകൊണ്ട് നബി(സ)യുടെ അടുത്തേക്ക് മടങ്ങി. ഉമർ(റ) എന്നെ പിന്തുടർന്നു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അബൂഹുറൈറൊ! നിനക്കെന്തുപറ്റി?" ഞാൻ പറഞ്ഞു. ഞാൻ ഉമറിനെ കണ്ടു. അപ്പോൾ താങ്കൾ എന്നെ നിയോഗിച്ച കാര്യം ഞാൻ അദ്ദേഹത്തെ അറിയിച്ചു. ഉടൻ അദ്ദേഹം എന്റെ നെഞ്ചിൽ അടിക്കുകയും എന്നോട് മടങ്ങാൻ പറയുകയും ചെയ്തു. ആ അടി കാരണം ഞാൻ ആസനം കുത്തിവീണു. തിരുനബി(സ) ചോദിച്ചു: "ഉമർ! നിന്നെ ഇങ്ങനെ ചെയ്യാൻ പ്രേരിപ്പിച്ചതെന്താണ്?" ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! എന്റെ മാതാപിതാക്കൾ നിങ്ങൾക്ക് സമർപ്പിതം. (താങ്കൾക്ക് വേണ്ടി എന്തിനും ഞാൻ സന്നദ്ധനാണ്) അല്ലാഹു ഒഴികെ യാതൊരു ആരാധ്യനുമില്ലായെന്ന് ദൃഢമായി സാക്ഷ്യം വഹിക്കുന്ന ആരെ കണ്ടാലും അവനെ സ്വർഗ്ഗം കൊണ്ട് സന്തോഷവാർത്ത അറിയിക്കുകയെന്ന് പറഞ്ഞ് താങ്കളുടെ രണ്ടു ചെരിപ്പും കൊടുത്തു അബൂഹുറൈറയെ താങ്കൾ നിയോഗിച്ചിരുന്നുവോ? പ്രവാചകൻ(സ) പറഞ്ഞു. "അതെ." ഉമർ(റ) പറഞ്ഞു: താങ്കൾ അങ്ങനെ ചെയ്യാതിരുന്നാലും! കാരണം ജനങ്ങൾ അതിനെമാത്രം ആശ്രയിക്കുമെന്ന് ഞാൻ ഭയക്കുന്നു. അതിനാൽ അവരെ സൽകർമ്മം ചെയ്യുന്നവരായി വിട്ടാലും! പ്രവാചകൻ(സ) പറഞ്ഞു: "എന്നാൽ അവരെ സൽകർമ്മമനുഷ്ഠിക്കാൻ വിട്ടേക്കുക." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 89, 90, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أُسَامَةَ بْنِ زَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَرِيَّةٍ، فَصَبَّحْنَا الْحُرَقَاتِ مِنْ جُهَيْنَةَ، فَأَدْرَكْتُ رَجُلًا، فَقَالَ: لَا إِلَهَ إِلَّا اللهُ، فَطَعَنْتُهُ، فَوَقَعَ فِي نَفْسِي مِنْ ذلك فَذَكَرْتُهُ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَقَالَ لَا إِلَهَ إِلَّا اللهُ وَقَتَلْتَهُ" قَالَ: قُلْتُ: يَا رَسُولَ اللهِ! إِنَّمَا قَالَهَا خَوْفًا مِنَ السِّلَاحِ، قَالَ: "أَفَلَا شَقَقْتَ عَنْ قَلْبِهِ حَتَّى تَعْلَمَ أَقَالَهَا أَمْ لَا؟" فَمَا زَالَ يُكَرِّرُهَا عَلَيَّ حَتَّى تَمَنَّيْتُ أَنِّي أَسْلَمْتُ يَوْمَئِذٍ، قَالَ: فَقَالَ سَعْدٌ: وَأَنَا وَاللهِ! لَا أَقْتُلُ مُسْلِمًا حَتَّى يَقْتُلَهُ ذُو الْبُطَيْنِ – يَعْنِي أُسَامَةَ، قَالَ: قَالَ رَجُلٌ: أَلَمْ يَقُلِ اللهُ {وَقَاتِلُوهُمْ حَتَّى لَا تَكُونَ فِتْنَةٌ وَيَكُونَ الدِّينُ كُلُّهُ لِلَّهِ}؟ فَقَالَ سَعْدٌ: قَدْ قَاتَلْنَا حَتَّى لَا تَكُونَ فِتْنَةٌ، وَأَنْتَ وَأَصْحَابُكَ تُرِيدُونَ أَنْ تُقَاتِلُوا حَتَّى تَكُونَ فِتْنَةٌ. (ق,د)', 'ഉസാമത്തുബ്നു സൈദ്(റ): നബി(സ) ഞങ്ങളെ ഒരു സൈന്യത്തിൽ നിയോഗിച്ചു. അങ്ങനെ പ്രഭാതത്തിൽ ഞങ്ങൾ ജുഹൈന ഗോത്രക്കാരിൽപ്പെട്ട ''ഹുറൊത്തു''കാരുടെ അടുത്തെത്തിയപ്പോൾ ഞാനൊരാളെ പിടികൂടി. ഉടനെ അയാൾ ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' (അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല) എന്ന് പറയുകയും ചെയ്തു. അന്നേരം ഞാനവന് ഒരു കുത്തു കൊടുത്തു. അത് എന്റെ ഹൃദയത്തിൽ അസ്വസ്ഥതയുണ്ടാക്കിയപ്പോൾ ഞാനക്കാര്യം നബി(സ)യോടു പറഞ്ഞു. അപ്പോൾ നബി(സ) ചോദിച്ചു: "അവൻ ''ലാഇലാഹ ഇല്ലല്ലാഹു'' എന്ന് പറഞ്ഞശേഷം നീ അവനെ വധിച്ചുവെന്നോ?" ഞാൻ പറഞ്ഞു: നബിയേ, ആയുധം ഭയന്നു മാത്രമാണ് അതവൻ പറഞ്ഞത്. നബി(സ) ചോദിച്ചു: "അവനത് നിഷ്കളങ്കമായി പറഞ്ഞതാണോ അല്ലയോ എന്നറിയാൻ നിനക്ക് അവന്റെ ഹൃദയം കീറി നോക്കാമായിരുന്നില്ലേ?" ഞാൻ ഇന്നാണ് (ആ സംഭവത്തിന് ശേഷമാണ്) മുസ്ലിമായതെങ്കിൽ എന്നാഗ്രഹിക്കുവോളം പ്രവാചകൻ അതാവർത്തിച്ച കൊണ്ടിരുന്നു. നിവേദകൻ പറയുന്നു; അപ്പോൾ സഅ്ദ്(റ) പറഞ്ഞു: അല്ലാഹുവാണെ, ദുൽബുത്വെയ്നി അഥവാ ഉസാമ ഇനി ഒരു മുസ്ലിമിനെ വധിക്കുന്നതുവരെ ഞാൻ ഒരു മുസ്ലിമിനെയും വധിക്കുകയില്ല. റിപ്പോർട്ടർ പറയുന്നു: ഒരാൾ ചോദിച്ചു: "കുഴപ്പം ഇല്ലാതാവുകയും മതം മുഴുവൻ അല്ലാഹുവിന്നു വേണ്ടിയാകുന്നതു വരെയും നിങ്ങൾ ധർമ്മ സമരത്തിലേർപ്പെടുക'' എന്ന് അല്ലാഹു പറഞ്ഞിട്ടില്ലേ?. തദവസരത്തിൽ സഅ്ദ്(റ) പറഞ്ഞു: തീർച്ചയായും ഞങ്ങൾ കുഴപ്പം ഇല്ലാതാകുന്നതു വരെ സമരം ചെയ്തിട്ടുണ്ട്. നീയും നിന്റെ കൂട്ടാളികളും കുഴപ്പം ഉണ്ടാകുന്നതുവരെ യുദ്ധം ചെയ്യാനാണ് ഉദ്ദേശിക്കുന്നത്. (ബു,മു,ദ)', 'أُسَامَةَ بْنِ زَيْدٍ', 'ഉസാമത്തുബ്നു സൈദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 90, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنِ الْمِقْدَادِ بْنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ قَالَ: يَا رَسُولَ اللهِ! أَرَأَيْتَ إِنْ لَقِيتُ رَجُلًا مِنَ الْكُفَّارفَقَاتَلَنِي، فَضَرَبَ إِحْدَى يَدَيَّ بِالسَّيْفِ فَقَطَعَهَا، ثُمَّ لَاذَ مِنِّي بِشَجَرَةٍ، فَقَالَ أَسْلَمْتُ لِلَّهِ أَفَأَقْتُلُهُ يَارَسُولَ اللهِ بَعْدَ أَنْ قَالَهَا؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقْتُلْهُ" قَالَ فَقُلْتُ: يَا رَسُولَ اللهِ! إِنَّهُ قَدْ قَطَعَ يَدِي، ثُمَّ قَالَ ذَلِكَ بَعْدَ أَنْ قَطَعَهَا، أَفَأَقْتُلُهُ؟ قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَقْتُلْهُ، فَإِنْ قَتَلْتَهُ فَإِنَّهُ بِمَنْزِلَتِكَ قَبْلَ أَنْ تَقْتُلَهُ، وَإِنَّكَ بِمَنْزِلَتِهِ قَبْلَ أَنْ يَقُولَ كَلِمَتَهُ الَّتِي قَالَ". (ق,د)', 'മിഖ്ദാദുബ്നുൽ അസ്വദ്(റ): അദ്ദേഹം ചോദിച്ചു: നബിയേ!, ഞാനൊരു അവിശ്വാസിയെ കണ്ടുമുട്ടുകയും അവൻ എന്നോടു യുദ്ധം ചെയ്യുകയും വാൾ കൊണ്ട് എന്റെ ഒരു കൈ മുറിക്കുകയും ചെയ്തശേഷം, ഒരു വൃക്ഷത്തിൽ അഭയം പ്രാപിക്കുകയും അനന്തരം ഞാൻ അല്ലാഹുവിനു കീഴടങ്ങി (മുസ്ലിമായി) എന്നു പറയുകയും ചെയ്താൽ എനിക്ക് അവനെ വധിക്കാമോ? നബി(സ) അരുളി: "നീ അവനെ വധിക്കരുത്." ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ! അവൻ എന്റെ കൈ മുറിച്ചതിനു ശേഷമാണ് അതുപറഞ്ഞത്. അതുകൊണ്ട് അവനെ എനിക്ക് വധിച്ചുകൂടെ? നബി(സ) പറഞ്ഞു: "നീ അവനെ വധിക്കരുത്. അഥവാ വധിക്കുകയാണെങ്കിൽ നീ അവനെ വധിക്കുന്നതിനു മുമ്പുള്ള നിന്റെ സ്ഥാനത്ത് അവനും അവൻ പറഞ്ഞവാക്യം ഉച്ചരിക്കുന്നതിനു മുമ്പുള്ള അവന്റെ സ്ഥാനത്ത് നീയുമായിരിക്കും.''(ബു,മു,ദ)', 'الْمِقْدَادِ بْنِ الْأَسْوَدِ', 'മിഖ്ദാദുബ്നുൽ അസ്വദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 91, 91, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ صَفْوَانَ بْنِ مُحْرِزٍ رَضِيَ اللهُ عَنْهُ: أَنَّ جُنْدَبَ بْنَ عَبْدِ اللهِ الْبَجَلِيَّ بَعَثَ إِلَى عَسْعَسِ بْنِ سَلَامَةَ زَمَنَ فِتْنَةِ ابْنِ الزُّبَيْرِ، فَقَالَ: اجْمَعْ لِي نَفَرًا مِنْ إِخْوَانِكَ حَتَّى أُحَدِّثَهُمْ، فَبَعَثَ رَسُولًا إِلَيْهِمْ، فَلَمَّا اجْتَمَعُوا جَاءَ جُنْدَبٌ وَعَلَيْهِ بُرْنُسٌ أَصْفَرُ، فَقَالَ: تَحَدَّثُوا بِمَا كُنْتُمْ تَحَدَّثُونَ بِهِ، حَتَّى دَارَ الْحَدِيثُ فَلَمَّا دَارَ الْحَدِيثُ إِلَيْهِ حَسَرَ الْبُرْنُسَ عَنْ رَأْسِهِ، فَقَالَ: إِنِّي أَتَيْتُكُمْ وَلَا أُرِيدُ أَنْ أُخْبِرَكُمْ إِلَّا عَنْ نَبِيِّكُمْ، إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ بَعْثًا مِنَ الْمُسْلِمِينَ إِلَى قَوْمٍ مِنَ الْمُشْرِكِينَ، وَإِنَّهُمُ الْتَقَوْا، فَكَانَ رَجُلٌ مِنَ الْمُشْرِكِينَ إِذَا شَاءَ أَنْ يَقْصِدَ إِلَى رَجُلٍ مِنَ الْمُسْلِمِينَ قَصَدَ لَهُ فَقَتَلَهُ، وَإِنَّ رَجُلًا مِنَ الْمُسْلِمِينَ قَصَدَ غَفْلَتَهُ، قَالَ: وَكُنَّا نُحَدَّثُ أَنَّهُ أُسَامَةُ بْنُ زَيْدٍ، فَلَمَّا رَفَعَ عَلَيْهِ السَّيْفَ قَالَ: لَا إِلَهَ إِلَّا اللهُ، فَقَتَلَهُ، فَجَاءَ الْبَشِيرُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلَهُ فَأَخْبَرَهُ حَتَّى أَخْبَرَهُ خَبَرَ الرَّجُلِ كَيْفَ صَنَعَ، فَدَعَاهُ فَسَأَلَهُ، فَقَالَ: "لِمَ قَتَلْتَهُ" قَالَ: يَا رَسُولَ اللهِ! أَوْجَعَ فِي الْمُسْلِمِينَ، وَقَتَلَ فُلَانًا وَفُلَانًا – وَسَمَّى لَهُ نَفَرًا – وَإِنِّي حَمَلْتُ عَلَيْهِ، فَلَمَّا رَأَى السَّيْفَ قَالَ: لَا إِلَهَ إِلَّا اللهُ، قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَقَتَلْتَهُ" قَالَ: نَعَمْ، قَالَ: "فَكَيْفَ تَصْنَعُ بِ ''لَا إِلَهَ إِلَّا اللهُ'' إِذَا جَاءَتْ يَوْمَ الْقِيَامَةِ؟" قَالَ: يَا رَسُولَ اللهِ! اسْتَغْفِرْ لِي! قَالَ: "وَكَيْفَ تَصْنَعُ بِ ''لَا إِلَهَ إِلَّا اللهُ'' إِذَا جَاءَتْ يَوْمَ الْقِيَامَةِ" قَالَ: فَجَعَلَ لَا يَزِيدُهُ عَلَى أَنْ يَقُولَ: "كَيْفَ تَصْنَعُ بِ ''لَا إِلَهَ إِلَّا اللهُ'' إِذَا جَاءَتْ يَوْمَ الْقِيَامَةِ". (م)', 'സഫ്വാനുബ്നു മുഹ്രിസ്(റ): ജുൻദബുബ്നു അബ്ദില്ലാഹിൽ ബജലിയ്യ്, അബ്ദുല്ലാഹിബ്നു സുബൈറി(റ)ന്റെ സമര കാലത്ത് അസ്അസുബ്നു സലാമത്തിന്റെ അടുക്കലേക്ക് ഇങ്ങനെ പറഞ്ഞയച്ചു: നീ നിന്റെ സ്നേഹിതന്മാരിൽ നിന്നും ഒരു സംഘത്തെ സംഘടിപ്പിക്കുക. എനിക്ക് അവരോടല്പം സംസാരിക്കാനുണ്ട്. അസ്അസുബ്നു സലാമത്ത് ഒരു ദൂതനെ ആ സ്നേഹിതന്മാരിലേക്ക് അയച്ചു. അവർ ഒരുമിച്ചുകൂടിയപ്പോൾ മഞ്ഞ വർണ്ണത്തിലുള്ള ഒരു തൊപ്പി ധരിച്ച് ജുൻദുബ് വന്ന് അവർ സംസാരിച്ചുകൊണ്ടിരിക്കുന്നത് തുടരാൻ അനുവാദം നൽകി. തദ്വാരാ അവർ മാറിമാറി സംസാരിച്ചുകൊണ്ടിരുന്നു. സംസാരിക്കാനുള്ള തന്റെ ഊഴം വന്നപ്പോൾ അദ്ദേഹം തലയിൽനിന്ന് തൊപ്പി അൽപം നീക്കിവെച്ച് ഇപ്രകാരം പറയാൻ തുടങ്ങി: നിശ്ചയം! നിങ്ങളുടെ നബിയിൽ നിന്ന് നിങ്ങളോട് ഹദീസ് പറഞ്ഞുതരാൻ വേണ്ടി മാത്രമാണ് ഞാൻ ഇവിടെ വന്നിട്ടുള്ളത്. നബി(സ) മുസ്ലിംകളിൽ നിന്നുള്ള ഒരു സൈന്യത്തെ ബഹുദൈവ വിശ്വാസികളിൽ നിന്നുള്ള ഒരു ജനതയുടെ അടുക്കലേക്കയച്ചു. അവർ യുദ്ധത്തിലേർപ്പെടുകയും ചെയ്തു. തദവസരത്തിൽ ആ ബഹുദൈവവിശ്വാസികളിൽപെട്ട ഒരാൾ മുസ്ലിംകളിൽ നിന്ന് താനുദ്ദേശിക്കുന്ന ഓരോരുത്തരെ പിടികൂടുകയും വധിക്കുകയും ചെയ്തുകൊണ്ടിരുന്നു. അപ്പോൾ മുസ്ലിംകളിൽപെട്ട ഒരാൾ അവനറിയാതെ അവനെ പിടികൂടി. അദ്ദേഹം ഉസാമത്തുബ്നു സൈദ്(റ) ആണെന്നു ഞങ്ങൾ പറയാറുണ്ടായിരുന്നു. അദ്ദേഹം അവനെ വധിക്കാൻ വേണ്ടി വാളുയർത്തിയപ്പോൾ അവൻ ''അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല'' എന്നു പറഞ്ഞു. ഉടൻ അദ്ദേഹം അവനെ വധിച്ചു. അനന്തരം സന്തോഷവാർത്തയുമായി ഒരാൾ നബിയുടെ അടുക്കലെത്തി. അവിടുന്ന് ചോദിച്ചതനുസരിച്ച് ആ മനുഷ്യനെക്കുറിച്ചും അവനോട് ചെയ്തതിനെക്കുറിച്ചും മുഴുവൻ വിവരവും നബി(സ)യെ അറിയിച്ചു. നബി(സ) അദ്ദേഹത്തെ (ഉസാമയെ) വിളിച്ചു ചോദിച്ചു: "നീ എന്തിനാണ് അവനെ വധിച്ചത്?" അദ്ദേഹം പറഞ്ഞു: നബിയേ, അവൻ മുസ്ലിംകളെ വല്ലാതെ വേദനിപ്പിച്ചിരിക്കുന്നു. ഒരുസംഘം ആളുകളുടെ പേർ അദ്ദേഹം നബിയെ അറിയിച്ചിട്ട് പറഞ്ഞു. അവരെയെല്ലാം അവൻ വധിക്കുകയും ചെയ്തു. തുടർന്ന് ഞാൻ അവനെ ആക്രമിച്ചു. വാൾ കണ്ടപ്പോൾ അവൻ ''ലാ ഇലാഹ ഇല്ലല്ലാഹു'' എന്നു പറഞ്ഞതാണ്. നബി(സ) ചോദിച്ചു: "നീ അവനെ വധിച്ചോ?" അദ്ദേഹം പറഞ്ഞു: അതെ, നബി(സ) ചോദിച്ചു. "അപ്പോൾ അന്ത്യദിനത്തിൽ ''ലാ ഇലാഹ ഇല്ലല്ലാഹു'' (നിനക്കെതിരെ സാക്ഷിയായി) വരുമ്പോൾ നീ എന്തു ചെയ്യും?" അദ്ദേഹം പറഞ്ഞു: നബിയെ, അങ്ങ് എനിക്ക് വേണ്ടി പൊറുക്കലിനെ തേടിയാലും, നബി(സ) ചോദിച്ചു: "അപ്പോൾ അന്ത്യദിനത്തിൽ ''ലാ ഇലാഹ ഇല്ലല്ലാഹു'' വരുമ്പോൾ നീ അതിനെ എന്ത് ചെയ്യും?" എന്നതിലപ്പുറം നബി(സ) ഒന്നും പറഞ്ഞില്ല. (മു)', 'صَفْوَانَ بْنِ مُحْرِزٍ', 'സഫ്വാനുബ്നു മുഹ്രിസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 91, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَفِي قَلْبِهِ وَزْنُ شَعِيرَةٍ مِنْ خَيْرٍ، وَيَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَفِي قَلْبِهِ وَزْنُ بُرَّةٍ مِنْ خَيْرٍ، وَيَخْرُجُ مِنَ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَفِي قَلْبِهِ وَزْنُ ذَرَّةٍ مِنْ خَيْرٍ". (ق,ت,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ഹൃദയത്തിൽ ഒരു യവമണിയോളം നന്മയുണ്ടായിരിക്കെ ''ലാഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന വാക്യം മൊഴിഞ്ഞവൻ നരകത്തിൽനിന്ന് പുറത്ത് കടക്കും. ഹൃദയത്തിൽ ഒരു ഗോതമ്പ് മണിയുടെ തൂക്കം നന്മയുണ്ടായിരിക്കെ ''ലാ ഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് ചൊല്ലിയവനും നരകത്തിൽ നിന്ന് പുറത്തുവരും. ഒരു അണുമണിത്തൂക്കം നന്മ ഹൃദയത്തിലുണ്ടായിരിക്കെ ''ലാ ഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് ചൊല്ലിയവൻ നരകത്തിൽ നിന്ന് പുറത്തുവരും." (ബു,മു,തു,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 92, 92, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللهِ، مَا الْمُوجِبَتَانِ؟ فَقَالَ: "مَنْ مَاتَ لَا يُشْرِكُ بِاللهِ شَيْئًا دَخَلَ الْجَنَّةَ وَمَنْ مَاتَ يُشْرِكُ بِاللهِ شَيْئًا دَخَلَ النَّارَ". (م)', 'ജാബിർ(റ): നബി(സ)യുടെ അടുക്കൽ ഒരാൾ വന്നു ചോദിച്ചു: (നരക സ്വർഗ്ഗങ്ങളെ) അനിവാര്യമാക്കിത്തീർക്കുന്ന രണ്ട് കാര്യങ്ങളേതാണ്? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവോട് ഒന്നിനേയും പങ്കുചേർക്കാതെ ഒരുത്തൻ മരണപ്പെട്ടാൽ അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കും. അല്ലാഹുവോട് വല്ലതും പങ്കുചേർത്താൽ അവൻ നരകത്തിൽ പ്രവേശിക്കും." (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 92, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ أَبِي الْأَسْوَدِ الدِّيلِيِّ، عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ نَائِمٌ عَلَيْهِ ثَوْبٌ أَبْيَضُ، ثُمَّ أَتَيْتُهُ فَإِذَا هُوَ نَائِمٌ، ثُمَّ أَتَيْتُهُ وَقَدِ اسْتَيْقَظَ فَجَلَسْتُ إِلَيْهِ فَقَالَ "مَا مِنْ عَبْدٍ قَالَ لَا إِلَهَ إِلَّا اللهُ ثُمَّ مَاتَ عَلَى ذَلِكَ إِلَّا دَخَلَ الْجَنَّةَ". قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ قَالَ: "وَإِنْ زَنَى وَإِنْ سَرَقَ". قُلْتُ: وَإِنْ زَنَى وَإِنْ سَرَقَ قَالَ: "وَإِنْ زَنَى وَإِنْ سَرَقَ" ثَلَاثًا، ثُمَّ قَالَ فِي الرَّابِعَةِ: "عَلَى رَغْمِ أَنْفِ أَبِي ذَرٍّ" قَالَ: فَخَرَجَ أَبُو ذَرٍّ وَهُوَ يَقُولُ: وَإِنْ رَغِمَ أَنْفُ أَبِي ذَرٍّ. (ق,ت)', 'അബുൽഅസ്വദുദ്ദിയലി: അബൂദർറ്(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: ഞാൻ നബി(സ)യുടെ അടുത്തു ചെന്നു. അവിടുന്ന് ഉറങ്ങുകയായിരുന്നു. തിരുമേനിയുടെ ശരീരത്തിൽ വെള്ള വസ്ത്രമുണ്ട്. വീണ്ടും ഞാൻ ചെന്നു. അപ്പോഴും ഉറങ്ങുകയായിരുന്നു. പിന്നെയും ചെന്നു. അപ്പോൾ അവിടുന്ന് ഉണർന്നിരുന്നു. ഞാൻ അവിടുത്തെ സമീപം ഇരുന്നു. നബി(സ) പറഞ്ഞു: "ഒരാൾ ''ലാ ഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് പറയുകയും, പിന്നെ ആ ആശയമുൾക്കൊണ്ടവനായി മരണപ്പെടുകയും ചെയ്താൽ അയാൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാതിരിക്കില്ല." ഞാൻ ചോദിച്ചു: അവൻ വ്യഭിചരിക്കുകയും മോഷ്ടിക്കുകയും ചെയ്തിട്ടുണ്ടെങ്കിലും? നബി(സ) പറഞ്ഞു: "അതെ, അവൻ വ്യഭിചരിക്കുകയും മോഷ്ടിക്കുകയും ചെയ്തിട്ടുണ്ടെങ്കിലും."ഞാൻ ചോദിച്ചു: അവൻ വ്യഭിചരിക്കുകയും മോഷ്ടിക്കുകയും ചെയ്തിട്ടുണ്ടെങ്കിലോ? നബി(സ) പറഞ്ഞു: "അതെ, അവൻ വ്യഭിചരിക്കുകയും മോഷ്ടിക്കുകയും ചെയ്തിട്ടുണ്ടെങ്കിലും" മൂന്ന് പ്രാവശ്യം ഇതാവർത്തിച്ചു പറഞ്ഞു. നാലാംതവണ പറഞ്ഞു: "അബൂദർറിന് ഇഷ്ടമല്ലെങ്കിലും." നിവേദകൻ പറയുന്നു: "അബൂദർറിനെ വകവെക്കാതെയാണെങ്കിലും" എന്ന് പറഞ്ഞ് അബൂദർറ് പുറത്തിറങ്ങി. (ബു,മു,തു)', 'أَبِي الْأَسْوَدِ الدِّيلِيِّ، عَنْ أَبِي ذَرٍّ', 'അബുൽഅസ്വദുദ്ദിയലി', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عُثْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ مَاتَ وَهُوَ يَعْلَمُ أَنَّهُ لَا إِلَهَ إِلَّا اللهُ دَخَلَ الْجَنَّةَ". (م)', 'ഉസ്മാൻ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ല എന്നുറപ്പിച്ച് ഒരാൾ മരണപ്പെട്ടാൽ അയാൾ സ്വർഗ്ഗത്തിൽ പ്രവേശിച്ചു." (മു)', 'عُثْمَانَ', 'ഉസ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 93, 93, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ أَوْ عَنْ أَبِي سَعِيدٍ – شَكَّ الْأَعْمَشُ – رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا كَانَ غَزْوَةُ تَبُوكَ أَصَابَ النَّاسَ مَجَاعَةٌ، قَالُوا: يَا رَسُولَ اللهِ! لَوْ أَذِنْتَ لَنَا فَنَحَرْنَا نَوَاضِحَنَا فَأَكَلْنَا وَادَّهَنَّا، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "افْعَلُوا" قَالَ: فَجَاءَ عُمَرُ فَقَالَ: يَا رَسُولَ اللهِ! إِنْ فَعَلْتَ قَلَّ الظَّهْرُ، وَلَكِنِ ادْعُهُمْ بِفَضْلِ أَزْوَادِهِمْ، ثُمَّ ادْعُ اللهَ لَهُمْ عَلَيْهَا بِالْبَرَكَةِ، لَعَلَّ اللهَ أَنْ يَجْعَلَ فِي ذَلِكَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "نَعَمْ". قَالَ: فَدَعَا بِنِطَعٍ فَبَسَطَهُ ثُمَّ دَعَا بِفَضْلِ أَزْوَادِهِمْ، قَالَ: فَجَعَلَ الرَّجُلُ يَجِيءُ بِكَفِّ ذُرَةٍ، قَالَ: وَيَجِيءُ الْآخَرُ بِكَفِّ تَمْرٍ: قَالَ: وَيَجِيءُ الْآخَرُ بِكِسْرَةٍ، حَتَّى اجْتَمَعَ عَلَى النِّطَعِ مِنْ ذَلِكَ شَيْءٌ يَسِيرٌ، قَالَ:فَدَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ بِالْبَرَكَةِ، ثُمَّ قَالَ: "خُذُوا فِي أَوْعِيَتِكُمْ" قَالَ: فَأَخَذُوا فِي أَوْعِيَتِهِمْ حَتَّى مَا تَرَكُوا فِي الْعَسْكَرِ وِعَاءً إِلَّا مَلَئُوهُ، قَالَ: فَأَكَلُوا حَتَّى شَبِعُوا وَفَضَلَتْ فَضْلَةٌ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ "أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنِّي رَسُولُ اللهِ، لَا يَلْقَى اللهَ بِهِمَا عَبْدٌ غَيْرَ شَاكٍّ فَيُحْجَبَ عَنِ الْجَنَّةِ". (م)', 'അബൂഹുറൈറ(റ): തബൂക് യുദ്ധദിവസം ജനങ്ങൾക്ക് ശക്തമായ വിശപ്പനുഭവപ്പെട്ടു. അവർ നബി(സ)യോട് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ, വെള്ളം ചുമക്കുന്ന ഞങ്ങളുടെ ഒട്ടകങ്ങളെ അറുത്ത് ഭക്ഷിക്കാനും അവയുടെ കൊഴുപ്പുകളിൽ നിന്ന് എണ്ണയെടുക്കാനും അങ്ങ് സമ്മതം തന്നാലും! നബി(സ) പറഞ്ഞു: "അങ്ങനെ ചെയ്തോളൂ." ഉമർ(റ) പറഞ്ഞു: തിരുദൂതരേ, അങ്ങനെ ചെയ്യുന്നപക്ഷം (യാത്ര ചെയ്യാനുള്ള) മുതുകുകൾ (മൃഗങ്ങൾ) കുറഞ്ഞുപോകും. എന്നാൽ, അവരുടെ ഭക്ഷണങ്ങളിൽ മിച്ചമുള്ളത് കൊണ്ടുവരാൻ പറയൂ നബിയേ! തുടർന്ന് അതിൽ ബറകത് (ദൈവാനുഗ്രഹം) ഉണ്ടാവാൻ അങ്ങ് പ്രാർത്ഥിക്കുകയും ചെയ്താൽ അല്ലാഹു കനിഞ്ഞേക്കാം. ഉമറി(റ)ന്റെ നിർദ്ദേശം നബി(സ) അംഗീകരിച്ചു. തുടർന്ന് തോൽ നിർമ്മിതമായ ഒരു വിരിപ്പ് കൊണ്ടുവരാൻ ആവശ്യപ്പെട്ടു. അത് വിരിച്ചുവെച്ചു. മിച്ചമുള്ള ഭക്ഷണങ്ങൾ കൊണ്ടുവരാൻ പറഞ്ഞു. ഒരാൾ ഒരുപിടി ചോളവുമായി വരുന്നു; മറ്റൊരാൾ ഒരു പിടി കാരക്ക, വേറൊരാൾ റൊട്ടിക്കഷ്ണം. അങ്ങനെ ആ തോൽവിരിപ്പിൽ കുറച്ചു വസ്തുക്കൾ ഒരുമിച്ചുകൂട്ടി നബി(സ) ബറകതിന് വേണ്ടി പ്രാർത്ഥിച്ച ശേഷം പറഞ്ഞു: "നിങ്ങളുടെ സംഭരണികൾ നിറക്കുക." അങ്ങനെ ആ തമ്പിൽ എല്ലാ പാത്രവും നിറക്കുകയും എല്ലാവരും ഭക്ഷിക്കുകയും ചെയ്തതിന് ശേഷവും ഭക്ഷണം മിച്ചംവന്നു. ശേഷം റസൂൽ പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ഇലാഹില്ലെന്നും ഞാൻ അല്ലാഹുവിന്റെ ദൂതനാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." സത്യസാക്ഷ്യത്തിൽ സംശയിക്കാതെ അല്ലാഹുവിനെ കണ്ടുമുട്ടുന്ന ഒരു വ്യക്തിക്കും സ്വർഗ്ഗം നിഷേധിക്കപ്പെടുകയില്ല." (മു)', 'أَبِي هُرَيْرَةَ أَوْ عَنْ أَبِي سَعِيدٍ – شَكَّ الْأَعْمَشُ –', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 93, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنِ الصُّنَابِحِيِّ عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ قَالَ: دَخَلْتُ عَلَيْهِ وَهُوَ فِي الْمَوْتِ فَبَكَيْتُ فَقَالَ: مَهْلًا! لِمَ تَبْكِي؟ فَوَاللهِ لَئِنِ اسْتُشْهِدْتُ لَأَشْهَدَنَّ لَكَ، وَلَئِنْ شُفِّعْتُ لَأَشْفَعَنَّ لَكَ، وَلَئِنِ اسْتَطَعْتُ لَأَنْفَعَنَّكَ، ثُمَّ قَالَ: وَاللهِ مَا مِنْ حَدِيثٍ سَمِعْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَكُمْ فِيهِ خَيْرٌ إِلَّا حَدَّثْتُكُمُوهُ إِلَّا حَدِيثًا وَاحِدًا، وَسَوْفَ أُحَدِّثُكُمُوهُ الْيَوْمَ وَقَدْ أُحِيطَ بِنَفْسِي، سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ حَرَّمَ اللهُ عَلَيْهِ النَّارَ". (م,ت)', 'സുനാബിഹിയ്യി(റ): ഞാൻ ഉബാദതുബ്നുസ്വാമിത്തി(റ)ന്റെ അടുക്കൽ അദ്ദേഹം മരണാസന്നനായിരിക്കെ കയറിച്ചെന്നു. അപ്പോൾ ഞാൻ കരഞ്ഞുപോയി. അദ്ദേഹം പറഞ്ഞു: നോക്കൂ! താങ്കളെന്തിന് കരയുന്നു. എന്നോട് സാക്ഷി നിൽക്കാൻ ആവശ്യപ്പെട്ടാൽ നിനക്കുവേണ്ടി ഞാൻ സാക്ഷിപറയും. എനിക്ക് ശുപാർശ ചെയ്യാൻ അനുവാദം നൽകപ്പെട്ടാൽ നിനക്കുവേണ്ടി ഞാൻ ശുപാർശ ചെയ്യും. എനിക്ക് കഴിയുമെങ്കിൽ ഞാൻ തീർച്ചയായും താങ്കൾക്ക് വേണ്ടി ഉപകാരം ചെയ്യും. തുടർന്ന് അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾക്ക് നന്മയുള്ള, നബി(സ)യിൽനിന്ന് ഞാൻ കേട്ട എല്ലാ ഹദീസുകളും നിങ്ങൾക്ക് ഞാൻ പറഞ്ഞു തന്നിട്ടുണ്ട്. ഒരു ഹദീസ് ഒഴികെ. അത് ഇന്നുഞാൻ പറഞ്ഞുതരാം. കാരണം ഞാൻ മരണാസന്നനായിരിക്കുന്നു. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ലെന്നും മുഹമ്മദ്(സ) അല്ലാഹുവിന്റെ പ്രവാചകനാണെന്നും സാക്ഷ്യം വഹിക്കുന്നവർക്ക് അല്ലാഹു നരകം നിഷിദ്ധമാക്കിയിരിക്കുന്നു." (മു,തു)', 'الصُّنَابِحِيِّ عَنْ عُبَادَةَ بْنِ الصَّامِتِ', 'സുനാബിഹിയ്യി(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 94, 94, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ رِدْفَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، لَيْسَ بَيْنِي وَبَيْنَهُ إِلَّا مُؤْخِرَةُ الرَّحْلِ، فَقَالَ: "يَا مُعَاذَ بْنَ جَبَلٍ!" قُلْتُ: لَبَّيْكَ رَسُولَ اللهِ وَسَعْدَيْكَ، ثُمَّ سَارَ سَاعَةً، ثُمَّ قَالَ: "يَا مُعَاذَ بْنَ جَبَلٍ!" قُلْتُ: لَبَّيْكَ رَسُولَ اللهِ وَسَعْدَيْكَ، ثُمَّ سَارَ سَاعَةً، ثُمَّ قَالَ: "يَا مُعَاذَ بْنَ جَبَلٍ!" قُلْتُ: لَبَّيْكَ رَسُولَ اللهِ وَسَعْدَيْكَ، قَالَ: "هَلْ تَدْرِي مَا حَقُّ اللهِ عَلَى الْعِبَادِ؟" قَالَ: قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "فَإِنَّ حَقَّ اللهِ عَلَى الْعِبَادِ أَنْ يَعْبُدُوهُ وَلَا يُشْرِكُوا بِهِ شَيْئًا". ثُمَّ سَارَ سَاعَةً قَالَ: "يَا مُعَاذَ بْنَ جَبَلٍ!" قُلْتُ: لَبَّيْكَ رَسُولَ اللهِ وَسَعْدَيْكَ، قَالَ: "هَلْ تَدْرِي مَا حَقُّ الْعِبَادِ عَلَى اللهِ إِذَا فَعَلُوا ذَلِكَ؟" قَالَ: قُلْتُ: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "أَنْ لَا يُعَذِّبَهُمْ". (ق,جه)', 'മുആദുബ്നു ജബൽ(റ): ഒരിക്കൽ നബി(സ)യുടെ പിന്നിലിരുന്ന് ഞാൻ യാത്ര ചെയ്യുകയായിരുന്നു. ഒട്ടക്കട്ടിലിന്റെ പിൻഭാഗമല്ലാതെ മറ്റൊന്നും ഞങ്ങൾക്കിടയിലുണ്ടായിരുന്നില്ല. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഓ മുആദുബ്നു ജബൽ!" ഞാൻ പറഞ്ഞു: ഞാനിതാ റസൂലേ! അങ്ങേക്ക് സൗഭാഗ്യം വരട്ടെ. അല്പം സഞ്ചരിച്ച ശേഷം വിളിച്ചു: "ഓ മുആദുബ്നു ജബൽ!" ഞാൻ പറഞ്ഞു: ഞാനിതാ റസൂലേ! അങ്ങേക്ക് വിജയം വരട്ടെ. അല്പം സഞ്ചരിച്ച ശേഷം വീണ്ടും വിളിച്ചു: "ഓ മുആദ്ബ്നു ജബൽ!" ഞാൻ പറഞ്ഞു: ഞാനിതാ റസൂലേ! അങ്ങേക്ക് വിജയം വരട്ടെ. നബി(സ) ചോദിച്ചു: "അല്ലാഹുവിന് അടിമകളിൽ നിന്നുള്ള അവകാശം എന്താണെന്ന് നിനക്കറിയാമോ?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ ദൂതനുമാണ് നന്നായി അറിയുക. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന് അടിമകളിൽ നിന്നുള്ള അവകാശം അവർ അവനെ ആരാധിക്കലും അവനിൽ ഒന്നും പങ്ക് ചേർക്കാതിരിക്കലുമാണ്." അല്പം സഞ്ചരിച്ച ശേഷം വീണ്ടും വിളിച്ചു: "ഓ മുആദുബ്നു ജബൽ!" ഞാൻ ഉത്തരം കൊടുത്തു: ഞാനിതാ റസൂലേ! അങ്ങേക്ക് സൗഭാഗ്യം വരട്ടെ! റസൂൽ ചോദിച്ചു: "അടിമകൾ അത് നിർവ്വഹിച്ചാൽ അവർക്ക് അല്ലാഹുവിൽ നിന്നുള്ള അവകാശമെന്തെന്നറിയുമോ?" ഞാൻ പറഞ്ഞു: അല്ലാഹുവിനും അവന്റെ ദൂതനും അറിയാം. നബി(സ) അരുളി: "അവരെ അവൻ ശിക്ഷിക്കാതിരിക്കലാണത്." (ബു,മു,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 94, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ مَحْمُودِ بْنِ الرَّبِيعِ، عَنْ عِتْبَانَ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدِمْتُ الْمَدِينَةَ فَلَقِيتُ عِتْبَانَ فَقُلْتُ: حَدِيثٌ بَلَغَنِي عَنْكَ ؟ قَالَ: أَصَابَنِي فِي بَصَرِي بَعْضُ الشَّيْءِ، فَبَعَثْتُ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنِّي أُحِبُّ أَنْ تَأْتِيَنِي فَتُصَلِّيَ فِي مَنْزِلِي فَأَتَّخِذَهُ مُصَلًّى، قَالَ: فَأَتَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَنْ شَاءَ اللهُ مِنْ أَصْحَابِهِ فَدَخَلَ وَهُوَ يُصَلِّي فِي مَنْزِلِي وَأَصْحَابُهُ يَتَحَدَّثُونَ بَيْنَهُمْ، ثُمَّ أَسْنَدُوا عُظْمَ ذَلِكَ وَكُبْرَهُ إِلَى مَالِكِ بْنِ دُخْشُمٍ، قَالُوا: وَدُّوا أَنَّهُ دَعَا عَلَيْهِ فَهَلَكَ، وَوَدُّوا أَنَّهُ أَصَابَهُ شَرٌّ، فَقَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ وَقَالَ: "أَلَيْسَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنِّي رَسُولُ اللهِ؟" قَالُوا: إِنَّهُ يَقُولُ ذَلِكَ وَمَا هُوَ فِي قَلْبِهِ، قَالَ: "لَا يَشْهَدُ أَحَدٌ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنِّي رَسُولُ اللهِ فَيَدْخُلَ النَّارَ أَوْ تَطْعَمَهُ". قَالَ أَنَسٌ: فَأَعْجَبَنِي هَذَا الْحَدِيثُ فَقُلْتُ لِابْنِي: اكْتُبْهُ، فَكَتَبَهُ. (م)', 'മഹമൂദ്ബ്നു റബീഅ്(റ): ഞാൻ മദീനയിൽ ചെന്നപ്പോൾ ഇത്ബാനുബ്നു മാലികിനെ കണ്ടു. ഞാൻ ചോദിച്ചു: നിങ്ങളെ ഉദ്ധരിച്ച് ഞാൻ ഒരു ഹദീസ് കേട്ടുവല്ലോ? അദ്ദേഹം പറഞ്ഞു: എനിക്ക് കണ്ണിനെന്തോ പറ്റി. നബി(സ) എന്റെ വീട്ടിൽ വന്ന് നിസ്കരിച്ചുതരാനും അവിടുന്ന് നിസ്കരിച്ച സ്ഥലം തനിക്ക് നിസ്കാരത്തിനായി നിശ്ചയിക്കാനും വേണ്ടി നബി(സ)യുടെ സമീപത്തേക്ക് (ഞാനൊരാളെ) പറഞ്ഞയച്ചു. അങ്ങനെ നബി(സ)യും കുറച്ച് അനുചരരും വീട്ടിലെത്തി. നബി(സ) വീട്ടിൽ കയറി നിസ്കരിച്ചു. സഹാബികൾ പരസ്പരം എന്തൊക്കെയോ സംസാരിക്കുകയാണ്. അതിലധികവും മാലിക് ബ്നു ദുഖ്ശുമിലേക്ക് ചേർത്താണവർ സംസാരിക്കുന്നത്. അവർ പറഞ്ഞു. നബി(സ) അദ്ദേഹത്തിനെതിരിൽ പ്രാർത്ഥിക്കുകയും തദ്വാരാ, അയാൾ നശിക്കുകയും ചെയ്തിരുന്നെങ്കിൽ. അയാൾക്ക് എന്തെങ്കിലും പിണയണമെന്നവർ ആഗ്രഹിച്ചു. നിസ്കാരം നിർവ്വഹിച്ച് കഴിഞ്ഞശേഷം നബി(സ) ചോദിച്ചു. "അദ്ദേഹം അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ് നബി(സ) അല്ലാഹുവിന്റെ ദൂതനാണെന്നും സാക്ഷ്യം വഹിക്കുന്നില്ലേ?" സ്വഹാബികൾ പറഞ്ഞു: ഹൃദയത്തിൽ വിശ്വാസമില്ലാതെ അദ്ദേഹമങ്ങനെ പറയുന്നുണ്ട്. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും ഞാൻ അവന്റെ ദൂതനാണെന്നും സാക്ഷ്യം വഹിച്ചവൻ നരകത്തിൽ പ്രവേശിക്കുകയില്ല." (നരകം അവനെ ഭക്ഷിക്കുകയില്ല). അനസ്(റ) പറഞ്ഞു: ഈ ഹദീസ് എഴുതാൻ ഞാനെന്റെ മകനോട് പറഞ്ഞപ്പോൾ അവൻ എഴുതിവെച്ചു. (മു)', 'مَحْمُودِ بْنِ الرَّبِيعِ، عَنْ عِتْبَانَ بْنِ مَالِكٍ', 'മഹമൂദ്ബ്നു റബീഅ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 95, 95, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُمَا يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ سَيُخَلِّصُ رَجُلًا مِنْ أُمَّتِي عَلَى رُءُوسِ الْخَلَائِقِ يَوْمَ الْقِيَامَةِ، فَيَنْشُرُ عَلَيْهِ تِسْعَةً وَتِسْعِينَ سِجِلًّا، كُلُّ سِجِلٍّ مِثْلُ مَدِّ الْبَصَرِ ثُمَّ يَقُولُ: أَتُنْكِرُ مِنْ هَذَا شَيْئًا؟ أَظَلَمَكَ كَتَبَتِي الْحَافِظُونَ؟ فَيَقُولُ: لَا يَا رَبِّ، فَيَقُولُ: أَفَلَكَ عُذْرٌ؟ فَيَقُولُ: لَا يَا رَبِّ، فَيَقُولُ: بَلَى! إِنَّ لَكَ عِنْدَنَا حَسَنَةً، فَإِنَّهُ لَا ظُلْمَ عَلَيْكَ الْيَوْمَ، فَتَخْرُجُ بِطَاقَةٌ فِيهَا أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. فَيَقُولُ: احْضُرْ وَزْنَكَ فَيَقُولُ: يَا رَبِّ مَا هَذِهِ الْبِطَاقَةُ مَعَ هَذِهِ السِّجِلَّاتِ؟! فَقَالَ: إِنَّكَ لَا تُظْلَمُ، قَالَ: فَتُوضَعُ السِّجِلَّاتُ فِي كَفَّةٍ وَالْبِطَاقَةُ فِي كَفَّةٍ، فَطَاشَتِ السِّجِلَّاتُ وَثَقُلَتِ الْبِطَاقَةُ فَلَا يَثْقُلُ مَعَ اسْمِ اللهِ شَيْءٌ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ന്യായ വിധിനാളിൽ സർവ്വസൃഷ്ടികൾക്കും മുകളിലായി ഒരു മനുഷ്യനെ അല്ലാഹു വേർതിരിച്ചു നിർത്തും. ശേഷം തൊണ്ണൂറ്റി ഒമ്പത് ഗ്രന്ഥങ്ങൾ അവന്ന് നൽകപ്പെടും. ഓരോ ഗ്രന്ഥവും കണ്ണെത്തും ദൂരത്തോളമുണ്ട്. തുടർന്ന് അല്ലാഹു ചോദിക്കും: ഇതിലെന്തെങ്കിലും നിഷേധിക്കുന്നുവോ? സൂക്ഷിപ്പുകാരായ എന്റെ എഴുത്തുകാർ നിന്നോട് അനീതി കാണിച്ചുവോ? അവൻ പറയും: ഇല്ല നാഥാ! അല്ലാഹു ചോദിക്കും: നിനക്കെന്തെങ്കിലും കാരണം ബോധിപ്പിക്കുവാനുണ്ടോ? അവൻ പറയും: ഇല്ല, നാഥാ! അല്ലാഹു പറയും: നമ്മുടെ അടുക്കൽ നിനക്ക് വലിയൊരു നന്മയുണ്ട്. അതിനാൽ ഇന്ന് നിന്നോട് അനീതിയില്ല. ശേഷം അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ലെന്നും മുഹമ്മദ് അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു എന്നെഴുതിയ ഒരു കാർഡ് പുറത്തെടുത്തിട്ട് പറയും. നിന്റെ (നന്മതിന്മകൾ) തൂക്കിക്കണക്കാക്കുന്നതിന് വരൂ. അവൻ പറയും: നാഥാ, ഈ കടലാസു തുണ്ടത്തെ ഈ ഗ്രന്ഥങ്ങളുമായി എന്ത് ചെയ്യുവാനാണ്!. അല്ലാഹു: നീ അനീതിക്കിരയാകില്ല. അങ്ങനെ ഗ്രന്ഥങ്ങൾ ഒരു തട്ടിലും കാർഡ് മറ്റൊരു തട്ടിലും വെക്കും. ഗ്രന്ഥങ്ങൾ ഭാരം കുറയുകയും കാർഡിന് ഭാരം കൂടുകയും ചെയ്യും. അല്ലാഹുവിന്റെ നാമത്തേക്കാൾ ഒന്നും ഭാരമാവുകയില്ല." (തു,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 95, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ سُفْيَانَ بْنِ عَبْدِ اللهِ الثَّقَفِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللهِ! قُلْ لِي فِي الْإِسْلَامِ قَوْلًا، لَا أَسْأَلُ عَنْهُ أَحَدًا بَعْدَكَ – وَفِي حَدِيثِ أَبِي أُسَامَةَ غَيْرَكَ – قَالَ: "قُلْ آمَنْتُ بِاللهِ فَاسْتَقِمْ". (م,ت,جه)', 'സുഫ്‌യാനുബ്നു അബ്ദില്ലാഹിസ്സഖഫി(റ): ഞാൻ നബി(സ)യോട് ചോദിച്ചു: തിരുദൂതരേ, ഇസ്ലാമിൽ എനിക്കിനി ആരോടും ചോദിക്കേണ്ടതില്ലാത്ത ഒരു വാചകം പറഞ്ഞുതരു. നബി(സ) പറഞ്ഞു: "ഞാൻ അല്ലാഹുവിൽ വിശ്വസിച്ചു എന്ന് നീ പ്രഖ്യാപിക്കുക. തുടർന്ന് വിശുദ്ധ ജീവിതം നയിക്കുക." (മു,തു,ജ)', 'سُفْيَانَ بْنِ عَبْدِ اللهِ الثَّقَفِيِّ', 'സുഫ്‌യാനുബ്നു അബ്ദില്ലാഹിസ്സഖഫി(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ النَّاسُ يَتَسَاءَلُونَ حَتَّى يُقَالَ هَذَا خَلَقَ اللهُ الْخَلْقَ، فَمَنْ خَلَقَ اللهَ؟ فَمَنْ وَجَدَ مِنْ ذَلِكَ شَيْئًا فَلْيَقُلْ: آمَنْتُ بِاللهِ". (ق,د)', 'അബൂഹുറൈ: നബി(സ) പറഞ്ഞു: "ഇതൊക്കെ അല്ലാഹു സൃഷ്ടിച്ചു. എന്നാൽ അല്ലാഹുവിനെ സൃഷ്ടിച്ചതാരാണ്? എന്ന് ചർച്ച ചെയ്യപ്പെടുന്നതുവരെ ജനങ്ങൾ ചോദിച്ചുകൊണ്ടേയിരിക്കും. അങ്ങനെ വല്ലതും ആരെങ്കിലും കണ്ടാൽ, ഞാൻ അല്ലാഹുവിൽ വിശ്വസിച്ചിരിക്കുന്നു എന്ന് അവൻ പ്രഖ്യാപിക്കട്ടെ." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈ', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُونَ يَسْأَلُونَكَ يَا أَبَاهُرَيْرَةَ حَتَّى يَقُولُوا هَذَا اللهُ فَمَنْ خَلَقَ اللهَ؟" قَالَ: فَبَيْنَا أَنَا فِي الْمَسْجِدِ إِذْ جَاءَنِي نَاسٌ مِنَ الْأَعْرَابِ فَقَالُوا: يَا أَبَا هُرَيْرَةَ! هَذَا اللهُ، فَمَنْ خَلَقَ اللهَ؟ قَالَ: فَأَخَذَ حَصًى بِكَفِّهِ فَرَمَاهُمْ ثُمَّ قَالَ: قُومُوا، قُومُوا، صَدَقَ خَلِيلِي. (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഓ അബൂ ഹുറൈറൊ, ജനങ്ങൾ നിന്നോട് ചോദിച്ചുകൊണ്ടേയിരിക്കും. അങ്ങനെ അവർ ചോദിക്കും: ഇതൊക്കെ (സൃഷ്ടിച്ചത്) അല്ലാഹുവെങ്കിൽ അല്ലാഹുവിനെ സൃഷ്ടിച്ചതാര്?" അബൂഹുറൈ(റ) പറയുന്നു: (പിന്നീടൊരിക്കൽ) ഞാൻ പള്ളിയിലിരിക്കുമ്പോൾ ഗ്രാമവാസികളിൽപ്പെട്ട ചിലയാളുകൾ വന്ന് ചോദിച്ചു: അബൂഹുറൈറൊ! ഇതാ, അല്ലാഹുവാണ് ഞങ്ങളെ സൃഷ്ടിച്ചത്. എന്നാൽ ആരാണ് അല്ലാഹുവിനെ സൃഷ്ടിച്ചത്? നിവേദകൻ പറയുന്നു: ഉടനെ അബൂഹുറൈറ(റ) ഒരു പിടി മണ്ണെടുത്ത് അവരെ എറിഞ്ഞുകൊണ്ട് പറഞ്ഞു: എഴുന്നേറ്റുപോകൂ, എന്റെ കൂട്ടുകാരൻ (തിരുനബി(സ) സത്യം പറഞ്ഞിരിക്കുന്നു. (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 96, 96, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنَ الْأَنْبِيَاءِ مِنْ نَبِيٍّ إِلَّا قَدْ أُعْطِيَ مِنَ الْآيَاتِ مَا مِثْلُهُ آمَنَ عَلَيْهِ الْبَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَى اللهُ إِلَيَّ، فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ". (ق)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "പൂർവ്വപ്രവാചകരിൽ ഓരോരുത്തർക്കും ജനങ്ങൾ വിശ്വസിക്കും വിധമുള്ള അമാനുഷിക ദൃഷ്ടാന്തങ്ങൾ നൽകപ്പെട്ടിട്ടുണ്ട്. എനിക്ക് നൽകപ്പെട്ടത് അല്ലാഹു നൽകിയ ദിവ്യസന്ദേശ(ഖുർആൻ)മാണ്. അതിനാൽ പുനരുത്ഥാന ദിവസം അവരിൽ വെച്ച് കൂടുതൽ അനുയായികളുള്ളവൻ ഞാനാകണമെന്ന് ഞാനാഗ്രഹിക്കുന്നു." (ബു,മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ! لَا يَسْمَعُ بِي أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ – يَهُودِيٌّ وَلَا نَصْرَانِيٌّ – ثُمَّ يَمُوتُ وَلَمْ يُؤْمِنْ بِالَّذِي أُرْسِلْتُ بِهِ إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹുവാണെ, ഈ സമുദായത്തിൽ ജൂതനും ക്രൈസ്തവനും ഉൾപ്പെടെ വല്ലവനും എന്നെക്കുറിച്ച് കേൾക്കുകയും എനിക്ക് നൽകപ്പെട്ട ദിവ്യസന്ദേശത്തിൽ വിശ്വസിക്കാതിരിക്കുകയും ചെയ്താൽ അവൻ നരക വാസികളിൽ പെടാതിരിക്കില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 97, 97, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنْ صَالِحِ بْنِ صَالِحٍ الْهَمْدَانِيِّ، عَنِ الشَّعْبِيِّ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَجُلًا مِنْ أَهْلِ خُرَاسَانَ سَأَلَ الشَّعْبِيَّ، فَقَالَ: يَا أَبَا عَمْرٍو! إِنَّ مَنْ قِبَلَنَا مِنْ أَهْلِ خُرَاسَانَ يَقُولُونَ فِي الرَّجُلِ إِذَا أَعْتَقَ أَمَتَهُ ثُمَّ تَزَوَّجَهَا فَهُوَ كَالرَّاكِبِ بَدَنَتَهُ، فَقَالَ الشَّعْبِيُّ: حَدَّثَنِي أَبُو بُرْدَةَ بْنُ أَبِي مُوسَى عَنْ أَبِيهِ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلَاثَةٌ يُؤْتَوْنَ أَجْرَهُمْ مَرَّتَيْنِ، رَجُلٌ مِنْ أَهْلِ الْكِتَابِ، آمَنَ بِنَبِيِّهِ وَأَدْرَكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَآمَنَ بِهِ وَاتَّبَعَهُ وَصَدَّقَهُ، فَلَهُ أَجْرَانِ، وَعَبْدٌ مَمْلُوكٌ، أَدَّى حَقَّ اللهِ تَعَالَى وَحَقَّ سَيِّدِهِ، فَلَهُ أَجْرَانِ، وَرَجُلٌ كَانَتْ لَهُ أَمَةٌ، فَغَذَّاهَا فَأَحْسَنَ غِذَاءَهَا، ثُمَّ أَدَّبَهَا فَأَحْسَنَ أَدَبَهَا، ثُمَّ أَعْتَقَهَا وَتَزَوَّجَهَا، فَلَهُ أَجْرَانِ، ثُمَّ قَالَ الشَّعْبِيُّ لِلْخُرَاسَانِيِّ: خُذْ هَذَا الْحَدِيثَ بِغَيْرِ شَيْءٍ فَقَدْ كَانَ الرَّجُلُ يَرْحَلُ فِيمَا دُونَ هَذَا إِلَى الْمَدِينَةِ. (ق,ت,ن,جه)', 'സ്വാലിഹുബ്നുസ്വാലിഹിൽ ഹമദാനി(റ): അദ്ദേഹം ശഅ്ബിയെ ഉദ്ധരിച്ചുകൊണ്ട് പറയുന്നു: ഖുറാസാൻ നിവാസിയായ ഒരാൾ ശഅ്ബിയോടു ഇപ്രകാരം ചോദിക്കുന്നത് ഞാൻ കണ്ടു! ഹേ! അബൂ അംറേ! ഒരാൾ തന്റെ അടിമസ്ത്രീയെ മോചിപ്പിക്കുകയും അനന്തരം അവളെ വിവാഹം കഴിക്കുകയും ചെയ്താൽ, അവൻ സ്വന്തം ഒട്ടകത്തിന്മേൽ സവാരി ചെയ്യുന്നവനെപ്പോലെയാണെന്ന് ഖുറാസാൻകാരിൽ നിന്ന് ഞങ്ങളുടെ ഭാഗത്തുള്ളവർ പറയുന്നു. അപ്പോൾ ശഅ്ബി പറഞ്ഞു: അബൂമൂസയെ ഉദ്ധരിച്ചുകൊണ്ട് അദ്ദേഹത്തിന്റെ മകൻ അബൂബുർദഃ എന്നോട് ഇങ്ങനെ പറഞ്ഞിട്ടുണ്ട്: നബി(സ) അരുളിയിരിക്കുന്നു: "മൂന്നു വിഭാഗം ആളുകൾക്ക് രണ്ട് പ്രതിഫലം നൽകപ്പെടുന്നതാണ്; വേദക്കാരിൽ ഒരാൾ തന്റെ നബിയിൽ വിശ്വസിച്ചു. അനന്തരം നബി(സ)യെക്കുറിച്ച് അറിഞ്ഞപ്പോൾ നബി(സ)യിൽ വിശ്വസിക്കുകയും പിൻപറ്റുകയും അംഗീകരിക്കുകയും ചെയ്താൽ അവന് രണ്ട് പ്രതിഫലം നൽകപ്പെടുന്നതാണ്. അല്ലാഹുവിനോടുള്ള ബാധ്യതകളും യജമാനനോടുള്ള ബാധ്യതകളും നിർവ്വഹിക്കുന്ന അടിമക്കും രണ്ട് പ്രതിഫലമുണ്ട്. ഒരു അടിമസ്ത്രീയുള്ളയാൾ അവൾക്ക് നല്ല നിലയിൽ ആഹാരം നൽകുകയും ശേഷം, വേണ്ടവിധം വിദ്യയും സംസ്കാരവും അഭ്യസിപ്പിക്കുകയും മോചനം നൽകി അവളെ വിവാഹം കഴിക്കുകയും ചെയ്താൽ അവനും രണ്ട് പ്രതിഫലമുണ്ട്." പിന്നീട് ശഅ്ബി, ഖുറാസാൻകാരനോടു പറഞ്ഞു: യാതൊരു പ്രയാസവും കൂടാതെ ഈ ഹദീസ് നീ സ്വീകരിച്ചുകൊള്ളുക. ഇതിനേക്കാൾ നിസ്സാരമായ കാര്യത്തിന് ആളുകൾ മദീനയിലേക്ക് യാത്ര ചെയ്യാറുണ്ടായിരുന്നു. (ബു,മു,തു,ന,ജ)', 'صَالِحِ بْنِ صَالِحٍ الْهَمْدَانِيِّ، عَنِ الشَّعْبِيِّ', 'സ്വാലിഹുബ്നുസ്വാലിഹിൽ ഹമദാനി(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 97, 98, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: سِرْنَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَيْنَ مَكَّةَ وَالْمَدِينَةِ، فَمَرَرْنَا بِوَادٍ، فَقَالَ: "أَيُّ وَادٍ هَذَا". فَقَالُوا: وَادِي الْأَزْرَقِ، فَقَالَ: "كَأَنِّي أَنْظُرُ إِلَى مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَذَكَرَ مِنْ لَوْنِهِ وَشَعَرِهِ شَيْئًا لَمْ يَحْفَظْهُ دَاوُدُ – وَاضِعًا إِصْبَعَيْهِ فِي أُذُنَيْهِ، لَهُ جُؤَارٌ إِلَى اللهِ بِالتَّلْبِيَةِ، مَارًّا بِهَذَا الْوَادِي". قَالَ: ثُمَّ سِرْنَا حَتَّى أَتَيْنَا عَلَى ثَنِيَّةٍ، فَقَالَ: "أَيُّ ثَنِيَّةٍ هَذِهِ". قَالُوا: هَرْشَى أَوْ لِفْتٌ، فَقَالَ: "كَأَنِّي أَنْظُرُ إِلَى يُونُسَ عَلَى نَاقَةٍ حَمْرَاءَ، عَلَيْهِ جُبَّةُ صُوفٍ، خِطَامُ نَاقَتِهِ لِيفٌ خُلْبَةٌ، مَارًّا بِهَذَا الْوَادِي مُلَبِّيًا". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞങ്ങൾ റസൂലി(സ)ന്റെ കൂടെ മക്കയുടെയും മദീനയുടെയും ഇടയ്ക്ക് യാത്ര ചെയ്യുകയായിരുന്നു. അങ്ങനെ ഞങ്ങൾ ഒരു താഴ്വരയിലൂടെ കടന്നുപോയി. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: ഇതേത് താഴ്വരയാണ്. അപ്പോൾ പറഞ്ഞു: ഇതു നീല താഴ്വരയാണ്. അപ്പോൾ പ്രവാചകർ(സ) പറഞ്ഞു: ''ഞാൻ ഇപ്പോൾ മൂസായെ കാണുന്നതായി എനിക്കു തോന്നുന്നു;'' ശേഷം തിരുമേനി(സ) അദ്ദേഹത്തിന്റെ (മൂസ(അ)യുടെ) നിറം, മുടി എന്നിവയെക്കുറിച്ചു പറഞ്ഞു -നിവേദകരിലൊരാളായ ദാവൂദ് അത് ഹൃദിസ്ഥമാക്കിയിട്ടില്ല - അദ്ദേഹം (മൂസാ (അ)) തന്റെ രണ്ട് ചൂണ്ടുവിരലുകൾ തന്റെ ഇരു ചെവികളിൽ വെച്ചുകൊണ്ട് ഉച്ചത്തിൽ തൽബിയത്ത് ചൊല്ലിക്കൊണ്ട് ഈ താഴ്വരയിലൂടെ നടക്കുകയാണ്. അനന്തരം ഞങ്ങൾ നടന്ന് ഒരു മലയിലൂടെയുള്ള ദുർഘടമായ ഒരു വഴിയിലെത്തിപ്പെട്ടു. അപ്പോൾ തിരുമേനി(സ) ചോദിച്ചു: ഇത് ഏത് ദുർഘടമായ പാതായാണ്? അവർ പറഞ്ഞു: ഇത് ''ഹർശ'' മലയിലെ അല്ലെങ്കിൽ ''ലിഫ്ത്'' മലയിലെ ദുർഘട പാടയാണ്. അപ്പോൾ പ്രവാചകർ(സ) പറഞ്ഞു: ''യൂനുസ്(അ) ഒരു രോമത്തിന്റെ ജുബ്ബ ധരിച്ചുകൊണ്ട് ചുവന്ന ഒട്ടകപ്പുറത്ത് ഇരുന്നുകൊണ്ട് ഈ താഴ്വരയിലൂടെ തൽബിയത്ത് ചെല്ലിക്കൊണ്ട് നടക്കുന്നത് ഞാനിപ്പോൾ കാണുന്നതായി എനിക്കു തോന്നുന്നു. അദ്ദേഹത്തിന്റെ ഒട്ടകത്തിന്റെ മൂക്കുകയർ ഈത്തപ്പന നാരിലുള്ളതാണ്. (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 98, 98, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حِينَ أُسْرِيَ بِي لَقِيتُ مُوسَى عَلَيْهِ السَّلَامُ – فَنَعَتَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَإِذَا رَجُلٌ – حَسِبْتُهُ قَالَ – مُضْطَرِبٌ، رَجِلُ الرَّأْسِ، كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ. قَالَ: وَلَقِيتُ عِيسَى – فَنَعَتَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَإِذَا رَبْعَةٌ أَحْمَرُ، كَأَنَّمَا خَرَجَ مِنْ دِيمَاسٍ. يَعْنِي حَمَّامًا. قَالَ: وَرَأَيْتُ إِبْرَاهِيمَ عَلَيْهِ السَّلَامُ، وَأَنَا أَشْبَهُ وَلَدِهِ بِهِ، قَالَ: فَأُتِيتُ بِإِنَاءَيْنِ فِي أَحَدِهِمَا لَبَنٌ وَفِي الْآخَرِ خَمْرٌ، فَقِيلَ لِي: خُذْ أَيَّهُمَا شِئْتَ، فَأَخَذْتُ اللَّبَنَ فَشَرِبْتُهُ، فَقَالَ: هُدِيتَ الْفِطْرَةَ – أَوْ: أَصَبْتَ الْفِطْرَةَ – أَمَا إِنَّكَ لَوْ أَخَذْتَ الْخَمْرَ غَوَتْ أُمَّتُكَ". (م)', 'അബുഹുറൈറ(റ): തിരുമേനി(സ) പറഞ്ഞു: "ഞാൻ നിശായാത്രയിൽ മൂസാ(അ)യെ കണ്ടുമുട്ടി. ശേഷം നബി(സ) മൂസാ(അ)യെക്കുറിച്ച് ഇപ്രകാരം വർണ്ണിച്ചു: -നിവേദകൻ പറയുന്നു: തിരുമേനി ഇപ്രകാരമാണ് (മൂസായെക്കുറിച്ച്) വിവരിച്ചത് എന്ന് ഞാൻ വിചാരിക്കുന്നു - ''അപ്പോഴതാ നീണ്ടു മെലിഞ്ഞൊട്ടിയ ഒരാൾ നിൽക്കുന്നു. ചുരുണ്ടതോ നീണ്ടതോ അല്ലാത്ത മുടിയുള്ളയാൾ, അദ്ദേഹത്തെ കണ്ടാൽ ശനൂഅ വംശത്തിൽപ്പെട്ട പുരുഷന്മാരെപ്പോലെയുണ്ട്.'' നബി(സ) തുടർന്നു പറഞ്ഞു: അനന്തരം ഞാൻ ഈസാ(അ)യെ കണ്ടു. -നബി(സ) അദ്ദേഹത്തെ വർണ്ണിച്ചു കൊണ്ടു പറഞ്ഞു: - അവിടെയതാ ഒത്ത ശരീരമുള്ള ചുകപ്പു (കലർന്ന) നിറമുള്ള ഒരു മനുഷ്യൻ അദ്ദേഹം അറയിൽ നിന്നും - അതായത് കുളിപ്പുരയിൽനിന്നും - പറത്തു വരുന്നവനെപ്പോലെയുണ്ട്.'' നബി(സ) തുടർന്നു പറഞ്ഞു: ''ഞാൻ ഇബ്റാഹീമി(അ)നെ കണ്ടു. ഞാൻ അദ്ദേഹത്തോടു ഏറ്റവും സദൃശനായ അദ്ദേഹത്തിന്റെ സന്തതിയാണ്; അനന്തരം എനിക്കു രണ്ടു പാനപാത്രങ്ങൾ നൽകപ്പെട്ടു. അവയിൽ ഒരെണ്ണത്തിൽ പാലും മറ്റേതിൽ മദ്യവുമായിരുന്നു. എന്നിട്ട് എന്നോട് പറയപ്പെട്ടു: ''ഇവ രണ്ടിൽ താങ്കൾ ഉദ്ദേശിക്കുന്നത് എടുത്തുകൊള്ളുക''. അപ്പോൾ ഞാൻ പാൽ എടുക്കുകയും അതു കുടിക്കുകയും ചെയ്തു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''താങ്കൾ ശുദ്ധപ്രകൃതിയിലേക്ക് നയിക്കപ്പെട്ടിരിക്കുന്നു. -താങ്കൾ ശുദ്ധപ്രകൃതിയിലായിരിക്കുന്നു- താങ്കൾ മദ്യമാണ് സ്വീകരിച്ചിരുന്നത് എങ്കിൽ താങ്കളുടെ സമുദായം വഴിപിഴച്ചു പോകുമായിരുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 98, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: ذَكَرَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بَيْنَ ظَهْرَانَيِ النَّاسِ الْمَسِيحَ الدَّجَّالَ فَقَالَ: "إِنَّ اللهَ تَبَارَكَ وَتَعَالَى لَيْسَ بِأَعْوَرَ، أَلَا، إِنَّ الْمَسِيحَ الدَّجَّالَ أَعْوَرُ عَيْنِ الْيُمْنَى، كَأَنَّ عَيْنَهُ عِنَبَةٌ طَافِيَةٌ". قَالَ: وَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَرَانِي اللَّيْلَةَ فِي الْمَنَامِ عِنْدَ الْكَعْبَةِ، فَإِذَا رَجُلٌ آدَمُ كَأَحْسَنِ مَا تَرَى مِنْ أُدْمِ الرِّجَالِ، تَضْرِبُ لِمَّتُهُ بَيْنَ مَنْكِبَيْهِ، رَجِلُ الشَّعْرِ، يَقْطُرُ رَأْسُهُ مَاءً، وَاضِعًا يَدَيْهِ عَلَى مَنْكِبَيْ رَجُلَيْنِ، وَهُوَ بَيْنَهُمَا يَطُوفُ بِالْبَيْتِ، فَقُلْتُ: مَنْ هَذَا؟ فَقَالُوا: الْمَسِيحُ ابْنُ مَرْيَمَ. وَرَأَيْتُ وَرَاءَهُ رَجُلًا جَعْدًا قَطَطًا، أَعْوَرَ عَيْنِ الْيُمْنَى، كَأَشْبَهِ مَنْ رَأَيْتُ مِنَ النَّاسِ بِابْنِ قَطَنٍ، وَاضِعًا يَدَيْهِ عَلَى مَنْكِبَيْ رَجُلَيْنِ، يَطُوفُ بِالْبَيْتِ، فَقُلْتُ: مَنْ هَذَا؟ قَالُوا: هَذَا الْمَسِيحُ الدَّجَّالُ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): പ്രവാചകർ(സ) ഒരിക്കൽ ജനങ്ങൾക്കു മധ്യേവെച്ച് മസിഹ് ദജ്ജാലിനെക്കുറിച്ച് ഇപ്രകാരം പറഞ്ഞു: നിശ്ചയം അത്യുന്നതനും അനുഗ്രഹദാതാവുമായ അല്ലാഹു കോങ്കണ്ണുള്ളവനുമല്ല. എന്നാൽ മസിഹ് ദജ്ജാലിന്റെ വലതു കണ്ണ് കോങ്കണ്ണാണ്. അവന്റെ കണ്ണ് പൊന്തി നിൽക്കുന്ന മുന്തിരി പോലുള്ളതാണ്. പ്രവാചകർ(സ) തുടർന്നു പറഞ്ഞു: ഒരു രാത്രിയിൽ ഞാൻ സ്വപ്നത്തിൽ എന്നെ കഅ്ബയുടെ അടുത്തുകണ്ടു. അപ്പോഴതാ അവിടെ അതീവ സുന്ദരനായ ഒരാൾ. അയാൾ തന്റെ മുടി ഇരുചുമലുകൾക്കിടയിലൂടെ താഴ്ത്തിയിട്ടിട്ടുണ്ട് മുടി ചീകിയിട്ടുണ്ട്. തലയിൽ നിന്നും വെള്ളം ഇറ്റി വീഴുന്നുണ്ട്. അദ്ദേഹം രണ്ടു പേർക്കിടയിലായി അവരുടെ ചുമലുകളിൽ കൈകളൂന്നികൊണ്ട് കഅ്ബയെ പ്രദക്ഷിണം ചെയ്യുകയാണ്. അപ്പോൾ ഞാൻ ചോദിച്ചു. ഇതാരാണ്? അവർ പറഞ്ഞു: ഇത് മർയമിന്റെ മകൻ മസീഹാകുന്നു. അതിനു പുറകിലായി നീളം കുറഞ്ഞതും ചുരുണ്ടതുമായ മുടിയുള്ള കുറിയ ഒരാളെ ഞാൻ കണ്ടു. അവന്റെ കണ്ണ് കോങ്കണ്ണാണ്. ജനങ്ങളിൽ വെച്ച് ഇബ്നുഖതാദിനോട് ഏറ്റവും സദൃശ്യനാണവൻ. അദ്ദേഹം തന്റെ കൈ രണ്ടു പേരുടെ ചുമലുകളിലായി വെച്ചുകൊണ്ട് കഅ്ബയെ പ്രദക്ഷിണം വെക്കുകയാണ്. അപ്പോൾ ഞാൻ ചോദിച്ചു: ഇതാരാണ്. അവർ പറഞ്ഞു: ഇത് മസീഹുദ്ദജ്ജാലാണ്. (മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْإِيمَانُ بِضْعٌ وَسَبْعُونَ – بِضْعٌ وَسِتُّونَ – شُعْبَةً، فَأَفْضَلُهَا قَوْلُ لَا إِلَهَ إِلَّا اللهُ، وَأَدْنَاهَا إِمَاطَةُ الْأَذَى عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ". (ق,د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സത്യവിശ്വാസം എഴുപതിൽപ്പരം -അറുപതിൽപരം- ശാഖകളാണ്. അവയിൽ ഏറ്റവും ശ്രേഷ്ഠം ''ലാഇലാഹ ഇല്ലല്ലാഹു'' (അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല) എന്നവചനവും അവയിൽ ഏറ്റവും താഴ്ന്ന പടിയിലുള്ളത് വഴിയിൽ നിന്ന് ഉപദ്രവം നീക്കലുമാണ്. ലജ്ജ സത്യവിശ്വാസത്തിന്റെ ഒരു ശാഖയാണ്." (ബു,മു,തു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','തു','ദ','ന']::text[], null, null, 99, 99, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَى رَجُلٍ مِنَ الْأَنْصَارِ، وَهُوَ يَعِظُ أَخَاهُ فِي الْحَيَاءِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "دَعْهُ! فَإِنَّ الْحَيَاءَ مِنَ الْإِيمَانِ". (ق,د,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) അൻസ്വാരികളിൽപ്പെട്ട ഒരാളുടെ അരികിലൂടെ നടന്നുപോയി. അദ്ദേഹം തന്റെ സഹോദരനെ ലജ്ജയെക്കുറിച്ച് ഗുണദോഷിക്കുകയായിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അവനെ വിട്ടേക്കുക. കാരണം നിശ്ചയം, ലജ്ജ സത്യവിശ്വാസത്തിന്റെ ഒരു ശാഖയാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 99, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا عِنْدَ عِمْرَانَ بْنِ حُصَيْنٍ فِي رَهْطٍ مِنَّا وَفِينَا بُشَيْرُ بْنُ كَعْبٍ فَحَدَّثَنَا عِمْرَانُ يَوْمَئِذٍ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْحَيَاءُ خَيْرٌ كُلُّهُ" – قَالَ أَوْ قَالَ الْحَيَاءُ كُلُّهُ خَيْرٌ – فَقَالَ بُشَيْرُ بْنُ كَعْبٍ: إِنَّا لَنَجِدُ فِي بَعْضِ الْكُتُبِ – أَوِ الْحِكْمَةِ – أَنَّ مِنْهُ سَكِينَةً، وَوَقَارًا لِلَّهِ، وَمِنْهُ ضَعْفٌ، قَالَ: فَغَضِبَ عِمْرَانُ حَتَّى احْمَرَّتَا عَيْنَاهُ، وَقَالَ: أَلَا أَرَانِي أُحَدِّثُكَ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَتُعَارِضُ فِيهِ، قَالَ: فَأَعَادَ عِمْرَانُ الْحَدِيثَ، قَالَ: فَأَعَادَ بُشَيْرٌ، فَغَضِبَ عِمْرَانُ، قَالَ: فَمَا زِلْنَا نَقُولُ فِيهِ: إِنَّهُ مِنَّا يَا أَبَا نُجَيْدٍ! إِنَّهُ لَا بَأْسَ بِهِ. (ق,د)', 'അബുഖതാദഃ(റ): ഒരിക്കൽ ഞങ്ങളൊരു സംഘലം ഇംറാനുബ്നു ഹുസൈ്വനിന്റെ അടുക്കൽ ഇരിക്കുകയായിരുന്നു. ഞങ്ങളോടൊപ്പം ബുശൈറുബ്നു കഅ്ബും ഉണ്ടായിരുന്നു. അപ്പോൾ ഇംറാൻ ഞങ്ങളോടു പറഞ്ഞു. നബി(സ) ഇപ്രകാരം അരുളിയിട്ടുണ്ട്: "ലജ്ജ പൂർണ്ണമായും നന്മയാണ്." അല്ലെങ്കിൽ ലജ്ജ മുഴുവൻ നന്മയാണ്. അപ്പോൾ ബുശൈറുബ്നു കഅ്ബ് പറഞ്ഞു: ഒതുക്കം, അല്ലാഹുവിന്റെ മഹത്വത്തോടുള്ള ആദരവ്, ബലഹീനത, എന്നിവയെല്ലാം അതിൽപ്പെട്ടതാണെന്ന് ചില ഗ്രന്ഥങ്ങളിലും തത്വശാസ്ത്രങ്ങളിലും നാം കാണുന്നുവല്ലോ. അപ്പോൾ ഇംറാന് കോപം വന്നു. അദ്ദേഹത്തിന്റെ കണ്ണുകൾ ചുവന്നുതുടുത്തു. ഞാൻ നിന്നോട് നബി(സ)യുടെ ഹദീസ് വിവരിക്കുമ്പോൾ നീ അതിൽ സംശയം പ്രകടിപ്പിക്കുകയോ? തുടർന്ന് ഇംറാൻ ആ ഹദീസ് ആവർത്തിച്ചു. ഉടനെ ബുശൈറും ആവർത്തിച്ചു. അപ്പോൾ (വീണ്ടും) ഇംറാന് കോപം വന്നു. അപ്പോൾ; ''ഹേ! അബൂ നുജൈദേ! അവൻ നമ്മിൽപ്പെട്ടവൻ തന്നെയാണ്. അവൻ പറയുന്നതിൽ കുഴപ്പമൊന്നുമില്ല'' എന്നു ഞങ്ങൾ പറഞ്ഞുകൊണ്ടിരുന്നു. (ബു,മു,ദ)', 'أَبِي قَتَادَةَ', 'അബുഖതാദഃ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "آيَةُ الْإِيمَانِ حُبُّ الْأَنْصَارِ، وَآيَةُ النِّفَاقِ بُغْضُ الْأَنْصَارِ". (ق,ن)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "അൻസ്വാരികളോടുള്ള സ്നേഹം സത്യവിശ്വാസത്തിന്റെയും അൻസ്വാരികളോടുള്ള കോപം കാപട്യത്തിന്റെയും അടയാളമാകുന്നു." (ബു,മു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ن']::text[], array['ബു','മു','ന']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ فِي الْأَنْصَارِ: "لَا يُحِبُّهُمْ إِلَّا مُؤْمِنٌ، وَلَا يُبْغِضُهُمْ إِلَّا مُنَافِقٌ، مَنْ أَحَبَّهُمْ أَحَبَّهُ اللهُ، وَمَنْ أَبْغَضَهُمْ أَبْغَضَهُ اللهُ". (ق,ت,جه)', 'ബറാഅ്(റ): നബി(സ) അൻസാരികളെക്കുറിച്ചു പറഞ്ഞു: "സത്യവിശ്വാസിയല്ലാതെ അവരെ സ്നേഹിക്കുകയില്ല. കപട വിശ്വാസിയല്ലാതെ അവരെ വെറുക്കുകയുമില്ല. അവരെ സ്നേഹിക്കുന്നവനെ അല്ലാഹു സ്നേഹിക്കുകയും അവരെ വെറുക്കുന്നനെ അല്ലാഹു വെറുക്കുകയും ചെയ്യും." (ബു,മു,തു,ജ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ زِرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ: إِنَّهُ لَعَهْدُ النَّبِيِّ الْأُمِّيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَيَّ أَنَّهُ: "لَا يُحِبُّكَ إِلَّا مُؤْمِنٌ، وَلَا يُبْغِضُكَ إِلَّا مُنَافِقٌ". (م,ت,ن,جه)', 'സിർറ്(റ): അലി(റ) പറഞ്ഞു: നിരക്ഷരനായ നബി(സ) എന്നോട് ഉറപ്പിച്ചു (കരാർ ചെയ്ത്) പറഞ്ഞു: "സത്യവിശ്വാസിയല്ലാതെ നിന്നെ സ്നേഹിക്കുകയില്ല. കപടവിശ്വാസിയല്ലാതെ നിന്നെ വെറുക്കുകയില്ല." (മു,തു,ന,ജ)', 'زِرٍّ', 'സിർറ്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 100, 100, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ، وَمَنْ قَامَ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ق,د,ت,ن)', 'അബൂഹറൈറ(റ): പ്രവാചകനരുളി. ''വിശ്വാസത്തോടും പ്രതിഫലേച്ഛയോടും കൂടി ആരെങ്കിലും റമദാനിൽ നിസ്കരിച്ചാൽ അവന് മുൻപാപങ്ങൾ പൊറുക്കപ്പെടുന്നതാണ്. വിശ്വാസത്തോടെയും പ്രതിഫലം കാംക്ഷിച്ചുകൊണ്ടും ലൈലത്തുൽ ഖദ്റിൽ ആരെങ്കിലും നിസ്കരിച്ചാൽ മുമ്പ് ചെയ്ത പാപങ്ങൾ അവന് പൊറുക്കപ്പെടുന്നതാണ്.'' (ബു,മു,ദ,തുന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹറൈറ(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തുന']::text[], null, null, 100, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വിശ്വാസത്തോടും പ്രതിഫലം കാംക്ഷിച്ചു കൊണ്ടും ആരെങ്കിലും റമദാനിൽ വ്രതമനുഷ്ഠിച്ചാൽ മുമ്പ് ചെയ്ത പാപങ്ങൾ അവന് പൊറുക്കപ്പെടുന്നതാണ്.''(ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنِ اتَّبَعَ جَنَازَةَ مُسْلِمٍ إِيمَانًا وَاحْتِسَابًا، وَكَانَ مَعَهُ حَتَّى يُصَلَّى عَلَيْهَا وَيُفْرَغَ مِنْ دَفْنِهَا، فَإِنَّهُ يَرْجِعُ مِنَ الْأَجْرِ بِقِيرَاطَيْنِ، كُلُّ قِيرَاطٍ مِثْلُ أُحُدٍ، وَمَنْ صَلَّى عَلَيْهَا ثُمَّ رَجَعَ قَبْلَ أَنْ تُدْفَنَ، فَإِنَّهُ يَرْجِعُ بِقِيرَاطٍ". (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: " വിശ്വാസത്തോടെയും പ്രതിഫലേച്ഛയോടെയും ആരെങ്കിലും ഒരു മുസ്ലിമിന്റെ മയ്യിത്തിനെ അനുഗമിക്കുകയും നിസ്കാരവും സംസ്കരണവും കഴിയുന്നതുവരെ കൂടെയുണ്ടാകുകയും ചെയ്താൽ, അയാൾ രണ്ട് ഖീറാത്ത് പ്രതിഫലവും കൊണ്ടായിരിക്കും തിരിച്ചു വരുന്നത്. ഓരോ ഖീറാത്തും ഉഹ്ദ് മലയോളമുള്ളതായിരിക്കും. എന്നാൽ നിസ്കരിച്ചശേഷം സംസ്കരണത്തിനു മുമ്പായി മടങ്ങുന്നവൻ ഒരു ഖീറാത്ത് പ്രതിഫലം കൊണ്ടാണ് തിരിച്ചുവരുന്നത്."¹ (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '¹ പൗരാണിക കാലത്തുപയോഗിച്ചിരുന്ന ഒരു നിശ്ചിത തൂക്കത്തിന്റെ പേരാണ് ഖീറാത്ത്. അത് എത്രയാണെന്നതിൽ പണ്ഡിതന്മാർക്കിടയിൽ അഭിപ്രായ വ്യത്യാസമുണ്ട്. ഈ ഹദീസിൽ ഖീറാത്ത് കൊണ്ടുദ്ദേശിക്കുന്നത് ഭീമമായ പ്രതിഫലമെന്നാണ്. ഉഹ്ദ് മലയോളം എന്ന വിശദീകരണത്തിൽ നിന്ന് അതിന്റെ വ്യാപ്തി ഊഹിക്കാം.', null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ طَارِقِ بْنِ شِهَابٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَوَّلُ مَنْ بَدَأَ بِالْخُطْبَةِ يَوْمَ الْعِيدِ قَبْلَ الصَّلَاةِ مَرْوَانُ، فَقَامَ إِلَيْهِ رَجُلٌ، فَقَالَ: الصَّلَاةُ قَبْلَ الْخُطْبَةِ، فَقَالَ: قَدْ تُرِكَ مَا هُنَالِكَ، فَقَالَ أَبُو سَعِيدٍ: أَمَّا هَذَا فَقَدْ قَضَى مَا عَلَيْهِ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ رَأَى مِنْكُمْ مُنْكَرًا فَلْيُغَيِّرْهُ بِيَدِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِلِسَانِهِ، فَإِنْ لَمْ يَسْتَطِعْ فَبِقَلْبِهِ، وَذَلِكَ أَضْعَفُ الْإِيمَانِ". (م,د,ت,ن,جه)', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ): പെരുന്നാൾ ദിവസം നിസ്കാരത്തിനു മുമ്പായി ഖുതുബ നിർവ്വഹിക്കൽ ആദ്യമായി ആരംഭിച്ചത് മർവാനാണ്.² (ഖുതുബ നിർവ്വഹിക്കവെ) ഒരാൾ എഴുന്നേറ്റ് നിന്നു പറഞ്ഞു: നിസ്കാരം ഖുതുബക്കു മുമ്പാണ്. മർവാൻ പറഞ്ഞു: ആ അവസ്ഥ ഉപേക്ഷിക്കപ്പെട്ടിരിക്കുന്നു. അപ്പോൾ അബൂസഈദ്(റ) പറഞ്ഞു: ഇദ്ദേഹം (എഴുന്നേറ്റ വ്യക്തി) തന്റെ ബാധ്യത നിർവ്വഹിച്ചിരിക്കുന്നു. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിങ്ങളിലാരെങ്കിലും വല്ല തെറ്റും കണ്ടാൽ തന്റെ കൈ കൊണ്ട് അത് തടത്തു കൊള്ളട്ടെ. അതിനവന് സാധിച്ചില്ലെങ്കിൽ തന്റെ നാവ് കൊണ്ട് തടയണം. അതിനുമവന് സാധിച്ചില്ലെങ്കിൽ തന്റെ ഹൃദയം കൊണ്ടെങ്കിലും (തടഞ്ഞുകൊള്ളട്ടെ). അത് (ഹൃദയം കൊണ്ട് വെറുക്കൽ) സത്യവിശ്വാസത്തിന്റെ ഏറ്റവും ബലഹീനമായ അവസ്ഥയാണ്." (മു,ദ,തു,ന,ജ)', 'طَارِقِ بْنِ شِهَابٍ', 'ത്വാരിഖുബ്നു ശിഹാബ്(റ)', '² പെരുന്നാൾ നിസ്കാരശേഷം ഖുതുബ നിർവ്വഹിക്കലാണ് സുന്നത്ത്. നിസ്കാരത്തിനു മുൻപേക്കു മാറ്റുക മുഖേന മർവാൻ മതവിഷയത്തിൽ തിരുചര്യക്കു വിരുദ്ധമായ പരിഷ്കരണം (ബിദ്അത്ത്) നടപ്പിലാക്കാൻ ശ്രമിക്കുകയായിരുന്നു. ഇതിനെതിരെ പ്രതികരിക്കുകയാണ് അബൂസഈദ്(റ).', null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 101, 101, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا رَأَيْتُمُ الرَّجُلَ يَتَعَاهَدُ الْمَسْجِدَ فَاشْهَدُوا لَهُ بِالْإِيمَانِ، فَإِنَّ اللهَ تَعَالَى يَقُولُ {إِنَّمَا يَعْمُرُ مَسَاجِدَ اللهِ مَنْ آمَنَ بِاللهِ وَالْيَوْمِ الْآخِرِ وَأَقَامَ الصَّلَاةَ وَآتَى الزَّكَاةَ} الْآيَةَ. [التوبة: ١٨] (ت)', 'അബൂസഈദ്(റ): നബി(സ) അരുളി: "പള്ളിയിൽ പവിത്രത കാത്തുസൂക്ഷിക്കുന്ന ഒരാളെ നിങ്ങൾ കണ്ടാൽ അവന് സത്യവിശ്വാസം കൊണ്ട് നിങ്ങൾ സാക്ഷ്യം വഹിക്കുക. കാരണം നിശ്ചയം അല്ലാഹു പറയുന്നു: അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുകയും നിസ്കാരം മുറപ്രകാരം അനുഷ്ഠിക്കുകയും സകാത്ത് (നിർബന്ധദാനം) നൽകുകയും ചെയ്യുന്നവർ മാത്രമാണ് അല്ലാഹുവിന്റെ പള്ളികളെ പരിപാലിക്കേണ്ടത്." (അത്തൗബ:18). (തു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['ت']::text[], array['തു']::text[], 'التوبة: ١٨', null, 101, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الْعَمَلِ أَفْضَلُ؟ فَقَالَ: "إِيمَانٌ بِاللهِ وَرَسُولِهِ" قِيلَ: ثُمَّ مَاذَا؟ قَالَ "الْجِهَادُ فِي سَبِيلِ اللهِ" قِيلَ: ثُمَّ مَاذَا؟ قَالَ "حَجٌّ مَبْرُورٌ". (ق,ت,ن)', 'അബൂഹുറൈറ(റ): കർമ്മത്തിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് ഏതെന്ന് നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിലും അവന്റെ ദൂതനിലും വിശ്വസിക്കൽ." അപ്പോൾ ചോദിക്കപ്പെട്ടു: പിന്നെ ഏതാണ്? നബി(സ) പറഞ്ഞു: "ദൈവിക മാർഗ്ഗത്തിലെ ധർമ്മസമരം" അപ്പോൾ ചോദിക്കപ്പെട്ടു: പിന്നെ ഏതാണ്? നബി(സ) പറഞ്ഞു: "പരിശുദ്ധ ഹജ്ജ് കർമ്മം." (ബു,മു,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ يَا رَسُولَ اللهِ! أَيُّ الْأَعْمَالِ أَفْضَلُ؟ قَالَ "الْإِيمَانُ بِاللهِ، وَالْجِهَادُ فِي سَبِيلِهِ". قَالَ: قُلْتُ: أَيُّ الرِّقَابِ أَفْضَلُ؟ قَالَ: "أَنْفَسُهَا عِنْدَ أَهْلِهَا وَأَكْثَرُهَا ثَمَنًا". قَالَ: قُلْتُ: فَإِنْ لَمْ أَفْعَلْ؟ قَالَ: "تُعِينُ صَانِعًا أَوْ تَصْنَعُ لِأَخْرَقَ". قَالَ: قُلْتُ: يَا رَسُولَ اللهِ! أَرَأَيْتَ إِنْ ضَعُفْتُ عَنْ بَعْضِ الْعَمَلِ؟ قَالَ: "تَكُفُّ شَرَّكَ عَنِ النَّاسِ، فَإِنَّهَا صَدَقَةٌ مِنْكَ عَلَى نَفْسِكَ". (ق)', 'അബൂദർറ്(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ! കർമ്മങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് ഏത്? തിരുമേനി പറഞ്ഞു: "അല്ലാഹുവിൽ വിശ്വസിക്കലും അവന്റെ മാർഗത്തിൽ സമരം ചെയ്യലും." ഞാൻ ചോദിച്ചു: അടിമത്ത മോചനത്തിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് ഏത്? നബി(സ) പറഞ്ഞു: "യജമാനന് ഏറ്റവും മൂല്യമുള്ളതും കൂടുതൽ വിലയുള്ളതും." (അദ്ദേഹം പറഞ്ഞു) ഞാൻ പറഞ്ഞു: എനിക്കത് ചെയ്യാനായില്ലെങ്കിൽ? നബി(സ) പറഞ്ഞു: "ജോലി ചെയ്യുന്നവനെ നീ സഹായിക്കുക; അല്ലെങ്കിൽ, ജോലി ചെയ്യാൻ കഴിയാത്തവന് ജോലി ചെയ്തുകൊടുക്കുക." ഞാൻ ചോദിച്ചു: എനിക്കൊരു ജോലിക്കും സാധ്യമല്ലെങ്കിലോ? നബി(സ) പറഞ്ഞു: "ജനങ്ങളെ ഉപദ്രവിക്കാതിരിക്കുക. നിശ്ചയം, അത് നീ നിന്നോട് ചെയ്യുന്ന ധർമ്മമാണ്." (ബു,മു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَبْدِ اللهِ بْنِ حُبْشِيٍّ الْخَثْعَمِيِّ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ سُئِلَ: أَيُّ الْأَعْمَالِ أَفْضَلُ؟ فَقَالَ: "إِيمَانٌ لَا شَكَّ فِيهِ، وَجِهَادٌ لَا غُلُولَ فِيهِ، وَحَجَّةٌ مَبْرُورَةٌ". (ن)', 'അബ്ദുല്ലാഹിബ്നു ഹുബ്ശിയ്യിൽ ഖസ്അമി(റ): ഒരാൾ നബി(സ)യോട് ചോദിച്ചു: കർമ്മങ്ങളിൽ ഏറ്റവും ശ്രേഷ്ഠമായത് ഏത്? നബി(സ) പറഞ്ഞു: "സംശയരഹിതമായ വിശ്വാസവും, വഞ്ചനയില്ലാത്ത സമരവും, പരിശുദ്ധമായ ഹജ്ജും." (ന)', 'عَبْدِ اللهِ بْنِ حُبْشِيٍّ الْخَثْعَمِيِّ', 'അബ്ദുല്ലാഹിബ്നു ഹുബ്ശിയ്യിൽ ഖസ്അമി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 102, 102, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَأَصْبَحْتُ يَوْمًا قَرِيبًا مِنْهُ وَنَحْنُ نَسِيرُ، فَقُلْتُ: يَا رَسُولَ اللهِ ! أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ وَيُبَاعِدُنِي عَنِ النَّارِ قَالَ: "لَقَدْ سَأَلْتَنِي عَنْ عَظِيمٍ، وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللهُ عَلَيْهِ؛ تَعْبُدُ اللهَ وَلَا تُشْرِكْ بِهِ شَيْئًا، وَتُقِيمُ الصَّلَاةَ، وَتُؤْتِي الزَّكَاةَ، وَتَصُومُ رَمَضَانَ، وَتَحُجُّ الْبَيْتَ". ثُمَّ قَالَ: "أَلَا أَدُلُّكَ عَلَى أَبْوَابِ الْخَيْرِ؟ الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ، وَصَلَاةُ الرَّجُلِ مِنْ جَوْفِ اللَّيْلِ". قَالَ: ثُمَّ تَلَا {تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ} حَتَّى بَلَغَ {يَعْمَلُونَ} [السجدة:١٦، ١٧] ثُمَّ قَالَ: "أَلَا أُخْبِرُكَ بِرَأْسِ الْأَمْرِ كُلِّهِ وَعَمُودِهِ وَذِرْوَةِ سَنَامِهِ؟" قُلْتُ: بَلَى يَا رَسُولَ اللهِ! قَالَ: "رَأْسُ الْأَمْرِ الْإِسْلَامُ، وَعَمُودُهُ الصَّلَاةُ، وَذِرْوَةُ سَنَامِهِ الْجِهَادُ". ثُمَّ قَالَ: "أَلَا أُخْبِرُكَ بِمِلَاكِ ذَلِكَ كُلِّهِ؟" قُلْتُ: بَلَى يَا نَبِيَّ اللهِ! فَأَخَذَ بِلِسَانِهِ قَالَ: "كُفَّ عَلَيْكَ هَذَا" فَقُلْتُ: يَا نَبِيَّ اللهِ! وَإِنَّا لَمُؤَاخَذُونَ بِمَا نَتَكَلَّمُ بِهِ، فَقَالَ: "ثَكِلَتْكَ أُمُّكَ يَا مُعَاذُ! وَهَلْ يَكُبُّ النَّاسَ فِي النَّارِ عَلَى وُجُوهِهِمْ – أَوْ عَلَى مَنَاخِرِهِمْ – إِلَّا حَصَائِدُ أَلْسِنَتِهِمْ". (ت,جه)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ)യോടൊപ്പം ഞാനൊരു യാത്ര ചെയ്തു. ഞങ്ങൾ സഞ്ചരിച്ചുകൊണ്ടിരിക്കെ, ഒരു ദിവസം നബി(സ)യുടെ സമീപത്തായപ്പോൾ ഞാൻ ചോദിച്ചു: നബിയെ! സ്വർഗ്ഗത്തിലെന്നെ പ്രവേശിപ്പിക്കുകയും, നരകത്തിൽ നിന്ന് എന്നെ അകറ്റുകയും ചെയ്യുന്ന കർമ്മം അങ്ങെനിക്ക് പറഞ്ഞുതന്നാലും. അവിടുന്നു പ്രത്യുത്തരം നൽകി: "വലിയ കാര്യത്തെക്കുറിച്ചാണ് നീ ചോദിച്ചത്. അല്ലാഹു എളുപ്പമാക്കി കൊടുത്തവർക്ക് അത് ലളിതമാണ്. അല്ലാഹുവിനെ ആരാധിക്കുക, ഒരു വസ്തുവിനെയും അവനോട് പങ്കുചേർക്കാതിരിക്കുക, മുറപ്രകാരം നിസ്കരിക്കുക, സകാത്ത് (നിർബന്ധദാനം) കൊടുക്കുക. റമദാനിൽ വ്രതമനുഷ്ഠിക്കുക, ഹജ്ജ് കർമ്മം നിർവ്വഹിക്കുക എന്നിവയാണത്." പിന്നെ നബി(സ) ചോദിച്ചു: "നന്മയുടെ കവാടങ്ങളെക്കുറിച്ച് നിനക്ക് അറിയിച്ചു തരട്ടെയോ? നോമ്പ് പരിചയാണ്, വെള്ളം അഗ്നിയെ കെടുത്തുന്നതുപോലെ ധർമ്മവും അർദ്ധരാത്രിയിലുള്ള നിസ്കാരവും പാപത്തെ കെടുത്തിക്കളയും." നിവേദകൻ പറയുന്നു: തുടർന്ന് പ്രവാചകൻ രാത്രി നിസ്കാരം പ്രോത്സാഹിപ്പിക്കുന്ന സൂറത്തുസ്സജദയിലെ പതിനാറ് പതിനേഴ് സൂക്തങ്ങൾ ഓതി. ശേഷം ചോദിച്ചു: "കാര്യങ്ങളുടെ ശിരസ്സും തൂണും അതിന്റെ ഉച്ചിയും ഞാൻ നിനക്ക് അറിയിച്ചു തരട്ടെയോ?" ഞാൻ പറഞ്ഞു: അതെ നബിയേ. നബി(സ) അരുളി: "കാര്യങ്ങളുടെ ശിരസ്സ് ഇസ്ലാമാണ്. തൂണ് നിസ്കാരമാണ്, ഉച്ചി ജിഹാദാണ് (ദൈവമാർഗ്ഗത്തിലുള്ള പ്രയത്നങ്ങൾ)." അനന്തരം നബി(സ) ചോദിച്ചു: "അവയുടെയെല്ലാം താങ്ങ് (കേന്ദ്രം) ഞാൻ പറഞ്ഞു തരട്ടെയോ?" ഞാൻ പറഞ്ഞു: അതെ നബിയെ! തത്സമയം നബി(സ) തന്റെ നാവ് പിടിച്ചുകൊണ്ട് പറഞ്ഞു: "നീ ഇതിനെ സൂക്ഷിക്കുക." ഞാൻ ചോദിച്ചു: ഞങ്ങളുടെ സംസാരം നിമിത്തം ഞങ്ങൾ ശിക്ഷിക്കപ്പെടുമോ? പ്രവാചകനരുളി: "(പരിതാപകരം!) ജനങ്ങളെ നരകത്തിൽ മുഖം (മൂക്ക്) കുത്തി വീഴ്ത്തുന്നത് നാവ് കൊയ്തെടുക്കുന്നതല്ലാതെ മറ്റെന്താണ്?" (തു,ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'السجدة:١٦، ١٧', null, 102, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَالُوا: يَا رَسُولَ اللهِ! أَيُّ الْإِسْلَامِ أَفْضَلُ؟ قَالَ: "مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ". (ق,ت,ن)', 'അബൂമുസാ(റ): അവർ (അനുചരന്മാർ) ചോദിച്ചു: നബിയെ! ഇസ്ലാമിലെ ഏത് കർമ്മമാണ് കൂടുതൽ ഉൽകൃഷ്ഠം? നബി(സ) പറഞ്ഞു: ''ആരുടെ നാവിൽ നിന്നും കൈയ്യിൽ നിന്നും മുസ്ലിംകൾ സുരക്ഷിതരാകുന്നുവോ അവനാണ് ഏറ്റവും ഉൽകൃഷ്ഠൻ.'' (ബു,മു,തു,ന)', 'أَبِي مُوسَى', 'അബൂമുസാ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ عَبْدِاللهِ بْنِ عَمْرو رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيُّ الْإِسْلَامِ خَيْرٌ؟ قَالَ: "تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلَامَ عَلَى مَنْ عَرَفْتَ وَمَنْ لَمْ تَعْرِفْ". (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ): ഏറ്റവും ഉത്തമമായ ഇസ്ലാം ഏതെന്ന് ഒരാൾ നബി(സ)യോട് ചോദിച്ചു. നബി(സ) പറഞ്ഞു: "ഭക്ഷണം നൽകുക. നിനക്ക് പരിചയമുള്ളവരോടും പരിചയമില്ലാത്തവരോടും സലാം പറയുക." (ബു,മു,ദ,ന,ജ)', 'عَبْدِاللهِ بْنِ عَمْرو', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 103, 103, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ بِهِنَّ حَلَاوَةَ الْإِيمَانِ وَطَعْمَهُ؛ أَنْ يَكُونَ اللهُ عَزَّ وَجَلَّ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَأَنْ يُحِبَّ فِي اللهِ وَأَنْ يُبْغِضَ فِي اللهِ، وَأَنْ تُوقَدَ نَارٌ عَظِيمَةٌ فَيَقَعَ فِيهَا أَحَبُّ إِلَيْهِ مِنْ أَنْ يُشْرِكَ بِاللهِ شَيْئًا". – وَفِي رِوَايَةٍ: وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ أَنْ أَنْقَذَهُ اللهُ مِنْهُ كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ". (ق,ن,جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "മൂന്നു ഗുണങ്ങൾ ഉള്ളവൻ അവ മുഖേന സത്യവിശ്വാസത്തിന്റെ മാധുര്യവും രുചിയും ആസ്വദിച്ചിരിക്കുന്നു. അല്ലാഹുവും അവന്റെ ദൂതനും മറ്റുള്ളവരെക്കാൾ അവന് പ്രിയങ്കരമാകുന്നു. അല്ലാഹുവിന്റെ പേരിൽ സ്നേഹിക്കുകയും അല്ലാഹുവിന്റെ പേരിൽ കോപിക്കുകയും ചെയ്യുക. വലിയ തീ കത്തിച്ചിട്ട് അതിൽ അകപ്പെടുന്നത് അല്ലാഹുവിൽ വല്ലതും പങ്കുചേർക്കുന്നതിനേക്കാൾ ഭേദപ്പെട്ടതായി തോന്നുക." മറ്റൊരു റിപ്പോർട്ടിൽ: "സത്യനിഷേധത്തിൽ നിന്ന് അല്ലാഹു രക്ഷിച്ചതിനുശേഷം അതിലേക്ക് മടങ്ങുന്നത് അഗ്നിയിലെറിയപ്പെടുന്നത് വെറുക്കുന്നതു പോലെ വെറുക്കുക." (ബു,മു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 103, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=9 and h.hadith_no=59), 1, 'وَفِي رِوَايَةٍ: وَأَنْ يَكْرَهَ أَنْ يَعُودَ فِي الْكُفْرِ بَعْدَ أَنْ أَنْقَذَهُ اللهُ مِنْهُ كَمَا يَكْرَهُ أَنْ يُقْذَفَ فِي النَّارِ". (ق,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "സത്യനിഷേധത്തിൽ നിന്ന് അല്ലാഹു രക്ഷിച്ചതിനുശേഷം അതിലേക്ക് മടങ്ങുന്നത് അഗ്നിയിലെറിയപ്പെടുന്നത് വെറുക്കുന്നതു പോലെ വെറുക്കുക." (ബു,മു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ – وَفِي رِوَايَةٍ: أَهْلِهِ وَمَالِهِ – وَالنَّاسِ أَجْمَعِينَ". (ق,ن,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "സ്വന്തം സന്താനങ്ങളേക്കാളും പിതാവിനേക്കാളും -മറ്റൊരു റിപ്പോർട്ടിൽ: സമ്പത്തിനേക്കാളും കുടുംബത്തേക്കാളും- മുഴുവൻ ജനങ്ങളേക്കാളും അവന് പ്രിയപ്പെട്ടവൻ ഞാനാകുന്നതു വരെ നിങ്ങളിലൊരാളും സത്യവിശ്വാസിയാകുകയില്ല." (ബു,മു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=9 and h.hadith_no=60), 1, 'وَفِي رِوَايَةٍ: أَهْلِهِ وَمَالِهِ – وَالنَّاسِ أَجْمَعِينَ". (ق,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: സമ്പത്തിനേക്കാളും കുടുംബത്തേക്കാളും- മുഴുവൻ ജനങ്ങളേക്കാളും അവന് പ്രിയപ്പെട്ടവൻ ഞാനാകുന്നതു വരെ നിങ്ങളിലൊരാളും സത്യവിശ്വാസിയാകുകയില്ല." (ബു,മു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ: مَنْ أَحَبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ، وَمَنْ كَانَ اللهُ عَزَّ وَجَلَّ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَمَنْ كَانَ أَنْ يُقْذَفَ فِي النَّارِ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ إِلَى الْكُفْرِ بَعْدَ أَنْ أَنْقَذَهُ اللهُ مِنْهُ". (ن)', 'അനസ്(റ): പ്രവാചകർ(സ) പറഞ്ഞു: മൂന്നു കാര്യങ്ങൾ ഉൾക്കൊണ്ടവൻ സത്യവിശ്വാസത്തിന്റെ മാധുര്യം അനുഭവിച്ചിരിക്കുന്നു: ഒരാൾ അല്ലാഹുവിനും അവന്റെ ദൂതനും വേണ്ടി മാത്രമായി ഒരു വ്യക്തിയെ സ്നേഹിക്കുക. അല്ലാഹുവും അവന്റെ ദൂതനും മറ്റെന്തിലും ഉപരിയായി അവന് പ്രിയങ്കരമായിരിക്കുക. അല്ലാഹു അവിശ്വാസത്തിൽനിന്നും മോചിപ്പിച്ച ശേഷം വീണ്ടും അതിലേക്ക് മടങ്ങുന്നതിനേക്കാൾ ഒരുത്തന് പ്രിയങ്കരമായമായത് അവൻ തിയ്യിലേക്ക് എറിയപ്പെടുന്നതായിരിക്കും. (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "ذَاقَ طَعْمَ الْإِيمَانِ مَنْ رَضِيَ بِاللهِ رَبًّا وَبِالْإِسْلَامِ دِينًا وَبِمُحَمَّدٍ رَسُولًا". (م,ت)', 'അബ്ബാസ്(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "അല്ലാഹുവിനെ പരിപാലകനായും ഇസ്ലാമിനെ ജീവിത രീതിയായും മുഹമ്മദി(സ)നെ ദൈവദൂതനായും തൃപ്തിപ്പെട്ടവൻ സത്യവിശ്വാസത്തിന്റെ രുചി ആസ്വദിച്ചിരിക്കുന്നു." (മു,തു)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസ്(റ)', null, null, array['م','ت']::text[], array['മു','തു']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ –أَوْ قَالَ: لِجَارِهِ– مَا يُحِبُّ لِنَفْسِهِ". (ق,ت,ن,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "സ്വന്തത്തിനുവേണ്ടി ഇഷ്ടപ്പെടുന്നത് തന്റെ സഹോദരന് വേണ്ടിയും - തന്റെ അയൽവാസിക്ക് വേണ്ടിയും- ഇഷ്ടപ്പെടുന്നതുവരെ നിങ്ങളിലാരും വിശ്വാസിയാകുകയില്ല." (ബു,മു,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 104, 104, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ بِهِنَّ حَلَاوَةَ الْإِسْلَامِ: مَنْ كَانَ اللهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا، وَمَنْ أَحَبَّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ، وَمَنْ يَكْرَهُ أَنْ يَرْجِعَ إِلَى الْكُفْرِ كَمَا يَكْرَهُ أَنْ يُلْقَى فِي النَّارِ". (ن)', 'അനസ്(റ): പ്രവാചകർ(സ) പറഞ്ഞു: മൂന്നു കാര്യങ്ങൾ ഉൾക്കൊണ്ടവൻ ഇസ്ലാമിന്റെ മാധുര്യം അനുഭവിച്ചറിഞ്ഞിരിക്കുന്നു. "ഒരുത്തന് അല്ലാഹുവും അവന്റെ ദൂതനും മറ്റെന്തിനേക്കാളും പ്രിയപ്പെട്ടതായിരിക്കുക, ഒരാൾ അല്ലാഹുവിന് വേണ്ടി മാത്രമായി മറ്റൊരു വ്യക്തിയെ സ്നേഹിക്കുക, ഒരാൾ താൻ നരകത്തിലേക്കെറിയപ്പെടുന്നത് വെറുക്കുന്നതു പോലെ താൻ അവിശ്വാസത്തിലേക്ക് മടങ്ങിപ്പോകുന്നതിനെ വെറുക്കുക" എന്നിവയാണവ. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 104, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "സത്യവിശ്വാസികളാകുന്നഡുവരെ നിങ്ങളാരും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല പരസ്പരം സ്നേഹിക്കുന്നതു വരെ നിങ്ങൾ സത്യവിശ്വാസികളാവുകയുമില്ല. പരസ്പരം സ്നേഹമുണ്ടാകാൻ ഒരു കാര്യം നിങ്ങൾക്ക് പറഞ്ഞുതരട്ടയോ? നിങ്ങൾക്കിടയിൽ സലാം വർദ്ധിപ്പിക്കുക." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ نَاسٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَأَلُوهُ: إِنَّا نَجِدُ فِي أَنْفُسِنَا مَا يَتَعَاظَمُ أَحَدُنَا أَنْ يَتَكَلَّمَ بِهِ، قَالَ: "وَقَدْ وَجَدْتُمُوهُ؟" قَالُوا: نَعَمْ، قَالَ: "ذَاكَ صَرِيحُ الْإِيمَانِ". (م,د)', 'അബുഹുറൈറ(റ): ഒരുകൂട്ടം സ്വാഹാബികൾ വന്ന് നബി(സ)യോട് പറഞ്ഞു: സംസാരിക്കുന്നതു പോലും അതി ഗുരുതരമായ തെറ്റായി ഞങ്ങൾ കണക്കാക്കാറുള്ള തരത്തിലുള്ള ചില കാര്യങ്ങൾ ഞങ്ങൾ ചിന്തിച്ചു പോകുന്നു. നബി(സ) ചോദിച്ചു: "അത്തരം ചിന്തകൾ നിങ്ങളെ പിടികൂടുന്നുണ്ടോ?" അവർ പറഞ്ഞു: അതെ, നബി(സ) പറഞ്ഞു: "അതു തന്നെയാണ് വ്യക്തമായ വിശ്വാസത്തിന്റെ അടയാളം." (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الدِّينَ يُسْرٌ، وَلَنْ يُشَادَّ الدِّينَ أَحَدٌ إِلَّا غَلَبَهُ، فَسَدِّدُوا، وَقَارِبُوا، وَأَبْشِرُوا، وَاسْتَعِينُوا بِالْغَدْوَةِ وَالرَّوْحَةِ وَشَيْءٍ مِنَ الدُّلْجَةِ". (خ,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "മതം എളുപ്പമാണ്. മതവിഷയങ്ങളിൽ അമിതമായ കാർക്കശ്യം പുലർത്തിയ ആരെയും അത് അതിജയിക്കാതിരുന്നിട്ടില്ല. അതിനാൽ നിങ്ങൾ ശരിയായതിലേക്ക് തിരിക്കുക, വിവേകപൂർവ്വം പ്രവർത്തിക്കുക. സുവിശേഷമറിയിക്കുക, പ്രഭാതത്തിലും സന്ധ്യയിലും രാത്രിയുടെ അവസാനയാമത്തിന്റെ ഒരംശത്തിലും നിങ്ങൾ അല്ലാഹുവോട് സഹായാർത്ഥന നടത്തുക." (ബു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَمَرَهُمْ أَمَرَهُمْ مِنَ الْأَعْمَالِ بِمَا يُطِيقُونَ، قَالُوا: إِنَّا لَسْنَا كَهَيْئَتِكَ يَا رَسُولَ اللهِ! إِنَّ اللهَ قَدْ غَفَرَ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، فَيَغْضَبُ حَتَّى يُعْرَفَ الْغَضَبُ فِي وَجْهِهِ، ثُمَّ يَقُولُ: "إِنَّ أَتْقَاكُمْ وَأَعْلَمَكُمْ بِاللهِ أَنَا". (خ)', 'ആഇശ(റ): നബി(സ) ജനങ്ങളോട് കൽപിക്കുമ്പോഴൊക്കെ അവർക്ക് ചെയ്യാൻ കഴിയുന്നതേ കൽപിച്ചിരുന്നുള്ളൂ. അവർ പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരേ! ഞങ്ങൾ അങ്ങയുടെ അവസ്ഥയിലല്ലല്ലോ? അങ്ങേക്ക് കഴിഞ്ഞതും വരാനിരിക്കുന്നതുമായ മുഴുവൻ പാപങ്ങളും പൊറുത്തുതന്നിട്ടുണ്ടല്ലോ? അപ്പോൾ നബി(സ) ദേഷ്യപ്പെട്ടു. ദേഷ്യം മുഖത്ത് പ്രതിഫലിച്ചു. തുടർന്ന് പറഞ്ഞു: "നിങ്ങളിൽ അല്ലാഹുവിനെ കൂടുതൽ അറിയുന്നവനും അവനെ അധികം ഭയക്കുന്നവനും ഞാനാണ്." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 105, 105, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَعِنْدَهَا امْرَأَةٌ قَالَ: "مَنْ هَذِهِ؟" قَالَتْ: فُلَانَةُ تَذْكُرُ مِنْ صَلَاتِهَا، قَالَ: "مَهْ! عَلَيْكُمْ بِمَا تُطِيقُونَ، فَوَاللهِ! لَا يَمَلُّ اللهُ حَتَّى تَمَلُّوا، وَكَانَ أَحَبَّ الدِّينِ إِلَيْهِ مَادَامَ عَلَيْهِ صَاحِبُهُ". (ق,ن,جه)', 'ആഇശ(റ): നബി(സ) ആഇശ(റ)യുടെ സമീപത്തേക്ക് കയറിച്ചെന്നു. അവിടെ ഒരു സ്ത്രീയുണ്ടായിരുന്നു. നബി(സ) ചോദിച്ചു: "ആരാണിത്?" ആഇശ(റ) പറഞ്ഞു: ''ഇന്നാലിന്ന സത്രീയാണ്''. ശേഷം അവളുടെ നിസ്കാരത്തെക്കുറിച്ച് ആഇശ(റ) (വർണ്ണിച്ചു) പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "നിർത്തൂ! നിങ്ങൾ നിങ്ങൾക്കു സാധിക്കുന്നത് ചെയ്താൽ മതി. അല്ലാഹുവാണെ! നിങ്ങൾക്ക് മടുപ്പുളവാകുന്നതുവരെ അല്ലാഹുവിന് മടുക്കുകയില്ല. ഒരാൾ സ്ഥിരമായി അനുഷ്ഠിക്കുന്നതാണ് മതകാര്യങ്ങളിൽ അല്ലാഹുവിന് ഏറ്റവും പ്രിയങ്കരം." (ബു,മു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 105, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُسْلِمُ مَنْ سَلِمَ النَّاسُ مِنْ لِسَانِهِ وَيَدِهِ، وَالْمُؤْمِنُ مَنْ أَمِنَهُ النَّاسُ عَلَى دِمَائِهِمْ وَأَمْوَالِهِمْ". (ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ജനങ്ങൾ ആരുടെ നാവിൽ നിന്ന് രക്ഷപ്പെട്ടുവോ അവനാണ് യഥാർത്ഥ മുസ്ലിം. ജനങ്ങൾ തങ്ങളുടെ രക്തത്തിന്റെയും സമ്പത്തിന്റെയും കാര്യത്തിൽ ആരിൽ നിന്ന് നിർഭയരായോ അവനാണ് സത്യവിശ്വാസി." (തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عَبْدِاللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ، وَالْمُهَاجِرُ مَنْ هَجَرَ مَا نَهَى اللهُ عَنْهُ". (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ): നബി(സ) പറഞ്ഞു: "ഒരുത്തന്റെ കയ്യിൽ നിന്നും നാവിൽ നിന്നും ഇതര മുസ്ലിംകൾ രക്ഷപ്പെട്ടുവെങ്കിൽ അവനാണ് പൂർണ്ണ മുസ്ലിം. അല്ലാഹു നിരോധിച്ച കാര്യങ്ങൾ ഒഴിവാക്കിയവനാണ് മുഹാജിർ." (ബു,മു,ദ,തു,ന)', 'عَبْدِاللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ أَبِي شُرَيْحٍ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيُحْسِنْ إِلَى جَارِهِ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ، وَمَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَسْكُتْ". (ق,د,ت,جه)', 'അബുശുറൈഹിൽ ഖുസാഈ(റ): നബി(സ) അരുളി: "ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നുവെങ്കിൽ അവൻ തന്റെ അയൽവാസിക്ക് നന്മ ചെയ്യട്ടെ. ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നുവെങ്കിൽ അവൻ തന്റെ അതിഥിയെ സൽക്കരിക്കട്ടെ. ആരെങ്കിലും അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നുവെങ്കിൽ അവൻ നല്ലത് പറയട്ടെ. അല്ലെങ്കിൽ മൗനം ദീക്ഷിക്കട്ടെ." (ബു,മു,ദ,തു,ജ)', 'أَبِي شُرَيْحٍ الْخُزَاعِيِّ', 'അബുശുറൈഹിൽ ഖുസാഈ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْجَنَّةَ مَنْ لَا يَأْمَنُ جَارُهُ بَوَائِقَهُ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഏതൊരാളുടെ ദ്രോഹങ്ങളിൽ നിന്ന് തന്റെ അയൽവാസി നിർഭയനാകുന്നില്ലയോ അവൻ സ്വർഗ്ഗത്തിൽ കടക്കുകയില്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 106, 106, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ نَبِيٍّ بَعَثَهُ اللهُ فِي أُمَّةٍ قَبْلِي إِلَّا كَانَ لَهُ مِنْ أُمَّتِهِ حَوَارِيُّونَ وَأَصْحَابٌ يَأْخُذُونَ بِسُنَّتِهِ وَيَقْتَدُونَ بِأَمْرِهِ ثُمَّ إِنَّهَا تَخْلُفُ مِنْ بَعْدِهِمْ خُلُوفٌ، يَقُولُونَ مَا لَا يَفْعَلُونَ، وَيَفْعَلُونَ مَا لَا يُؤْمَرُونَ، فَمَنْ جَاهَدَهُمْ بِيَدِهِ فَهُوَ مُؤْمِنٌ، وَمَنْ جَاهَدَهُمْ بِلِسَانِهِ فَهُوَ مُؤْمِنٌ، وَمَنْ جَاهَدَهُمْ بِقَلْبِهِ فَهُوَ مُؤْمِنٌ، وَلَيْسَ وَرَاءَ ذَلِكَ مِنَ الْإِيمَانِ حَبَّةُ خَرْدَلٍ". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "എനിക്കു മുമ്പുള്ള സമുദായങ്ങളിലേക്ക് അല്ലാഹു നിയോഗിച്ച ഏതൊരു നബിക്കും, അദ്ദഹത്തിന്റെ ആജ്ഞകളനുസരിക്കുകയും അദ്ദേഹത്തിന്റെ ചര്യ പിൻതുടരുകയും ചെയ്യുന്ന കുറച്ച് നിഷ്കളങ്ക സഹായികളും അനുയായികളും ഉണ്ടായിട്ടുണ്ട്. പിന്നീട് അവർക്കുശേഷം പിൻഗാമികൾ നിലവിൽ വരും. അവർ ചെയ്യാത്തത് പറയുകയും കൽപിക്കപ്പെടാത്തത് പ്രവർത്തിക്കുകയും ചെയ്യും. തദവസരത്തിൽ തന്റെ കൈകൊണ്ട് അവരോടു സമരം ചെയ്യുന്നവൻ സത്യവിശ്വാസിയാണ്. തന്റെ നാക്ക് കൊണ്ട് അവരോട് സമരം ചെയ്യുന്നവനും സത്യവിശ്വാസിയാണ്. തന്റെ ഹൃദയം കൊണ്ട് അവരോടു സമരം ചെയ്യുന്നവനും സത്യവിശ്വാസിയാണ്. അതിനപ്പുറം കടുകുമണിയോളം സത്യവിശ്വാസമില്ല." (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 106, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى صَلَاتَنَا وَاسْتَقْبَلَ قِبْلَتَنَا وَأَكَلَ ذَبِيحَتَنَا فَذَلِكُمُ الْمُسْلِمُ". (خ,ن)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നമ്മുടെ നിസ്കാരം നിർവ്വഹിക്കുകയും നമ്മുടെ ഖിബ്ലയിലേക്ക് തിരിയുകയും നാം അറുത്തത് ഭക്ഷിക്കുകയും ചെയ്യുന്നവനാണ് മുസ്ലിം." (ബു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جِهَارًا غَيْرَ سِرٍّ يَقُولُ: "أَلَا إِنَّ آلَ أَبِي – يَعْنِي فُلَانًا – لَيْسُوا لِي بِأَوْلِيَاءَ، إِنَّمَا وَلِيِّيَ اللهُ وَصَالِحُ الْمُؤْمِنِينَ". (ق)', 'അംറുബ്നുൽ ആസ്(റ): നബി(സ) ഉച്ചത്തിൽ പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ പിതൃകുടുംബമല്ല എന്റെ സഹായി. നിശ്ചയം, എന്റെ സഹായി അല്ലാഹുവും സച്ചരിതരായ വിശ്വാസികളുമാണ്." (ബു,മു)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الْمُؤْمِنِ كَمَثَلِ الْخَامَةِ مِنَ الزَّرْعِ، تُفِيئُهَا الرِّيحُ، تَصْرَعُهَا مَرَّةً وَتَعْدِلُهَا أُخْرَى حَتَّى تَهِيجَ، وَمَثَلُ الْكَافِرِ كَمَثَلِ الْأَرْزَةِ الْمُجْذِيَةِ عَلَى أَصْلِهَا، لَا يُفِيئُهَا شَيْءٌ حَتَّى يَكُونَ انْجِعَافُهَا مَرَّةً وَاحِدَةً". (ق)', 'കഅ്ബ്(റ): നബി(സ) പറഞ്ഞു: "വിശ്വാസി കാറ്റിൽ ഉലയുന്ന ഇളം കൃഷിച്ചെടി പോലെയാണ്. ചിലപ്പോൾ അത് ചായുകയും മറ്റു ചിലപ്പോൾ ഉയരുകയും ചെയ്യും. ഉണങ്ങുന്നത് വരെ. അവിശ്വാസി ഉറച്ച് നിൽക്കുന്ന ദേവദാരു മരം പോലെയാണ്. അതിനെ ഒന്നും ഉലയ്ക്കുകയില്ല. പക്ഷേ പെട്ടെന്നൊരു പിഴുതുമാറ്റലായിരിക്കും അതിനുണ്ടാവുക." (ബു,മു)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ النُّعْمَانِ بْنِ بَشِيرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الْمُؤْمِنِينَ فِي تَوَادِّهِمْ وَتَرَاحُمِهِمْ وَتَعَاطُفِهِمْ مَثَلُ الْجَسَدِ، إِذَا اشْتَكَى مِنْهُ عُضْوٌ تَدَاعَى لَهُ سَائِرُ الْجَسَدِ بِالسَّهَرِ وَالْحُمَّى". (ق)', 'നുഅ്മാനുബ്നു ബശീർ(റ): നബി(സ) പറഞ്ഞു: "പരസ്പര സ്നേഹത്തിലും അനുകമ്പയിലും കാരുണ്യത്തിലും വിശ്വാസികളുടെ ഉപമ ഒരു ശരീരം പോലെയാണ്. അതിൽ ഒരു അവയവം രോഗബാധിതമായാൽ ഉറക്കമൊഴിച്ചും പനി പിടിച്ചും മറ്റവയവങ്ങൾ അതിനോട് സഹകരിക്കുന്നു." (ബു,മു)', 'النُّعْمَانِ بْنِ بَشِيرٍ', 'നുഅ്മാനുബ്നു ബശീർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 107, 107, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَثَلُ الْمُؤْمِنِ الَّذِي يَقْرَأُ الْقُرْآنَ مَثَلُ الْأُتْرُجَّةِ، طَعْمُهَا طَيِّبٌ وَرِيحُهَا طَيِّبٌ، وَمَثَلُ الْمُؤْمِنِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ التَّمْرَةِ، طَعْمُهَا طَيِّبٌ وَلَا رِيحَ لَهَا، وَمَثَلُ الْمُنَافِقِ الَّذِي يَقْرَأُ الْقُرْآنَ كَمَثَلِ الرَّيْحَانَةِ، رِيحُهَا طَيِّبٌ وَطَعْمُهَا مُرٌّ، وَمَثَلُ الْمُنَافِقِ الَّذِي لَا يَقْرَأُ الْقُرْآنَ كَمَثَلِ الْحَنْظَلَةِ، طَعْمُهَا مُرٌّ وَلَا رِيحَ لَهَا". (ق,د,ت,ن,جه)', 'അബൂമൂസൽ അശ്അരി(റ): നബി(സ) പറഞ്ഞു: "ഖുർആൻ പാരായണം ചെയ്യുന്ന വിശ്വാസി ഒരു ഓറഞ്ച് പോലെയാണ്. നല്ല രുചിയും സുഗന്ധവുമാണതിന്. എന്നാൽ ഖുർആൻ പാരായണം ചെയ്യാത്ത വിശ്വാസി ഒരു കാരക്ക പോലെയാണ്. അതിന് നല്ല രുചിയുണ്ടെങ്കിലും ഗന്ധം തീരെയില്ല. ഖുർആൻ ഓതുന്ന കപടവിശ്വാസി റൈഹാൻ ചെടി പോലെയാണ്, നല്ല പരിമളമാണതിന്. എന്നാൽ കയ്പ്പു രസമാണ്. ഖുർആൻ പാരായണം ചെയ്യാത്ത കപട വിശ്വാസിയുടെ ഉപമ ഒരു ആട്ടങ്ങ പോലെയാണ്. അതിന് കൈപ്പു രുചിയാണ്, പരിമളവുമില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 107, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَخْبِرُونِي بِشَجَرَةٍ تُشْبِهُ أَوْ كَالرَّجُلِ الْمُسْلِمِ، لَا يَتَحَاتُّ وَرَقُهَا وَلَا، وَلَا، وَلَا، تُؤْتِي أُكُلَهَا كُلَّ حِينٍ" قَالَ ابْنُ عُمَرَ: فَوَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ، وَرَأَيْتُ أَبَا بَكْرٍ وَعُمَرَ لَا يَتَكَلَّمَانِ، فَكَرِهْتُ أَنْ أَتَكَلَّمَ، فَلَمَّا لَمْ يَقُولُوا شَيْئًا قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هِيَ النَّخْلَةُ" فَلَمَّا قُمْنَا قُلْتُ لِعُمَرَ: يَا أَبَتَاهُ! وَاللهِ! لَقَدْ كَانَ وَقَعَ فِي نَفْسِي أَنَّهَا النَّخْلَةُ، فَقَالَ: مَا مَنَعَكَ أَنْ تَكَلَّمَ؟ قَالَ: لَمْ أَرَكُمْ تَكَلَّمُونَ، فَكَرِهْتُ أَنْ أَتَكَلَّمَ – أَوْ أَقُولَ – شَيْئًا، قَالَ عُمَرُ: لَأَنْ تَكُونَ قُلْتَهَا أَحَبُّ إِلَيَّ مِنْ كَذَا وَكَذَا. (ق,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുക്കൽ ഇരിക്കുമ്പോൾ അവിടുന്ന് ചോദിച്ചു: "മുസ്ലിമിനോട് സാദൃശ്യമുള്ള ഒരു മരമേതെന്ന് പറയാമോ? അതിന്റെ ഇല പൊഴിയുകയോ അങ്ങനെയുള്ള മറ്റുവല്ലതും ഉണ്ടാവുകയോ ഇല്ല. എല്ലാ സമയത്തും അത് കനി നൽകും." ഇബ്നുഉമർ(റ) പറയുന്നു: അത് ഈത്തപ്പനയാണെന്ന് എനിക്കുതോന്നി. അബൂബക്കർ, ഉമർ(റ) എന്നിവർ ഒന്നും പറയുന്നില്ലെന്ന് കണ്ട ഞാൻ അതു പറയാൻ ഇഷ്ടപ്പെട്ടില്ല. അവരാരും മറുപടി പറയാതിരുന്നപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് ഈത്തപ്പനയാണ്." അങ്ങനെ ഞങ്ങൾ എഴുന്നേറ്റപ്പോൾ ഞാൻ ഉമറിനോട് പറഞ്ഞു: പിതാവേ! അല്ലാഹുവാണെ, അത് ഈത്തപ്പഴം തന്നെയെന്ന് എനിക്ക് തോന്നിയിരുന്നു. ഉമർ(റ) ചോദിച്ചു: നീ അത് പറയാതിരുന്നതെന്തേ? ഞാൻ പറഞ്ഞു: നിങ്ങളാരും സംസാരിക്കുന്നത് കണ്ടില്ല. അതുകൊണ്ട് ഞാനെന്തെങ്കിലും പറയാൻ ഇഷ്ടപ്പെട്ടില്ല. ഉമർ(റ) പറഞ്ഞു: നീ അത് പറയുന്നതായിരുന്നു മറ്റു പലതിനേക്കാളും എനിക്ക് പ്രിയങ്കരം. (ബു,മു,തു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَدْخُلُ أَهْلُ الْجَنَّةِ الْجَنَّةَ وَأَهْلُ النَّارِ النَّارَ، ثُمَّ يَقُولُ اللهُ تَعَالَى: أَخْرِجُوا مِنَ النَّارِ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ حَبَّةٍ مِنْ خَرْدَلٍ مِنْ إِيمَانٍ، فَيَخْرُجُونَ مِنْهَا، قَدِ اسْوَدُّوا فَيُلْقَوْنَ فِي نَهَرِ الْحَيَا – أَوِ الْحَيَاةِ شَكَّ مَالِكٌ – فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي جَانِبِ السَّيْلِ، أَلَمْ تَرَ أَنَّهَا تَخْرُجُ صَفْرَاءَ مُلْتَوِيَةً". (ق)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗാവകാശികൾ സ്വർഗ്ഗത്തിലും നരകാവകാശികൾ നരകത്തിലും പ്രവേശിച്ചു കഴിഞ്ഞാൽ അല്ലാഹു പറയും: ''ഒരു കടുകുമണിതൂക്കം സത്യവിശ്വാസം ഹൃദയത്തിലുള്ളവരെ നരകത്തിൽ നിന്ന് പുറത്തെടുക്കുക!'' അങ്ങനെയവരെ പുറത്തെടുക്കും. അവർ കറുത്തിരുണ്ട് പോയിരിക്കും. അവരെ ''ജീവനദി''യിൽ ഇടും. ഒലിക്കുന്ന വെള്ളത്തിനടുത്ത് ധാന്യമണികൾ കിളിർക്കുന്നതുപോലെ അവ മുളച്ചുവരും. മഞ്ഞ നിറത്തിൽ വളഞ്ഞ് അത് പുറത്തേക്കുവരുന്നത് നീ കണ്ടിട്ടില്ലേ." (ബു,മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 108, 108, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ لَا يَظْلِمُ مُؤْمِنًا حَسَنَةً يُعْطَى بِهَا فِي الدُّنْيَا، وَيُجْزَى بِهَا فِي الْآخِرَةِ، وَأَمَّا الْكَافِرُ فَيُطْعَمُ بِحَسَنَاتِ مَا عَمِلَ بِهَا لِلَّهِ فِي الدُّنْيَا حَتَّى إِذَا أَفْضَى إِلَى الْآخِرَةِ لَمْ تَكُنْ لَهُ حَسَنَةٌ يُجْزَى بِهَا". (م)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "ഭൗതികലോകത്ത് ഗുണവും അന്ത്യനാളിൽ പ്രതിഫലവും നൽകപ്പെടുന്ന യാതൊരു നന്മയുടെ കാര്യത്തിലും ഒരു സത്യവിശ്വാസിയോടും അല്ലാഹു അക്രമം ചെയ്യില്ല. എന്നാൽ സത്യനിഷേധി അല്ലാഹുവിനുവേണ്ടി ചെയ്യുന്ന സൽകർമ്മങ്ങൾക്ക് ഭൗതികലോകത്തുതന്നെ ഫലം നൽകപ്പെടും. അങ്ങനെ പരലോകത്തു വന്നാൽ പ്രതിഫലാർഹമായ യാതൊരു നന്മയും അവന്നുണ്ടാവുകയില്ല." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 108, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللهَ تَجَاوَزَ لِأُمَّتِي مَا حَدَّثَتْ بِهِ أَنْفُسَهَا مَا لَمْ يَتَكَلَّمُوا أَوْ يَعْمَلُوا بِهِ". (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം മനസ്സുകളിൽ തോന്നുന്ന കാര്യങ്ങളെ എന്റെ സമുദായത്തിന് അല്ലാഹു പൊറുത്ത് കൊടുത്തിരിക്കുന്നു. അവർ അവയെ പ്രവർത്തിക്കുകയോ മൊഴിയുകയോ ചെയ്യാതിരിക്കുന്ന കാലമത്രയും." (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ سَعْدِ ابْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: أَعْطَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رِجَالًا وَلَمْ يُعْطِ رَجُلًا مِنْهُمْ شَيْئًا، قَالَ سَعْدٌ: يَا رَسُولَ اللهِ! أَعْطَيْتَ فُلَانًا وَفُلَانًا وَلَمْ تُعْطِ فُلَانًا شَيْئًا وَهُوَ مُؤْمِنٌ، فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَوْ مُسْلِمٌ" حَتَّى أَعَادَهَا سَعْدٌ ثَلَاثًا وَالنَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ أَوْ مُسْلِمٌ، ثُمَّ قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي لَأُعْطِي رِجَالًا وَأَدَعُ مَنْ هُوَ أَحَبُّ إِلَيَّ مِنْهُمْ لَا أُعْطِيهِ شَيْئًا مَخَافَةَ أَنْ يُكَبُّوا فِي النَّارِ عَلَى وُجُوهِهِمْ". (ق,د,ن)', 'സഅ്ദ്ബ്നു അബീ വഖാസ്(റ): നബി(സ) കുറേ ആളുകൾക്ക് (സമ്പത്ത്) വിതരണം ചെയ്തു. (പക്ഷെ) അതിൽ ഒരാൾക്ക് കൊടുത്തില്ല. സഅദ്(റ) നബി(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ! അവനും ഇവനുമൊക്കെ അങ്ങ് കൊടുത്തു. പക്ഷേ, ഇയാൾക്ക് കൊടുത്തില്ലല്ലോ. അദ്ദേഹവും മുഅ്മിനാണല്ലോ. നബി(സ) ചോദിച്ചു: "അതോ മുസ്ലിമോ?" സഅ്ദ്(റ) തന്റെ ചോദ്യവും നബി(സ) അവിടുത്തെ ഉത്തരവും മൂന്ന് പ്രാവശ്യം ആവർത്തിച്ചു. ശേഷം പറഞ്ഞു: "നിശ്ചയം ചിലർക്ക് ഞാൻ കൊടുക്കും എനിക്കേറ്റവും ഇഷ്ടപ്പെട്ടവരെ അവർ നരകത്തിൽ വീഴുമോ എന്ന് ഭയന്നതിനാൽ ഒന്നും നൽകാതെ ഞാൻ ഒഴിവാക്കുന്നു." (ബു,മു,ദ,ന)', 'سَعْدِ ابْنِ أَبِي وَقَّاصٍ', 'സഅ്ദ്ബ്നു അബീ വഖാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَمْرِو بْنِ شُرَحْبِيلَ رَضِيَ اللهُ عَنْهُ عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مُلِئَ عَمَّارٌ إِيمَانًا إِلَى مُشَاشِهِ". (ن,جه)', 'അംറുബ്നു ശുറഹ്ബീൽ(റ) ഒരു സ്വഹാബിയിൽ നിന്ന്: നബി(സ) പറഞ്ഞു: "അമ്മാർ(റ) തന്റെ എല്ലുകളുടെ അഗ്രംവരെ ഈമാൻ നിറക്കപ്പെട്ട വ്യക്തിയാണ്." (ന,ജ)', 'عَمْرِو بْنِ شُرَحْبِيلَ', 'അംറുബ്നു ശുറഹ്ബീൽ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 109, 109, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عن جابر بن عبد الله رَضِيَ اللهُ عَنْهُمَا يَقُولُ: قَالَ رَسُولُ اللهِ صلّى الله عليه وسلم: "غِلَظُ الْقُلُوبِ وَالْجَفَاءُ فِي الْمَشْرِقِ، وَالْإِيمَانُ فِي أَهْلِ الْحِجَازِ". (م)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) അരുളി: "ഹൃദയകാഠിന്യവും പരുഷ പെരുമാറ്റവും പൗരസ്ത്യരുടെ സ്വഭാവമാകുന്നു.³ സത്യവിശ്വാസം ഹിജാസുകാരിലുമാണ്." (മു)', 'جابر بن عبد الله', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', '³ മദീനയുടെ കിഴക്കു സ്ഥിതി ചെയ്യുന്ന നജ്ദിനെയാണുദ്ദേശിക്കുന്നത് എന്ന് മനസ്സിലാക്കാം.', null, array['م']::text[], array['മു']::text[], null, null, 109, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "جَاءَ أَهْلُ الْيَمَنِ، هُمْ أَرَقُّ أَفْئِدَةً وَأَضْعَفُ قُلُوبًا، الْإِيمَانُ يَمَانٍ وَالْحِكْمَةُ يَمَانِيَةٌ، السَّكِينَةُ فِي أَهْلِ الْيَمَنِ وَالْفَخْرُ وَالْخُيَلَاءُ فِي الْفَدَّادِينَ أَهْلِ الْوَبَرِ قِبَلَ مَطْلِعِ الشَّمْسِ". (ق,ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "യമൻ നിവാസികൾ വന്നിരിക്കുന്നു. അവർ ഏറ്റവും ലോല ഹൃദയരും വിനയ മനസ്കരുമാണ്. (യഥാർത്ഥ) സത്യവിശ്വാസം യമൻകാരുടേതാണ്. തത്വജ്ഞാനവും യമൻകാരുടേതാണ്. വിനയ സ്വഭാവവും യമൻകാരുടേതാണ്. ദുരഭിമാനവും അഹങ്കാരവും കിഴക്കുഭാഗത്ത് രോമത്തമ്പുകളിൽ പാർക്കുന്ന ഒട്ടകങ്ങളുടെ പിന്നിൽനിന്ന് അട്ടഹസിക്കുന്ന ഒട്ടകക്കാരിലുമാണ്." (ബു,മു,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','ت']::text[], array['ബു','മു','തു']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ يَقُولُ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَا أَنَا نَائِمٌ، رَأَيْتُ النَّاسَ يُعْرَضُونَ عَلَيَّ، وَعَلَيْهِمْ قُمُصٌ، مِنْهَا مَا يَبْلُغُ الثُّدِيَّ، وَمِنْهَا مَا دُونَ ذَلِكَ، وَعُرِضَ عَلَيَّ عُمَرُ بْنُ الْخَطَّابِ وَعَلَيْهِ قَمِيصٌ يَجُرُّهُ" قَالُوا: فَمَا أَوَّلْتَ ذَلِكَ يَا رَسُولَ اللهِ؟ قَالَ: "الدِّينَ". (ق,ت,ن)', 'അബൂസഈദിൽഖുദ്രി(റ): നബി(സ) അരുളി: "ഞാൻ നിദ്രയിലായിരിക്കെ കുപ്പായം ധരിച്ച ചില മനുഷ്യരെ എന്റെ മുമ്പിൽ പ്രദർശിപ്പിച്ചതു കണ്ടു. ചിലരുടെ കുപ്പായം മാറിടം വരെയുണ്ട്. ചിലരുടേത് അത്രയും ഇല്ല. കൂട്ടത്തിൽ ഉമറുബ്നുൽ ഖത്താബുണ്ട്. അദ്ദേഹം ധരിച്ചിരുന്ന കുപ്പായം നിലത്ത് ഇഴഞ്ഞു കിടന്നിരുന്നു." അവർ ചോദിച്ചു: നബിയേ! ഈ സ്വപ്നത്തിന് അങ്ങ് നൽകിയ വ്യാഖ്യാനമെന്ത്? നബി(സ) അരുളി: "അത് മതനിഷ്ഠയാണ്." (ബു,മു,തു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽഖുദ്രി(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 110, 110, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'قَوْلُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بُنِيَ الْإِسْلَامُ عَلَى خَمْسٍ وَهُوَ قَوْلٌ وَفِعْلٌ وَيَزِيدُ وَيَنْقُصُ". قَالَ اللهُ تَعَالَى: {لِيَزْدَادُوا إِيمَانًا مَعَ إِيمَانِهِمْ} {وَزِدْنَاهُمْ هُدًى} {وَيَزِيدُ اللهُ الَّذِينَ اهْتَدَوْا هُدًى} {وَالَّذِينَ اهْتَدَوْا زَادَهُمْ هُدًى وَآتَاهُمْ تَقْوَاهُمْ} وَقَوْلُهُ: {وَيَزْدَادَ الَّذِينَ آمَنُوا إِيمَانًا} وَقَوْلُهُ: {أَيُّكُمْ زَادَتْهُ هَذِهِ إِيمَانًا فَأَمَّا الَّذِينَ آمَنُوا فَزَادَتْهُمْ إِيمَانًا} وَقَوْلُهُ جَلَّ ذِكْرُهُ: {فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا} وَقَوْلُهُ تَعَالَى: {وَمَا زَادَهُمْ إِلَّا إِيمَانًا وَتَسْلِيمًا} وَالْحُبُّ فِي اللهِ وَالْبُغْضُ فِي اللهِ مِنَ الْإِيمَانِ. وَكَتَبَ عُمَرُ بْنُ عَبْدِالْعَزِيزِ إِلَى عَدِيِّ بْنِ عَدِيٍّ: إِنَّ لِلْإِيمَانِ فَرَائِضَ وَشَرَائِعَ وَحُدُودًا وَسُنَنًا، فَمَنِ اسْتَكْمَلَهَا اسْتَكْمَلَ الْإِيمَانَ، وَمَنْ لَمْ يَسْتَكْمِلْهَا لَمْ يَسْتَكْمِلِ الْإِيمَانَ، فَإِنْ أَعِشْ فَسَأُبَيِّنُهَا لَكُمْ حَتَّى تَعْمَلُوا بِهَا، وَإِنْ أَمُتْ فَمَا أَنَا عَلَى صُحْبَتِكُمْ بِحَرِيصٍ. وَقَالَ إِبْرَاهِيمُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ {وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي} وَقَالَ مُعَاذُ بْنُ جَبَلٍ: اجْلِسْ بِنَا نُؤْمِنْ سَاعَةً، وَقَالَ ابْنُ مَسْعُودٍ: الْيَقِينُ الْإِيمَانُ كُلُّهُ، وَقَالَ ابْنُ عُمَرَ: لَا يَبْلُغُ الْعَبْدُ حَقِيقَةَ التَّقْوَى حَتَّى يَدَعَ مَا حَاكَ فِي الصَّدْرِ، وَقَالَ مُجَاهِدٌ: {شَرَعَ لَكُمْ مِنَ الدِّينِ} أَوْصَيْنَاكَ يَا مُحَمَّدُ وَإِيَّاهُ دِينًا وَاحِدًا، وَقَالَ ابْنُ عَبَّاسٍ: {شِرْعَةً وَمِنْهَاجًا} سَبِيلًا وَسُنَّةً {دُعَاؤُكُمْ} إِيمَانُكُمْ لِقَوْلِهِ عَزَّ وَجَلَّ {قُلْ مَا يَعْبَأُ بِكُمْ رَبِّي لَوْلَا دُعَاؤُكُمْ} وَمَعْنَى الدُّعَاءِ فِي اللُّغَةِ الْإِيمَانُ. (خ)', 'ഇസ്ലാം നിർമ്മിക്കപ്പെട്ടത് അഞ്ച് തൂണുകളിലാണെന്ന നബി(സ)യുടെ പ്രസ്താവന. "വിശ്വാസം വാക്കും പ്രവർത്തിയും കൂടിയിട്ടുള്ളതാണ്. അത് കൂടുകയും കുറയുകയും ചെയ്യും." അല്ലാഹു പറയുന്നു: "അവരുടെ വിശ്വാസത്തോടൊപ്പം അവർക്ക് വിശ്വാസം വർദ്ധിക്കുവാൻ" നാം അവർക്ക് സന്മാർഗ്ഗം വർദ്ധിപ്പിക്കും" "സന്മാർഗ്ഗം സിദ്ധിച്ചവർക്ക് അല്ലാഹു മാർഗ്ഗദശനം വർദ്ധിപ്പിക്കും" "സന്മാർഗ്ഗം സിദ്ധിച്ചവർക്ക് അല്ലാഹു മാർഗ്ഗദർശനം വർദ്ധിപ്പിക്കുകയും സൂക്ഷ്മതാബോധം നൽകുകയും ചെയ്യും." "വിശ്വാസികൾക്ക് കൂടുതൽ കൂടുതൽ വിശ്വാസം കൈവരാൻ വേണ്ടി" അല്ലാഹു വീണ്ടും പറയുന്നു: "ഇത് നിങ്ങളിൽ ആർക്കാണ് വിശ്വാസം വർദ്ധിപ്പിക്കുക? എന്നാൽ സത്യവിശ്വാസികൾക്ക് ഇത് വിശ്വാസം വർദ്ധിപ്പിച്ചിരിക്കുന്നു." അല്ലാഹുവിന്റെ പ്രസ്താവന: "നിങ്ങൾ അവരെ (ശത്രുക്കളെ) ഭയപ്പെടുക (എന്ന് പറഞ്ഞപ്പോൾ) അവർക്കത് വിശ്വാസം വർദ്ധിപ്പിക്കുകയാണ് ചെയ്തത്" അല്ലാഹുവിന്റെ വചനം: "അത് (മർദ്ദനം) സത്യവിശ്വാസികൾക്ക് അവരുടെ വിശ്വാസവും അനുസരണവും വർദ്ധിപ്പിച്ചുകൊടുക്കുക മാത്രമാണ് ചെയ്തത്" അല്ലാഹുവിന്റെ പേരിൽ സ്നേഹിക്കലും അല്ലാഹുവിന്റെ പേരിൽ കോപിക്കലും സത്യവിശ്വാസത്തിൽപ്പെട്ടതാണ്. ഉമറുബ്നു അബ്ദുൽ അസീസ്, അദിയ്യുബ്നു അദിയ്യിന് എഴുതി: നിശ്ചയം! വിശ്വാസത്തിന് ചില നിർബന്ധ കടമകളും, നിയമവ്യവസ്ഥകളും, പരിധികളും, സുന്നത്തുക(ചര്യകൾ) ളുമുണ്ട് അവയെ പൂർത്തീകരിച്ചവൻ, വിശ്വാസത്തെ സമ്പൂർണ്ണമാക്കി. അവയെ പൂർത്തീകരിക്കാത്തവൻ വിശ്വാസത്തെ പൂർണ്ണമാക്കിയില്ല. ഞാൻ ജീവിക്കുകയാണെങ്കിൽ നിങ്ങൾക്ക് പ്രവർത്തിക്കാനുതകുംവിധം അവ വിശദീകരിക്കുന്നതാണ്. ഇനി ഞാൻ മരിക്കുകയാണെങ്കിൽ നിങ്ങളോടൊപ്പം ജീവിച്ചിരിക്കാൻ ഞാൻ അത്യാഗ്രഹമുള്ളവനല്ല.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا مِنَ الْيَهُودِ قَالَ لَهُ: يَا أَمِيرَ الْمُؤْمِنِينَ! آيَةٌ فِي كِتَابِكُمْ تَقْرَءُونَهَا، لَوْ عَلَيْنَا مَعْشَرَ الْيَهُودِ نَزَلَتْ لَاتَّخَذْنَا ذَلِكَ الْيَوْمَ عِيدًا، قَالَ: أَيُّ آيَةٍ؟ قَالَ: {الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا}، قَالَ عُمَرُ: قَدْ عَرَفْنَا ذَلِكَ الْيَوْمَ، وَالْمَكَانَ الَّذِي نَزَلَتْ فِيهِ عَلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ قَائِمٌ بِعَرَفَةَ يَوْمَ جُمُعَةٍ. (ق,ت,ن)', 'ഉമർ(റ): ജൂതനായ ഒരാൾ അദ്ദേഹത്തോട് പറഞ്ഞു: അമീറുൽ മുഅ്മിനീൻ നിങ്ങളുടെ വേദഗ്രന്ഥത്തിൽ നിങ്ങൾ പാരായണം ചെയ്യുന്ന ഒരു വചനം; ഞങ്ങൾ ജൂതന്മാർക്കാണതവതരിച്ചിരുന്നതെങ്കിൽ ആ ദിനം ഞങ്ങൾ ആഘോഷ ദിവസമാക്കുമായിരുന്നു. അദ്ദേഹം ചോദിച്ചു: ഏത് വചനം? അയാൾ പറഞ്ഞു: "ഇന്ന് നിങ്ങൾക്ക് നാം നിങ്ങളുടെ മതം സമ്പൂർണ്ണമാക്കിത്തരികയും എന്റെ അനുഗ്രഹം നിങ്ങളുടെ മേൽ പൂർത്തീകരിക്കുകയും ഇസ്ലാമിനെ നിങ്ങൾക്കുള്ള മതമായി നാം തൃപ്തിപ്പെടുകയും ചെയ്തിരിക്കുന്നു." എന്ന വചനം. ഉമർ(റ) പറഞ്ഞു: നബി(സ)ക്ക് ആ വചനമിറങ്ങിയ സ്ഥലവും ദിവസവും ഞങ്ങൾക്കറിയാം. നബി(സ) വെള്ളിയാഴ്ച അറഫയിൽ നിൽക്കുമ്പോഴായിരുന്നു അത് ഇറങ്ങിയത്. (ബു,മു,തു,ന)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമർ(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 111, 111, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ مِنْ أَكْمَلِ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا وَأَلْطَفُهُمْ بِأَهْلِهِ". (د,ت)', 'ആഇശ(റ): നബി(സ) അരുളി: "സത്യവിശ്വാസികളിൽ വിശ്വാസം സമ്പൂർണ്ണമായവർ, ഏറ്റവും നല്ല സ്വഭാവമുള്ളവരും സ്വന്തം ഭാര്യയോടു (കുടുംബത്തോടു) ഏറ്റവും അനുകമ്പയുള്ളവരുമത്രെ." (ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 111, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ، وَلَا يَسْرِقُ السَّارِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ، وَلَكِنَّ التَّوْبَةَ مَعْرُوضَةٌ". قَالَ ترمدي هذا حديث حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: ഒരു വ്യഭിചാരി അവൻ വ്യഭിചരിക്കുന്ന സന്ദർഭത്തിൽ സത്യവിശ്വാസിയായിക്കൊണ്ട് വ്യഭിചരിക്കുകയില്ല. ഒരു മോഷ്ടാവ് അവൻ മോഷ്ടിക്കുന്ന അവസരത്തിൽ സത്യവിശ്വാസിയായിക്കൊണ്ട് മോഷ്ടിക്കുകയില്ല. എന്നാൽ പശ്ചാത്താപം സ്വീകരിക്കപ്പെടുന്നതാണ്. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَطَبَ النَّاسَ فَوَعَظَهُمْ ثُمَّ قَالَ: "يَا مَعْشَرَ النِّسَاءِ! تَصَدَّقْنَ، فَإِنَّكُنَّ أَكْثَرُ أَهْلِ النَّارِ" فَقَالَتِ امْرَأَةٌ مِنْهُنَّ: وَلِمَ ذَاكَ يَا رَسُولَ اللهِ؟ قَالَ: "لِكَثْرَةِ لَعْنِكُنَّ يَعْنِي وَكُفْرِكُنَّ الْعَشِيرَ" قَالَ: "وَمَا رَأَيْتُ مِنْ نَاقِصَاتِ عَقْلٍ وَدِينٍ أَغْلَبَ لِذَوِي الْأَلْبَابِ وَذَوِي الرَّأْيِ مِنْكُنَّ". قَالَتِ امْرَأَةٌ مِنْهُنَّ: وَمَا نُقْصَانُ دِينِهَا وَعَقْلِهَا؟ قَالَ: "شَهَادَةُ امْرَأَتَيْنِ مِنْكُنَّ بِشَهَادَةِ رَجُلٍ، وَنُقْصَانُ دِينِكُنَّ الْحَيْضَةُ، تَمْكُثُ إِحْدَاكُنَّ الثَّلَاثَ وَالْأَرْبَعَ لَا تُصَلِّي". (ت)', 'അബുഹുറൈറ(റ): നിശ്ചയം നബി(സ) ജനങ്ങളോടു പ്രസംഗിക്കുകയും അവരെ ഉപദേശിക്കുകയും ചെയ്തു. പിന്നെ പറഞ്ഞു: "സ്ത്രീ സമൂഹമേ! നിങ്ങൾ ദാനധർമ്മം ചെയ്യുക. കാരണം നരകവാസികളിൽ അധികവും നിങ്ങളാണ്." അപ്പോൾ അവരിൽ നിന്ന് ഒരു സ്ത്രീ ചോദിച്ചു: തിരുദൂതരേ, അത് എന്തുകൊണ്ടാണ്? നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ശാപവാക്കുകളും ഭർത്താവിനോടുള്ള നന്ദികേടും കൂടുതലായതിനാലാണ്." തുടർന്ന് പറഞ്ഞു: "ബുദ്ധിയും മതവും പരിമിതമായ വിഭാഗങ്ങളിൽ നിന്ന് നിങ്ങളേക്കാൾ ബുദ്ധിയുള്ളവരെയും കാഴ്ചപാടുള്ളവരെയും അതിജയിക്കുന്ന മറ്റാരെയും ഞാൻ കണ്ടിട്ടില്ല." ഒരു സ്ത്രീ ചോദിച്ചു: ദീനിലും ബുദ്ധിയിലുമുള്ള ന്യൂനത എന്നാൽ എന്താണ്? നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ രണ്ടുപേരുടെ സാക്ഷ്യം ഒരു പുരുഷന്റെ സാക്ഷ്യത്തിന്റെ സ്ഥാനത്താകുന്നതേയുള്ളൂ. നിങ്ങളുടെ ദീനിലുള്ള ന്യൂനത ആർത്തവമാകുന്നു. നിങ്ങളിൽ നിന്ന് ഓരോരുത്തരും മൂന്നോ നാലോ ദിവസം നിസ്കരിക്കാതെ കഴിഞ്ഞുകൂടുന്നുവല്ലോ." (തു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 112, 112, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا مُجَادَلَةُ أَحَدِكُمْ فِي الْحَقِّ يَكُونُ لَهُ فِي الدُّنْيَا بِأَشَدَّ مُجَادَلَةً مِنَ الْمُؤْمِنِينَ لِرَبِّهِمْ فِي إِخْوَانِهِمُ الَّذِينَ أُدْخِلُوا النَّارَ، قَالَ: يَقُولُونَ: رَبَّنَا! إِخْوَانُنَا، كَانُوا يُصَلُّونَ مَعَنَا وَيَصُومُونَ مَعَنَا وَيَحُجُّونَ مَعَنَا، فَأَدْخَلْتَهُمُ النَّارَ؟ قَالَ: فَيَقُولُ: اذْهَبُوا، فَأَخْرِجُوا مَنْ عَرَفْتُمْ مِنْهُمْ، قَالَ: فَيَأْتُونَهُمْ فَيَعْرِفُونَهُمْ بِصُورِهِمْ، فَمِنْهُمْ مَنْ أَخَذَتْهُ النَّارُ إِلَى أَنْصَافِ سَاقَيْهِ، وَمِنْهُمْ مَنْ أَخَذَتْهُ إِلَى كَعْبَيْهِ، فَيُخْرِجُونَهُمْ، فَيَقُولُونَ: رَبَّنَا! قَدْ أَخْرَجْنَا مَنْ أَمَرْتَنَا، قَالَ: وَيَقُولُ: أَخْرِجُوا مَنْ كَانَ فِي قَلْبِهِ وَزْنُ دِينَارٍ مِنَ الْإِيمَانِ، ثُمَّ قَالَ: مَنْ كَانَ فِي قَلْبِهِ وَزْنُ نِصْفِ دِينَارٍ، حَتَّى يَقُولَ: مَنْ كَانَ فِي قَلْبِهِ وَزْنُ ذَرَّةٍ، قَالَ أَبُو سَعِيدٍ: فَمَنْ لَمْ يُصَدِّقْ فَلْيَقْرَأْ هَذِهِ الْآيَةَ: {إِنَّ اللهَ لَا يَغْفِرُ أَنْ يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَلِكَ لِمَنْ يَشَاءُ} إِلَى: {عَظِيمًا} [النساء:٤٨] (ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "ഈ ലോകത്ത് സത്യത്തിനു വേണ്ടിയുള്ള നിങ്ങളിലൊരാളുടെയും സംവാദം, നരകത്തിൽ പ്രവേശിപ്പിക്കപ്പെട്ട തങ്ങളുടെ സഹോദരങ്ങളുടെ വിഷയത്തിൽ സത്യവിശ്വാസികൾ തങ്ങളുടെ നാഥനോട് നടത്തുന്ന സംവാദത്തേക്കാൾ ശക്തമല്ല." നബി(സ) പറഞ്ഞു: "അവർ പറയും: ഞങ്ങളുടെ നാഥാ! ഞങ്ങളുടെ സഹോദരങ്ങൾ ഞങ്ങളോടൊപ്പം നിസ്കരിക്കുകയും വ്രതമനുഷ്ഠിക്കുകയും ഹജ്ജ് ചെയ്യുകയും ചെയ്തിരുന്നു. എന്നിട്ടും നീ അവരെ നരകത്തിൽ പ്രവേശിപ്പിച്ചിരിക്കുകയാണല്ലോ? അപ്പോൾ അല്ലാഹു പറയും: "നിങ്ങൾ പോയി അവരിൽ നിന്നും നിങ്ങൾക്ക് പരിചയമുള്ളവരെ പുറത്ത് കൊണ്ടു വരിക." നിവേദകൻ പറയുന്നു: അങ്ങനെ അവർ പോകുകയും അവരുടെ രൂപം മുഖേന അവരെ തിരിച്ചറിയുകയും ചെയ്യും. അപ്പോൾ അവിടെ തണ്ടംകാലിന്റെ പകുതിയോളം നരകം പിടികൂടിയവരും ഞെരിയാണിയോളം പിടികൂടിയവരും അവരുടെ കൂട്ടത്തിലുണ്ട്. ശേഷം സത്യവിശ്വാസികൾ അവരെ പുറത്ത് കൊണ്ടുവന്ന് പറയും; ഞങ്ങളുടെ നാഥാ! നീ ഞങ്ങളോടു കൽപിച്ചവരെ ഞങ്ങൾ പുറത്തുകൊണ്ടു വന്നിരിക്കുന്നു. നിവേദകൻ പറയുന്നു: അല്ലാഹു പറയും; "ആരുടെയെങ്കിലും ഹൃദയത്തിൽ ഒരു ദീനാറിന്റെ അളവോളം വിശ്വാസമുണ്ടെങ്കിൽ നിങ്ങൾ അവനെ പുറത്ത് കൊണ്ടുവരിക." ശേഷം അല്ലാഹു പറയും; "ആരുടെയെങ്കിലും ഹൃദയത്തിൽ ഒരു ദീനാറിന്റെ പകുതിയോളം അളവ് വിശ്വാസമുണ്ടെങ്കിൽ (നിങ്ങളവനെ പുറത്തു കൊണ്ടുവരിക)" ആരുടെയെങ്കിലും ഹൃദയത്തിൽ അണുമണിതൂക്കം (വിശ്വാസമുണ്ടെങ്കിൽ) എന്ന് വരെ അല്ലാഹു പറയും." അബുസഈദ് പറഞ്ഞു: ആർക്കെങ്കിലും (ഇതിനെക്കുറിച്ച്) ദൃഢവിശ്വാസം ഇല്ലെങ്കിൽ അവൻ ഈ സൂക്തം പാരായണം ചെയ്തുകൊള്ളട്ടെ: ''നിശ്ചയം! അല്ലാഹു അവനോടു പങ്കു ചേർക്കുന്നതിനെ പൊറുത്തു കൊടുക്കുകയില്ല. അതിന് താഴെയുള്ളത് അവൻ ഉദ്ദേശിക്കുന്നവർക്ക് അവൻ പൊറുത്തു കൊടുക്കും.....'' ''ഗുരുതരമായ കുറ്റം കെട്ടിച്ചമച്ചിരിക്കുന്നു'' എന്നതുവരെ." (അന്നിസാഅ്: 48) (ന,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], 'النساء:٤٨', null, 112, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ، وَلَا يَسْرِقُ السَّارِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ، وَلَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ". وَكَانَ أَبُو هُرَيْرَةَ يُلْحِقُ مَعَهُنَّ: وَلَا يَنْتَهِبُ نُهْبَةً ذَاتَ شَرَفٍ يَرْفَعُ النَّاسُ إِلَيْهِ فِيهَا أَبْصَارَهُمْ حِينَ يَنْتَهِبُهَا وَهُوَ مُؤْمِنٌ، وَفِي حَدِيثِ هَمَّامٍ: "يَرْفَعُ إِلَيْهِ الْمُؤْمِنُونَ أَعْيُنَهُمْ فِيهَا وَهُوَ حِينَ يَنْتَهِبُهَا مُؤْمِنٌ". وَزَادَ: "وَلَا يَغُلُّ أَحَدُكُمْ حِينَ يَغُلُّ وَهُوَ مُؤْمِنٌ، فَإِيَّاكُمْ إِيَّاكُمْ". (ق,د,ت,ن,جه)', 'അബുഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വ്യഭിചാരി വ്യഭിചരിക്കുമ്പോൾ സത്യവിശ്വാസിയല്ല. മോഷ്ടിക്കുന്നവനും മോഷ്ടിക്കുമ്പോൾ സത്യവിശ്വാസിയല്ല. മദ്യപിക്കുന്നവൻ മദ്യപിക്കുമ്പോൾ സത്യവിശ്വാസിയല്ല." ജനങ്ങൾ കണ്ണുമിഴിച്ചു നോക്കിനിൽക്കവെ, വലിയ സമ്പത്ത് കൊള്ളയടിക്കുന്ന അവസരത്തിൽ കൊള്ളക്കാരൻ സത്യവിശ്വാസിയല്ല, എന്നുകൂടി അബുഹുറൈറ(റ) കൂട്ടിച്ചേർത്തിരുന്നു. ''സത്യവിശ്വാസികൾ അവരുടെ കണ്ണുകൾ ഉയർത്തി നോക്കിക്കൊണ്ടിരിക്കവെ, കൊള്ളയടിക്കുന്ന നേരം അവൻ സത്യവിശ്വാസിയല്ല.'' എന്നു ഹമ്മാമിന്റെ ഹദീസിലുണ്ട്. നിങ്ങളിലൊരാൾ വഞ്ചന ചെയ്യുകയാണെങ്കിൽ ആ അവസരത്തിൽ അവൻ സത്യവിശ്വാസിയല്ല. ആയതിനാൽ നിങ്ങൾ സൂക്ഷിക്കുക. എന്നു കൂടി അദ്ദേഹം പറഞ്ഞിട്ടുണ്ട്. (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 113, 113, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنِ ابْنِ شِمَاسَةَ الْمَهْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: حَضَرْنَا عَمْرَو بْنَ الْعَاصِ وَهُوَ فِي سِيَاقَةِ الْمَوْتِ، فَبَكَى طَوِيلًا وَحَوَّلَ وَجْهَهُ إِلَى الْجِدَارِ، فَجَعَلَ ابْنُهُ يَقُولُ: يَا أَبَتَاهُ! أَمَا بَشَّرَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِكَذَا؟ أَمَا بَشَّرَكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِكَذَا؟ قَالَ: فَأَقْبَلَ بِوَجْهِهِ فَقَالَ: إِنَّ أَفْضَلَ مَا نُعِدُّ شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللهِ، إِنِّي كُنْتُ عَلَى أَطْبَاقٍ ثَلَاثٍ، لَقَدْ رَأَيْتُنِي وَمَا أَحَدٌ أَشَدَّ بُغْضًا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنِّي، وَلَا أَحَبَّ إِلَيَّ أَنْ أَكُونَ قَدِ اسْتَمْكَنْتُ مِنْهُ فَقَتَلْتُهُ، فَلَوْ مُتُّ عَلَى تِلْكَ الْحَالِ لَكُنْتُ مِنْ أَهْلِ النَّارِ، فَلَمَّا جَعَلَ اللهُ الْإِسْلَامَ فِي قَلْبِي أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: ابْسُطْ يَمِينَكَ فَلْأُبَايِعْكَ، فَبَسَطَ يَمِينَهُ، قَالَ: فَقَبَضْتُ يَدِي قَالَ: "مَا لَكَ يَا عَمْرُو؟!" قَالَ: قُلْتُ: أَرَدْتُ أَنْ أَشْتَرِطَ، قَالَ: "تَشْتَرِطُ بِمَاذَا؟" قُلْتُ: أَنْ يُغْفَرَ لِي، قَالَ: "أَمَا عَلِمْتَ أَنَّ الْإِسْلَامَ يَهْدِمُ مَا كَانَ قَبْلَهُ، وَأَنَّ الْهِجْرَةَ تَهْدِمُ مَا كَانَ قَبْلَهَا، وَأَنَّ الْحَجَّ يَهْدِمُ مَا كَانَ قَبْلَهُ" وَمَا كَانَ أَحَدٌ أَحَبَّ إِلَيَّ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَلَا أَجَلَّ فِي عَيْنِي مِنْهُ، وَمَا كُنْتُ أُطِيقُ أَنْ أَمْلَأَ عَيْنَيَّ مِنْهُ إِجْلَالًا لَهُ، وَلَوْ سُئِلْتُ أَنْ أَصِفَهُ مَا أَطَقْتُ لِأَنِّي لَمْ أَكُنْ أَمْلَأُ عَيْنَيَّ مِنْهُ، وَلَوْ مُتُّ عَلَى تِلْكَ الْحَالِ لَرَجَوْتُ أَنْ أَكُونَ مِنْ أَهْلِ الْجَنَّةِ، ثُمَّ وَلِينَا أَشْيَاءَ مَا أَدْرِي مَا حَالِي فِيهَا، فَإِذَا أَنَا مُتُّ فَلَا تَصْحَبْنِي نَائِحَةٌ وَلَا نَارٌ، فَإِذَا دَفَنْتُمُونِي فَشُنُّوا عَلَيَّ التُّرَابَ شَنًّا، ثُمَّ أَقِيمُوا حَوْلَ قَبْرِي قَدْرَ مَا تُنْحَرُ جَزُورٌ وَيُقْسَمُ لَحْمُهَا، حَتَّى أَسْتَأْنِسَ بِكُمْ وَأَنْظُرَ مَاذَا أُرَاجِعُ بِهِ رُسُلَ رَبِّي. (م)', 'ഇബ്നുശിമാസതുൽ മഹ്രി(റ): അംറുബ്നുൽ ആസ്(റ) മരണാസന്നനായിരിക്കെ ഞങ്ങൾ അദ്ദേഹത്തെ സന്ദർശിച്ചു. അദ്ദേഹം കുറേ കരഞ്ഞു. മുഖം ചുമരിനോട് ചേർത്തുവെച്ചു. മകൻ ഇങ്ങനെ പറയുന്നുണ്ടായിരുന്നു; ഉപ്പാ, അല്ലാഹുവിന്റെ റസൂൽ നിങ്ങൾക്ക് എന്തൊക്കെ വാഗ്ദാനങ്ങൾ ചെയ്തിട്ടുണ്ട്. അങ്ങനെയും ഇങ്ങനെയും എന്തെല്ലാം! റിപ്പോർട്ടർ പറയുന്നു: അംറ്(റ) മുഖം തിരിച്ച് പറഞ്ഞു: നാം കണക്കാക്കുന്നതിൽ ഏറ്റവും ശ്രേഷ്ഠം ''ലാ ഇലാഹ ഇല്ലല്ലാഹ്, മുഹമ്മദുർറസുലുല്ലാഹ്'' എന്ന സത്യസാക്ഷ്യം തന്നെ. എന്നാൽ എനിക്ക് മൂന്ന് ഘട്ടങ്ങൾ ഉണ്ടായിട്ടുണ്ട്. ഒരു ഘട്ടത്തിൽ, നബി(സ)യോട് ഏറ്റം വിദ്വേഷമുള്ളവനായിരുന്നു ഞാൻ. സൗകര്യപ്പെട്ടാൽ അവിടുത്തെ കൊന്ന് കളയുകയായിരുന്നു എനിക്കേറ്റം ഇഷ്ടം. ആ അവസ്ഥയിൽ ഞാൻ മരണപ്പെടുകയാണെങ്കിൽ ഞാൻ നരകവാസികളിലാകുമായിരുന്നേനെ! എന്നാൽ, അല്ലാഹു എന്റെ ഹൃദയത്തിൽ ഇസ്ലാം നിക്ഷേപിച്ചതോടെ ഞാൻ നബി(സ)യുടെ അടുത്തുചെന്ന് പറഞ്ഞു: കൈ നീട്ടൂ! ഞാൻ ബൈഅത്ത് ചെയ്യട്ടെ! അവിടുന്ന് കൈ നീട്ടി. പക്ഷേ, ഞാൻ എന്റെ കൈ നീട്ടിയില്ല. പിടിച്ചു വെച്ചു. അപ്പോൾ പ്രവാചകൻ ചോദിച്ചു: " നിനക്ക് എന്തു പറ്റി അംറേ?" ഞാൻ പറഞ്ഞു: എനിക്കൊരു നിബന്ധനയുണ്ട്. നബി(സ) പറഞ്ഞു: "എന്ത് നിബന്ധന?" ഞാൻ പറഞ്ഞു: എന്റെ തെറ്റുകൾ പൊറുക്കപ്പെടണം. നബി(സ) പറഞ്ഞു: "ഇസ്ലാമും, ഹിജ്റയും ഹജ്ജും അവക്ക് മുമ്പുണ്ടായവയെ പൊളിച്ചുകളയുമെന്ന് നിനക്കറിയില്ലേ?" (അന്നുമുതൽ) നബി(സ)യേക്കാൾ ഇഷ്ടമോ മഹത്വമോ ഞാനാർക്കും നൽകിയിട്ടില്ല. അവിടത്തോടുള്ള ആദരവ് നിമിത്തം കൺനിറയെ ഒന്നുനോക്കാൻ പോലും എനിക്ക് കഴിഞ്ഞിരുന്നില്ല. ആരെങ്കിലും അവിടുത്തെ വർണ്ണിക്കാൻ ആവശ്യപ്പെട്ടാൽ എനിക്ക് സാധിക്കുമായിരുന്നില്ല; കാരണം ഞാൻ നബിയെ കൺനിറയെ കണ്ടിട്ടുണ്ടായിരുന്നില്ല. ആ അവസ്ഥയിൽ ഞാൻ മരണപ്പെട്ടിരുന്നെങ്കിൽ ഞാൻ സ്വർഗ്ഗവാസികളിൽ ഉൾപ്പെടുമെന്ന് എനിക്ക് പ്രതീക്ഷയുണ്ടായിരുന്നു. പിന്നീട് നാം പലകാര്യങ്ങളും ഏറ്റെടുത്തു. അപ്പോഴുള്ള എന്റെ കഥയെന്തായിരിക്കുമെന്ന് എനിക്കറിയില്ല. (ഏതായാലും) ഞാൻ മരിച്ചാൽ (ജാഹിലിയ്യാ: കാലത്ത് ചെയ്തിരുന്നപോലെ) തീയിനെയോ അലമുറയിടുന്ന പെണ്ണിനേയോ എനിക്കൊപ്പം കൊണ്ടുവരരുത്. എന്നെ മറവ് ചെയ്താൽ എന്റെ (ഖബറിനു)മേൽ മണ്ണ് കോരിയിടുക. തുടർന്ന് ഒരു ഒട്ടകത്തെ അറുത്ത് അതിന്റെ മാംസം വീതിക്കാനാവശ്യമായ സമയം നിങ്ങൾ എന്റെ ഖബറിന്റെ ചാരത്ത് നില്ക്കുക. നിങ്ങൾ കാരണമായി എനിക്ക് ഉല്ലാസം കിട്ടാനും എന്റെ നാഥന്റെ ദൂതരോട് (മലക്കുകൾ) എന്ത് ഉത്തരം പറയണമെന്ന് മനസ്സിലാക്കാനും വേണ്ടി. (മു)', 'ابْنِ شِمَاسَةَ الْمَهْرِيِّ', 'ഇബ്നുശിമാസതുൽ മഹ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 113, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا أَسْلَمَ الْعَبْدُ فَحَسُنَ إِسْلَامُهُ يُكَفِّرُ اللهُ عَنْهُ كُلَّ سَيِّئَةٍ كَانَ زَلَفَهَا، وَكَانَ بَعْدَ ذَلِكَ الْقِصَاصُ، الْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةِ ضِعْفٍ، وَالسَّيِّئَةُ بِمِثْلِهَا إِلَّا أَنْ يَتَجَاوَزَ اللهُ عَنْهَا". (خ,ن)', 'അബൂസഈദുൽഖുദ്രി(റ): നബി(സ) പറയുന്നതായി കേട്ടു: "ഒരടിമ നിഷ്കളങ്കമായി ഇസ്ലാം സ്വീകരിച്ചാൽ അതിനുമുമ്പ് വന്നുപോയ പാപങ്ങൾ അല്ലാഹു പൊറുത്തുകൊടുക്കും. അതിനുശേഷം പ്രതിക്രിയയാണുണ്ടാകുക. നന്മക്ക് അതിന്റെ പത്തിരട്ടി മുതൽ എഴുനൂറിരട്ടി വരെയും, തിന്മക്കും അല്ലാഹു ഒഴിവാക്കിത്തന്നില്ലെങ്കിൽ അതിനു തുല്യമായും പ്രതിഫലം ലഭിക്കും." (ബു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽഖുദ്രി(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 114, 114, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ أُنَاسٌ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللهِ! أَنُؤَاخَذُ بِمَا عَمِلْنَا فِي الْجَاهِلِيَّةِ؟ قَالَ: "أَمَّا مَنْ أَحْسَنَ مِنْكُمْ فِي الْإِسْلَامِ فَلَا يُؤَاخَذُ بِهَا، وَمَنْ أَسَاءَ أُخِذَ بِعَمَلِهِ فِي الْجَاهِلِيَّةِ وَالْإِسْلَامِ". (ق,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഒരുകൂട്ടമാളുകൾ നബി(സ)യോട് ചോദിച്ചു: പ്രവാചകരേ! അജ്ഞാന (ജാഹിലിയ്യാ) കാലത്ത് ചെയ്തതിന്റെ പേരിൽ ഞങ്ങൾ ശിക്ഷിക്കപ്പെടുമോ? നബി(സ) പറഞ്ഞു: "ഇസ്ലാമിൽ സുകൃതം ചെയ്തവൻ മുൻ പ്രവർത്തികളുടെ പേരിൽ ശിക്ഷിക്കപ്പെടുകയില്ല. എന്നാൽ (ഇസ്ലാമിൽ വന്ന ശേഷവും) ആരെങ്കിലും ദുർനടപ്പിലായാൽ അജ്ഞാന കാലത്തും ഇസ്ലാമിലും ചെയ്ത പ്രവർത്തനങ്ങളുടെ പേരിൽ അയാൾ ശിക്ഷിക്കപ്പെടും." (ബു,മു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيْ رَسُولَ اللهِ! أَرَأَيْتَ أُمُورًا كُنْتُ أَتَحَنَّثُ بِهَا فِي الْجَاهِلِيَّةِ مِنْ صَدَقَةٍ أَوْ عَتَاقَةٍ أَوْ صِلَةِ رَحِمٍ، أَفِيهَا أَجْرٌ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَسْلَمْتَ عَلَى مَا أَسْلَفْتَ مِنْ خَيْرٍ". (ق)', 'ഹകീമുബ്നു ഹിസാം(റ): അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു: നബിയെ! അജ്ഞാന കാലത്ത് ഞാൻ ആരാധനയായി ചെയ്ത ദാനധർമങ്ങൾ, അടിമത്ത മോചനം, കുടുംബബന്ധം ചേർക്കൽ തുടങ്ങിയ പ്രവർത്തനങ്ങളെ സംബന്ധിച്ച് അങ്ങെന്തു പറയുന്നു? അതിൽ പ്രതിഫലമുണ്ടോ? നബി(സ) പറഞ്ഞു: "മുമ്പുചെയ്ത നന്മകളുമായാണ് നീ ഇസ്ലാം സ്വീകരിച്ചത്." (ബു,മു)', 'حَكِيمِ بْنِ حِزَامٍ', 'ഹകീമുബ്നു ഹിസാം(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ عَائِشَةَ قَالَتْ رَضِيَ اللهُ عَنْهَا: قُلْتُ: يَا رَسُولَ اللهِ! ابْنُ جُدْعَانَ كَانَ فِي الْجَاهِلِيَّةِ يَصِلُ الرَّحِمَ، وَيُطْعِمُ الْمِسْكِينَ، فَهَلْ ذَاكَ نَافِعُهُ؟ قَالَ: "لَا يَنْفَعُهُ، إِنَّهُ لَمْ يَقُلْ يَوْمًا: رَبِّ اغْفِرْ لِي خَطِيئَتِي يَوْمَ الدِّينِ". (م)', 'ആഇശ(റ): ഞാൻ ചോദിച്ചു: നബിയേ! ഇബ്നുജുദ്ആൻ അജ്ഞാന കാലഘട്ടത്തിൽ കുടുംബബന്ധം പുലർത്തുകയും അഗതികളെ ഭക്ഷിപ്പിക്കുകയും ചെയ്തിരുന്നു. അത് അദ്ദേഹത്തിന് പ്രയോജനപ്പെടുമോ? നബി(സ) പറഞ്ഞു: "അത് അദ്ദേഹത്തിന് പ്രയോജനപ്പെടുകയില്ല. കാരണം അവൻ ഒരിക്കൽപോലും; എന്റെ നാഥാ! പ്രതിഫലദിനം എന്റെ പാപങ്ങൾ എനിക്ക് നീ പൊറുത്തു തരേണമേ! എന്ന് പറഞ്ഞിട്ടില്ല." (മു)', 'عَائِشَةَ قَالَتْ', 'ആഇശ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: مَنْ يَقُمْ لَيْلَةَ الْقَدْرِ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ. (خ)', 'അബൂഹുറൈറ(റ): പ്രവാചകർ(സ) പറഞ്ഞു: വല്ലവനും വിശ്വാസത്തോടെയും പ്രതിഫലേച്ഛയോടെയും ലൈലത്തുൽ ഖദ്റിൽ(നിർണ്ണിത രാത്രിയിൽ) നിസ്കരിച്ചാൽ അവന്ന് തന്റെ മുൻകഴിഞ്ഞ പാപങ്ങൾ അല്ലാഹു പൊറുത്തു കൊടുക്കുന്നതാണ്. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ حديث إِنَّمَا الْأَعْمَالُ بِالنِّيَّاتِ....، وَإِنَّمَا لِكُلِّ امْرِئٍ مَا نَوَى فَمَنْ كَانَتْ هِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ فَهِجْرَتُهُ إِلَى اللهِ وَرَسُولِهِ، وسرد باقي الحديث. (خ)', 'ഉമർ(റ): നിശ്ചയം കർമ്മങ്ങൾക്ക് പ്രതിഫലം ലഭിക്കുക അവയുടെ ഉദ്ദേശങ്ങൾക്കനുസരിച്ചു മാത്രമാണ്..... നിശ്ചയം ഓരോ വ്യക്തിക്കും അവൻ ഉദ്ദേശിച്ചത് മാത്രമാണ് (കർമ്മത്തിന്റെ പ്രതിഫലമായി) ഉണ്ടാകുക. വല്ലവന്റെയും ഹിജ്റ അല്ലാഹുവിലേക്കും അവന്റെ ദൂതനിലേക്കുമാണെങ്കിൽ അത് അപ്രകാരം തന്നെ ആയിരിക്കും. ഹദീസ് തുടർന്നു പറഞ്ഞു...... (ബു)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 115, 115, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ زُبَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ أَبَا وَائِلٍ عَنِ الْمُرْجِئَةِ، فَقَالَ: حَدَّثَنِي عَبْدُاللهِ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سِبَابُ الْمُسْلِمِ فُسُوقٌ، وَقِتَالُهُ كُفْرٌ". (ق,ت,ن,جه)', 'സുബൈദ്(റ): മുർജിഅഃ വിഭാഗത്തെക്കുറിച്ച് അബൂവാഇലിനോട് ഞാൻ ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറഞ്ഞതായി അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) പറഞ്ഞു: "മുസ്ലിമിനെ ശകാരിക്കൽ അധർമ്മവും അവനോടു യുദ്ധം ചെയ്യൽ സത്യനിഷേധവുമാണ്." (ബു,മു,തു,ന,ജ)', 'زُبَيْدٍ', 'സുബൈദ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنِ الْمَعْرُورِ بْنِ سُوَيْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَرْنَا بِأَبِي ذَرٍّ بِالرَّبَذَةِ وَعَلَيْهِ بُرْدٌ وَعَلَى غُلَامِهِ مِثْلُهُ، فَقُلْنَا: يَا أَبَا ذَرٍّ! لَوْ جَمَعْتَ بَيْنَهُمَا كَانَتْ حُلَّةً، – وَفِي رِوَايَةٍ: فَقَالَ الْقَوْمُ: يَا أَبَا ذَرٍّ! لَوْ كُنْتَ أَخَذْتَ الَّذِي عَلَى غُلَامِكَ فَجَعَلْتَهُ مَعَ هَذَا فَكَانَتْ حُلَّةً وَكَسَوْتَ غُلَامَكَ ثَوْبًا غَيْرَهُ؟ – فَقَالَ: إِنَّهُ كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنْ إِخْوَانِي كَلَامٌ، وَكَانَتْ أُمُّهُ أَعْجَمِيَّةً، فَعَيَّرْتُهُ بِأُمِّهِ، فَشَكَانِي إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَلَقِيتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أَبَا ذَرٍّ! إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ"، قُلْتُ: يَا رَسُولَ اللهِ! مَنْ سَبَّ الرِّجَالَ سَبُّوا أَبَاهُ وَأُمَّهُ، قَالَ: "يَا أَبَا ذَرٍّ! إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ، هُمْ إِخْوَانُكُمْ جَعَلَهُمُ اللهُ تَحْتَ أَيْدِيكُمْ، فَأَطْعِمُوهُمْ مِمَّا تَأْكُلُونَ، وَأَلْبِسُوهُمْ مِمَّا تَلْبَسُونَ، وَلَا تُكَلِّفُوهُمْ مَا يَغْلِبُهُمْ، فَإِنْ كَلَّفْتُمُوهُمْ فَأَعِينُوهُمْ". (ق,د)', 'മഅ്റൂറുബ്നു സുവൈദ്(റ): ഞങ്ങൾ റബദയിൽ വെച്ച് അബൂദർറി(റ)ന്റെയരികിലൂടെ നടക്കുകയായിരുന്നു. അദ്ദേഹവും അദ്ദേഹത്തിന്റെ അടിമയും ഒരേതരം വരയുള്ള വസ്ത്രമാണ് ധരിച്ചിട്ടുള്ളത്. ഞങ്ങൾ പറഞ്ഞു: അബൂദർറ്! ഇതുരണ്ടും ചേർത്താൽ ഒരു മുഴുവസ്ത്രം ലഭിക്കുമല്ലോ! - അബൂദാവൂദിന്റെ റിപ്പോർട്ട് പ്രകാരം: ജനങ്ങൾ പറഞ്ഞു: അബൂദർറ്! അടിമയുടെ വസ്ത്രമെടുത്ത് ഇതിനോട് ചേർത്താൽ ഒരു മുഴുവസ്ത്രം ലഭിക്കുമല്ലോ! അടിമക്ക് മറ്റൊരു വസ്ത്രം നൽകിയാൽ പോരേ? - അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാനും എന്റെ കൂട്ടുകാരിലൊരാളും തമ്മിൽ ഒരു സംസാരമുണ്ടായി. അദ്ദേഹത്തിന്റെ ഉമ്മ അനറബിയായിരുന്നു. അയാളുടെ ഉമ്മയെ ചൂണ്ടിക്കാട്ടി ഞാൻ അയാളെ ആക്ഷേപിച്ചു. അയാൾ എന്നെക്കുറിച്ച് നബി(സ)യോട് പരാതിപ്പെട്ടു. അങ്ങനെ ഞാൻ നബി(സ)യെ കണ്ടപ്പോൾ അവിടുന്ന് എന്നോട് പറഞ്ഞു. "അബൂദർറ്! അജ്ഞാന കാലത്തെ ചില ദുർഗ്ഗുണങ്ങൾ അവശേഷിച്ച വ്യക്തിയാണല്ലോ നീ!" ഞാൻ പറഞ്ഞു: നബിയേ! ആരെങ്കിലും ആളുകളെ ചീത്തപറഞ്ഞാൽ അവർ അയാളുടെ മാതാപിതാക്കളെയും പറയാറുണ്ടല്ലോ? നബി(സ) പറഞ്ഞു: "അബൂദർറ്! അജ്ഞാനകാലത്തെ ചില ദുർഗ്ഗുണങ്ങൾ അവശേഷിച്ച വ്യക്തിയാണല്ലോ നീ! അവർ നിങ്ങളുടെ സഹോദരന്മാരാണ്. അല്ലാഹു അവരെ നിങ്ങളുടെ നിയന്ത്രണത്തിനും കീഴിലാക്കിയിരിക്കുന്നു (എന്നേയുള്ളൂ). ആയതിനാൽ നീ ഭക്ഷിക്കുന്നതിൽ നിന്നുതന്നെ അവന്ന് ഭക്ഷിക്കാൻ കൊടുക്കുക. നീ ധരിക്കുന്ന അതേതരം വസ്ത്രം അവനും ധരിക്കാൻ കൊടുക്കുക. അവർക്ക് അസാധ്യമായ ജോലികളൊന്നും അവരെ ഏൽപ്പിക്കരുത്. ഇനി നിങ്ങൾ വിഷമകരമായ ജോലി എന്തെങ്കിലും അവരെ ഏൽപിച്ചാൽ നിങ്ങൾ അവരെ സഹായിക്കണം." (ബു,മു,ദ)', 'الْمَعْرُورِ بْنِ سُوَيْدٍ', 'മഅ്റൂറുബ്നു സുവൈദ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=9 and h.hadith_no=104), 1, 'وَفِي رِوَايَةٍ: فَقَالَ الْقَوْمُ: يَا أَبَا ذَرٍّ! لَوْ كُنْتَ أَخَذْتَ الَّذِي عَلَى غُلَامِكَ فَجَعَلْتَهُ مَعَ هَذَا فَكَانَتْ حُلَّةً وَكَسَوْتَ غُلَامَكَ ثَوْبًا غَيْرَهُ؟ – فَقَالَ: إِنَّهُ كَانَ بَيْنِي وَبَيْنَ رَجُلٍ مِنْ إِخْوَانِي كَلَامٌ، وَكَانَتْ أُمُّهُ أَعْجَمِيَّةً، فَعَيَّرْتُهُ بِأُمِّهِ، فَشَكَانِي إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَلَقِيتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "يَا أَبَا ذَرٍّ! إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ"، قُلْتُ: يَا رَسُولَ اللهِ! مَنْ سَبَّ الرِّجَالَ سَبُّوا أَبَاهُ وَأُمَّهُ، قَالَ: "يَا أَبَا ذَرٍّ! إِنَّكَ امْرُؤٌ فِيكَ جَاهِلِيَّةٌ، هُمْ إِخْوَانُكُمْ جَعَلَهُمُ اللهُ تَحْتَ أَيْدِيكُمْ، فَأَطْعِمُوهُمْ مِمَّا تَأْكُلُونَ، وَأَلْبِسُوهُمْ مِمَّا تَلْبَسُونَ، وَلَا تُكَلِّفُوهُمْ مَا يَغْلِبُهُمْ، فَإِنْ كَلَّفْتُمُوهُمْ فَأَعِينُوهُمْ". (ق,د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا يَدْخُلُ الْجَنَّةَ مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ مِنْ كِبْرٍ" قَالَ رَجُلٌ: إِنَّ الرَّجُلَ يُحِبُّ أَنْ يَكُونَ ثَوْبُهُ حَسَنًا وَنَعْلُهُ حَسَنَةً؟ قَالَ: "إِنَّ اللهَ جَمِيلٌ يُحِبُّ الْجَمَالَ، الْكِبْرُ بَطَرُ الْحَقِّ وَغَمْطُ النَّاسِ". (م,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "അണുമണിത്തൂക്കം അഹങ്കാരം ഹൃദയത്തിലുള്ള ഒരാളും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല." ഒരാൾ ചോദിച്ചു: മനുഷ്യൻ തന്റെ വസ്ത്രവും പാദരക്ഷയും ഭംഗിയുള്ളതാകാൻ (മെച്ചമായത്) ഇഷ്ടപ്പെടുന്നു. (അതും അഹംഭാവമാണോ?). നബി(സ) പറഞ്ഞു: "അല്ലാഹു ഭംഗിയുള്ളവനും ഭംഗി ഇഷ്ടപ്പെടുന്നവനുമാണ്. സത്യത്തെ നിഷേധിക്കലും മനുഷ്യരെ നിന്ദ്യരായി കാണലുമാണ് അഹങ്കാരം. (മു,ദ,തു,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 116, 116, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَرَجَ يُخْبِرُ بِلَيْلَةِ الْقَدْرِ فَتَلَاحَى رَجُلَانِ مِنَ الْمُسْلِمِينَ فَقَالَ: إِنِّي خَرَجْتُ لِأُخْبِرَكُمْ بِلَيْلَةِ الْقَدْرِ وَإِنَّهُ تَلَاحَى فُلَانٌ وَفُلَانٌ فَرُفِعَتْ، وَعَسَى أَنْ يَكُونَ خَيْرًا لَكُمْ، الْتَمِسُوهَا فِي السَّبْعِ وَالتِّسْعِ وَالْخَمْسِ. (خ)', 'ഉബാദത്തുബിനു സാമിത്ത്(റ) പറയുന്നു: ലൈലത്തുൽ ഖദ്റിനെക്കുറിച്ചു വിവരമറിയിക്കാൻ വേണ്ടി ഒരിക്കൽ പ്രവാചകൻ(സ) പുറത്തുവന്നു. ആസന്ദർഭത്തിൽ മുസ്ലിംകളിൽപ്പെട്ട രണ്ടുപേർ തമ്മിൽ കലഹിക്കുകയായിരുന്നു. അപ്പേൾ പ്രവാചകർ(സ) പറഞ്ഞു: ഞാൻ പുറത്തുവന്നത് ലൈലത്തുൽ ഖദ്റിനെസംബന്ധിച്ച് നിങ്ങൾക്കു അറിയിച്ചുതരാൻ വേണ്ടിയാണ്. അപ്പോൾ ഇന്നവ്യക്തിയും ഇന്നവ്യക്തിയും തമ്മിൽ കലഹിക്കുകയാണ്. തന്നിമിത്തം ലൈലത്തുൽ ഖദ്റിനെ സംബന്ധിച്ച ജ്ഞാനം എന്നിൽ നിന്നും ഉയർത്തപ്പെട്ടിരിക്കുകയാണ്. ഒരു പക്ഷേ നിങ്ങൾക്കതു ഗുണകരമായിസംഭവിച്ചേക്കാം. നിങ്ങൾ അതിനെ റമദാനിലെ 27, 29, 25 രാവുകളിൽ തേടിക്കൊള്ളുക. (ബു)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദത്തുബിനു സാമിത്ത്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ ثَابِتِ بْنِ الضَّحَّاكِ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَيْسَ عَلَى الْعَبْدِ نَذْرٌ فِيمَا لَا يَمْلِكُ، وَلَاعِنُ الْمُؤْمِنِ كَقَاتِلِهِ، وَمَنْ قَذَفَ مُؤْمِنًا بِكُفْرٍ فَهُوَ كَقَاتِلِهِ، وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عَذَّبَهُ اللهُ بِمَا قَتَلَ بِهِ نَفْسَهُ يَوْمَ الْقِيَامَةِ". (خ,ت)', 'സാബിതുബ്നു ളഹ്ഹാക്(റ): നബി(സ) അരുളി: "ഉടമസ്ഥാവകാശം ഇല്ലാത്തതിൽ നേർച്ച ചെയ്യൽ ഒരു അടിമക്കും ബാധ്യതയില്ല. സത്യവിശ്വാസിയെ ശപിക്കുന്നവൻ അവന്റെ ഘാതകനെ പോലെയാണ്. ഒരു സത്യവിശ്വാസിയെ ആരെങ്കിലും സത്യനിഷേധം (കുഫ്ർ) കൊണ്ട് ആരോപിച്ചാൽ അവൻ അദ്ദേഹത്തിന്റെ (സത്യവിശ്വാസിയുടെ) ഘാതകനെപ്പോലെയാണ്. ആരെങ്കിലും വല്ല വസ്തുവും കൊണ്ട് ആത്മഹത്യ ചെയ്താൽ, അതേവസ്തു കൊണ്ട് അന്ത്യദിനത്തിൽ അല്ലാഹു അവനെ ശിക്ഷിക്കുന്നതാണ്." (ബു,തു)', 'ثَابِتِ بْنِ الضَّحَّاكِ', 'സാബിതുബ്നു ളഹ്ഹാക്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا امْرِئٍ قَالَ لِأَخِيهِ يَا كَافِرُ فَقَدْ بَاءَ بِهَا أَحَدُهُمَا، إِنْ كَانَ كَمَا قَالَ، وَإِلَّا رَجَعَتْ عَلَيْهِ". (ت)', 'ഇബ്നുഉമർ(റ): നബി(സ) അരുളി: "ആരെങ്കിലും തന്റെ സഹോദരനെ കാഫിർ (സത്യനിഷേധി) എന്ന് വിളിച്ചാൽ നിശ്ചയം അവരിരുവരിലൊരാൾ സത്യനിഷേധവുമായി മടങ്ങി. വിളിക്കപ്പെട്ടയാൾ (യഥാർത്ഥത്തിൽ) അങ്ങനെത്തന്നെയെങ്കിൽ അപ്രകാരം തന്നെ. അല്ലയെങ്കിൽ വിളിച്ചവനിലേക്ക് അത് മടങ്ങി." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُرِيتُ النَّارَ، فَإِذَا أَكْثَرُ أَهْلِهَا النِّسَاءُ يَكْفُرْنَ". قِيلَ: أَيَكْفُرْنَ بِاللهِ؟ قَالَ: "يَكْفُرْنَ الْعَشِيرَ، وَيَكْفُرْنَ الْإِحْسَانَ، لَوْ أَحْسَنْتَ إِلَى إِحْدَاهُنَّ الدَّهْرَ، ثُمَّ رَأَتْ مِنْكَ شَيْئًا قَالَتْ: مَا رَأَيْتُ مِنْكَ خَيْرًا قَطُّ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) അരുളി: "നരകം എനിക്ക് കാണിക്കപ്പെട്ടു. അതിലധികവും നിഷേധികളായ സ്ത്രീകളാണ്." അപ്പോൾ നബി(സ)യോട് ചോദിക്കപ്പെട്ടു: അവർ അല്ലാഹുവിനെയാണോ നിഷേധിക്കുന്നത്? നബി(സ) പറഞ്ഞു: "അവർ ഭർത്താക്കന്മാരെ (അവരുടെ നന്മകളെ) നിഷേധിക്കുന്നു. ആ നന്മകളോട് അവർ നന്ദികേട് കാണിക്കുന്നു. ജീവിതകാലം മുഴുവൻ നീ ഒരു സ്ത്രീക്ക് നന്മ ചെയ്തുകൊടുത്തു. എന്നിട്ട് അവളുടെ (ഹിതത്തിന് വിരുദ്ധമായ) വല്ലതും നിന്നിൽനിന്ന് അവൾ ദർശിച്ചാൽ അവൾ പറയും: നിങ്ങളിൽ നിന്ന് ഒരു നന്മയും ഞാൻ ഇതുവരെ കണ്ടിട്ടില്ല." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 117, 117, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اثْنَتَانِ فِي النَّاسِ هُمَا بِهِمْ كُفْرٌ، الطَّعْنُ فِي النَّسَبِ وَالنِّيَاحَةُ عَلَى الْمَيِّتِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) അരുളി: "ജനങ്ങളിൽ നിലനിൽക്കുന്ന രണ്ട് ശീലങ്ങൾ സത്യനിഷേധമാണ്. കുലത്തിന്റെ പേരിൽ ആക്ഷേപിക്കുന്നതും മരിച്ചവന്റെ പേരിൽ വിലപിച്ച് കരയലുമാണത്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 117, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ أَبِي عُثْمَانَ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا ادُّعِيَ زِيَادٌ لَقِيتُ أَبَا بَكْرَةَ، فَقُلْتُ لَهُ: مَا هَذَا الَّذِي صَنَعْتُمْ؟ إِنِّي سَمِعْتُ سَعْدَ بْنَ أَبِي وَقَّاصٍ يَقُولُ: سَمِعَ أُذُنَايَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَقُولُ: "مَنِ ادَّعَى أَبًا فِي الْإِسْلَامِ غَيْرَ أَبِيهِ يَعْلَمُ أَنَّهُ غَيْرُ أَبِيهِ، فَالْجَنَّةُ عَلَيْهِ حَرَامٌ". (م)', 'അബൂഉസ്മാൻ(റ): സിയാദ് (അബുസുഫ്യാന്റെ മകനാണെന്നു) വാദിക്കപ്പെട്ട സന്ദർഭത്തിൽ ഞാൻ അബുബക്റയെ കണ്ടുമുട്ടി. ഞാനദ്ദേഹത്തോടു ചോദിച്ചു: നിങ്ങളെന്താണീ ചെയ്തത്? സഅ്ദുബ്നു അബിവഖാസ് പറയുന്നത് ഞാൻ കേട്ടു: ''ഇസ്ലാമിൽ (വന്നതിനുശേഷം) ആരെങ്കിലും തന്റെ പിതാവല്ലെന്നറിഞ്ഞു കൊണ്ട് ഒരന്യനെ തന്റെ പിതാവാണെന്നു വാദിച്ചാൽ സ്വർഗ്ഗം അവന് നിഷിദ്ധമാണ്'' എന്ന് നബി(സ) പറയുന്നത് ഞാൻ എന്റെ രണ്ട് കാതുകൾകൊണ്ട് നേർക്കുനേരെ കേട്ടിട്ടുണ്ട്. (മു)', 'أَبِي عُثْمَانَ', 'അബൂഉസ്മാൻ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَيْسَ مِنْ رَجُلٍ ادَّعَى لِغَيْرِ أَبِيهِ وَهُوَ يَعْلَمُهُ إِلَّا كَفَرَ، وَمَنِ ادَّعَى مَا لَيْسَ لَهُ فَلَيْسَ مِنَّا، وَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ، وَمَنْ دَعَا رَجُلًا بِالْكُفْرِ أَوْ قَالَ عَدُوَّ اللهِ وَلَيْسَ كَذَلِكَ إِلَّا حَارَ عَلَيْهِ". (م)', 'അബൂദർറ്(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "മന:പൂർവ്വം തന്റെ പിതാവല്ലാത്ത മറ്റൊരാളെ പിതാവാക്കുന്ന ഒരാളും അവിശ്വാസിയാകാതിരിക്കില്ല. തനിക്ക് അവകാശപ്പെടാത്തത് വാദിച്ചു വാങ്ങുന്നവൻ നമ്മിൽപ്പെട്ടവനല്ല. അവൻ നരകത്തിൽ തന്റെ ഇരിപ്പിടം ഉറപ്പിച്ചുകൊള്ളട്ടെ. ആരെങ്കിലും ഒരു മനുഷ്യനെ സത്യനിഷേധിയെന്നോ, അല്ലാഹുവിന്റെ ശത്രുവെന്നോ വിളിച്ചാൽ യാഥാർത്ഥ്യം അങ്ങിനെയല്ലെങ്കിൽ വിളിച്ചവനിലേക്ക് തന്നെ അത് മടങ്ങുന്നതാണ്." (മു)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنِ الشَّعْبِيِّ عَنْ جَرِيرٍ رَضِيَ اللهُ عَنْهُمَا أَنَّهُ سَمِعَهُ يَقُولُ: أَيُّمَا عَبْدٍ أَبَقَ مِنْ مَوَالِيهِ فَقَدْ كَفَرَ حَتَّى يَرْجِعَ إِلَيْهِمْ. قَالَ: مَنْصُورٌ: قَدْ وَاللهِ رُوِيَ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَلَكِنِّي أَكْرَهُ أَنْ يُرْوَى عَنِّي هَهُنَا بِالْبَصْرَةِ. (م)', 'ശഅ്ബി(റ), ജരീർ(റ) പറയുന്നത് കേട്ടു: തന്റെ യജമാനന്മാരുടെ അടുക്കൽ നിന്നും ഓടിപ്പോകുന്ന ഏത് അടിമയും അവരിലേക്ക് മടങ്ങിച്ചെല്ലുന്നതു വരെയും സത്യനിഷേധിയായിരിക്കും. മൻസൂർ (റിപ്പോർട്ടർ) പറയുന്നു: അല്ലാഹുവാണെ, ഇത് നബി(സ)യിൽ നിന്ന് റിപ്പോർട്ട് ചെയ്യപ്പെട്ടതു തന്നെയാണ്. എന്നാൽ ഇവിടെ ബസ്വറയിൽ വെച്ച് ഇത് എന്നിൽ നിന്നും റിപ്പോർട്ട് ചെയ്യപ്പെടുന്നത് ഞാൻ വെറുക്കുന്നു. (മു)', 'الشَّعْبِيِّ عَنْ جَرِيرٍ', 'ശഅ്ബി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَبَقَ الْعَبْدُ لَمْ تُقْبَلْ لَهُ صَلَاةٌ". (م)', 'ജരീർ(റ): നബി(സ) പറഞ്ഞു: "അടിമ ഒളിച്ചോടിയാൽ അവന്റെ നിസ്കാരം സ്വീകരിക്കപ്പെടുകയില്ല." (മു)', 'جَرِيرِ بْنِ عَبْدِ اللهِ', 'ജരീർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "بَيْنَ الْكُفْرِ وَالْإِيمَانِ تَرْكُ الصَّلَاةِ". (م,د,ت,ن,جه)', 'ജാബിർ(റ): നബി(സ) പറഞ്ഞു: "സത്യനിഷേധത്തിന്റെയും സത്യവിശ്വാസത്തിന്റെയും ഇടയിലുള്ള(വ്യത്യാസം)ത് നിസ്കാരം ഉപേക്ഷിക്കലാണ്." (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 118, 118, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ تَرْكُ الصَّلَاةِ". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت)', 'ജാബിർ(റ) പ്രവാചകൻ(സ) പറഞ്ഞു: സത്യവിശ്വാസിയായ അടിമയുടെയും അവിശ്വാസത്തിന്റെയും ഇടയിലെ അന്തരം നിസ്കാരം ഉപേക്ഷിക്കലാകുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (തു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 118, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الْعَهْدُ الَّذِي بَيْنَنَا وَبَيْنَهُمُ الصَّلَاةُ، فَمَنْ تَرَكَهَا فَقَدْ كَفَرَ". قَالَ ترمدي هَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ. (ت,ن,جه)', 'ബുറൈദ(റ) പ്രവാചകൻ(സ) പറഞ്ഞു: നമുക്കും(സത്യവിശ്വാസികൾക്കും) അവർക്കും (അവിശ്വാസികൾക്കും) ഇടയിലെ വൃത്യാസം നിസ്കാരമാകുന്നു. അത് വെടിഞ്ഞവൻ തീർച്ചയായും അവിശ്വാസി ആയിരിക്കുന്നു. (ഹദിസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (തു,ന,ജ)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَبْدِ اللهِ بْنِ شَقِيقٍ الْعُقَيْلِيِّ قَالَ: كَانَ أَصْحَابُ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَرَوْنَ شَيْئًا مِنَ الْأَعْمَالِ تَرْكُهُ كُفْرٌ غَيْرَ الصَّلَاةِ. (ت)', 'അബ്ദുല്ലാഹിബ്നു ശഖീഖ്(റ): അദ്ദേഹം പറയുന്നു: ഇസ്ലാമിലെ അനുഷ്ടാനകർമ്മങ്ങളിൽ നമസ്കാരമല്ലാത്ത മറ്റൊന്നും ഉപേക്ഷിക്കുന്നത് അവിശ്വാസമായി മുഹമ്മദ് നബി(സ)യുടെ അനുചരന്മാർ കണക്കാക്കിയിരുന്നില്ല. (തു)', 'عَبْدِ اللهِ بْنِ شَقِيقٍ الْعُقَيْلِيِّ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ശഖീഖ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنِ الْأَحْنَفِ بْنِ قَيْسٍ رَضِيَ اللهُ عَنْهُ قَالَ: ذَهَبْتُ لِأَنْصُرَ هَذَا الرَّجُلَ، فَلَقِينِي أَبُو بَكْرَةَ، فَقَالَ: أَيْنَ تُرِيدُ؟ قُلْتُ: أَنْصُرُ هَذَا الرَّجُلَ، قَالَ: ارْجِعْ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا الْتَقَى الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَالْقَاتِلُ وَالْمَقْتُولُ فِي النَّارِ". فَقُلْتُ: يَا رَسُولَ اللهِ! هَذَا الْقَاتِلُ، فَمَا بَالُ الْمَقْتُولِ؟ قَالَ: "إِنَّهُ كَانَ حَرِيصًا عَلَى قَتْلِ صَاحِبِهِ". (خ)', 'അഹ്നഫുബ്നു ഖൈസ്(റ): ഞാൻ (വഴക്കിടുന്ന) ആ മനുഷ്യനെ സഹായിക്കാൻ പോകുമ്പോൾ അബൂബക്റയെ കണ്ടുമുട്ടി. അദ്ദേഹം ചോദിച്ചു: നീ എങ്ങോട്ടാണ്? ഞാൻ പറഞ്ഞു: അയാളെ സഹായിക്കാൻ. അദ്ദേഹം പറഞ്ഞു: തിരിച്ചുപോകൂ. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "രണ്ട് മുസ്ലിംകൾ വാളെടുത്ത് പരസ്പരം യുദ്ധം ചെയ്താൽ വധിച്ചവനും വധിക്കപ്പെട്ടവനും നരകത്തിലായിരിക്കും." അപ്പോൾ ഞാൻ ചോദിച്ചു: നബിയേ! ഘാതകന്റെ കാര്യം ശരി തന്നെ. കൊല്ലപ്പെട്ടവൻ എന്തു തെറ്റുചെയ്തു.? നബി(സ) അരുളി: " നിശ്ചയം, തന്റെ സഹോദരനെ കൊല്ലാൻ അവൻ അത്യാഗ്രഹമുള്ളവനായിരുന്നു." (ബു)', 'الْأَحْنَفِ بْنِ قَيْسٍ', 'അഹ്നഫുബ്നു ഖൈസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا وَعَدَ الرَّجُلُ وَيَنْوِي أَنْ يَفِيَ بِهِ فَلَمْ يَفِ بِهِ فَلَا جُنَاحَ عَلَيْهِ". (د,ت)', 'സൈദുബ്നു അർഖം(റ): നബി(സ) പറഞ്ഞു: "പൂർത്തീകരിക്കണമെന്ന് കരുതി ഒരാൾ വാഗ്ദാനം നൽകുകയും എന്നാൽ പിന്നീടത് പൂർത്തീകരിക്കാൻ സാധിക്കാതെ വരികയും ചെയ്താൽ അയാൾക്ക് (അതിന്റെ പേരിൽ) കുറ്റമില്ല." (ദ,തു)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 119, 119, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ زَيْدِ ابْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْحِ بِالْحُدَيْبِيَةِ فِي إِثْرِ السَّمَاءِ كَانَتْ مِنَ اللَّيْلِ، فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَى النَّاسِ، فَقَالَ: "هَلْ تَدْرُونَ مَاذَا قَالَ رَبُّكُمْ؟" قَالُوا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "قَالَ: أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ، فَأَمَّا مَنْ قَالَ: مُطِرْنَا بِفَضْلِ اللهِ وَرَحْمَتِهِ، فَذَلِكَ مُؤْمِنٌ بِي كَافِرٌ بِالْكَوْكَبِ، وَأَمَّا مَنْ قَالَ مُطِرْنَا بِنَوْءِ كَذَا وَكَذَا، فَذَلِكَ كَافِرٌ بِي مُؤْمِنٌ بِالْكَوْكَبِ". (م)', 'സൈദ്ബ്നു ഖാലിദുൽ ജുഹനി(റ): ഹുദൈബിയ്യയിൽ, മഴ തിമർത്തു പെയ്ത ഒരു രാത്രിക്കു പിറകെ നബി(സ) ഞങ്ങളുമായി സുബ്ഹി നിസ്കരിച്ചു. (നിസ്കാരത്തിൽനിന്ന്) വിരമിച്ച ശേഷം നബി(സ) ജനങ്ങളെ അഭിസംബോധന ചെയ്ത് പറഞ്ഞു: "ജനങ്ങളെ, നിങ്ങളുടെ നാഥൻ എന്താണ് പറഞ്ഞതെന്ന് നിങ്ങൾക്കറിയുമോ?" അവർ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് നന്നായി അറിയുന്നത്. നബി(സ) പറഞ്ഞു: "എന്റെ അടിമകളിൽ സത്യവിശ്വാസിയും സത്യനിഷേധിയും (ഈ) പ്രഭാതം അനുഭവിച്ചിരിക്കുന്നു. അല്ലാഹുവിന്റെ ഔദാര്യവും അനുഗ്രഹവും നിമിത്തം നമുക്ക് മഴ ലഭിച്ചു എന്ന് പറഞ്ഞവൻ എന്നിൽ വിശ്വസിക്കുകയും നക്ഷത്രത്തിൽ അവിശ്വസിക്കുകയും ചെയ്തവനത്രെ. ഇന്നാലിന്ന രാശി കാരണമാണ് മഴ ലഭിച്ചത് എന്ന് പറയുന്നവൻ എന്നിൽ അവിശ്വസിക്കുകയും നക്ഷത്രങ്ങളിൽ വിശ്വസിക്കുകയും ചെയ്തവനാണ്." (മു)', 'زَيْدِ ابْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദ്ബ്നു ഖാലിദുൽ ജുഹനി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 119, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ فِي حَجَّةِ الْوَدَاعِ: "وَيْحَكُمْ – أَوْ قَالَ وَيْلَكُمْ – لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ". (م)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഹജ്ജത്തുൽ വദാഇൽ നബി(സ) പറഞ്ഞു: "നിങ്ങൾക്കു നാശം, എനിക്കുശേഷം, പരസ്പരം പിരടികൾ വെട്ടുന്ന സത്യനിഷേധികളായി നിങ്ങൾ പരിണമിക്കരുത്." (മു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ عَبْدِاللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَرْبَعٌ مَنْ كُنَّ فِيهِ كَانَ مُنَافِقًا خَالِصًا، وَمَنْ كَانَتْ فِيهِ خَصْلَةٌ مِنْهُنَّ كَانَتْ فِيهِ خَصْلَةٌ مِنَ النِّفَاقِ حَتَّى يَدَعَهَا، إِذَا اؤْتُمِنَ خَانَ، وَإِذَا حَدَّثَ كَذَبَ، وَإِذَا عَاهَدَ غَدَرَ، وَإِذَا خَاصَمَ فَجَرَ". (ق,ت,ن)', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ): നബി(സ) പറഞ്ഞു: "നാല് സ്വഭാവങ്ങളുള്ളവർ യഥാർത്ഥ കപടവിശ്വാസിയായി, അതിലൊരു സ്വഭാവമുള്ളവനിൽ അതൊഴിവാക്കുന്നതുവരെ കാപട്യത്തിൽ നിന്നൊരംശമുണ്ട്. വിശ്വസിച്ചാൽ വഞ്ചിക്കുക, സംസാരിച്ചാൽ കളവ് പറയുക, കരാറിലേർപ്പെട്ടാൽ ലംഘിക്കുക, തർക്കിച്ചാൽ തെറി പറയുക. (ബു,മു,തു,ന)', 'عَبْدِاللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നുഅംറ്(റ)', null, null, array['ق','ت','ن']::text[], array['ബു','മു','തു','ന']::text[], null, null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: آيَةُ الْمُنَافِقِ ثَلَاثٌ؛ إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا اؤْتُمِنَ خَانَ. (خ)', 'അബൂഹുറൈറ(റ): പ്രവാചകർ(സ) പറഞ്ഞു: കപടവിശ്വാസിയുടെ ലക്ഷണം മൂന്നെണ്ണമാണ്. സംസാരിച്ചാൽ കളവു പറയുക, വാഗ്ദാനം ചെയ്താൽ ലംഘിക്കുക, വിശ്വസിച്ചാൽ ചതിക്കുക, എന്നിവയാണവ. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَثَلُ الْمُنَافِقِ كَمَثَلِ الشَّاةِ الْعَائِرَةِ بَيْنَ الْغَنَمَيْنِ، تَعِيرُ فِي هَذِهِ مَرَّةً، وَفِي هَذِهِ مَرَّةً، لَا تَدْرِي أَيَّهَا تَتْبَعُ". (ن,م)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് ആട്ടിൻ പറ്റങ്ങളിൽ ഏതിനെയാണ് പിന്തുടരേണ്ടതെന്നറിയാതെ അങ്ങോട്ടുമിങ്ങോട്ടും ചാഞ്ചാടിക്കൊണ്ടിരിക്കുന്ന ഒരാടിനെപ്പോലെയാണ് കപടവിശ്വാസി." (മു,ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن','م']::text[], array['മു','ന']::text[], null, null, 120, 120, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ عَبْدِاللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا نَزَلَتْ:{الَّذِينَ آمَنُوا وَلَمْ يَلْبِسُوا إِيمَانَهُمْ بِظُلْمٍ} قَالَ أَصْحَابُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَيُّنَا لَمْ يَظْلِمْ، فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ: {إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ}. (خ)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "വിശ്വസിക്കുകയും തങ്ങളുടെ വിശ്വാസത്തെ അധർമ്മവുമായി കൂട്ടിക്കലർത്താതിരിക്കുകയും ചെയ്തവർ..." (അൻആം: 82) എന്ന സൂക്തം അവതരിച്ചപ്പോൾ സ്വഹാബത്തു ചോദിച്ചു: നബിയേ, ആരാണ് ഞങ്ങളുടെ കൂട്ടത്തിൽ അക്രമം ചെയ്യാത്തത്. അപ്പോൾ "നിശ്ചയം, അല്ലാഹുവിൽ പങ്കുചേർക്കൽ കടുത്ത അക്രമം തന്നെയാകുന്നു" (ലുഖ്മാൻ: 13). എന്ന സൂക്തം അവതരിച്ചു. (ബു)', 'عَبْدِاللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 120, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ؟ ثَلَاثًا: – الْإِشْرَاكُ بِاللهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَشَهَادَةُ الزُّورِ – أَوْ قَوْلُ الزُّورِ – وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُتَّكِئًا، فَجَلَسَ فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ. (م)', 'അബൂബക്റഃ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പമിരിക്കുമ്പോൾ അവിടുന്ന് ചോദിച്ചു: "വൻ പാപങ്ങളിൽ വെച്ചേറ്റവും വലിയവ ഏതാണെന്ന് ഞാൻ പറഞ്ഞ് തരട്ടെയോ? അത് മൂന്നെണ്ണമാണ്. അല്ലാഹുവിൽ പങ്കുചേർക്കലും, മാതാപിതാക്കളെ ബുദ്ധിമുട്ടിക്കലും, കള്ളസാക്ഷ്യം വഹിക്കലുമാണവ." ചാരിയിരിക്കുകയായിരുന്ന നബി(സ) നിവർന്നിരുന്ന് ഇത് ആവർത്തിച്ചു കൊണ്ടിരുന്നു. അവിടന്ന് ഒന്നു നിർത്തിയിരുന്നെങ്കിൽ! ഞങ്ങൾ പറഞ്ഞുപോയി. (മു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റഃ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ، عَنْ أَبِيهِ قَالَ: كُنَّا عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَلَا أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ – ثَلَاثًا–: الْإِشْرَاكُ بِاللهِ، وَعُقُوقُ الْوَالِدَيْنِ، وَشَهَادَةُ الزُّورِ. أَوْ: قَوْلُ الزُّورِ". وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُتَّكِئًا فَجَلَسَ، فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ. (م)', 'അബ്ദുർറഹ്മാൻബിനു അബീബക്റ(റ) തന്റെ പിതാവിൽനിന്ന് ഉദ്ധരിക്കുന്നു: അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ തിരുമേനി(സ)യുടെ അടുക്കലായിരുന്നപ്പോൾ അവിടുന്ന് പറഞ്ഞു: വൻ പാപങ്ങളിൽവെച്ച് ഏറ്റവും വലിയ മൂന്നെണ്ണത്തെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്കറിയിച്ചു തരട്ടെയോ! ''അല്ലാഹുവിൽ പങ്കുചേർക്കൽ, മാതാപിതാക്കളെ ബുദ്ധിമുട്ടിക്കൽ, കള്ളസാക്ഷ്യം വഹിക്കൽ - അതായത് കള്ളസാക്ഷ്യം പറയൽ - എന്നിവയാണവ. ഇതു പറയുമ്പോൾ തിരുമേനി ചാരി ഇരിക്കുകയായിരുന്നു. അനന്തരം തിരുമേനി(സ) നേരെ ഇരുന്നു. റസൂൽ(സ) ഇക്കാര്യം ആവർത്തിച്ചു പറഞ്ഞുകൊണ്ടിരുന്നു. അങ്ങനെ ഞങ്ങൾ ഇത്രത്തോളം പറഞ്ഞു പോയി: ''റസൂൽ(സ) ഒന്നു മിണ്ടാതിരുന്നങ്കിൽ എത്രനന്നായിരുന്നു. (മു)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ، عَنْ أَبِيهِ قَالَ', 'അബ്ദുർറഹ്മാൻബിനു അബീബക്റ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'قَالَ عَبْدُ اللهِ رَضِيَ اللهُ عَنْهُ: قَالَ رَجُلٌ: يَا رَسُولَ اللهِ! أَيُّ الذَّنْبِ أَكْبَرُ عِنْدَ اللهِ؟ قَالَ: "أَنْ تَدْعُوَ لِلهِ نِدًّا وَهُوَ خَلَقَكَ" قَالَ: ثُمَّ أَيٌّ؟ قَالَ: "أَنْ تَقْتُلَ وَلَدَكَ مَخَافَةَ أَنْ يَطْعَمَ مَعَكَ" قَالَ: ثُمَّ أَيٌّ؟ قَالَ: "أَنْ تُزَانِي حَلِيلَةَ جَارِكَ" فَأَنْزَلَ اللهُ عَزَّ وَجَلَّ تَصْدِيقَهَا {وَالَّذِينَ لَا يَدْعُونَ مَعَ اللهِ إِلَهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ وَمَنْ يَفْعَلْ ذَلِكَ يَلْقَ أَثَامًا}. (م)', 'അബദുല്ലാഹ്(റ): ഒരാൾ പറഞ്ഞു: തിരുദൂതരേ! ഏതാണ് അല്ലാഹുവിന്റെ അടുക്കൽ മഹാപാപം? നബി(സ) പറഞ്ഞു: "നിന്നെ സൃഷ്ടിച്ചത് അല്ലാഹുവായിരിക്കെ അവന് സമന്മാരെ സ്ഥാപിച്ച് ആരാധിക്കുക." അയാൾ ചോദിച്ചു: പിന്നെ ഏതാണ്? നബി(സ) പറഞ്ഞു: "നിന്റെ കൂടെ ഭക്ഷിക്കുമോ എന്ന് ഭയന്നു നിന്റെ കുഞ്ഞിനെ നീ വധിക്കൽ." അയാൾ ചോദിച്ചു: പിന്നെ ഏത്? നബി(സ) പറഞ്ഞു: "നിന്റെ അയൽവാസിയുടെ പത്നിയെ വ്യഭിചരിക്കൽ." ഇതിനെ സത്യപ്പെടുത്തിക്കൊണ്ട് "അല്ലാഹുവിനോടൊപ്പം മറ്റൊരു ആരാധ്യനെയും വിളിച്ചു പ്രാർത്ഥിക്കാത്തവരും, അല്ലാഹു പവിത്രമാക്കിയ ജീവനെ ന്യായമായ കാരണത്താലല്ലാതെ ഹനിച്ച് കളയാത്തവരും, വ്യഭിചരിക്കാത്തവരുമാണവർ. (അല്ലാഹുവിന്റെ ഇഷ്ടദാസന്മാർ) ആരെങ്കിലും ഇവ ചെയ്യുന്ന പക്ഷം അവൻ പാപഫലം കണ്ടെത്തുകതന്നെ ചെയ്യും." (ഫുർഖാൻ : 68) എന്ന ആയത്ത് അവതരിപ്പിച്ചു. (മു)', null, 'അബദുല്ലാഹ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 121, 121, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اجْتَنِبُوا السَّبْعَ الْمُوبِقَاتِ" قِيلَ: يَا رَسُولَ اللهِ! وَمَا هُنَّ؟ قَالَ: "الشِّرْكُ بِاللهِ، وَالسِّحْرُ، وَقَتْلُ النَّفْسِ الَّتِي حَرَّمَ اللهُ إِلَّا بِالْحَقِّ، وَأَكْلُ مَالِ الْيَتِيمِ، وَأَكْلُ الرِّبَا، وَالتَّوَلِّي يَوْمَ الزَّحْفِ، وَقَذْفُ الْمُحْصَنَاتِ الْغَافِلَاتِ الْمُؤْمِنَاتِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഏഴ് വൻപാപങ്ങൾ ഒഴിവാക്കുക." അപ്പോൾ ചോദിക്കപ്പെട്ടു: അവ ഏതൊക്കെയാണത് നബിയെ? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിൽ പങ്കുചേർക്കൽ, മാരണം, ന്യായമില്ലാതെ അല്ലാഹു ആദരിച്ച ആത്മാവിനെ വധിക്കൽ, അനാഥയുടെ ധനം ഭക്ഷിക്കൽ, പലിശ ഭുജിക്കൽ, യുദ്ധദിനത്തിൽ പിന്തിരിഞ്ഞോടൽ, വിശ്വാസിനികളും (ദുർവൃത്തി) വെടിയുന്നവരും പതിവ്രതകളുമായ സ്ത്രീകളിൽ (വ്യഭിചാരം) ആരോപിക്കൽ." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 121, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا أَهْلُ النَّارِ الَّذِينَ هُمْ أَهْلُهَا فَإِنَّهُمْ لَا يَمُوتُونَ فِيهَا وَلَا يَحْيَوْنَ، وَلَكِنْ نَاسٌ أَصَابَتْهُمُ النَّارُ بِذُنُوبِهِمْ – أَوْ قَالَ بِخَطَايَاهُمْ – فَأَمَاتَهُمْ إِمَاتَةً حَتَّى إِذَا كَانُوا فَحْمًا، أُذِنَ بِالشَّفَاعَةِ فَجِيءَ بِهِمْ ضَبَائِرَ ضَبَائِرَ، فَبُثُّوا عَلَى أَنْهَارِ الْجَنَّةِ، ثُمَّ قِيلَ: يَا أَهْلَ الْجَنَّةِ! أَفِيضُوا عَلَيْهِمْ، فَيَنْبُتُونَ نَبَاتَ الْحِبَّةِ تَكُونُ فِي حَمِيلِ السَّيْلِ". فَقَالَ رَجُلٌ مِنَ الْقَوْمِ كَأَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ كَانَ بِالْبَادِيَةِ. (م)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "നരകത്തിന്റെ യഥാർത്ഥ അവകാശികളായ നരകവാസികൾ (അവിശ്വാസികൾ) അവിടെ മരിക്കുകയില്ല; എന്നാൽ ജീവിക്കുകയുമില്ല. പക്ഷേ പാപങ്ങൾ നിമിത്തം നരകാഗ്നി ഏറ്റ ജനങ്ങളിൽ (വിശ്വാസികൾ) ചിലരെ അല്ലാഹു മരിപ്പിക്കും. അവർ കരിക്കട്ടയായിത്തീരുമ്പോൾ അല്ലാഹു അവർക്കുവേണ്ടി ശുപാർശ ചെയ്യാൻ അനുവാദം നൽകും. തുടർന്ന് അവരെ കൊച്ചുകൊച്ചു സംഘങ്ങളായി കൊണ്ടുവന്ന് സ്വർഗ്ഗത്തിലെ നദികളിൽ വിതറും. പിന്നെ സ്വർഗ്ഗവാസികളോട് (അല്ലാഹു) പറയും: "അവരുടെമേൽ വെള്ളം ചൊരിയൂ!" വെള്ളത്തിന്നടുത്ത് കിളിർക്കുന്ന ധാന്യമണികൾ പോലെ അവർ മുളച്ചുപൊങ്ങും." കൂട്ടത്തിൽ ഒരാൾ പറഞ്ഞു: (നബി(സ)യുടെ വിവണം കേട്ടാൽ) തിരുമേനി(സ) ജീവിച്ചിരുന്നത് ഉൾപ്രദേശത്തായിരുന്നോ എന്നു തോന്നിപ്പോവും. (മു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 122, 122, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "آخِرُ مَنْ يَدْخُلُ الْجَنَّةَ رَجُلٌ فَهُوَ يَمْشِي مَرَّةً وَيَكْبُو مَرَّةً، وَتَسْفَعُهُ النَّارُ مَرَّةً، فَإِذَا مَا جَاوَزَهَا الْتَفَتَ إِلَيْهَا، فَقَالَ: تَبَارَكَ الَّذِي نَجَّانِي مِنْكِ، لَقَدْ أَعْطَانِي اللهُ شَيْئًا مَا أَعْطَاهُ أَحَدًا مِنَ الْأَوَّلِينَ وَالْآخِرِينَ، فَتُرْفَعُ لَهُ شَجَرَةٌ، فَيَقُولُ: أَيْ رَبِّ! أَدْنِنِي مِنْ هَذِهِ الشَّجَرَةِ، فَلِأَسْتَظِلَّ بِظِلِّهَا، وَأَشْرَبَ مِنْ مَائِهَا، فَيَقُولُ اللهُ عَزَّ وَجَلَّ: يَا ابْنَ آدَمَ! لَعَلِّي إِنْ أَعْطَيْتُكَهَا سَأَلْتَنِي غَيْرَهَا؟ فَيَقُولُ: لَا يَا رَبِّ! وَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا، وَرَبُّهُ يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ، فَيُدْنِيهِ مِنْهَا، فَيَسْتَظِلُّ بِظِلِّهَا وَيَشْرَبُ مِنْ مَائِهَا، ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ هِيَ أَحْسَنُ مِنَ الْأُولَى، فَيَقُولُ: أَيْ رَبِّ! أَدْنِنِي مِنْ هَذِهِ لِأَشْرَبَ مِنْ مَائِهَا وَأَسْتَظِلَّ بِظِلِّهَا، لَا أَسْأَلُكَ غَيْرَهَا، فَيَقُولُ: يَا ابْنَ آدَمَ! أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا؟ فَيَقُولُ: لَعَلِّي إِنْ أَدْنَيْتُكَ مِنْهَا تَسْأَلُنِي غَيْرَهَا؟ فَيُعَاهِدُهُ أَنْ لَا يَسْأَلَهُ غَيْرَهَا، وَرَبُّهُ يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهِ، فَيُدْنِيهِ مِنْهَا فَيَسْتَظِلُّ بِظِلِّهَا وَيَشْرَبُ مِنْ مَائِهَا، ثُمَّ تُرْفَعُ لَهُ شَجَرَةٌ عِنْدَ بَابِ الْجَنَّةِ هِيَ أَحْسَنُ مِنَ الْأُولَيَيْنِ، فَيَقُولُ: أَيْ رَبِّ! أَدْنِنِي مِنْ هَذِهِ لِأَسْتَظِلَّ بِظِلِّهَا وَأَشْرَبَ مِنْ مَائِهَا لَا أَسْأَلُكَ غَيْرَهَا، فَيَقُولُ: يَا ابْنَ آدَمَ! أَلَمْ تُعَاهِدْنِي أَنْ لَا تَسْأَلَنِي غَيْرَهَا؟ قَالَ بَلَى يَا رَبِّ! هَذِهِ، لَا أَسْأَلُكَ غَيْرَهَا، وَرَبُّهُ يَعْذِرُهُ لِأَنَّهُ يَرَى مَا لَا صَبْرَ لَهُ عَلَيْهَا، فَيُدْنِيهِ مِنْهَا، فَإِذَا أَدْنَاهُ مِنْهَا فَيَسْمَعُ أَصْوَاتَ أَهْلِ الْجَنَّةِ، فَيَقُولُ: أَيْ رَبِّ! أَدْخِلْنِيهَا، فَيَقُولُ: يَا ابْنَ آدَمَ! مَا يَصْرِينِي مِنْكَ؟ أَيُرْضِيكَ أَنْ أُعْطِيَكَ الدُّنْيَا وَمِثْلَهَا مَعَهَا؟ قَالَ: يَا رَبِّ! أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ؟" – فَضَحِكَ ابْنُ مَسْعُودٍ، فَقَالَ: أَلَا تَسْأَلُونِي مِمَّ أَضْحَكُ؟ فَقَالُوا: مِمَّ تَضْحَكُ؟ قَالَ: هَكَذَا ضَحِكَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: مِمَّ تَضْحَكُ يَا رَسُولَ اللهِ؟ قَالَ: "مِنْ ضَحِكِ رَبِّ الْعَالَمِينَ حِينَ قَالَ أَتَسْتَهْزِئُ مِنِّي وَأَنْتَ رَبُّ الْعَالَمِينَ، فَيَقُولُ: إِنِّي لَا أَسْتَهْزِئُ مِنْكَ، وَلَكِنِّي عَلَى مَا أَشَاءُ قَادِرٌ". (م)', 'ഇബ്നുമസഊദ്(റ): നബി(സ) പറഞ്ഞു: "അവസാനം സ്വർഗ്ഗത്തിൽ കടക്കുന്നയാൾ അല്പം നടക്കും, ചിലപ്പോൾ മുഖം കുത്തിവീഴും. മറ്റുചിലപ്പോൾ അവനു നരകത്തിന്റെ ജ്വാലകളേൽക്കും. നരകത്തിന്റെ പരിധി വിട്ടുകഴിഞ്ഞാൽ നരകത്തിലേക്ക് തിരിഞ്ഞ് നോക്കിക്കൊണ്ട് അയാൾ പറയും: ''എന്നെ അതിൽ നിന്ന് രക്ഷപ്പെടുത്തിയ അല്ലാഹു അനുഗ്രഹ പൂർണ്ണൻ. മുൻഗാമികൾക്കോ പിൻഗാമികൾക്കോ നൽകാത്തത് അല്ലാഹു എനിക്ക് നൽകിയിരിക്കുന്നു.'' അപ്പോൾ അവനുവേണ്ടി ഒരുമരം ഉയർത്തപ്പെടും. അവൻ പറയും: ''നാഥാ! എന്നെ ഈ മരത്തോട് അടുപ്പിക്കണേ! ഞാൻ അതിന്റെ തണൽ കൊള്ളട്ടേ. അതിൽനിന്ന് വരുന്ന വെള്ളം കുടിക്കട്ടെ!'' അല്ലാഹു പറയും: ''മനുഷ്യാ! നിനക്ക് അത് ഞാൻ നൽകിയാൽ മറ്റ് വല്ലതും നീ ചോദിക്കുമോ?'' അവൻ പറയും: "നാഥാ!, ഇല്ല!" അവൻ നാഥനോട് കരാർ ചെയ്യുന്നു. തനിക്ക് ക്ഷമിക്കാനാവാത്തതാണ് അവൻ കണ്ടിരിക്കുന്നതെന്നതിനാൽ നാഥൻ അവന് വിട്ടുവീഴ്ച ചെയ്യുന്നു. അവനെ മരത്തിനടുത്തേക്ക് അടുപ്പിക്കുന്നു. അവൻ അതിന്റെ തണലും ജലവും ആസ്വദിക്കുന്നു. കൂടുതൽ സുന്ദരമായ ഒരു വൃക്ഷം അവിടെ ഉയർത്തപ്പെടുന്നു. അപ്പോൾ അവൻ പറയും: ''നാഥാ! എന്നെ ആ മരത്തിലേക്കടുപ്പിക്കൂ! അതിന്റെ വെള്ളവും തണലും ഞാനനുഭവിക്കട്ടെ! ഞാൻ മറ്റൊന്നും ചോദിക്കില്ല!'' അല്ലാഹു പറയും: ''മറ്റൊന്നും ചോദിക്കില്ലെന്ന് നീ കരാർ ചെയ്തിരുന്നില്ലേ?'' അതെ നാഥാ, ഇതല്ലാതെ ഞാനൊന്നും നിന്നോട് ചോദിക്കില്ല!'' ''ആ വൃക്ഷത്തോട് നിന്നെ അടുപ്പിച്ചാൽ നീ മറ്റെന്തെങ്കിലും ചോദിക്കുമോ?'' ഒന്നും ചോദിക്കില്ലെന്ന് അവൻ കരാർ ചെയ്യുന്നു. തനിക്ക് ക്ഷമിക്കാൻ കഴിയാത്തതാണ് അവൻ കണ്ടിരിക്കുന്നതെന്നതിനാൽ അല്ലാഹു അവന്ന് വിട്ടുവീഴ്ച ചെയ്യുന്നു. അവനെ വൃക്ഷത്തോടടുപ്പിക്കുന്നു. അവൻ അതിന്റെ തണലും ജലവും ആസ്വദിക്കുന്നു. വീണ്ടും സ്വർഗ്ഗ കവാടത്തിനടുത്ത് മറ്റൊരു വൃക്ഷം ഉയർത്തപ്പെടുന്നു. അതാണ് കൂടുതൽ സുന്ദരം. അപ്പോൾ അവൻ പറയും: ''നാഥാ! എന്നെ ആ മരത്തിലേക്കടുപ്പിക്കൂ! അതിന്റെ വെള്ളവും തണലും ഞാനനുഭവിക്കട്ടെ! ഞാൻ മറ്റൊന്നും ചോദിക്കില്ല!'' അല്ലാഹു പറയും: ''മറ്റൊന്നും ചോദിക്കില്ലെന്ന് നീ കരാർ ചെയ്തിരുന്നില്ലേ?'' ''അതെ! നാഥാ! ഇതല്ലാതെ ഞാനൊന്നും നിന്നോട് ചോദിക്കില്ല!'' ''ആ വൃക്ഷത്തോട് നിന്നെ അടുപ്പിച്ചാൽ നീ മറ്റെന്തെങ്കിലും ചോദിക്കില്ലേ?'' ഒന്നും ചോദിക്കില്ലെന്ന് അവൻ കരാർ ചെയ്യുന്നു. തനിക്ക് ക്ഷമിക്കാൻ കഴിയാത്തതാണ് അവൻ കണ്ടിരിക്കുന്നതെന്നതിനാൽ അല്ലാഹു അവന്ന് വിട്ടുവീഴ്ച ചെയ്യുന്നു. അവനെ വൃക്ഷത്തോടടുപ്പിക്കുന്നു. അവൻ സ്വർഗ്ഗത്തോടടുക്കുമ്പോൾ സ്വർഗ്ഗക്കാരുടെ ശബ്ദം കേൾക്കുന്നു. അവൻ പറയുന്നു: ''നാഥാ! എന്നെ അതിൽ പ്രവേശിപ്പിച്ചാലും!'' അല്ലാഹു പറയും: മനുഷ്യാ എന്ത് കിട്ടിയാലാണ് നീ ഒഴിഞ്ഞ് പോവുക. നിനക്ക് ദുൻയാവും അതിന് തുല്യമായതും കിട്ടിയാൽ നീ തൃപ്തിപ്പെടുമോ? അവൻ പറയും: ''നാഥാ! നീ എന്നെ പരിഹസിക്കുന്നുവോ? നീ ലോകരക്ഷിതാവല്ലേ?" ഇതു പറഞ്ഞ് ഇബ്നുമസ്ഊദ്(റ) ചിരിച്ചു ശേഷം പറഞ്ഞു: ഞാൻ ചിരിക്കുന്നതെന്തേ എന്ന് നിങ്ങൾ ചോദിക്കുന്നില്ലേ? അവർ ചോദിച്ചു: നിങ്ങളെന്തിന് ചിരിക്കുന്നു.? ഇബ്നുമസ്ഊദ് പറഞ്ഞു: നബി(സ) ഇങ്ങനെ ചിരിച്ചിട്ടുണ്ട്. അപ്പോൾ അനുചരർ ചോദിച്ചു: നബിയെ! അങ്ങെന്തിന് ചിരിക്കുന്നു? നബി(സ) പറഞ്ഞു: "ലോകരക്ഷിതാവായ നീ എന്നെ കളിയാക്കുകയാണോ എന്ന് ചോദിച്ചപ്പോൾ രക്ഷിതാവായ അല്ലാഹു ചിരിച്ചതു കൊണ്ടാണ് ഞാൻ ചിരിക്കുന്നത്. തുടർന്ന് അല്ലാഹു പറയും: ''ഞാൻ നിന്നെ പരിഹസിക്കുകയല്ല. പക്ഷേ, ഞാനുദ്ദേശിക്കുന്നതൊക്കെ എനിക്ക് സാധിക്കുന്നതാണ്!." (മു)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 122, 123, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ أَبِي الزُّبَيْرِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ جَابِرَ بْنَ عَبْدِ اللهِ يُسْأَلُ عَنِ الْوُرُودِ، فَقَالَ: نَجِيءُ نَحْنُ يَوْمَ الْقِيَامَةِ عَنْ كَذَا وَكَذَا – انْظُرْ – أَيْ ذَلِكَ فَوْقَ النَّاسِ، قَالَ: فَتُدْعَى الْأُمَمُ بِأَوْثَانِهَا وَمَا كَانَتْ تَعْبُدُ، الْأَوَّلُ فَالْأَوَّلُ، ثُمَّ يَأْتِينَا رَبُّنَا بَعْدَ ذَلِكَ، فَيَقُولُ: مَنْ تَنْظُرُونَ؟ فَيَقُولُونَ: نَنْظُرُ رَبَّنَا، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: حَتَّى نَنْظُرَ إِلَيْكَ، فَيَتَجَلَّى لَهُمْ يَضْحَكُ، قَالَ: فَيَنْطَلِقُ بِهِمْ وَيَتَّبِعُونَهُ، وَيُعْطَى كُلُّ إِنْسَانٍ مِنْهُمْ – مُنَافِقٌ أَوْ مُؤْمِنٌ – نُورًا، ثُمَّ يَتَّبِعُونَهُ وَعَلَى جِسْرِ جَهَنَّمَ كَلَالِيبُ وَحَسَكٌ تَأْخُذُ مَنْ شَاءَ اللهُ، ثُمَّ يُطْفَأُ نُورُ الْمُنَافِقِينَ، ثُمَّ يَنْجُو الْمُؤْمِنُونَ، فَتَنْجُو أَوَّلُ زُمْرَةٍ وُجُوهُهُمْ كَالْقَمَرِ لَيْلَةَ الْبَدْرِ سَبْعُونَ أَلْفًا لَا يُحَاسَبُونَ، ثُمَّ الَّذِينَ يَلُونَهُمْ كَأَضْوَإِ نَجْمٍ فِي السَّمَاءِ، ثُمَّ كَذَلِكَ، ثُمَّ تَحِلُّ الشَّفَاعَةُ وَيَشْفَعُونَ حَتَّى يَخْرُجَ مِنَ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللهُ وَكَانَ فِي قَلْبِهِ مِنَ الْخَيْرِ مَا يَزِنُ شَعِيرَةً، فَيُجْعَلُونَ بِفِنَاءِ الْجَنَّةِ، وَيَجْعَلُ أَهْلُ الْجَنَّةِ يَرُشُّونَ عَلَيْهِمُ الْمَاءَ حَتَّى يَنْبُتُوا نَبَاتَ الشَّيْءِ فِي السَّيْلِ، وَيَذْهَبُ حُرَاقُهُ، ثُمَّ يَسْأَلُ حَتَّى تُجْعَلَ لَهُ الدُّنْيَا وَعَشَرَةُ أَمْثَالِهَا مَعَهَا". (م)', 'അബൂസുബൈർ(റ): ജാബിറുബ്നു അബ്ദില്ല(റ)യോട് വുറൂദി⁴നെക്കുറിച്ച് ചോദിക്കുന്നത് ഞാൻ കേട്ടു. അദ്ദേഹം പറഞ്ഞു: നാം (വിശ്വാസികൾ) അന്ത്യനാളിൽ ഉയർന്ന സ്ഥലങ്ങളിൽ വന്നെത്തും. ജനതകൾ അവരുടെ വിഗ്രഹങ്ങളുടെയും മറ്റു ആരാധ്യവസ്തുക്കളുടെയും കൂടെ വിളിക്കപ്പെടും. തുടർന്ന് അല്ലാഹു നമ്മോട് പറയും: നിങ്ങളാരെയാണ് നോക്കുന്നത്? അവർ പറയും: ഞങ്ങളുടെ രക്ഷിതാവിനെ. അല്ലാഹു: ഞാനാണ് നിങ്ങളുടെ രക്ഷിതാവ്. അവർ: എങ്കിൽ ഞങ്ങൾ നിന്നെ കാണട്ടേ. അല്ലാഹു അവർക്ക് പുഞ്ചിരിച്ചുകൊണ്ട് പ്രത്യക്ഷനാകും. തുടർന്ന് അവൻ അവരെ കൊണ്ടുപോകുകയും അവനെ അവർ പിന്തുടരുകയും ചെയ്യുന്നു. സത്യവിശ്വാസിക്കും കപടനുമെല്ലാം അവൻ ഒരു പ്രകാശം നൽകുന്നു. നരകത്തിന്റെ പാലത്തിൽ അഗ്രം വളഞ്ഞ കമ്പികളും മുള്ളുകളുമുണ്ട്. അല്ലാഹു ഉദ്ദേശിച്ചവരെ അവ പിടിച്ചുകളയും. പിന്നെ കപടന്മാരുടെ പ്രകാശം അല്ലാഹു കെടുത്തും. വിശ്വാസികൾ രക്ഷപ്പെടും. ആദ്യസംഘം രക്ഷപ്പെട്ടു വരുമ്പോൾ അവരുടെ മുഖങ്ങൾ പൗർണ്ണമി രാവിനെപ്പോലെ വെട്ടിത്തിളങ്ങുന്നു. അവർ എഴുപതിനായിരമുണ്ടാകും. അവർക്ക് വിചാരണ ഉണ്ടാവില്ല. തുടർന്ന് അവരുടെ ശേഷമുള്ളവർ വരും. ആകാശത്തിലെ നന്നായി ജ്വലിക്കുന്ന നക്ഷത്രങ്ങൾ പോലെ അങ്ങനെയങ്ങനെ ഓരോ സംഘങ്ങൾ വരും. പിന്നീട് ശുപാർശ അനുവദിക്കപ്പെടും ''ലാ ഇലാഹ ഇല്ലല്ലാഹ്'' എന്ന് പറയുകയും ഹൃദയത്തിൽ ഗോതമ്പു മണിയോളമെങ്കിലും നന്മ ശേഷിക്കുകയും ചെയ്ത എല്ലാവരെയും അവർ ശുപാർശയിലൂടെ മോചിതരാക്കും. പിന്നീട് അവരെ സ്വർഗ്ഗമുറ്റത്ത് കൊണ്ടുവരും. സ്വർഗ്ഗവാസികൾ അവർക്കുമേൽ വെള്ളം തെളിക്കും. ഒലിപ്പു വെള്ളത്തിലിടുന്ന ഒരു വസ്തു മുളക്കുന്നതു പോലെ അവർ മുളക്കുകയും കരിപ്പാടുകൾ നീങ്ങുകയും ചെയ്യും. തുടർന്ന് അവൻ ഓരോന്ന് ആവശ്യപ്പെടാൻ തുടങ്ങും; ദുൻയാവും അതോടൊപ്പം അതിന്റെ പത്തിരട്ടിയും അവന് നൽകപ്പെടുന്നതുവരെ." (മു)', 'أَبِي الزُّبَيْرِ', 'അബൂസുബൈർ(റ)', '⁴. ഒരാളും നരകത്തിനടുത്ത് വരാതിരിക്കില്ല (മർയം 71) എന്ന സൂക്തത്തിൽ പരാമർശിച്ച വരവ് (വുറൂദ്) ആണ് ചോദ്യത്തിൽ ഉദ്ദേശിച്ചിരിക്കുന്നത്.', null, array['م']::text[], array['മു']::text[], null, null, 123, 124, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ يَزِيدَ الْفَقِيرِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ قَدْ شَغَفَنِي رَأْيٌ مِنْ رَأْيِ الْخَوَارِجِ، فَخَرَجْنَا فِي عِصَابَةٍ ذَوِي عَدَدٍ نُرِيدُ أَنْ نَحُجَّ ثُمَّ نَخْرُجَ عَلَى النَّاسِ، قَالَ: فَمَرَرْنَا عَلَى الْمَدِينَةِ فَإِذَا جَابِرُ بْنُ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا يُحَدِّثُ الْقَوْمَ جَالِسٌ إِلَى سَارِيَةٍ عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَإِذَا هُوَ قَدْ ذَكَرَ الْجَهَنَّمِيِّينَ قَالَ: فَقُلْتُ لَهُ: يَا صَاحِبَ رَسُولِ اللهِ! مَا هَذَا الَّذِي تُحَدِّثُونَ؟ وَاللهُ يَقُولُ: {إِنَّكَ مَنْ تُدْخِلِ النَّارَ فَقَدْ أَخْزَيْتَهُ} وَ{كُلَّمَا أَرَادُوا أَنْ يَخْرُجُوا مِنْهَا أُعِيدُوا فِيهَا} فَمَا هَذَا الَّذِي تَقُولُونَ؟ قَالَ: فَقَالَ: أَتَقْرَأُ الْقُرْآنَ؟ قُلْتُ: نَعَمْ، قَالَ: فَهَلْ سَمِعْتَ بِمَقَامِ مُحَمَّدٍ عَلَيْهِ السَّلَامُ يَعْنِي الَّذِي يَبْعَثُهُ اللهُ فِيهِ؟ قُلْتُ: نَعَمْ، قَالَ: فَإِنَّهُ مَقَامُ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَحْمُودُ الَّذِي يُخْرِجُ اللهُ بِهِ مَنْ يُخْرِجُ، قَالَ: ثُمَّ نَعَتَ وَضْعَ الصِّرَاطِ وَمَرَّ النَّاسِ عَلَيْهِ، قَالَ: وَأَخَافُ أَنْ لَا أَكُونَ أَحْفَظُ ذَاكَ، قَالَ: غَيْرَ أَنَّهُ قَدْ زَعَمَ أَنَّ قَوْمًا يَخْرُجُونَ مِنَ النَّارِ بَعْدَ أَنْ يَكُونُوا فِيهَا، قَالَ: يَعْنِي فَيَخْرُجُونَ كَأَنَّهُمْ عِيدَانُ السَّمَاسِمِ، قَالَ: فَيَدْخُلُونَ نَهَرًا مِنْ أَنْهَارِ الْجَنَّةِ، فَيَغْتَسِلُونَ فِيهِ فَيَخْرُجُونَ كَأَنَّهُمُ الْقَرَاطِيسُ، فَرَجَعْنَا فَقُلْنَا: وَيْحَكُمْ، أَتُرَوْنَ الشَّيْخَ يَكْذِبُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَرَجَعْنَا فَلَا وَاللهِ مَا خَرَجَ مِنَّا غَيْرُ رَجُلٍ وَاحِدٍ، أَوْ كَمَا قَالَ أَبُو نُعَيْمٍ. (م)', 'യസീദുൽ ഫഖീർ(റ): ഖവാരിജു⁵കളുടെ ചില ആശയങ്ങൾ എന്നെ ആകർഷിച്ചിരുന്നു. ഹജ്ജ് നിർവ്വഹിക്കുകയും ശേഷം പ്രചാരണ പ്രവർത്തനങ്ങളുമായി ജനങ്ങൾക്കിടയിലേക്കിറങ്ങുകയുമാകാമെന്ന ഉദ്ദേശ്യത്തോടെ ഏതാനും പേരടങ്ങുന്ന സംഘം ചേർന്ന് ഞങ്ങൾ പുറപ്പെട്ടു. റിപ്പോർട്ടർ പറയുന്നു: ഞങ്ങൾ മദീനയിലൂടെ നടക്കുമ്പോൾ ജാബിറുബ്നു അബ്ദില്ല(റ) ജനങ്ങൾക്ക് നബി(സ)യുടെ ഹദീസ് പറഞ്ഞ് കൊടുക്കുന്നതു കണ്ടു. അദ്ദേഹം ഒരു തൂണ് ചാരിയിരിക്കുകയാണ്. നരകവാസികളെക്കുറിച്ച് പറഞ്ഞുകൊണ്ടിരിക്കുന്നതിനിടെ ഞാനദ്ദേഹത്തോട് ചോദിച്ചു: ഓ റസൂലിന്റെ സ്വഹാബീ, നിങ്ങളെന്താണീ പറയുന്നത്? അല്ലാഹു പറഞ്ഞത് ഇങ്ങനെയാണല്ലോ; "നീ ആരെയെങ്കിലും നരകത്തിൽ പ്രവേശിപ്പിച്ചാൽ നീ അവനെ നിന്ദ്യനാക്കിക്കളഞ്ഞു. (ആലു ഇംറാൻ 192) "അവർ നരകത്തിൽനിന്ന് പുറത്ത് കടക്കാൻ ഉദ്ദേശിക്കുമ്പോഴൊക്കെയും അതിലേക്ക് തന്നെ അവർ മടക്കപ്പെടും" എന്നിട്ടും എന്താണ് നിങ്ങളീ പറഞ്ഞുകൊണ്ടിരിക്കുന്നത്! അദ്ദേഹം ചോദിച്ചു: താങ്കൾ ഖുർആൻ ഓതാറുണ്ടോ? ഞാൻ: അതെ. ജാബിർ(റ): എങ്കിൽ, അല്ലാഹു മുഹമ്മദ് നബി(സ)ക്ക് പുനരുദ്ധാരണത്തോടെ നൽകുന്ന അൽ മഖാമുൽ മഹ്മൂദി (സ്തുതിക്കപ്പെട്ട സ്ഥലം) എന്ന സ്ഥാനത്തെക്കുറിച്ച് താങ്കൾ കേട്ടിട്ടുണ്ടോ? ഞാൻ: അതെ! ജാബിർ(റ) പറഞ്ഞു: അല്ലാഹു ജനങ്ങളെ നരകത്തിൽനിന്ന് പുറത്ത് കൊണ്ടുവരുന്നത് ആ മഖാമുൽ മഹ്മൂദ് മുഖേനയാണ്. തുടർന്ന് അദ്ദേഹം സ്വിറാതി(പാലം)ന്റെ സ്ഥാനവും അതിലൂടെ ജനങ്ങൾ നടക്കുന്നതുമൊക്കെ വർണ്ണിച്ചുതന്നു. അവ മുഴുവനും മനഃപാഠമാക്കിയില്ലല്ലോ എന്ന് ഞാൻ ഭയപ്പെടുന്നു. ഇതദ്ദേഹം വാദിച്ചിട്ടുണ്ടെന്ന് തീർച്ച "ഒരു വിഭാഗം ആളുകൾ നരകത്തിൽ കിടന്നശേഷം എള്ളിൻ തണ്ടുകൾപോലെ അതിൽനിന്ന് പുറത്തുവരും. തുടർന്ന് അവരെ സ്വർഗ്ഗനദികളിൽ വിടും. അതിലവർ കുളിക്കും. (വെളുത്ത) കടലാസുകൾ പോലെ അവർ അതിൽ നിന്ന് പുറത്തുവരും!". (ഈ വിവരണം കേട്ടപ്പോൾ) ഞങ്ങൾ (ഖവാരിജിയ്യത്തിൽ നിന്ന്) മടങ്ങി. ഞങ്ങൾ ചോദിച്ചു: നിങ്ങൾക്കു നാശം! ഈ ഗുരു നബി(സ)യെക്കുറിച്ച് കള്ളം പറയുകയാണെന്ന് നിങ്ങൾ ധരിക്കുന്നുവോ. ഞങ്ങളെല്ലാവരും പിന്മടങ്ങി: അല്ലാഹുവാണെ, ഒരു മനുഷ്യനൊഴികെ മറ്റാരും പിന്നെ ഖവാരിജി സ്ഥാനത്തിൽ തുടർന്നില്ല. (മു)', 'يَزِيدَ الْفَقِيرِ', 'യസീദുൽ ഫഖീർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 124, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَخْرُجُ مِنَ النَّارِ أَرْبَعَةٌ، فَيُعْرَضُونَ عَلَى اللهِ فَيَلْتَفِتُ أَحَدُهُمْ فَيَقُولُ: أَيْ رَبِّ! إِذْ أَخْرَجْتَنِي مِنْهَا فَلَا تُعِدْنِي فِيهَا، فَيُنْجِيهِ اللهُ مِنْهَا". (م)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)പറഞ്ഞു: "നരകത്തിൽ നിന്ന് നാലാളുകൾ പുറത്ത് വരും. അവർ അല്ലാഹുവിന്റെ മുമ്പിൽ പ്രദർശിപ്പിക്കപ്പെടും. അവരിൽ ഒരാൾ തിരിഞ്ഞു നോക്കിപ്പറയും: നാഥാ, എന്നെ അതിൽ നിന്ന് പുറത്തുകൊണ്ടു വന്നിരിക്കെ ഇനിയും അതിലേക്ക് തന്നെ മടക്കരുതേ!'' അങ്ങനെ അദ്ദേഹത്തെ അല്ലാഹു നരകത്തിൽ നിന്ന് രക്ഷിക്കും. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', '⁵. ദൈവത്തിനല്ലാതെ വിധികർതൃത്വമില്ലെന്ന് വാദിച്ച് അലി(റ)യുടെ സൈന്യത്തിൽ നിന്നും തെറ്റിപ്പിരിഞ്ഞ രാഷ്ട്രീയ പ്രസ്ഥാനം. ഇസ്ലാമിക സമൂഹത്തിലെ ആദ്യത്തെ അവാന്തര വിഭാഗമാണിവർ. നരകത്തിൽ കടന്നവരെല്ലാം അവിടെ ശാശ്വതമാണെന്ന് പുലർത്തുന്നവരാണിവർ. അലി(റ)യും മുആവിയ(റ)യും തമ്മിലുള്ള തർക്കങ്ങൾ തുടങ്ങിയ ഒട്ടേറെ പിഴച്ച ആശയങ്ങൾ വെച്ച് മദ്ധ്യസ്ഥരുടെ തീരുമാനത്തിനു വിടാം എന്ന ഇമാം അലി(റ)യുടെ നിലപാടിനെ ചോദ്യം ചെയ്തുകൊണ്ടാണ് ഇവർ വഴിപിരിഞ്ഞത്.', null, array['م']::text[], array['മു']::text[], null, null, 125, 125, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ عِنْدَ سَعِيدِ بْنِ جُبَيْرٍ فَقَالَ: أَيُّكُمْ رَأَى الْكَوْكَبَ الَّذِي انْقَضَّ الْبَارِحَةَ؟ قُلْتُ: أَنَا، ثُمَّ قُلْتُ: أَمَا إِنِّي لَمْ أَكُنْ فِي صَلَاةٍ وَلَكِنِّي لُدِغْتُ، قَالَ : فَمَاذَا صَنَعْتَ؟ قُلْتُ: اسْتَرْقَيْتُ، قَالَ: فَمَا حَمَلَكَ عَلَى ذَلِكَ؟ قُلْتُ: حَدِيثٌ حَدَّثْنَاهُ الشَّعْبِيُّ، فَقَالَ: وَمَا حَدَّثَكُمُ الشَّعْبِيُّ؟ قُلْتُ: حَدَّثَنَا عَنْ بُرَيْدَةَ بْنِ حُصَيْبٍ الْأَسْلَمِيِّ أَنَّهُ قَالَ: لَا رُقْيَةَ إِلَّا مِنْ عَيْنٍ أَوْ حُمَةٍ، فَقَالَ: قَدْ أَحْسَنَ مَنِ انْتَهَى إِلَى مَا سَمِعَ، وَلَكِنْ حَدَّثَنَا ابْنُ عَبَّاسٍ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "عُرِضَتْ عَلَيَّ الْأُمَمُ، فَرَأَيْتُ النَّبِيَّ وَمَعَهُ الرُّهَيْطُ، وَالنَّبِيَّ وَمَعَهُ الرَّجُلُ وَالرَّجُلَانِ، وَالنَّبِيَّ لَيْسَ مَعَهُ أَحَدٌ، إِذْ رُفِعَ لِي سَوَادٌ عَظِيمٌ، فَظَنَنْتُ أَنَّهُمْ أُمَّتِي، فَقِيلَ لِي: هَذَا مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَوْمُهُ، وَلَكِنِ انْظُرْ إِلَى الْأُفُقِ، فَنَظَرْتُ فَإِذَا سَوَادٌ عَظِيمٌ، فَقِيلَ لِي: انْظُرْ إِلَى الْأُفُقِ الْآخَرِ، فَإِذَا سَوَادٌ عَظِيمٌ، فَقِيلَ لِي: هَذِهِ أُمَّتُكَ، وَمَعَهُمْ سَبْعُونَ أَلْفًا يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ" ثُمَّ نَهَضَ فَدَخَلَ مَنْزِلَهُ، فَخَاضَ النَّاسُ فِي أُولَئِكَ الَّذِينَ يَدْخُلُونَ الْجَنَّةَ بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ، فَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ صَحِبُوا رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ بَعْضُهُمْ: فَلَعَلَّهُمُ الَّذِينَ وُلِدُوا فِي الْإِسْلَامِ وَلَمْ يُشْرِكُوا بِاللهِ، وَذَكَرُوا أَشْيَاءَ، فَخَرَجَ عَلَيْهِمْ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "مَا الَّذِي تَخُوضُونَ فِيهِ؟" فَأَخْبَرُوهُ، فَقَالَ: "هُمُ الَّذِينَ لَا يَرْقُونَ وَلَا يَسْتَرْقُونَ وَلَا يَتَطَيَّرُونَ وَعَلَى رَبِّهِمْ يَتَوَكَّلُونَ". فَقَامَ عُكَّاشَةُ بْنُ مِحْصَنٍ فَقَالَ: ادْعُ اللهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: "أَنْتَ مِنْهُمْ" ثُمَّ قَامَ رَجُلٌ آخَرُ فَقَالَ: ادْعُ اللهَ أَنْ يَجْعَلَنِي مِنْهُمْ، فَقَالَ: "سَبَقَكَ بِهَا عُكَّاشَةُ". (م)', 'ഹുസൈ്വനുബ്നു അബ്ദുറഹ്മാൻ(റ): ഞാൻ സഈദുബ്നു ജുബൈറി(റ)ന്റെ അടുത്തു നിൽക്കുമ്പോൾ അദ്ദേഹം ചോദിച്ചു: ഇന്നലെ രാത്രി വീണ നക്ഷത്രത്തെ ആരാണ് കണ്ടത്. ഞാൻ പറഞ്ഞു: ഞാൻ കണ്ടു, കാരണം ഇന്നലെ ഞാൻ നിസ്കാരത്തിൽ മുഴുകിയിട്ടൊന്നുമുണ്ടായിരുന്നില്ല. പ്രത്യുത എനിക്ക് വിഷബാധയേറ്റിരുന്നു. സഈദ് ചോദിച്ചു: എന്നിട്ട് നീ എന്തുചെയ്തു. ഞാൻ പറഞ്ഞു: ഞാൻ മന്ത്രിച്ചു സഈദ് ചോദിച്ചു: അതിന് നിന്നെ പ്രേരിപ്പിച്ചതെന്താണ്? ഞാൻ പറഞ്ഞു: ശഅ്ബി ഉദ്ധരിച്ച ഒരു ഹദീസ് സഈദ് പറഞ്ഞു: ശഅ്ബി പറഞ്ഞതെന്തായിരുന്നു? ഞാൻ പറഞ്ഞു: "ബുറൈദത്തുബ്നു ഹുസൈബിൽ അസ്ലമി ഞങ്ങളോട് പറഞ്ഞു: കണ്ണേറിനും, വിഷബാധക്കുമല്ലാതെ മന്ത്രമില്ല" സഈദ് പറഞ്ഞു: കേട്ടതനുസരിച്ച് പ്രവർത്തിച്ചത് ഏതായാലും നന്ന്, പക്ഷെ, നബി(സ)യിൽ നിന്ന് ഇബ്നുഅബ്ബാസ്(റ) നിവേദനം ചെയ്യുന്ന ഒരു ഹദീസിൽ ഇങ്ങനെ കാണാം: നബി(സ) പറഞ്ഞു: "എനിക്ക് ജനസമൂഹങ്ങളെ കാണിച്ചുതന്നു. അവരിൽ ഒരു നബിയെ ഞാൻ കണ്ടു; അദ്ദേഹത്തോടൊപ്പം പത്തിൽ താഴെ വരുന്ന ഒരു സംഘമാണുള്ളത്. മറ്റൊരു നബിയെകണ്ടു. അദ്ദേഹത്തോടൊപ്പം ഒന്നും രണ്ടും ആളുകൾ! ഒരാൾപോലും കൂടെയില്ലാത്ത നബിയും ഉണ്ട്! അപ്പോഴാണ് ഒരു വൻസംഘം ഉയർന്നു കണ്ടത്. അതെന്റെ സമുദായമായിരിക്കുമെന്ന് ഞാൻ കരുതി. പക്ഷേ, അത് മൂസാനബിയും സമുദായവുമാണെന്ന് എനിക്ക് വിവരം ലഭിച്ചു. ചക്രവാളത്തിലേക്ക് നോക്കുവാൻ എന്നോട് കൽപ്പിച്ചു. അതാ അവിടെ ഒരു വൻ സംഘം! തുടർന്ന് മറ്റേ ചക്രവാളത്തിലേക്ക് നോക്കാൻ ഉത്തരവ് ലഭിച്ചു. അവിടെയും അതാ ഒരു വൻസംഘം. അവയാണ് തന്റെ സമുദായമെന്ന് വിവരം ലഭിച്ചു. അവരിൽ വിചാരണയോ ശിക്ഷയോ കൂടാതെ സ്വർഗ്ഗത്തിൽ കടക്കുന്ന എഴുപതിനായിരം പേരുണ്ട്." ഇതുപറഞ്ഞ് നബി(സ) വീട്ടിലേക്കുപോയി. ജനങ്ങൾ ഈ ആളുകളെക്കുറിച്ച ചർച്ചയിൽ ഏർപ്പെട്ടു. ചിലർ പറഞ്ഞു: ഒരുപക്ഷേ, നബിയുടെ അനുചരന്മാരായിരിക്കും അവർ. മറ്റുചിലർ പറഞ്ഞു: മുസ്ലിമായി ജനിച്ച് ശിർക് ചെയ്യാതെ ജീവിച്ചവരായിരിക്കും. അങ്ങനെ അവർ പലതും പറഞ്ഞുകൊണ്ടിരിക്കെ നബി(സ) അവർക്കിടയിലേക്ക് ഇറങ്ങിവന്ന് ചോദിച്ചു: "നിങ്ങളെന്തിലാണ് മുഴുകിയിരിക്കുന്നത്." അവർ വിഷയം പറഞ്ഞപ്പോൾ നബി(സ) സംഗതി വിശദീകരിച്ചു: "മന്ത്രിക്കുകയോ മന്ത്രിപ്പിക്കുകയോ പക്ഷിലക്ഷണം നോക്കുകയോ ചെയ്യാതെ അല്ലാഹുവിൽ പരിപൂർണ്ണമായി ഭാരമേൽപ്പിക്കുന്നവരാണവർ⁶" അപ്പോൾ ഉക്കാശതുബ്നു മിഹ്സ്വൻ(റ) എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: അവരിൽ എന്നെയും ഉൾപ്പെടുത്താൻ പ്രാർത്ഥിച്ചാലും. നബി(സ) പറഞ്ഞു: "നീ അവരിൽ പെട്ടവനാണ്." പിന്നെ മറ്റൊരാൾ എഴുന്നേറ്റുനിന്ന് പറഞ്ഞു: ഞാനും അവരിൽ ഉൾപ്പെടാൻ പ്രാർത്ഥിച്ചാലും. നബി(സ): "ആ സ്ഥാനം നിന്നേക്കാൾ ആദ്യം ഉക്കാശ ചോദിച്ചു പോയല്ലോ." (മു)', 'حُصَيْنِ بْنِ عَبْدِ الرَّحْمَنِ', 'ഹുസൈ്വനുബ്നു അബ്ദുറഹ്മാൻ(റ)', '⁶. പൂർണ്ണമായും അല്ലാഹുവിൽ അർപ്പിച്ച് സമ്പൂർണ്ണ സമർപ്പണവുമായി കഴിയുന്നവരാണു മുതവക്കിലുകൾ.', null, array['م']::text[], array['മു']::text[], null, null, 125, 126, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَقُولُ اللهُ عَزَّ وَجَلَّ: يَا آدَمُ، فَيَقُولُ: لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ فِي يَدَيْكَ، قَالَ: يَقُولُ: أَخْرِجْ بَعْثَ النَّارِ، قَالَ: وَمَا بَعْثُ النَّارِ؟ قَالَ: مِنْ كُلِّ أَلْفٍ تِسْعَ مِائَةٍ وَتِسْعَةً وَتِسْعِينَ، قَالَ: فَذَاكَ حِينَ يَشِيبُ الصَّغِيرُ {وَتَضَعُ كُلُّ ذَاتِ حَمْلٍ حَمْلَهَا وَتَرَى النَّاسَ سُكَارَى وَمَا هُمْ بِسُكَارَى وَلَكِنَّ عَذَابَ اللهِ شَدِيدٌ} قَالَ: فَاشْتَدَّ عَلَيْهِمْ". قَالُوا: يَا رَسُولَ اللهِ، أَيُّنَا ذَلِكَ الرَّجُلُ؟ فَقَالَ: "أَبْشِرُوا، فَإِنَّ مِنْ يَأْجُوجَ وَمَأْجُوجَ أَلْفًا، وَمِنْكُمْ رَجُلٌ" قَالَ: ثُمَّ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَطْمَعُ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ" فَحَمِدْنَا اللهَ وَكَبَّرْنَا، ثُمَّ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَطْمَعُ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ" فَحَمِدْنَا اللهَ وَكَبَّرْنَا، ثُمَّ قَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَطْمَعُ أَنْ تَكُونُوا شَطْرَ أَهْلِ الْجَنَّةِ، إِنَّ مَثَلَكُمْ فِي الْأُمَمِ كَمَثَلِ الشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الْأَسْوَدِ – وَفِي رِوَايَةٍ: أَوْ كَالشَّعْرَةِ السَّوْدَاءِ فِي الثَّوْرِ الْأَبْيَضِ – أَوْ كَالرَّقْمَةِ فِي ذِرَاعِ الْحِمَارِ". (م)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "അല്ലാഹു പറയും: ഓ! ആദം! ആദം(അ) പറയുകയും: നാഥാ! ഞാനിതാ! നിന്റെ അധീനത്തിലാണ് വിജയം, നന്മ മുഴുവൻ നിന്റെ പക്കലാണ്. അല്ലാഹു പറയും: നരക സംഘത്തെ പുറത്തേക്കു കൊണ്ടുവരൂ. ആദം പറയും: ഏതാണ് നരകസംഘം? അല്ലാഹു പറയും: ഓരോ ആയിരത്തിലും തൊള്ളായിരത്തി തൊണ്ണൂറ്റി ഒമ്പതു പേർ." നബി(സ) തുടരുന്നു: "കുട്ടികൾ നരക്കുകയും ഗർഭിണികൾ പ്രസവിച്ചു പോകുകയും ജനങ്ങളൊക്കെയും മത്ത് പിടിക്കാതെതന്നെ മത്ത് പിടിച്ചവരാകുകയും ചെയ്യുന്ന ദിവസമാണത്. അല്ലാഹുവിന്റെ ശിക്ഷ ഘോരമായിരിക്കും." റിപ്പോർട്ടർ പറയുന്നു: ഇതുകേട്ട് ജനങ്ങൾക്ക് പ്രയാസം തോന്നി. അവർ ചോദിച്ചു: ആ ഒരു മനുഷ്യൻ ഞങ്ങളിൽ ആരാണ്? നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സന്തോഷിക്കൂ. യഅ്ജൂജ് മഅ്ജൂജിൽ നിന്ന് ആയിരം പേരുണ്ടാകുമ്പോൾ നിങ്ങളിൽ നിന്ന് ഒരാൾ മാത്രമേ ഉണ്ടാകൂ" ശേഷം നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനാണെ! സ്വർഗ്ഗവാസികളിൽ നാലിലൊന്ന് നിങ്ങളാവണമെന്ന് ഞാൻ കൊതിക്കുന്നു." അപ്പോൾ ഞങ്ങൾ അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവന്റെ മഹത്വം ഉൽഘോഷിക്കുകയും ചെയ്തു. വീണ്ടും നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനാണെ! സ്വർഗ്ഗവാസികളിൽ മൂന്നിലൊന്ന് നിങ്ങളാവണമെന്ന് ഞാൻ കൊതിക്കുന്നു." ഞങ്ങൾ അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവന്റെ മഹത്വം ഉൽഘോഷിക്കുകയും ചെയ്തു. പിന്നെയും നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവനാണെ! സ്വർഗ്ഗവാസികളിൽ പകുതിയും നിങ്ങളാകണമെന്ന് ഞാൻ കൊതിക്കുന്നു. തീർച്ചയായും സമൂഹങ്ങളിൽ നിങ്ങൾക്കുള്ള ഉപമ കറുത്ത കാളയുടെ തൊലിപ്പുറത്തുള്ള വെളുത്ത രോമം പോലെയോ വെളുത്ത കാളയുടെ തൊലിപ്പുറത്തുള്ള കറുത്തരോമം പോലെയോ കഴുതയുടെ കയ്യിന്മേലുള്ള വര പോലെയോ ആണ്." (മു)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 126, 127, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=9 and h.hadith_no=137), 1, 'وَفِي رِوَايَةٍ: أَوْ كَالشَّعْرَةِ السَّوْدَاءِ فِي الثَّوْرِ الْأَبْيَضِ – أَوْ كَالرَّقْمَةِ فِي ذِرَاعِ الْحِمَارِ". (م)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي قُبَّةٍ نَحْوًا مِنْ أَرْبَعِينَ رَجُلًا، فَقَالَ: "أَتَرْضَوْنَ أَنْ تَكُونُوا رُبُعَ أَهْلِ الْجَنَّةِ؟" قَالَ: قُلْنَا: نَعَمْ، فَقَالَ: "أَتَرْضَوْنَ أَنْ تَكُونُوا ثُلُثَ أَهْلِ الْجَنَّةِ؟" فَقُلْنَا: نَعَمْ، فَقَالَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَرْجُو أَنْ تَكُونُوا نِصْفَ أَهْلِ الْجَنَّةِ، وَذَاكَ أَنَّ الْجَنَّةَ لَا يَدْخُلُهَا إِلَّا نَفْسٌ مُسْلِمَةٌ، وَمَا أَنْتُمْ فِي أَهْلِ الشِّرْكِ إِلَّا كَالشَّعْرَةِ الْبَيْضَاءِ فِي جِلْدِ الثَّوْرِ الْأَسْوَدِ أَوْ كَالشَّعْرَةِ السَّوْدَاءِ فِي جِلْدِ الثَّوْرِ الْأَحْمَرِ". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ ഏകദേശം നാൽപതാളുകൾ നബി(സ)യുടെ കൂടെ ഒരു ''ഖുബ്ബ''യിലിരിക്കവെ അവിടുന്ന് ചോദിച്ചു: "നിങ്ങൾ സ്വർഗ്ഗത്തിന്റെ നാലിലൊന്നാകാൻ ആഗ്രഹിക്കുന്നുവോ? റിപ്പോർട്ടർ പറയുന്നു: ഞങ്ങൾ പറഞ്ഞു: അതേ. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സ്വർഗ്ഗത്തിന്റെ മൂന്നിലൊന്നാകാൻ ആഗ്രഹിക്കുന്നുവോ?" ഞങ്ങൾ പറഞ്ഞു: അതേ. നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ സാക്ഷി, നിങ്ങൾ സ്വർഗ്ഗവാസികളുടെ പകുതിയോളം വരണമെന്ന് ഞാൻ ആഗ്രഹിക്കുന്നു. മുസ്ലിംകളല്ലാതെ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയില്ല. ശിർക്കിന്റെ ആളുകളുടെ ഇടയിൽ നിങ്ങൾ കറുത്ത കാളയുടെ തൊലിയിലെ വെള്ള രോമങ്ങൾ പോലെയോ ചുവന്ന കാളയുടെ തൊലിയിലെ കറുത്ത രോമങ്ങൾ പോലെയോ ആണ്." (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 127, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَيَأْتِيَنَّ عَلَى أُمَّتِي مَا أَتَى عَلَى بَنِي إِسْرَائِيلَ حَذْوَ النَّعْلِ بِالنَّعْلِ، حَتَّى إِنْ كَانَ مِنْهُمْ مَنْ أَتَى أُمَّهُ عَلَانِيَةً لَكَانَ فِي أُمَّتِي مَنْ يَصْنَعُ ذَلِكَ، وَإِنَّ بَنِي إِسْرَائِيلَ تَفَرَّقَتْ عَلَى ثِنْتَيْنِ وَسَبْعِينَ مِلَّةً، وَتَفْتَرِقُ أُمَّتِي عَلَى ثَلَاثٍ وَسَبْعِينَ مِلَّةً، كُلُّهُمْ فِي النَّارِ إِلَّا مِلَّةً وَاحِدَةً" قَالُوا: وَمَنْ هِيَ يَا رَسُولَ اللهِ؟ قَالَ: "مَا أَنَا عَلَيْهِ وَأَصْحَابِي". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "ബനൂഇസ്റാഈല്യരിൽ സംഭവിച്ചതെല്ലാം എന്റെ സമുദായത്തിലും സംഭവിക്കും; ചെരുപ്പ് ചെരുപ്പിനോടെന്ന പോലെ. അവരിൽ പരസ്യമായി ഉമ്മയെ വേഴ്ച ചെയ്തവരുണ്ടെങ്കിൽ അത് ചെയ്യുന്നവൻ എന്റെ സമുദായത്തിലുമുണ്ടാവും. നിശ്ചയം. ബനൂഇസ്റാഈല്യർ വിഭാഗമായി ഭിന്നിച്ചു. എന്റെ സമൂഹം എഴുപത്തിമൂന്ന് വിഭാഗമായി ഭിന്നിക്കും. അതിൽ ഒരു വിഭാഗമൊഴികെ എല്ലാവരും നരകത്തിലാണ്." അവർ ചോദിച്ചു: തിരുദൂതരേ, ആരാണവർ? നബി(സ) പറഞ്ഞു: "ഞാനും എന്റെ സഹചാരികളും (സ്വഹാബികൾ) നിലകൊള്ളുന്ന സരണി സ്വീകരിച്ചവർ." (തു)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عن عبد الله بن عمرو رضي الله عنه قال: سمعت رسول الله صلى الله عليه وسلم يقول: "إن الله عز وجل خلق خلقه في ظلمة، فألقى عليهم من نوره، فمن أصابه من ذلك النور اهتدى، ومن أخطأه ضل، فلذلك أقول: جف القلم على علم الله". (ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഒരുതരം ഇരുളിൽ അല്ലാഹു സൃഷ്ടികളെ സൃഷ്ടിച്ചു. തുടർന്ന് തന്റെ പ്രകാശം അവർക്കുമേൽ വർഷിച്ചു. ആ പ്രകാശമേറ്റവർ സന്മാർഗ്ഗ സിദ്ധരായി. അത് ലഭിക്കാതെ പോയവർ പിഴച്ചു. അതുകൊണ്ടാണ് ഞാൻ പറയുന്നത്. അല്ലാഹുവിന്റെ അറിവിൽ പേന (മഷി) ഉണങ്ങിപ്പോയിരിക്കുന്നു. (വിധി നിശ്ചയിച്ചിരിക്കുന്നു)." (തു)', 'عبد الله بن عمرو', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الْإِسْلَامَ بَدَأَ غَرِيبًا، وَسَيَعُودُ غَرِيبًا كَمَا بَدَأَ، وَهُوَ يَأْرِزُ بَيْنَ الْمَسْجِدَيْنِ كَمَا تَأْرِزُ الْحَيَّةُ فِي جُحْرِهَا". (م)', 'ഇബ്നുഉമർ(റ): പ്രവാചകർ(സ) പറഞ്ഞു: നിശ്ചയം ഇസ്ലാം അപരിചിതമായതായി കൊണ്ടാണ് ആരംഭിച്ചത്. അത് അപരിചിതാവസ്ഥയിലേക്ക് തന്നെ മടങ്ങുകയും ചെയ്യും. പാമ്പ് തന്റെ മാളത്തിലേക്ക് ചുരുണ്ടുകൂടുന്നതുപോലെ അത് ആ രണ്ട് പള്ളികൾക്ക് (മസ്ജിദുൽ ഹറാം, മസ്ജിദുന്നബവി) ഇടയിലേക്ക് മടങ്ങുകയും ചെയ്യും. (മു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 128, 128, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَحْصُوا لِي كَمْ يَلْفِظُ الْإِسْلَامَ" قَالَ: فَقُلْنَا: يَا رَسُولَ اللهِ! أَتَخَافُ عَلَيْنَا وَنَحْنُ مَا بَيْنَ السِّتِّ مِائَةِ إِلَى السَّبْعِ مَائَةٍ، قَالَ: "إِنَّكُمْ لَا تَدْرُونَ لَعَلَّكُمْ أَنْ تُبْتَلَوْا" قَالَ: فَابْتُلِينَا حَتَّى جَعَلَ الرَّجُلُ مِنَّا لَا يُصَلِّي إِلَّا سِرًّا. (م)', 'ഹുദൈഫ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം നിൽക്കവെ, അവിടുന്ന് ചോദിച്ചു: "എത്രപേർ ഇസ്ലാം പ്രഖ്യാപിക്കുന്നുണ്ട് എന്നൊന്ന് എണ്ണിത്തരൂ." റിപ്പോർട്ടർ പറയുന്നു: ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ ദൂതരേ, ഞങ്ങൾ അറുനൂറ് എഴുനൂറ് പേർ ഉണ്ടായിരിക്കെ ഞങ്ങളുടെ കാര്യത്തിൽ അങ്ങ് ഭയപ്പെടുകയോ? നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പരീക്ഷണങ്ങൾക്ക് വിധേയമായേക്കാം. നിങ്ങൾക്കത് ഇപ്പോൾ അറിയില്ല." ഹുദൈഫ(റ) പറയുന്നു: ഞങ്ങൾ പരീക്ഷിക്കപ്പെട്ടു. രഹസ്യമായി മാത്രം നിസ്കരിക്കേണ്ട ഗതികേടുപോലും ഉണ്ടായി. (മു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 128, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: " يُوشِكُ أَنْ يَكُونَ خَيْرَ مَالِ الْمُسْلِمِ غَنَمٌ يَتْبَعُ بِهَا شَغَفَ الْجِبَالِ وَمَوَاقِعَ الْقَطْرِ يَفِرُّ بِدِينِهِ مِنَ الْفِتَنِ". (خ,ن)', 'അബൂസഈദ്(റ): നബി(സ) പറഞ്ഞു: "സത്യവിശ്വാസികളുടെ സമ്പത്തിൽ അതിശ്രേഷ്ഠം ആടുകളായിത്തീരുന്ന കാലം അടുക്കുന്നു. കലാപങ്ങളിൽ നിന്ന് തന്റെ മതവുമായി ഓടിയകന്നു മലമുകളിലും മഴപ്രദേശങ്ങളിലും അവൻ ആടുമേച്ചു ജീവിക്കേണ്ട കാലമായിരിക്കുമത്." (ബു,ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ زَيْدِ بْنِ مِلْحَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ الدِّينَ لَيَأْرِزُ إِلَى الْحِجَازِ كَمَا تَأْرِزُ الْحَيَّةُ إِلَى جُحْرِهَا، وَلَيَعْقِلَنَّ الدِّينُ مِنَ الْحِجَازِ مَعْقِلَ الْأُرْوِيَّةِ مِنْ رَأْسِ الْجَبَلِ، إِنَّ الدِّينَ بَدَأَ غَرِيبًا، وَيَرْجِعُ غَرِيبًا، فَطُوبَى لِلْغُرَبَاءِ! الَّذِينَ يُصْلِحُونَ مَا أَفْسَدَ النَّاسُ مِنْ بَعْدِي مِنْ سُنَّتِي". (ت)', 'സൈദ്ബിൻ മിൽഹ(റ): നബി(സ) പറഞ്ഞു: "പാമ്പ് മാളത്തിലേക്ക് വലിയുംപോലെ ഈ മതം ഹിജാസിലേക്ക് വലിയും. മലയാട് മലമുകളിൽ അഭയം പ്രാപിക്കും പ്രകാരം ഈ മതം ഹിജാസിൽ അഭയം തേടും. ഈ മതം ഒരു ഒരു അപരിചിതാവസ്ഥയിലാണ് തുടങ്ങിയത്; അത് അപരിചതമായതു തന്നെ ആയിത്തീരുകയും ചെയ്യും. (അന്നത്തെ) അപരിചിതർക്ക് (വിരളമായ അനുയായികൾക്ക്) മംഗളങ്ങൾ. എന്റെ ചര്യയിൽ എനിക്ക് ശേഷം ജനങ്ങൾ വികൃതമാക്കിയത് നന്നാക്കുന്നവരാണവർ." (തു)', 'زَيْدِ بْنِ مِلْحَةَ', 'സൈദ്ബിൻ മിൽഹ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 129, 129, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُتِيتُ بِالْبُرَاقِ، وَهُوَ دَابَّةٌ أَبْيَضُ، طَوِيلٌ، فَوْقَ الْحِمَارِ وَدُونَ الْبَغْلِ، يَضَعُ حَافِرَهُ عِنْدَ مُنْتَهَى طَرْفِهِ" قَالَ: "فَرَكِبْتُهُ حَتَّى أَتَيْتُ بَيْتَ الْمَقْدِسِ" قَالَ: "فَرَبَطْتُهُ بِالْحَلْقَةِ الَّتِي يَرْبِطُ بِهِ الْأَنْبِيَاءُ" قَالَ: "ثُمَّ دَخَلْتُ الْمَسْجِدَ، فَصَلَّيْتُ فِيهِ رَكْعَتَيْنِ، ثُمَّ خَرَجْتُ، فَجَاءَنِي جِبْرِيلُ عَلَيْهِ السَّلَامُ بِإِنَاءٍ مِنْ خَمْرٍ وَإِنَاءٍ مِنْ لَبَنٍ، فَاخْتَرْتُ اللَّبَنَ، فَقَالَ جِبْرِيلُ عَلَيْهِ السَّلَامُ: اخْتَرْتَ الْفِطْرَةَ، ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ، فَاسْتَفْتَحَ جِبْرِيلُ، فَقِيلَ: مَنْ أَنْتَ؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: قَدْ بُعِثَ إِلَيْهِ، فَفُتِحَ لَنَا فَإِذَا أَنَا بِآدَمَ، فَرَحَّبَ بِي وَدَعَا لِي بِخَيْرٍ، ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الثَّانِيَةِ، فَاسْتَفْتَحَ جِبْرِيلُ عَلَيْهِ السَّلَامُ، فَقِيلَ: مَنْ أَنْتَ؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: قَدْ بُعِثَ إِلَيْهِ، فَفُتِحَ لَنَا، فَإِذَا أَنَا بِابْنَيِ الْخَالَةِ عِيسَى ابْنِ مَرْيَمَ وَيَحْيَى بْنِ زَكَرِيَّاءَ صَلَوَاتُ اللهِ عَلَيْهِمَا فَرَحَّبَا وَدَعَوَا لِي بِخَيْرٍ، ثُمَّ عَرَجَ بِي إِلَى السَّمَاءِ الثَّالِثَةِ، فَاسْتَفْتَحَ جِبْرِيلُ، فَقِيلَ: مَنْ أَنْتَ؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: قَدْ بُعِثَ إِلَيْهِ، فَفُتِحَ لَنَا، فَإِذَا أَنَا بِيُوسُفَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا هُوَ قَدْ أُعْطِيَ شَطْرَ الْحُسْنِ، فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ، ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الرَّابِعَةِ، فَاسْتَفْتَحَ جِبْرِيلُ عَلَيْهِ السَّلَامُ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قَالَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: قَدْ بُعِثَ إِلَيْهِ، فَفُتِحَ لَنَا، فَإِذَا أَنَا بِإِدْرِيسَ فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ، قَالَ اللهُ عَزَّ وَجَلَّ: {وَرَفَعْنَاهُ مَكَانًا عَلِيًّا} ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ الْخَامِسَةِ، فَاسْتَفْتَحَ جِبْرِيلُ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: قَدْ بُعِثَ إِلَيْهِ، فَفُتِحَ لَنَا، فَإِذَا أَنَا بِهَارُونَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ، ثُمَّ عَرَجَ بِنَا إِلَى السَّمَاءِ السَّادِسَةِ، فَاسْتَفْتَحَ جِبْرِيلُ عَلَيْهِ السَّلَامُ، قِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: قَدْ بُعِثَ إِلَيْهِ، فَفُتِحَ لَنَا، فَإِذَا أَنَا بِمُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَحَّبَ وَدَعَا لِي بِخَيْرٍ، ثُمَّ عَرَجَ إِلَى السَّمَاءِ السَّابِعَةِ، فَاسْتَفْتَحَ جِبْرِيلُ، فَقِيلَ: مَنْ هَذَا؟ قَالَ: جِبْرِيلُ، قِيلَ: وَمَنْ مَعَكَ؟ قَالَ: مُحَمَّدٌ، قِيلَ: وَقَدْ بُعِثَ إِلَيْهِ؟ قَالَ: قَدْ بُعِثَ إِلَيْهِ، فَفُتِحَ لَنَا، فَإِذَا أَنَا بِإِبْرَاهِيمَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مُسْنِدًا ظَهْرَهُ إِلَى الْبَيْتِ الْمَعْمُورِ، وَإِذَا هُوَ يَدْخُلُهُ كُلَّ يَوْمٍ سَبْعُونَ أَلْفَ مَلَكٍ لَا يَعُودُونَ إِلَيْهِ، ثُمَّ ذَهَبَ بِي إِلَى السِّدْرَةِ الْمُنْتَهَى، وَإِذَا وَرَقُهَا كَآذَانِ الْفِيَلَةِ، وَإِذَا ثَمَرُهَا كَالْقِلَالِ، قَالَ فَلَمَّا غَشِيَهَا مِنْ أَمْرِ اللهِ مَا غَشِيَ تَغَيَّرَتْ، فَمَا أَحَدٌ مِنْ خَلْقِ اللهِ يَسْتَطِيعُ أَنْ يَنْعَتَهَا مِنْ حُسْنِهَا، فَأَوْحَى اللهُ إِلَيَّ مَا أَوْحَى، فَفَرَضَ عَلَيَّ خَمْسِينَ صَلَاةً فِي كُلِّ يَوْمٍ وَلَيْلَةٍ فَنَزَلْتُ إِلَى مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَا فَرَضَ رَبُّكَ عَلَى أُمَّتِكَ؟ قُلْتُ: خَمْسِينَ صَلَاةً، قَالَ: ارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ، فَإِنَّ أُمَّتَكَ لَا يُطِيقُونَ ذَلِكَ، فَإِنِّي قَدْ بَلَوْتُ بَنِي إِسْرَائِيلَ وَخَبَرْتُهُمْ، قَالَ: فَرَجَعْتُ إِلَى رَبِّي، فَقُلْتُ: يَا رَبِّ! خَفِّفْ عَلَى أُمَّتِي، فَحَطَّ عَنِّي خَمْسًا، فَرَجَعْتُ إِلَى مُوسَى فَقُلْتُ: حَطَّ عَنِّي خَمْسًا، قَالَ: إِنَّ أُمَّتَكَ لَا يُطِيقُونَ ذَلِكَ، فَارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ، قَالَ: فَلَمْ أَزَلْ أَرْجِعُ بَيْنَ رَبِّي تَبَارَكَ وَتَعَالَى وَبَيْنَ مُوسَى عَلَيْهِ السَّلَامُ حَتَّى قَالَ: يَا مُحَمَّدُ! إِنَّهُنَّ خَمْسُ صَلَوَاتٍ كُلَّ يَوْمٍ وَلَيْلَةٍ لِكُلِّ صَلَاةٍ عَشْرٌ فَذَلِكَ خَمْسُونَ صَلَاةً، وَمَنْ هَمَّ بِحَسَنَةٍ فَلَمْ يَعْمَلْهَا كُتِبَتْ لَهُ حَسَنَةً، فَإِنْ عَمِلَهَا كُتِبَتْ لَهُ عَشْرًا، وَمَنْ هَمَّ بِسَيِّئَةٍ فَلَمْ يَعْمَلْهَا لَمْ تُكْتَبْ شَيْئًا، فَإِنْ عَمِلَهَا كُتِبَتْ سَيِّئَةً وَاحِدَةً، قَالَ: فَنَزَلْتُ حَتَّى انْتَهَيْتُ إِلَى مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَخْبَرْتُهُ، فَقَالَ: ارْجِعْ إِلَى رَبِّكَ فَاسْأَلْهُ التَّخْفِيفَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: فَقُلْتُ: قَدْ رَجَعْتُ إِلَى رَبِّي حَتَّى اسْتَحْيَيْتُ مِنْهُ". (م)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) പറഞ്ഞു: "എന്റെയടുക്കൽ ബുറാഖ് എത്തി. വെളുത്തു നീണ്ട ആ മൃഗം കഴുതയേക്കാൾ വലുതും എന്നാൽ കോവർ കഴുതയേക്കാൾ ചെറുതുമായിരുന്നു. കണ്ണെത്തുന്ന ദൂരത്താണത് കുളമ്പ് വെക്കുന്നത്! ഞാനതിൽ കയറി. അങ്ങനെ ബൈതുൽമുഖദ്ദസിലെത്തി. (മുൻ) പ്രവാചകന്മാർ കെട്ടാൻ ഉപയോഗിച്ചിരുന്ന ഒരു കണ്ണി കൊണ്ട് ഞാനതിനെ കെട്ടിയിട്ടു. ശേഷം പള്ളിയിൽ കയറി രണ്ട് റക്അത്ത് നിസ്കരിച്ചു. പുറത്തിറങ്ങിയപ്പോൾ ജിബ്രീൽ(അ) രണ്ട് പാത്രവുമായി വന്നു. ഒന്നിൽ പാൽ. മറ്റേതിൽ മദ്യം! ഞാൻ പാൽ തെരഞ്ഞെടുത്തു. ''അങ്ങ് ശുദ്ധമായത് തെരഞ്ഞെടുത്തിരിക്കുന്നു.'' എന്ന് ജിബ്രീൽ(അ) പ്രതികരിച്ചു. തുടർന്ന് എന്നെയും കൊണ്ട് ജിബ്രീൽ ഉപരിലോകത്തേക്ക് കയറി. ജിബ്രീൽ (കവാടം) തുറക്കാൻ ആവശ്യപ്പെട്ടു. അപ്പോൾ ചോദിക്കപ്പെട്ടു: ആരാണത്? അദ്ദേഹം പറഞ്ഞു: ജിബ്രീലാണ്. കൂടെ ആര്? എന്ന് ചോദിക്കപ്പെട്ടപ്പോൾ ''മുഹമ്മദ്'' എന്ന് അദ്ദേഹം പറഞ്ഞു. അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരുന്നുവോ? എന്നു ചോദിക്കപ്പെട്ടു. അതെ, അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരിക്കുന്നു എന്ന് മറുപടി നൽകി. വാതിൽ തുറക്കപ്പെട്ടു. അവിടെ അതാ ആദം(അ). അവിടുന്ന് എന്നെ സ്വീകരിച്ചു. എനിക്ക് നന്മകൊണ്ട് പ്രാർത്ഥിച്ചു. പിന്നെ എന്നെയുമായി ജിബ്രീൽ രണ്ടാം ആകാശത്തിൽ കയറി. ജിബ്രീൽ കവാടം തുറക്കാൻ ആവശ്യപ്പെട്ടു. ഇതാരാണ് എന്നു ചോദിക്കപ്പെട്ടു? ഇത് ജിബ്രീൽ ആണെന്ന് പ്രത്യുത്തരം നൽകി. നിങ്ങളുടെ കൂടെ ആരാണ് എന്ന് ചോദിക്കപ്പെട്ടു? മുഹമ്മദ്(സ) ആണെന്ന് മറുപടി നൽകി. അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരുന്നുവോ? എന്നു ചോദിക്കപ്പെട്ടു. അതെ, അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരിക്കുന്നു എന്ന് മറുപടി നൽകി. വാതിൽ തുറക്കപ്പെട്ടു. അവിടെ സഹോദരൻ ഈസബ്നു മർയമും യഹ്യബ്നു സകരിയ്യയും (നില്ക്കുന്നു). അവർ രണ്ടുപേരും എനിക്ക് സ്വാഗതമോതി, പ്രാർത്ഥിച്ചു. തുടർന്ന് എന്നെയുമായി മൂന്നാം ആകാശത്തേക്കു പോയി. ജിബ്രീൽ ആ കവാടം തുറക്കാൻ ആവശ്യപ്പെട്ടു. ഇതാരാണ് ചോദിക്കപ്പെട്ടു? ഇത് ജിബ്രീൽ ആണെന്ന് മറുപടി നൽകി. നിങ്ങളുടെ കൂടെ ആരാണ്? എന്ന് ചോദിക്കപ്പെട്ടു. മുഹമ്മദ്(സ) ആണെന്ന് പ്രത്യുത്തരം നൽകി. അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരുന്നുവോ? എന്നു ചോദിക്കപ്പെട്ടു. അതെ, അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരിക്കുന്നു എന്ന് മറുപടി നൽകി. വാതിൽ തുറക്കപ്പെട്ടു. അവിടെ യൂസുഫ് നബി(അ) ഉണ്ടായിരുന്നു. അദ്ദേഹത്തിന് സൗന്ദര്യത്തിന്റെ പകുതി നൽകപ്പെട്ടിരിക്കുന്നു. യൂസുഫ്(അ) എനിക്ക് സ്വാഗതമരുളി, നന്മക്കായ് പ്രാർത്ഥിച്ചു. പിന്നെ നാലാം ആകാശത്തിലേക്ക് ഞങ്ങൾ കയറി. ജിബ്രീൽ തുറക്കാൻ ആവശ്യപ്പെട്ടു. ഇതാരാണ്? എന്ന് ചോദിക്കപ്പെട്ടു. ഇത് ജിബ്രീൽ ആണെന്ന് ഉത്തരം നൽകി. നിങ്ങളുടെ കൂടെ ആരാണ്? എന്ന് ചോദിക്കപ്പെട്ടു. മുഹമ്മദ്(സ) ആണെന്ന് പ്രത്യുത്തരം നൽകി. അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരുന്നുവോ? എന്നു ചോദിക്കപ്പെട്ടു. അതെ, അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരിക്കുന്നു എന്ന് മറുപടി നൽകി. വാതിൽ തുറക്കപ്പെട്ടു. അവിടെ ഇദ്രീസ്(അ) ഉണ്ടായിരുന്നു. അദ്ദേഹം എന്നെ സ്വീകരിച്ചു. എനിക്ക് നന്മകൊണ്ട് പ്രാർത്ഥിച്ചു. അല്ലാഹു (ഇദ്രീസ് നബിയെക്കുറിച്ച്) ''അദ്ദേഹത്തെ നാം ഉയർന്ന സ്ഥലത്തേക്ക് ഉയർത്തി പ്രസ്താവിച്ചിട്ടുണ്ട്.'' അഞ്ചാം ആകാശത്തിലെത്തുന്നു. ജിബ്രീൽ തുറക്കാൻ ആവശ്യപ്പെട്ടു. ഇതാരാണ്? എന്നു ചോദിക്കപ്പെട്ടു. ഇത് ജിബ്രീൽ ആണെന്നു ഉത്തരം നൽകി. നിങ്ങളുടെ കൂടെ ആരാണ്? എന്ന് ചോദിക്കപ്പെട്ടു. മുഹമ്മദ്(സ) ആണെന്ന് പ്രത്യുത്തരം നൽകി. അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരുന്നുവോ? എന്നു ചോദിക്കപ്പെട്ടു. അതെ, അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരിക്കുന്നു എന്ന് മറുപടി നൽകി. വാതിൽ തുറപ്പെട്ടു. അവിടെ ഹാറൂൻ നബി(അ)യെ കണ്ടു. ഹാറൂൻ(അ) എന്നെ സ്വീകരിച്ചു. നന്മക്കായി പ്രാർഥിച്ചു. തുടർന്ന് ആറാം ആകാശത്തേക്ക്. ജിബ്രീൽ തുറക്കാൻ ആവശ്യപ്പെട്ടു. ആരാണത്? എന്ന് ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ ആണെന്ന് മറുപടി പറഞ്ഞു. നിങ്ങളുടെ കൂടെ ആരാണ്? എന്ന് ചോദിക്കപ്പെട്ടു. മുഹമ്മദ്(സ) ആണെന്ന് പ്രത്യുത്തരം നൽകി. അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരുന്നുവോ? എന്നു ചോദിക്കപ്പെട്ടു. അതെ, അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരിക്കുന്നു എന്ന് മറുപടി നൽകി. ആകാശം തുറക്കപ്പെട്ടു. അവിടെയതാ മൂസാ നബി(അ). എന്നെ സ്വാഗതം ചെയ്യുകയും എനിക്കുവേണ്ടി പ്രാർത്ഥിക്കുകയും ചെയ്തു. പിന്നെ ഏഴാം ആകാശത്തേക്ക് യാത്ര തിരിക്കുന്നു. വാതിൽ തുറക്കാനാവശ്യപ്പെടുന്നു. ആരാണത്? എന്ന ചോദിക്കപ്പെട്ടു. ജിബ്രീൽ ആണെന്ന് മറുപടി നൽകി. നിങ്ങളുടെ കൂടെ ആരാണ്? എന്ന് ചോദിക്കപ്പെട്ടു. മുഹമ്മദ്(സ) ആണെന്ന് പ്രത്യുത്തരം നൽകി. അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരുന്നുവോ? എന്നു ചോദിക്കപ്പെട്ടു. അതെ, അദ്ദേഹത്തിലേക്ക് ആളെ നിയോഗിച്ചിരിക്കുന്നു എന്ന് മറുപടി നൽകി. ആകാശ കവാടം തുറക്കപ്പെട്ടു. അവിടെ ഇബ്രാഹീം നബിയെ കണ്ടു. ''ബൈത്തുൽ മഅ്മൂറി''⁷ലേക്ക് ചാരിയിരിക്കുകയാണ് ഇബ്രാഹീം(അ). ദിവസവും എഴുപതിനായിരം മലക്കുകൾ അവിടെ കയറുന്നു. അവരൊന്നും പിന്നെ മടങ്ങിവരാറില്ല. പിന്നീട് ഞങ്ങൾ ''സിദ്റതുൽ മുൻതഹാ'' എന്ന വൃക്ഷത്തിനടുത്തേക്ക് പോയി. ആനകളുടെ ചെവിപോലുള്ള ഇലകളും ഭരണികൾ പോലുള്ള പഴങ്ങളുമുള്ള വൃക്ഷം. അല്ലാഹുവിന്റെ കൽപനപ്രകാരം അതിനെ പൊതിയാനുള്ളതൊക്കെ (ചമയങ്ങൾ) പൊതിഞ്ഞപ്പോൾ അതിനു മാറ്റം വന്നു. അതിന്റെ സൗന്ദര്യം വർണ്ണിക്കാൻ ഒരു സൃഷ്ടിക്കും സാധ്യമല്ല. എനിക്ക് അപ്പോൾ അല്ലാഹു ബോധനം നൽകിയതൊക്കെ ബോധനം നൽകി. അമ്പത് നേരം നിസ്കാരം എനിക്ക് നിർബന്ധമായി കൽപിച്ചു. ഞാൻ മടങ്ങിവരവെ മൂസാനബി(അ)യുടെ അടുത്തെത്തിയപ്പോൾ അദ്ദേഹം ചോദിച്ചു: താങ്കളുടെ നാഥൻ സമുദായത്തിന് എന്താണ് നിർബന്ധമാക്കിയത്?. ഞാൻ പറഞ്ഞു: അൻപത് നേരത്തെ നിസ്കാരം. മൂസാ(അ) പറഞ്ഞു: മടങ്ങൂ, ലഘൂകരിച്ചുതരാൻ ആവശ്യപ്പെടൂ, നിങ്ങളുടെ സമുദായത്തിന് അത് സാധിക്കില്ല. ഞാൻ ബനൂഇസ്രാഈലിനു (അനേകം) പരീക്ഷിച്ച് അറിഞ്ഞതാണ്. (അങ്ങനെ) ഞാൻ എന്റെ നാഥന്റെ സമീപത്തേക്കുതന്നെ തിരിച്ചുപോയി പറഞ്ഞു: നാഥാ, എന്റെ സമുദായത്തിന് ലഘൂകരിച്ചുതരൂ. അങ്ങനെ അഞ്ചു നേത്ത് മാത്രമാക്കി നിസ്കാരം ചുരുക്കിത്തന്നു. ഞാൻ മൂസ(അ)യുടെ അടുത്തേക്കുതന്നെ മടങ്ങി, അഞ്ചെണ്ണം ആക്കി ചുരുക്കിത്തന്ന കാര്യം അറിയിച്ചു. മൂസാ നബി(അ) പറഞ്ഞു: നിങ്ങളുടെ സമുദായത്തിന് അതും സാധിക്കുകയില്ല. മടങ്ങിച്ചെന്ന് (ഇനിയും) കുറച്ചുതരാൻ ആവശ്യപ്പെടൂ. നബി(സ) പറഞ്ഞു: മൂസാനബി(അ)ക്കും അല്ലാഹുവിനും ഇടയിൽ ഞാൻ അങ്ങോട്ടുമിങ്ങോട്ടും പോയ്ക്കൊണ്ടിരുന്നു. അവസാനം അല്ലാഹു പറഞ്ഞു: "ഓ മുഹമ്മദ്! നിശ്ചയം, അവ ദിവസവും അഞ്ച് നിസ്കാരങ്ങളാണ്. ഓരോ നിസ്കാരത്തിനും പത്ത് കൂലി കിട്ടുമ്പോൾ അൻപതായി. ആരെങ്കിലും ഒരു സൽക്കർമ്മം ഉദ്ദേശിച്ചു, (പക്ഷേ) ചെയ്യാൻ സാധിച്ചില്ല. എങ്കിൽ അയാൾക്ക് ഒരു കൂലി രേഖപ്പെടുത്തും. ചെയ്താൽ പത്ത് പ്രതിഫലവും രേഖപ്പെടുത്തും. ആരെങ്കിലും ഒരു തെറ്റ് ചെയ്യാൻ ഉദ്ദേശിച്ചു, പക്ഷെ ചെയ്തില്ല. എന്നാൽ ഒന്നും രേഖപ്പെടുത്തില്ല. ചെയ്താൽ ഒരു തെറ്റുമാത്രമായി രേഖപ്പെടുത്തുന്നു. നബി(സ) തുടർന്നു പറയുന്നു: അങ്ങനെ ഞാനിറങ്ങി. മൂസാനബിയെ സമീപിച്ചു വിഷയം ധരിപ്പിച്ചു. അപ്പോൾ മൂസാനബി പറഞ്ഞു: മടങ്ങൂ, ഇനിയും ലഘൂകരണം ആവശ്യപ്പെടൂ, നബി(സ) പറയുന്നു: ഞാൻ പറഞ്ഞു: ഞാൻ (പലപ്രാവശ്യം) അല്ലാഹുവിലേക്ക് മടങ്ങിപ്പോയി. (ഇനി) എനിക്ക് ലജ്ജ തോന്നുന്നു. (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', '⁷. വിശുദ്ധ മക്കയിൽ സ്ഥിതി ചെയ്യുന്ന കഅ്ബയുടെ നേരെ മുകളിലായി ആകാശത്ത് മലക്കുകളുടെ ആരാധനക്കായുള്ള ദൈവഭവനമാണിതെന്ന് കാണാം.', null, array['م']::text[], array['മു']::text[], null, null, 129, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا أُسْرِيَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْتُهِيَ بِهِ إِلَى سِدْرَةِ الْمُنْتَهَى وَهِيَ فِي السَّمَاءِ السَّادِسَةِ إِلَيْهَا يَنْتَهِي مَا يُعْرَجُ بِهِ مِنَ الْأَرْضِ فَيُقْبَضُ مِنْهَا وَ إِلَيْهَا يَنْتَهِي مَا يُهْبَطُ بِهِ مِنْ فَوْقِهَا فَيُقْبَضُ مِنْهَا قَالَ: "{إِذْ يَغْشَى السِّدْرَةَ مَا يَغْشَى} قَالَ: فَرَاشٌ مِنْ ذَهَبٍ، قَالَ: فَأُعْطِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثَلَاثًا، أُعْطِيَ الصَّلَوَاتِ الْخَمْسَ، وَأُعْطِيَ خَوَاتِيمَ سُورَةِ الْبَقَرَةِ، وَغُفِرَ لِمَنْ لَمْ يُشْرِكْ بِاللهِ مِنْ أُمَّتِهِ شَيْئًا الْمُقْحِمَاتُ". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): രാപ്രയാണ വേളയിൽ നബി(സ) ആറാം ആകാശത്തുള്ള സിദ്റതുൽ മുൻതഹാ എന്ന വൃക്ഷത്തിനടുത്തെത്തി. ഭൂമിയിൽ നിന്ന് കയറിപ്പോകുന്നതും ആകാശത്തു നിന്നിറങ്ങുന്നതും അവിടെ ചെന്നവസാനിക്കുകയും അവിടെ പിടിച്ചുവെക്കപ്പെടുകയും ചെയ്യുന്നു. നബി(സ) പറഞ്ഞു: "ആ ഇലന്തമരത്തെ ആവരണം ചെയ്യുന്നതൊക്കയും അതിനെ ആവരണം ചെയ്തിരുന്നപ്പോൾ (53:16) എന്ന് പറഞ്ഞത് ഒരു സ്വർണ്ണ വിരിപ്പിനെക്കുറിച്ചാണ്. നബി(സ)ക്ക് മൂന്ന് കാര്യങ്ങൾ അല്ലാഹു നൽകി; അഞ്ചുനേരത്തെ നിസ്കാരം, സൂറതുൽബഖറയുടെ അവസാന സൂക്തങ്ങൾ, തന്റെ സമുദായത്തിൽ അല്ലാഹുവിൽ പങ്കുചേർക്കാത്തവർക്ക് നാശകാരികളായ ദോഷങ്ങളിൽ നിന്നുള്ള വിമോചനം." (മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "حِينَ أُسْرِيَ بِي لَقِيتُ مُوسَى عَلَيْهِ السَّلَامُ – فَنَعَتَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَإِذَا رَجُلٌ حَسِبْتُهُ قَالَ مُضْطَرِبٌ رَجِلُ الرَّأْسِ كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ، قَالَ: وَلَقِيتُ عِيسَى – فَنَعَتَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فَإِذَا رَبْعَةٌ أَحْمَرُ كَأَنَّمَا خَرَجَ مِنْ دِيمَاسٍ يَعْنِي حَمَّامًا، قَالَ: وَرَأَيْتُ إِبْرَاهِيمَ عَلَيْهِ السَّلَامُ وَأَنَا أَشْبَهُ وَلَدِهِ بِهِ، قَالَ: فَأُتِيتُ بِإِنَاءَيْنِ فِي أَحَدِهِمَا لَبَنٌ وَفِي الْآخَرِ خَمْرٌ، فَقِيلَ لِي: خُذْ أَيَّهُمَا شِئْتَ، فَأَخَذْتُ اللَّبَنَ فَشَرِبْتُهُ، فَقَالَ: هُدِيتَ الْفِطْرَةَ، أَوْ أَصَبْتَ الْفِطْرَةَ، أَمَا إِنَّكَ لَوْ أَخَذْتَ الْخَمْرَ غَوَتْ أُمَّتُكَ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ രാപ്രയാണ വേളയിൽ ഞാൻ മൂസാനബി(അ)യെ കണ്ടുമുട്ടി. നബി(സ) മൂസാനബി(അ)യെ വർണ്ണിച്ചു. ചുരുണ്ട തലമുടി ചീകിവെച്ച, മെലിഞ്ഞ ഒരാൾ. ശനൂഅഃ വർഗ്ഗക്കാരിൽപ്പെട്ടയാളാണെന്ന് തോന്നും. ഈസാ നബി(അ)യെയും കണ്ടു. അദ്ദേഹത്തെയും നബി(സ) വർണ്ണിച്ചു. ചുവന്ന ഒത്ത ഒരാൾ. കുളിപ്പുരയിൽ നിന്ന് ഇറങ്ങി വരികയാണെന്ന് തോന്നും. ഇബ്രാഹീം നബി(അ)യെയും ഞാൻ കണ്ടു. അവിടുത്തോട് ഏറ്റം സാദൃശ്യമുള്ള മകൻ ഞാൻ തന്നെയായിരിക്കും. തുടർന്ന് എനിക്ക് രണ്ട് പാത്രങ്ങൾ കൊണ്ടുവന്നു. ഒന്നിൽ പാലും മറ്റേതിൽ മദ്യവും. ഇഷ്ടമുള്ളത് തെരഞ്ഞെടുക്കാൻ എനിക്ക് ഉത്തരവ് കിട്ടി. ഞാൻ പാലെടുത്ത് കുടിച്ചു. അപ്പോൾ അദ്ദേഹം (ജിബ്രീൽ) പറഞ്ഞു: ''അങ്ങ് ശുദ്ധമായത് പുൽകിയിരിക്കുന്നു'' മദ്യമാണ് താങ്കൾ തെരഞ്ഞെടുത്തതെങ്കിൽ താങ്കളുടെ സമുദായം മുഴുവനായി പിഴച്ചുപോകുമായിരുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 132, 132, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ رَأَيْتُنِي فِي الْحِجْرِ وَقُرَيْشٌ تَسْأَلُنِي عَنْ مَسْرَايَ، فَسَأَلَتْنِي عَنْ أَشْيَاءَ مِنْ بَيْتِ الْمَقْدِسِ لَمْ أُثْبِتْهَا فَكُرِبْتُ كُرْبَةً مَا كُرِبْتُ مِثْلَهُ قَطُّ، قَالَ: فَرَفَعَهُ اللهُ لِي أَنْظُرُ إِلَيْهِ، مَا يَسْأَلُونِي عَنْ شَيْءٍ إِلَّا أَنْبَأْتُهُمْ بِهِ، وَقَدْ رَأَيْتُنِي فِي جَمَاعَةٍ مِنَ الْأَنْبِيَاءِ، فَإِذَا مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يُصَلِّي، فَإِذَا رَجُلٌ ضَرْبٌ جَعْدٌ كَأَنَّهُ مِنْ رِجَالِ شَنُوءَةَ، وَإِذَا عِيسَى ابْنُ مَرْيَمَ عَلَيْهِ السَّلَامُ قَائِمٌ يُصَلِّي، أَقْرَبُ النَّاسِ بِهِ شَبَهًا عُرْوَةُ بْنُ مَسْعُودٍ الثَّقَفِيُّ، وَإِذَا إِبْرَاهِيمُ عَلَيْهِ السَّلَامُ قَائِمٌ يُصَلِّي، أَشْبَهُ النَّاسِ بِهِ صَاحِبُكُمْ ، يَعْنِي نَفْسَهُ، فَحَانَتِ الصَّلَاةُ فَأَمَمْتُهُمْ فَلَمَّا فَرَغْتُ مِنَ الصَّلَاةِ قَالَ قَائِلٌ يَا مُحَمَّدُ هَذَا مَالِكٌ صَاحِبُ النَّارِ فَسَلِّمْ عَلَيْهِ فَالْتَفَتُّ إِلَيْهِ فَبَدَأَنِي بِالسَّلَامِ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: ഞാൻ (കഅ്ബയിലെ) ഹിജ്റിൽ ഇരിക്കുമ്പോൾ ഖുറൈശികൾ എന്റെ രാപ്രയാണത്തെക്കുറിച്ച് എന്നോട് ചോദിച്ചു. ബൈത്തുൽ മുഖദ്ദസിനെക്കുറിച്ച് എനിക്ക് കൃത്യമായി അറിയാത്ത പലകാര്യങ്ങളും അവർ ചോദിക്കാൻ തുടങ്ങി. മുമ്പൊന്നും അനുഭവിക്കാത്ത വിഷമം അപ്പോഴെനിക്കുണ്ടായി. അപ്പോൾ, അല്ലാഹു ബൈത്തുൽ മുഖദ്ദസിനെ എനിക്ക് ഉയർത്തിക്കാണിച്ചു തന്നു. അവർ ചോദിക്കുന്നതിനൊക്കെ അതിലേക്കുനോക്കി ഞാൻ മറുപടി പറഞ്ഞു: "(രാപ്രയാണ വേളയിൽ) മുൻപ്രവാചകന്മാരുടെ ഒരു സംഘത്തിൽ ഞാനെത്തിയിരുന്നു. (അവിടെ) മൂസാനബി(അ) നിന്ന് നിസ്കരിക്കുന്നു. മെലിഞ്ഞ, മുടി (സ്വല്പം) ചുരുണ്ട മനുഷ്യൻ. കണ്ടാൽ ശനൂഅഃ വർഗ്ഗക്കാരിൽ പെട്ടയാളാണെന്ന് തോന്നും. ഈസാനബിയും (അവിടെയതാ) നിസ്കരിക്കുന്നു. ഉർവത്തുബ്നു മസ്ഊദ് അസ്സഖഫി(റ)ക്കാണ് അദ്ദേഹത്തോട് ഏറ്റവും സാമ്യം. ഇബ്രാഹീം നബി(അ)യും നിസ്കരിക്കുന്നു. അവിടുത്തോട് ഏറ്റം സാമൃത നിങ്ങളുടെ കൂട്ടുകാരനായ എനിക്കുതന്നെയാണ്. നിസ്കാരത്തിന് സമയമായി. ഞാൻ അവർക്കെല്ലാം ഇമാമായി നിസ്കരിച്ചു. നിസ്കാരത്തിൽനിന്ന് വിരമിച്ചപ്പോൾ എന്നോട് ഒരാൾ പറഞ്ഞു: ''ഓ മുഹമ്മദ്, ഇതാണ് മാലിക്(അ), നരകത്തിന്റെ കാവൽക്കാരൻ! അദ്ദേഹത്തിന് സലാം ചൊല്ലൂ''. ഞാൻ തിരിഞ്ഞുനോക്കി. അപ്പോൾ മാലിക്(അ) എനിക്ക് സലാം ചൊല്ലി." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 132, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنِ الشَّيْبَانِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ زِرَّ بْنَ حُبَيْشٍ عَنْ قَوْلِ اللهِ عَزَّ وَجَلَّ: {فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى} [النجم:٩] قَالَ: أَخْبَرَنِي ابْنُ مَسْعُودٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى جِبْرِيلَ لَهُ سِتُّ مِائَةِ جَنَاحٍ. (م)', 'ശൈബാനി(റ): സൂറ: അന്നജ്മ് ഒമ്പതാം വാക്യ(അങ്ങനെ അദ്ദേഹം രണ്ടു വില്ലുകളുടെ അകലത്തിലോ അതിലും അടുത്തോ ആയിരുന്നു)ത്തെക്കുറിച്ച് ഞാൻ സിർറുബ്നു ഹുബൈശിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അറുനൂറ് ചിറകുകളുമായി ജിബ്രീലി(അ)നെ നബി(സ) കണ്ട സന്ദർഭത്തെ കുറിച്ചാണെന്നാണ് ഇബ്നു മസ്ഊദ്(റ) ഇതിനെ വിശദീകരിച്ചത്. (മു)', 'الشَّيْبَانِيِّ', 'ശൈബാനി(റ)', null, null, array['م']::text[], array['മു']::text[], 'النجم:٩', null, 133, 133, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: {مَا كَذَبَ الْفُؤَادُ مَا رَأَى} {وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى} قَالَ: رَآهُ بِفُؤَادِهِ مَرَّتَيْنِ. (م)', 'ഇബ്നുഅബ്ബാസ്(റ): "കണ്ണ് കണ്ടത് ഹൃദയം നിഷേധിച്ചിട്ടില്ല." മറ്റൊരു പ്രാവശ്യംകൂടി അവനെ (ജിബ്രീൽ(അ)നെ) നബി(സ) കണ്ടിട്ടുണ്ട്. നജ്മ്: 11-13) എന്ന സൂക്തം (വ്യാഖ്യാനിച്ചുകൊണ്ട്)
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ مَسْرُوقٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مُتَّكِئًا عِنْدَ عَائِشَةَ رَضِيَ اللهُ عَنْهَا فَقَالَتْ: يَا أَبَا عَائِشَةَ! ثَلَاثٌ مَنْ تَكَلَّمَ بِوَاحِدَةٍ مِنْهُنَّ فَقَدْ أَعْظَمَ عَلَى اللهِ الْفِرْيَةَ، قُلْتُ: مَا هُنَّ؟ قَالَتْ: مَنْ زَعَمَ أَنَّ مُحَمَّدًا صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَأَى رَبَّهُ فَقَدْ أَعْظَمَ عَلَى اللهِ الْفِرْيَةَ، قَالَ: وَكُنْتُ مُتَّكِئًا فَجَلَسْتُ فَقُلْتُ: يَا أُمَّ الْمُؤْمِنِينَ! أَنْظِرِينِي وَلَا تَعْجَلِينِي، أَلَمْ يَقُلِ اللهُ عَزَّ وَجَلَّ: {وَلَقَدْ رَآهُ بِالْأُفُقِ الْمُبِينِ} [التكوير:٢٣] {وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى} [النجم:١٣] فَقَالَتْ: أَنَا أَوَّلُ هَذِهِ الْأُمَّةِ سَأَلَ عَنْ ذَلِكَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنَّمَا هُوَ جِبْرِيلُ، لَمْ أَرَهُ عَلَى صُورَتِهِ الَّتِي خُلِقَ عَلَيْهَا غَيْرَ هَاتَيْنِ الْمَرَّتَيْنِ، رَأَيْتُهُ مُنْهَبِطًا مِنَ السَّمَاءِ سَادًّا، عِظَمُ خَلْقِهِ مَا بَيْنَ السَّمَاءِ إِلَى الْأَرْضِ" فَقَالَتْ: أَوَ لَمْ تَسْمَعْ أَنَّ اللهَ يَقُولُ: {لَا تُدْرِكُهُ الْأَبْصَارُ وَهُوَ يُدْرِكُ الْأَبْصَارَ وَهُوَ اللَّطِيفُ الْخَبِيرُ} [الأنعام:١٠٣] أَوَ لَمْ تَسْمَعْ أَنَّ اللهَ يَقُولُ {وَمَا كَانَ لِبَشَرٍ أَنْ يُكَلِّمَهُ اللهُ إِلَّا وَحْيًا أَوْ مِنْ وَرَاءِ حِجَابٍ أَوْ يُرْسِلَ رَسُولًا فَيُوحِيَ بِإِذْنِهِ مَا يَشَاءُ إِنَّهُ عَلِيٌّ حَكِيمٌ} [الشورى:٥١] قَالَتْ: وَمَنْ زَعَمَ أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَتَمَ شَيْئًا مِنْ كِتَابِ اللهِ فَقَدْ أَعْظَمَ عَلَى اللهِ الْفِرْيَةَ، وَاللهُ يَقُولُ: {يَا أَيُّهَا الرَّسُولُ بَلِّغْ مَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ وَإِنْ لَمْ تَفْعَلْ فَمَا بَلَّغْتَ رِسَالَتَهُ} [المائدة:٦٧] قَالَتْ: وَمَنْ زَعَمَ أَنَّهُ يُخْبِرُ بِمَا يَكُونُ فِي غَدٍ فَقَدْ أَعْظَمَ عَلَى اللهِ الْفِرْيَةَ، وَاللهُ يَقُولُ: {قُلْ لَا يَعْلَمُ مَنْ فِي السَّمَوَاتِ وَالْأَرْضِ الْغَيْبَ إِلَّا اللهُ} [النمل:٥٦] وَفِي رِوَايَةٍ: قَالَتْ: وَلَوْ كَانَ مُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَاتِمًا شَيْئًا مِمَّا أُنْزِلَ عَلَيْهِ لَكَتَمَ هَذِهِ الْآيَةَ {وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللهَ وَتُخْفِي فِي نَفْسِكَ مَا اللهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللهُ أَحَقُّ أَنْ تَخْشَاهُ} [الاحزاب:٣٧]. (م)', 'മസ്റൂഖ്(റ): ഞാൻ ആഇശ(റ)യുടെ സമീപം ഇരിക്കുകയായിരുന്നു. അവർ എന്നോട് പറഞ്ഞു: അബൂആഈശാ, മൂന്നുകാര്യങ്ങളിലൊന്ന് ആരെങ്കിലും വാദിച്ചാൽ അവൻ അല്ലാഹുവിനെക്കുറിച്ച് പച്ചക്കള്ളം പറഞ്ഞിരിക്കുന്നു. അവയേതാണെന്ന് ഞാൻ ചോദിച്ചു. ആഇശ(റ) പറഞ്ഞു: മുഹമ്മദ് നബി(സ) തന്റെ നാഥനെ കണ്ടു എന്ന് പറഞ്ഞവൻ അല്ലാഹുവിനെക്കുറിച്ച് വലിയ കളവ് പറഞ്ഞിരിക്കുന്നു. മസ്റൂഖ്(റ) പറയുന്നു: ചാരിയിരിക്കുകയായിരുന്ന ഞാൻ (ഇതുകേട്ട്) നിവർന്നിരുന്നു ചോദിച്ചു: വിശ്വാസികളുടെ മാതാവേ, എനിക്ക് സ്വല്പം സാവകാശം നൽകിയാലും, ധൃതികാണിക്കരുത്, ''തീർച്ചയായും നബി(സ) വ്യക്തമായ ചക്രവാളത്തിൽ വെച്ച് അവനെ കണ്ടു''. (തക്വീർ 23), ''മറ്റൊരു പ്രാവശ്യം നബി(സ) അവനെ കണ്ടിരിക്കുന്നു.'' (നജ്മ് 13) എന്നിങ്ങനെ അല്ലാഹു പറഞ്ഞിട്ടില്ലേ? ആഇശ(റ) പറഞ്ഞു: ഈ സമുദായത്തിൽ നിന്ന് ഈ സുക്തത്തെകുറിച്ച് നബി(സ)യോട് ആദ്യമായി ചോദിച്ചത് ഞാനാണ്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് ജിബ്രീലി(അ)നെ കുറിച്ചാണ്. (സൂക്തത്തിൽ പറഞ്ഞ) ഈ രണ്ട് പ്രാവശ്യമല്ലാതെ ഞാൻ ജിബ്രീലിനെ അദ്ദേഹത്തിന്റെ തനതായ രൂപത്തിൽ കണ്ടിട്ടില്ല. ജിബ്രീൽ ആകാശഭൂമികൾക്കിടയിൽ തന്റെ ആകാരവലിപ്പം വിടർത്തി ആകാശത്ത് നിന്നിറങ്ങുന്നതാണ് ഞാൻ കണ്ടത്." മഹതി തുടരുന്നു: "കണ്ണുകൾ അവനെ കാണുകയില്ല. അവൻ കണ്ണുകളെ കാണുന്നു. അവൻ സൂക്ഷ്മ ജ്ഞാനിയും അഭിജ്ഞനുമാണ്." "വഹ്യ് മുഖേനയോ മറയ്ക്കു പിന്നിൽനിന്നോ ദൂതൻ മുഖേനയോ അല്ലാതെ അല്ലാഹു ഒരു മനുഷ്യനോടും സംസാരിക്കുകയില്ല. തീർച്ചയായും അവൻ ഉന്നതനും യുക്തിമാനുമാകുന്നു" എന്ന് അല്ലാഹു പറഞ്ഞത് നീ കേട്ടിട്ടില്ലേ?
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=9 and h.hadith_no=151), 1, 'وَفِي رِوَايَةٍ: قَالَتْ: وَلَوْ كَانَ مُحَمَّدٌ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَاتِمًا شَيْئًا مِمَّا أُنْزِلَ عَلَيْهِ لَكَتَمَ هَذِهِ الْآيَةَ {وَإِذْ تَقُولُ لِلَّذِي أَنْعَمَ اللهُ عَلَيْهِ وَأَنْعَمْتَ عَلَيْهِ أَمْسِكْ عَلَيْكَ زَوْجَكَ وَاتَّقِ اللهَ وَتُخْفِي فِي نَفْسِكَ مَا اللهُ مُبْدِيهِ وَتَخْشَى النَّاسَ وَاللهُ أَحَقُّ أَنْ تَخْشَاهُ} [الاحزاب:٣٧]. (م)', 'മറ്റൊരു നിവേദനിൽ: മുഹമ്മദ് നബി(സ)ക്ക് അക്കവതരിച്ചുകിട്ടിയ വല്ലതും മറച്ചു വെക്കുന്നവനാണെങ്കിൽ ഈ സൂക്തം മറച്ചുവെക്കുമായിരുന്നു. "അല്ലാഹുവും ശേഷം നീയും അനുഗ്രഹം ചെയ്ത ഒരാളോട് നീ പറഞ്ഞ സന്ദർഭം (ഓർക്കുക). നിന്റെ ഭാര്യയെ നീ കൂടെ പാർപ്പിക്കുക. അല്ലാഹുവിനെ സൂക്ഷിക്കുക. (അപ്പോൾ) അല്ലാഹു വെളിപ്പെടുത്താൻ പോകുന്ന ഒരുകാര്യം നിന്റെ മനസ്സിൽ നീ മറച്ചുവെക്കുകയും ജനങ്ങളെ ഭയപ്പെടുകയും ചെയ്തു. എന്നാൽ നീ പേടിക്കുവാൻ ഏറ്റവും അർഹൻ അല്ലാഹുവാകുന്നു." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ فِينَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِخَمْسِ كَلِمَاتٍ فَقَالَ: "إِنَّ اللهَ عَزَّ وَجَلَّ لَا يَنَامُ، وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ، يَخْفِضُ الْقِسْطَ وَيَرْفَعُهُ، يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ قَبْلَ عَمَلِ النَّهَارِ وَعَمَلُ النَّهَارِ قَبْلَ عَمَلِ اللَّيْلِ، حِجَابُهُ النُّورُ – وَفِي رِوَايَةِ أَبِي بَكْرٍ النَّارُ – لَوْ كَشَفَهُ لَأَحْرَقَتْ سُبُحَاتُ وَجْهِهِ مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ". (م)', 'അബൂമൂസ(റ): നബി(സ) എഴുന്നേറ്റുനിന്ന് ഞങ്ങളോട് അഞ്ച് കാര്യങ്ങൾ പറഞ്ഞു: "അല്ലാഹു ഉറങ്ങുകയില്ല. ഉറക്കം അവന് യോജിച്ചതല്ല, അവൻ നീതി താഴ്ത്തുകയും ഉയർത്തുകയും ചെയ്യുന്നു, പകലിലെ കർമ്മങ്ങൾക്ക് മുമ്പ് രാത്രിയിലെ കർമ്മങ്ങൾ അവനിലേക്ക് ഉയർത്തപ്പെടും, രാത്രിയിലെ കർമ്മങ്ങൾക്കു മുമ്പ് പകലിലെ കർമങ്ങൾ അവനിലേക്ക് ഉയർത്തപ്പെടും, അവന്റെ മറ പ്രകാശമാണ്. - അബൂബക്കറിന്റെ റിപ്പോർട്ടിൽ അഗ്നി എന്നാണ്.- അതവൻ വെളിപ്പെടുത്തിയാൽ അവന്റെ തിരുവദന പ്രകാശം മുഴുവൻ സൃഷ്ടികളെയും കരിച്ചുകളയും." (മു)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 135, 135, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=9 and h.hadith_no=152), 1, 'وَفِي رِوَايَةٍ أَبِي بَكْرٍ النَّارُ – لَوْ كَشَفَهُ لَأَحْرَقَتْ سُبُحَاتُ وَجْهِهِ مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ". (م)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ نَاسًا قَالُوا لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: يَا رَسُولَ اللهِ! هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "هَلْ تُضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ؟ " قَالُوا: لَا يَا رَسُولَ اللهِ، قَالَ: "هَلْ تُضَارُّونَ فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ؟" قَالُوا: لَا يَا رَسُولَ اللهِ، قَالَ: "فَإِنَّكُمْ تَرَوْنَهُ كَذَلِكَ، يَجْمَعُ اللهُ النَّاسَ يَوْمَ الْقِيَامَةِ فَيَقُولُ: مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْهُ، فَيَتْبَعُ مَنْ كَانَ يَعْبُدُ الشَّمْسَ الشَّمْسَ وَيَتْبَعُ مَنْ كَانَ يَعْبُدُ الْقَمَرَ الْقَمَرَ وَيَتْبَعُ مَنْ كَانَ يَعْبُدُ الطَّوَاغِيتَ الطَّوَاغِيتَ وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا مُنَافِقُوهَا، فَيَأْتِيهِمُ اللهُ تَبَارَكَ وَتَعَالَى فِي صُورَةٍ غَيْرِ صُورَتِهِ الَّتِي يَعْرِفُونَ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: نَعُوذُ بِاللهِ مِنْكَ، هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا، فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ، فَيَأْتِيهِمُ اللهُ تَعَالَى فِي صُورَتِهِ الَّتِي يَعْرِفُونَ، فَيَقُولُ: أَنَا رَبُّكُمْ، فَيَقُولُونَ: أَنْتَ رَبُّنَا، فَيَتَّبِعُونَهُ وَيُضْرَبُ الصِّرَاطُ بَيْنَ ظَهْرَيْ جَهَنَّمَ فَأَكُونُ أَنَا وَأُمَّتِي أَوَّلَ مَنْ يُجِيزُ، وَ لَا يَتَكَلَّمُ يَوْمَئِذٍ إِلَّا الرُّسُلُ، وَدَعْوَى الرُّسُلِ يَوْمَئِذٍ اللَّهُمَّ سَلِّمْ سَلِّمْ، وَفِي جَهَنَّمَ كَلَالِيبُ مِثْلُ شَوْكِ السَّعْدَانِ، هَلْ رَأَيْتُمُ السَّعْدَانَ؟ قَالُوا: نَعَمْ يَا رَسُولَ اللهِ، قَالَ: فَإِنَّهَا مِثْلُ شَوْكِ السَّعْدَانِ غَيْرَ أَنَّهُ لَا يَعْلَمُ مَا قَدْرُ عِظَمِهَا إِلَّا اللهُ تَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ، فَمِنْهُمُ الْمُؤْمِنُ بَقِيَ بِعَمَلِهِ، وَمِنْهُمُ الْمُجَازَى حَتَّى يُنَجَّى، حَتَّى إِذَا فَرَغَ اللهُ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ وَأَرَادَ أَنْ يُخْرِجَ بِرَحْمَتِهِ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ أَمَرَ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مِنَ النَّارِ مَنْ كَانَ لَا يُشْرِكُ بِاللهِ شَيْئًا مِمَّنْ أَرَادَ اللهُ تَعَالَى أَنْ يَرْحَمَهُ مِمَّنْ يَقُولُ لَاإِلَهَ إِلَّا اللهُ، فَيَعْرِفُونَهُمْ فِي النَّارِ يَعْرِفُونَهُمْ بِأَثَرِ السُّجُودِ، تَأْكُلُ النَّارُ مِنِ ابْنِ آدَمَ إِلَّا أَثَرَ السُّجُودِ، حَرَّمَ اللهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ فَيُخْرَجُونَ مِنَ النَّارِ وَقَدِ امْتُحِشُوا فَيُصَبُّ عَلَيْهِمْ مَاءُ الْحَيَاةِ، فَيَنْبُتُونَ مِنْهُ كَمَا تَنْبُتُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ، ثُمَّ يَفْرُغُ اللهُ تَعَالَى مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ وَيَبْقَى رَجُلٌ مُقْبِلٌ بِوَجْهِهِ عَلَى النَّارِ وَهُوَ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ، فَيَقُولُ: أَيْ رَبِّ اصْرِفْ وَجْهِي عَنِ النَّارِ، فَإِنَّهُ قَدْ قَشَبَنِي رِيحُهَا وَأَحْرَقَنِي ذَكَاؤُهَا، فَيَدْعُو اللهَ مَا شَاءَ اللهُ أَنْ يَدْعُوَهُ ثُمَّ يَقُولُ اللهُ تَبَارَكَ وَتَعَالَى: هَلْ عَسَيْتَ إِنْ فَعَلْتُ ذَلِكَ بِكَ أَنْ تَسْأَلَ غَيْرَهُ؟ فَيَقُولُ: لَا أَسْأَلُكَ غَيْرَهُ، وَيُعْطِي رَبَّهُ مِنْ عُهُودٍ وَمَوَاثِيقَ مَا شَاءَ اللهُ فَيَصْرِفُ اللهُ وَجْهَهُ عَنِ النَّارِ، فَإِذَا أَقْبَلَ عَلَى الْجَنَّةِ وَرَآهَا سَكَتَ مَا شَاءَ اللهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ: أَيْ رَبِّ قَدِّمْنِي إِلَى بَابِ الْجَنَّةِ، فَيَقُولُ اللهُ لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ لَا تَسْأَلُنِي غَيْرَ الَّذِي أَعْطَيْتُكَ، وَيْلَكَ يَا ابْنَ آدَمَ، مَا أَغْدَرَكَ! فَيَقُولُ: أَيْ رَبِّ، وَيَدْعُو اللهَ حَتَّى يَقُولَ لَهُ: فَهَلْ عَسَيْتَ إِنْ أَعْطَيْتُكَ ذَلِكَ أَنْ تَسْأَلَ غَيْرَهُ؟ فَيَقُولُ: لَا وَعِزَّتِكَ، فَيُعْطِي رَبَّهُ مَا شَاءَ اللهُ مِنْ عُهُودٍ وَمَوَاثِيقَ فَيُقَدِّمُهُ إِلَى بَابِ الْجَنَّةِ، فَإِذَا قَامَ عَلَى بَابِ الْجَنَّةِ انْفَهَقَتْ لَهُ الْجَنَّةُ، فَرَأَى مَا فِيهَا مِنَ الْخَيْرِ وَالسُّرُورِ، فَيَسْكُتُ مَا شَاءَ اللهُ أَنْ يَسْكُتَ ثُمَّ يَقُولُ: أَيْ رَبِّ، أَدْخِلْنِي الْجَنَّةَ، فَيَقُولُ اللهُ تَبَارَكَ وَتَعَالَى لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ عُهُودَكَ وَمَوَاثِيقَكَ أَنْ لَا تَسْأَلَ غَيْرَ مَا أُعْطِيتَ، وَيْلَكَ يَا ابْنَ آدَمَ، مَا أَغْدَرَكَ! فَيَقُولُ أَيْ رَبِّ لَا أَكُونُ أَشْقَى خَلْقِكَ، فَلَا يَزَالُ يَدْعُو اللهَ حَتَّى يَضْحَكَ اللهُ تَبَارَكَ وَتَعَالَى مِنْهُ، فَإِذَا ضَحِكَ اللهُ مِنْهُ قَالَ: ادْخُلِ الْجَنَّةَ، فَإِذَا دَخَلَهَا قَالَ اللهُ لَهُ: تَمَنَّهْ، فَيَسْأَلُ رَبَّهُ وَيَتَمَنَّى حَتَّى إِنَّ اللهَ لَيُذَكِّرُهُ مِنْ كَذَا وَكَذَا حَتَّى إِذَا انْقَطَعَتْ بِهِ الْأَمَانِيُّ قَالَ اللهُ تَعَالَى: ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ" قَالَ عَطَاءُ بْنُ يَزِيدَ: وَأَبُو سَعِيدٍ الْخُدْرِيُّ مَعَ أَبِي هُرَيْرَةَ لَا يَرُدُّ عَلَيْهِ مِنْ حَدِيثِهِ شَيْئًا حَتَّى إِذَا حَدَّثَ أَبُو هُرَيْرَةَ "أَنَّ اللهَ قَالَ لِذَلِكَ الرَّجُلِ: وَمِثْلُهُ مَعَهُ" قَالَ أَبُو سَعِيدٍ رَضِيَ اللهُ عَنْهُ: "وَعَشَرَةُ أَمْثَالِهِ مَعَهُ" يَا أَبَا هُرَيْرَةَ، قَالَ أَبُو هُرَيْرَةَ: مَا حَفِظْتُ إِلَّا قَوْلَهُ "ذَلِكَ لَكَ وَمِثْلُهُ مَعَهُ". قَالَ أَبُو سَعِيدٍ رَضِيَ اللهُ عَنْهُ: أَشْهَدُ أَنِّي حَفِظْتُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَوْلَهُ "ذَلِكَ لَكَ وَعَشَرَةُ أَمْثَالِهِ" قَالَ أَبُو هُرَيْرَةَ: وَذَلِكَ الرَّجُلُ آخِرُ أَهْلِ الْجَنَّةِ دُخُولًا الْجَنَّةَ. (ق)', 'അബൂഹുറൈറ(റ): ഒരു വിഭാഗമാളുകൾ നബി(സ)യോട് ചോദിച്ചു: നബിയെ! വിധിനാളിൽ ഞങ്ങളുടെ നാഥനെ ഞങ്ങൾ കാണുമോ? നബി(സ) പറഞ്ഞു: "പൗർണ്ണമി ദിനത്തിൽ ചന്ദ്രനെ കാണുവാൻ നിങ്ങൾ ക്ലേശിക്കേണ്ടി വരുമോ?" അവർ പറഞ്ഞു: ഇല്ല നബിയെ. നബി(സ) പറഞ്ഞു: "കാർമേഘമില്ലാത്ത നേരം സൂര്യനെ കാണാൻ നിങ്ങൾ വിഷമം സഹിക്കേണ്ടതുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല. നബി(സ) പറഞ്ഞു: "അപ്രകാരം (ഒരു ബുദ്ധിമുട്ടുമില്ലാതെ) നിങ്ങൾ അല്ലാഹുവിനെ കാണും. വിധിനാളിൽ ജനങ്ങളെയെല്ലാം ഒരുമിച്ചുകൂട്ടി അല്ലാഹു പറയും: ''ഓരോരുത്തരും അവരവരുടെ ആരാധ്യ വസ്തുക്കളെ അനുധാവനം ചെയ്യട്ടെ!'' സൂര്യനെ ആരാധിച്ചവർ സൂര്യനെ, ചന്ദ്രനെ ആരാധിച്ചവർ ചന്ദ്രനെ, വിഗ്രഹാദികളെ ആരാധിച്ചവർ അവയെ എന്നിപ്രകാരം അനുഗമിക്കും. അവസാനം കപടവിശ്വാസികളടങ്ങുന്ന മുസ്ലിം സമുദായംമാത്രം അവശേഷിക്കും. അവർ മനസ്സിലാക്കിയ രീതിയിലല്ലാതെ അവർക്ക് പ്രത്യക്ഷനായി അല്ലാഹു പറയും: ''ഞാനാണ് നിങ്ങളുടെ നാഥൻ'' അവർ പറയും: നിന്നിൽനിന്ന് ഞങ്ങൾ അല്ലാഹുവിനോട് അഭയം തേടുന്നു. ഇതാണ് ഞങ്ങളുടെ സ്ഥലം. ഞങ്ങളുടെ രക്ഷിതാവ് വരുന്നതുവരെ. അല്ലാഹു പ്രത്യക്ഷനായാൽ ഞങ്ങൾക്കവനെ തിരിച്ചറിയാനാവും.'' അപ്പോൾ അവർ മനസ്സിലാക്കിയ രീതിയിൽ പ്രത്യക്ഷപ്പെട്ട് അല്ലാഹു പറയും; ''ഞാനാണ് നിങ്ങളുടെ നാഥൻ.'' അവർ പ്രതികരിക്കും; നീ തന്നെയാണ് ഞങ്ങളുടെ നാഥൻ. അവർ അവനെ അനുഗമിക്കും. നരകത്തിനു മുകളിൽ സ്വിറാത് (പാലം) ഉയർത്തപ്പെടും. ഞാനും എന്റെ സമുദായവുമായിരിക്കും ആദ്യം പാലം കടക്കുന്നത്. ദൈവദൂതന്മാരല്ലാതെ ആരും അന്ന് സംസാരിക്കില്ല. അന്ന് അവർക്ക് പറയാനുണ്ടാവുക; ''നാഥാ! രക്ഷ,രക്ഷ!'' എന്നായിരിക്കും. ''സഅ്ദാൻ'' ചെടിയുടെ മുള്ളുപോലുള്ള കൊളുത്തു കമ്പികൾ നരകത്തിലുണ്ട്. നിങ്ങൾ സഅ്ദാൻ കണ്ടിട്ടുണ്ടോ?" അവർ പറഞ്ഞു: അതെ. നബി(സ) പറഞ്ഞു: "സഅ്ദാൻ മുള്ളുകൾ പോലെയാണത്. പക്ഷെ അതിന്റെ വലിപ്പത്തിന്റെ കണക്ക് അല്ലാഹുവിനു മാത്രമേ അറിയൂ. തങ്ങളുടെ കർമ്മങ്ങൾക്കനുസരിച്ച് അവരെ അത് റാഞ്ചിയെടുക്കും. തങ്ങളുടെ കർമ്മങ്ങളുമായി നിൽക്കുന്ന വിശ്വാസികൾ അവരിലുണ്ട്. കർമ്മത്തിനു പ്രതിഫലം നൽകപ്പെട്ട് വിജയിക്കുന്നവനുമുണ്ട്. ജനങ്ങൾക്കിടയിൽ അല്ലാഹു തീർപ്പ് കൽപ്പിച്ച് കഴിഞ്ഞാൽ തന്റെ ദാക്ഷിണ്യം നിമിത്തം നരകക്കാരിൽപ്പെട്ട കുറെയാളുകളെ അല്ലാഹു പുറത്തെടുക്കാൻ ഉദ്ദേശിക്കും. لا إله إلا الله എന്നു പറയുന്ന അല്ലാഹു അനുഗ്രഹം ചൊരിയാൻ ഉദ്ദേശിച്ച, അല്ലാഹുവിൽ ഒന്നിനെയും പങ്കുചേർക്കാത്ത മുഴുവൻ ആളുകളേയും നരകത്തിൽനിന്ന് പുറത്തെടുക്കാൻ അല്ലാഹു മലക്കുകളോട് കൽപിക്കും. നരകത്തിന്റെ മലക്കുകൾ അവരെ തിരിച്ചറിയും. സുജൂദിന്റെ അടയാളം മുഖേനയാണ് അവരെ മലക്കുകൾ തിരിച്ചറിയുക. സുജൂദിന്റെ അടയാളമല്ലാത്തതൊക്കെയും മനുഷ്യനിൽ നിന്ന് നരകാഗ്നി ഭുജിക്കും. സുജൂദിന്റെ അടയാളം തിന്നുന്നത് അല്ലാഹു നരകത്തിന് വിലക്കിയിരിക്കുന്നു. അവരെ നരകത്തിൽ നിന്ന് പുറത്തെടുക്കും. അവർ കത്തിക്കരിഞ്ഞിട്ടുണ്ടായിരിക്കും. ജീവജലം അവർക്കുമേൽ ഒഴിക്കും. ഒഴുകുന്ന വെള്ളത്തിന് സമീപം വളരുന്ന ധാന്യമണികൾ മുളക്കുന്നതുപോലെ അവർ മുളക്കും. തുടർന്ന് അല്ലാഹു അടിമകൾക്കിടയിൽ ന്യായം വിധിക്കുന്നതിൽനിന്ന് വിരമിക്കും. ഒരു മനുഷ്യൻ നരകാഗ്നിയുമായി മുഖാമുഖം നിൽക്കുന്നുണ്ടാകും. അവനായിരിക്കും സ്വർഗ്ഗവാസികളിൽ അവസാനമായി സ്വർഗ്ഗത്തിൽ കടക്കുന്നവൻ. അവൻ പറയും: നാഥാ, എന്റെ മുഖം നരകത്തിൽ നിന്ന് തിരിച്ചുതരണേ. അതിന്റെ ദുർഗന്ധം എന്നെ വിഷമേൽപ്പിച്ചിരിക്കുന്നു. അതിന്റെ ജ്വാല എന്നെ കരിച്ചിരിക്കുന്നു. അങ്ങനെ അവൻ പ്രാർത്ഥിക്കാൻ ഉദ്ദേശിച്ചതൊക്കെ അല്ലാഹുവിനോട് പ്രാർത്ഥിക്കുന്നു. അല്ലാഹു പറയും: അത് നിനക്ക് ചെയ്തു തന്നാൽ നീ മറ്റെന്തെങ്കിലും ചോദിക്കുമോ? അവൻ പറയും: ഇല്ല, ഒന്നും ചോദിക്കില്ല. തുടർന്ന് അല്ലാഹു ഉദ്ദേശിച്ച ഉടമ്പടിയും കരാറും അയാൾ നൽകുന്നു. അല്ലാഹു അവന്റെ മുഖം നരകത്തിൽനിന്ന് തിരിക്കുന്നു. സ്വർഗ്ഗത്തിന് നേർക്ക് തിരിഞ്ഞ് സ്വർഗ്ഗം കാണുമ്പോൾ അല്ലാഹു ഉദ്ദേശിച്ചത്രയും സമയം അവൻ മൗനം ദീക്ഷിക്കുന്നു. പിന്നെ പറയും: നാഥാ! എന്നെ സ്വർഗ്ഗ കവാടത്തിലേക്ക് അടുപ്പിക്കണേ. അപ്പോൾ അല്ലാഹു പറയും: ഞാൻ നിനക്ക് നൽകിയതല്ലാതെ ഇനി മറ്റൊന്നും ചോദിക്കില്ലെന്ന് നീ കരാർ ചെയ്തതല്ലേ? നാശം! നീ വല്ലാത്തൊരാൾ തന്നെ! അവൻ പറയും: എന്റെ നാഥാ! ....... അവൻ പ്രാർത്ഥിച്ചുകൊണ്ടേയിരിക്കും. അങ്ങനെ അല്ലാഹു അവനോട് ചോദിക്കും: ''അത് നിനക്ക് നൽകിയാൽ മറ്റു വല്ലതും നീ ചോദിക്കുമോ?.'' അവൻ പറയും: നിന്റെ ഔന്നത്യം തന്നെയാണെ, ഇല്ല. തുടർന്ന് നാഥനോട് അല്ലാഹു ഉദ്ദേശിച്ച ഉടമ്പടിയും കരാറും അയാൾ നൽകുന്നു. അല്ലാഹു അവന്റെ മുഖം നരകത്തിൽനിന്ന് തിരിക്കുന്നു. സ്വർഗ്ഗ കവാടത്തിലെത്തിയാൽ സ്വർഗ്ഗം നിറഞ്ഞു നിൽക്കുന്നതവൻ കാണും. അതിലെ സന്തോഷവും നന്മയുമൊക്കെ അവൻ കാണും. അല്ലാഹു ഉദ്ദേശിക്കുന്നത്ര നേരം അവൻ മൗനം ദീക്ഷിക്കും. പിന്നീടവൻ പറയും: നാഥാ! എന്നെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കേണമേ! അല്ലാഹു പറയും: ''നിനക്ക് കിട്ടിയതല്ലാതെ ഇനി ഒന്നും ചോദിക്കില്ലെന്ന് നീ കരാർ ചെയ്തതല്ലേ? മനുഷ്യാ നാശം! നീ എന്തൊരു വഞ്ചകൻ! അവൻ പറയും: ഞാൻ നിന്റെ സൃഷ്ടികളിൽ ഏറ്റവും ഹതഭാഗ്യനാകുന്നില്ല. അവനങ്ങനെ പ്രാർത്ഥിച്ചുകൊണ്ടിരിക്കും. അവസാനം അല്ലാഹു അവനിൽ തൃപ്തിപ്പെടും. അല്ലാഹു തൃപ്തിപ്പെട്ടാൽ അവൻ പറയും: സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുക. അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിച്ചാൽ അല്ലാഹു പറയും: ''(വേണ്ടതെല്ലാം) മോഹിക്കൂ.'' അങ്ങനെ അവൻ തന്റെ നാഥനോട് ആവശ്യപ്പെടും. വീണ്ടും ആഗ്രഹിക്കും. അല്ലാഹു അവനെ മുഴുവൻ മോഹങ്ങളും തീരുന്നതുവരെ ഒരോകാര്യം ഓർമ്മിപ്പിക്കും. അല്ലാഹു പറയും: അതെല്ലാം നിനക്കുള്ളതാണ്. അതിന്റത്രയും."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَهْوَنُ أَهْلِ النَّارِ عَذَابًا أَبُو طَالِبٍ وَهُوَ مُنْتَعِلٌ بِنَعْلَيْنِ يَغْلِي مِنْهُمَا دِمَاغُهُ". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "നരക വാസികളിൽ ഏറ്റവും നേരിയ ശിക്ഷ അനുഭവിക്കുക അബൂത്വാലിബാണ്. അദ്ദേഹം രണ്ട് (അഗ്നി) ചെരിപ്പുകൾ ധരിച്ചിരിക്കും. തദ്വാരാ അദ്ദേഹത്തിന്റെ തലച്ചോറ് തിളച്ചു പതയും." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 137, 137, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "آتِي بَابَ الْجَنَّةِ يَوْمَ الْقِيَامَةِ فَأَسْتَفْتِحُ، فَيَقُولُ الْخَازِنُ: مَنْ أَنْتَ؟ فَأَقُولُ: مُحَمَّدٌ، فَيَقُولُ: بِكَ أُمِرْتُ، لَا أَفْتَحُ لِأَحَدٍ قَبْلَكَ". (م)', 'അനസ്ബിന്മാലിക്(റ): നബി(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ ഞാൻ സ്വർഗ്ഗ കവാടത്തിങ്കൽചെന്ന് വാതിൽ തുറക്കാൻ ആവശ്യപ്പെടും. അപ്പോൾ സ്വർഗ്ഗ കാവൽക്കാരൻ ചോദിക്കും: താങ്കൾ ആരാണ്? ഞാൻ പറയും: മുഹമ്മദ്. അദ്ദേഹം പറയും: നിങ്ങൾക്ക് തുറന്ന് തരാനാണ് എന്നോട് കൽപിച്ചിരിക്കുന്നത്. നിങ്ങൾക്കു മുമ്പേ ഒരാൾക്കും ഞാനിത് തുറന്നുകൊടുക്കുകയില്ല." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബിന്മാലിക്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 137, 138, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أُتِيَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بِلَحْمٍ فَرُفِعَ إِلَيْهِ الذِّرَاعُ، وَكَانَتْ تُعْجِبُهُ فَنَهَسَ مِنْهَا نَهْسَةً فَقَالَ: "أَنَا سَيِّدُ النَّاسِ يَوْمَ الْقِيَامَةِ، وَهَلْ تَدْرُونَ بِمَ ذَاكَ؟ يَجْمَعُ اللهُ يَوْمَ الْقِيَامَةِ الْأَوَّلِينَ وَالْآخِرِينَ فِي صَعِيدٍ وَاحِدٍ، فَيُسْمِعُهُمُ الدَّاعِي وَيَنْفُذُهُمُ الْبَصَرُ وَتَدْنُو الشَّمْسُ فَيَبْلُغُ النَّاسَ مِنَ الْغَمِّ وَالْكَرْبِ مَا لَا يُطِيقُونَ وَمَا لَا يَحْتَمِلُونَ، فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ: أَلَا تَرَوْنَ مَا أَنْتُمْ فِيهِ، أَلَا تَرَوْنَ مَا قَدْ بَلَغَكُمْ، أَلَا تَنْظُرُونَ مَنْ يَشْفَعُ لَكُمْ إِلَى رَبِّكُمْ، فَيَقُولُ بَعْضُ النَّاسِ لِبَعْضٍ: ائْتُوا آدَمَ، فَيَأْتُونَ آدَمَ فَيَقُولُونَ: يَا آدَمُ، أَنْتَ أَبُو الْبَشَرِ، خَلَقَكَ اللهُ بِيَدِهِ وَنَفَخَ فِيكَ مِنْ رُوحِهِ وَأَمَرَ الْمَلَائِكَةَ فَسَجَدُوا لَكَ، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى إِلَى مَا نَحْنُ فِيهِ، أَلَا تَرَى إِلَى مَا قَدْ بَلَغَنَا، فَيَقُولُ آدَمُ، إِنَّ رَبِّي غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنَّهُ نَهَانِي عَنِ الشَّجَرَةِ فَعَصَيْتُهُ، نَفْسِي! نَفْسِي! اذْهَبُوا إِلَى غَيْرِي، اذْهَبُوا إِلَى نُوحٍ، فَيَأْتُونَ نُوحًا، فَيَقُولُونَ: يَا نُوحُ، أَنْتَ أَوَّلُ الرُّسُلِ إِلَى الْأَرْضِ، وَسَمَّاكَ اللهُ عَبْدًا شَكُورًا، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى مَا نَحْنُ فِيهِ، أَلَا تَرَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنَّهُ قَدْ كَانَتْ لِي دَعْوَةٌ دَعَوْتُ بِهَا عَلَى قَوْمِي، نَفْسِي! نَفْسِي! اذْهَبُوا إِلَى إِبْرَاهِيمَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَأْتُونَ إِبْرَاهِيمَ فَيَقُولُونَ: أَنْتَ نَبِيُّ اللهِ وَخَلِيلُهُ مِنْ أَهْلِ الْأَرْضِ، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى إِلَى مَا نَحْنُ فِيهِ، أَلَا تَرَى إِلَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ إِبْرَاهِيمُ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَا يَغْضَبُ بَعْدَهُ مِثْلَهُ، وَذَكَرَ كَذَبَاتِهِ، نَفْسِي! نَفْسِي! اذْهَبُوا إِلَى غَيْرِي اذْهَبُوا إِلَى مُوسَى، فَيَأْتُونَ مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَيَقُولُونَ: يَا مُوسَى أَنْتَ رَسُولُ اللهِ فَضَّلَكَ اللهُ بِرِسَالَاتِهِ وَبِتَكْلِيمِهِ عَلَى النَّاسِ، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى إِلَى مَا نَحْنُ فِيهِ، أَلَا تَرَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ مُوسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَإِنِّي قَتَلْتُ نَفْسًا لَمْ أُومَرْ بِقَتْلِهَا، نَفْسِي! نَفْسِي! اذْهَبُوا إِلَى عِيسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَأْتُونَ عِيسَى فَيَقُولُونَ: يَا عِيسَى، أَنْتَ رَسُولُ اللهِ وَكَلَّمْتَ النَّاسَ فِي الْمَهْدِ وَكَلِمَةٌ مِنْهُ أَلْقَاهَا إِلَى مَرْيَمَ وَرُوحٌ مِنْهُ، فَاشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى مَا نَحْنُ فِيهِ، أَلَا تَرَى مَا قَدْ بَلَغَنَا، فَيَقُولُ لَهُمْ عِيسَى صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِنَّ رَبِّي قَدْ غَضِبَ الْيَوْمَ غَضَبًا لَمْ يَغْضَبْ قَبْلَهُ مِثْلَهُ وَلَنْ يَغْضَبَ بَعْدَهُ مِثْلَهُ، وَلَمْ يَذْكُرْ لَهُ ذَنْبًا، نَفْسِي! نَفْسِي! اذْهَبُوا إِلَى غَيْرِي، اذْهَبُوا إِلَى مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَيَأْتُونِي فَيَقُولُونَ: يَا مُحَمَّدُ، أَنْتَ رَسُولُ اللهِ وَخَاتَمُ الْأَنْبِيَاءِ، وَغَفَرَ اللهُ لَكَ مَا تَقَدَّمَ مِنْ ذَنْبِكَ وَمَا تَأَخَّرَ، اشْفَعْ لَنَا إِلَى رَبِّكَ، أَلَا تَرَى مَا نَحْنُ فِيهِ، أَلَا تَرَى مَا قَدْ بَلَغَنَا، فَأَنْطَلِقُ، فَآتِي تَحْتَ الْعَرْشِ، فَأَقَعُ سَاجِدًا لِرَبِّي، ثُمَّ يَفْتَحُ اللهُ عَلَيَّ وَيُلْهِمُنِي مِنْ مَحَامِدِهِ وَحُسْنِ الثَّنَاءِ عَلَيْهِ شَيْئًا لَمْ يَفْتَحْهُ لِأَحَدٍ قَبْلِي، ثُمَّ يُقَالُ: يَا مُحَمَّدُ، ارْفَعْ رَأْسَكَ، سَلْ تُعْطَهْ، اشْفَعْ تُشَفَّعْ، فَأَرْفَعُ رَأْسِي فَأَقُولُ: يَا رَبِّ، أُمَّتِي! أُمَّتِي! فَيُقَالُ: يَا مُحَمَّدُ، أَدْخِلِ الْجَنَّةَ مِنْ أُمَّتِكَ مَنْ لَا حِسَابَ عَلَيْهِ مِنَ الْبَابِ الْأَيْمَنِ مِنْ أَبْوَابِ الْجَنَّةِ، وَهُمْ شُرَكَاءُ النَّاسِ فِيمَا سِوَى ذَلِكَ مِنَ الْأَبْوَابِ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ إِنَّ مَا بَيْنَ الْمِصْرَاعَيْنِ مِنْ مَصَارِيعِ الْجَنَّةِ لَكَمَا بَيْنَ مَكَّةَ وَهَجَرَ أَوْ كَمَا بَيْنَ مَكَّةَ وَبُصْرَى". (م)', 'അബൂഹുറൈറ(റ): ഒരു ദിവസം നബി(സ)ക്ക് ഒരാൾ അല്പം മാംസം കൊടുത്തയച്ചു. നബി(സ)ക്ക് ഏറ്റവും ആകർഷണീയമായി തോന്നിയ കൊറുക് നബി(സ)ക്ക് ഉയർത്തിക്കാണിച്ചപ്പോൾ, അത് കടിച്ചുകൊണ്ട് പറഞ്ഞു: "ഞാൻ അന്ത്യനാളിൽ ജനങ്ങളുടെ നേതാവായിരിക്കും. അതെന്തു കൊണ്ടാണെന്ന് നിങ്ങൾക്കറിയുമോ? അന്ത്യനാളിൽ മുൻഗാമികളെയും പിൻഗാമികളേയും അല്ലാഹു നിരപ്പായ സ്ഥലത്ത് ഒരുമിച്ചുകൂട്ടും. അവരെ ഒരാൾ വിളിച്ചാൽ എല്ലാവരും കേൾക്കും. നോക്കിയാൽ എല്ലാവരേയും കാണും. (അത്രയും സമനിരപ്പായ സ്ഥലം) സൂര്യൻ അടുത്തുവരും. ജനങ്ങൾക്ക് അസഹ്യമായ മനഃപ്രയാസവും ബുദ്ധിമുട്ടും അനുഭവപ്പെടും. അവർ പരസ്പരം പറയും: നിങ്ങളുടെ അവസ്ഥ കാണുന്നില്ലേ? വന്നുഭവിച്ചത് അറിയുന്നില്ലേ? നിങ്ങൾക്കുവേണ്ടി രക്ഷിതാവിനോട് ശുപാർശ ചെയ്യുവാൻ കഴിയുന്ന ഒരാളെക്കുറിച്ച് നിങ്ങൾ ചിന്തിക്കുന്നില്ലേ? അപ്പോൾ ചിലർ ചിലരോട് പറയും: നിങ്ങൾ ആദം നബി(അ)യുടെ സമീപിക്കുക. അങ്ങനെ ആദം നബിയുടെ അടുത്തേക്ക് പോയിപ്പറയും: ആദം! അങ്ങ് മനുഷ്യ പിതാവാണ്. അല്ലാഹു അങ്ങയെ അവന്റെ ശക്തികൊണ്ട് സൃഷ്ടിച്ചു. അവൻ തന്റെ ''റൂഹി''നെ താങ്കളിൽ ഊതി. മലക്കുകളോട് താങ്കൾക്ക് സാഷ്ടാംഗം ചെയ്യാൻ കൽപിച്ചത് കാരണം അവർ താങ്കൾക്ക് പ്രണമിച്ചു. അതിനാൽ ഞങ്ങൾക്കുവേണ്ടി അങ്ങയുടെ രക്ഷിതാവിനോട് താങ്കൾ ശുപാർശ ചെയ്താലും. ഞങ്ങളുടെ ഈ അവസ്ഥ താങ്കൾ കാണുന്നില്ലേ? ഞങ്ങൾ എത്തിപ്പെട്ടിരിക്കുന്നത് അറിയുന്നില്ലേ?. അപ്പോൾ ആദം നബി(അ) പറയും: എന്റെ നാഥൻ ഇന്ന് വല്ലാതെ കോപിച്ചിരിക്കുന്നു. ഇതിനുമുമ്പ് ഇത്ര കോപിച്ചിട്ടില്ല. ഇനി കോപിക്കുകയുമില്ല. ഒരു പ്രത്യേക വൃക്ഷം എനിക്ക് അവൻ വിലക്കിയിരുന്നു. പക്ഷേ ഞാൻ അത് ലംഘിച്ചുപോയി. എന്റെ തടി! എന്റെ തടി!! (ഹാ! എന്റെ കാര്യം കഷ്ടം) എന്ന ചിന്തയിലാണ് ഞാൻ. നിങ്ങൾ മറ്റാരുടെയെങ്കിലും സമീപിക്കൂ. നൂഹ് നബി(അ)യുടെ അടുക്കൽ പോകൂ! അവർ നൂഹ്(അ)ന്റെ അടുത്തു ചെന്ന് പറയും: ഭൂമിയിൽ നിയോഗിതനായ ആദ്യ പ്രവാചകനാണ് താങ്കൾ. അങ്ങേയറ്റം ''നന്ദിയുള്ള അടിമ'' എന്നാണ് അല്ലാഹു താങ്കളെ വിളിച്ചത്. താങ്കളുടെ നാഥനോട് ഞങ്ങളുടെ കാര്യത്തിൽ അങ്ങ് ശുപാർശ പറഞ്ഞാലും! ഞങ്ങളുടെ അവസ്ഥ കാണുന്നില്ലേ? ഞങ്ങൾക്ക് വന്നുഭവിച്ചിരിക്കുന്നത് അറിയുന്നില്ലേ? നൂഹ് നബി(അ) പറയും: മുമ്പൊന്നും കോപിച്ചിട്ടില്ലാത്ത വിധം എന്റെ നാഥൻ ഇന്ന് കോപിച്ചിരിക്കുന്നു. ഇനി ഇതുപോലെ കോപിക്കുകയുമില്ല. എനിക്ക് (ഉത്തരം കിട്ടുമെന്ന് വാഗ്ദാനം ചെയ്യപ്പെട്ട) ഒരു പ്രാർത്ഥനയുണ്ടായിരുന്നു. അത് ഞാൻ എന്റെ സമുദായത്തിനെതിരെ പ്രയോഗിച്ചു കളഞ്ഞു! എന്റെ തടി! എന്റെ തടി!! നിങ്ങൾ ഇബ്രാഹിം നബി(അ)യെ സമീപിക്കുക. അവർ ഇബ്രാഹിം നബിയെ സമീപിച്ച് പറയും: താങ്കൾ അല്ലാഹുവിന്റെ പ്രവാചകനും ഭൂവാസികളിൽ അല്ലാഹുവിന്റെ കൂട്ടുകാരനുമാണല്ലോ? താങ്കളുടെ റബ്ബിനോട് ശുപാർശ ചെയ്താലും. ഞങ്ങളുടെ അവസ്ഥ കാണുന്നില്ലേ? ഞങ്ങളെത്തിപ്പെട്ടിരിക്കുന്ന രംഗം താങ്കളറിയുന്നില്ലേ?. ഇബ്രാഹിം നബി(അ) അവരോട് പറയും: മുമ്പൊന്നും കോപിക്കാത്തവിധം എന്റെ നാഥൻ ഇന്ന് ശക്തമായി കോപിച്ചിരിക്കുന്നു. തുടർന്ന് തനിക്ക് പറയേണ്ടിവന്ന വ്യംഗ്യാർത്ഥ പ്രയോഗങ്ങളെക്കുറിച്ച് ⁸ പറഞ്ഞു: എന്റെ കാര്യം! എന്റെ കാര്യം! നിങ്ങൾ മറ്റാരുടെയെങ്കിലുമടുത്ത് പോകൂ! മൂസാ നബി(അ)യെ സമീപിക്കൂ. അവർ മൂസാനബി(അ)യുടെ അടുക്കൽ ചെന്ന് പറയും: മൂസാ! താങ്കൾ അല്ലാഹുവിന്റെ ദൂതനാണ്. അല്ലാഹു താങ്കൾക്ക് അവന്റെ ''രിസാലത്'' കൊണ്ടും (അവനുമായുള്ള) സംഭാഷണം കൊണ്ടും മറ്റുള്ളവരേക്കാൾ ശ്രേഷ്ഠത നൽകിയിരിക്കുന്നു. ഞങ്ങൾക്കുവേണ്ടി അങ്ങ് നാഥനോട് ശുപാർശ ചെയ്താലും. അവരോട് മൂസ(അ) പറയും: എന്റെ നാഥൻ മുമ്പുണ്ടായില്ലാത്തവിധം കോപിച്ചിരിക്കുന്നു. ഇനി ഇങ്ങനെ കോപിക്കുകയുമില്ല. കൽപന ലഭിക്കാതെ ഞാൻ ഒരാളെ കൊന്നിട്ടുണ്ട്. എന്റെ കാര്യം! എന്റെ കാര്യം!! നിങ്ങൾ ഈസാ(അ)യെ സമീപിക്കൂ. അവർ ഇസാനബി(അ)യുടെ അടുക്കൽ ചെന്നുപറയും: ഓ! ഈസാ! താങ്കൾ അല്ലാഹുവിന്റെ ദൂതനാണ്. തൊട്ടിലിൽ വെച്ച് അങ്ങ് ജനങ്ങളോട് സംസാരിച്ചു. മർയമിലേക്ക് അല്ലാഹു നിക്ഷേപിച്ച അവനിൽ നിന്നുമുള്ള ''കലിമതും'' റൂഹു''മാണ് അങ്ങ്. താങ്കളുടെ നാഥങ്കലേക്ക് ഞങ്ങൾക്കുവേണ്ടി ശുപാർശ ചെയ്താലും. ജനങ്ങളുടെ ഈ ദുര്യോഗം താങ്കൾ കാണുന്നില്ലേ? ഈ അവസ്ഥ താങ്കൾ അറിയുന്നില്ലേ? ഇസാനബി(അ) അവരോട് പറയും: ഇന്ന് എന്റെ നാഥൻ മുമ്പൊന്നും കോപിക്കാത്തിധം കോപിച്ചിരിക്കുന്നു. ഇനി ഇതുപോലെ കോപിക്കുകയുമില്ല. ഹാ! എന്റെ തടി! എന്റെ തടി!. -അദ്ദേഹം തന്റെ തെറ്റുകളെക്കുറിച്ചൊന്നും പറയുന്നില്ല- നിങ്ങൾ മറ്റാരെയെങ്കിലും സമീപിക്കൂ. നിങ്ങൾ മുഹമ്മദ് നബി(സ)യുടെ അടുത്തേക്കു പോകൂ.'' അങ്ങനെ അവർ എന്റെ അടുക്കൽ വന്നുപറയും: അല്ലയോ മുഹമ്മദ് നബിയേ! അങ്ങ് അല്ലാഹുവിന്റെ ദൂതനും അന്ത്യപ്രവാചകനുമാണ്. അല്ലാഹു താങ്കൾക്ക് എല്ലാ പാപങ്ങളും പൊറുത്തു തന്നിരിക്കുന്നു. അങ്ങയുടെ നാഥനോട് ശുപാർശ ചെയ്യൂ! ഞങ്ങളുടെ അവസ്ഥ താങ്കൾ മനസ്സിലാക്കുന്നില്ലേ? ഈ പരിതസ്ഥിതി അങ്ങ് കാണുന്നില്ലേ? അപ്പോൾ ഞാൻ പോയി അർശിന്റെ താഴെ സുജൂദിൽ വീഴും. മുമ്പ് മറ്റൊരാൾക്കും വെളിപ്പെടുത്തിക്കൊടുത്തിട്ടില്ലാത്ത അല്ലാഹുവിന്റെ ഉൽകൃഷ്ട ഗുണഗണങ്ങളും നല്ല പ്രകീർത്തനങ്ങളും അല്ലാഹു എനിക്ക് ബോധനം നൽകും. പിന്നെ പറയും: "ഓ മുഹമ്മദ്! തല ഉയർത്തുക. ചോദിക്കുക, നൽകപ്പെടും. ശുപാർശ ചോദിച്ചുകൊള്ളുക സ്വീകരിക്കപ്പെടും." ഞാൻ തല ഉയർത്തിപ്പറയും: ''നാഥാ എന്റെ സമുദായം, എന്റെ സമുദായം!'' അപ്പോൾ നബി(സ)യോട് പറയും: ''മുഹമ്മദ്! നിന്റെ സമുദായത്തിൽ വിചാരണയില്ലാത്ത ആളുകളെ സ്വർഗ്ഗ കവാടങ്ങളിലെ ബാബുൽ അയ്മനിലൂടെ നീ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുക. ഈ വാതിൽ ഒഴികെയുള്ള കവാടങ്ങൾ മാത്രമെ ഇവർ ഇതര ജനങ്ങളുമായി പങ്കിടുന്നുള്ളൂ. (ഈ വാതിൽ ഇവരുടെ വിശേഷങ്ങളിൽ പെട്ടതാണെന്നർത്ഥം) മുഹമ്മദിന്റെ ആത്മാവ് ആരുടെ പക്കലാണോ, അവൻ സാക്ഷി; സ്വർഗ്ഗ കവാടത്തിൽ രണ്ട് ഭാഗങ്ങൾക്കിടയിലുള്ള ദൂരം മക്കക്കും ഹിജ്റിനും⁹ (റിപ്പോർട്ടർ സംശയിക്കുന്നു) അല്ലെങ്കിൽ ബുസ്വറാക്കും¹⁰ മക്കയ്ക്കും ഇടയ്ക്കുള്ളതുപോലെയാണ്." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '⁸. നക്ഷത്രങ്ങളെകുറിച്ച് ഇതെന്റെ നാഥനാണ് എന്ന് പറഞ്ഞതും, ''അവരിൽ വലിയവനാണ് ഇത് ചെയ്തത്'' എന്ന് പറഞ്ഞതും ഉത്സവത്തിനു ക്ഷണിച്ചപ്പോൾ ''എനിക്ക് സുഖമില്ല'' എന്ന് പറഞ്ഞതും ഈജിപ്തിലെ അക്രമിയായ രാജാവിന്റെ മുന്നിൽ തന്റെ ഭാര്യ സാറ മാനഭംഗത്തിനു വിധേയമാകുമെന്ന ഘട്ടത്തിൽ അവളെന്റെ സഹോദരിയാണെന്ന് പറഞ്ഞതുമാണുദ്ദേശ്യം. ഇതൊന്നും അസത്യമായിരുന്നില്ല. ഉത്സവത്തിൽ പങ്കെടുക്കുന്നതു സുഖമുള്ള കാര്യമല്ലല്ലോ. എല്ലാ മനുഷ്യരും ആദം സന്തതികൾ എന്ന നിലക്ക് സഹോദരങ്ങൾ തന്നെ. പക്ഷേ എതിരാളികൾ ഈ പ്രസ്താവനയിലൂടെ രോഗമെന്നും കൂടപ്പിറപ്പെന്നും കരുതിയിരിക്കാം. നിർബന്ധിത സാഹചര്യത്തിൽ ഉപയോഗിക്കേണ്ടി വന്ന ഈ പ്രയോഗങ്ങളെ ഓർത്താണ് ഇബ്രാഹീം(അ) ആശങ്കപ്പെടുന്നത്.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ:قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لِكُلِّ نَبِيٍّ دَعْوَةٌ مُسْتَجَابَةٌ فَتَعَجَّلَ كُلُّ نَبِيٍّ دَعْوَتَهُ، وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ، فَهِيَ نَائِلَةٌ إِنْ شَاءَ اللهُ مَنْ مَاتَ مِنْ أُمَّتِي لَا يُشْرِكُ بِاللهِ شَيْئًا". (م)', 'അബൂഹുറൈ(റ): നബി(സ) പറഞ്ഞു: "ഓരോ പ്രവാചകനും ഉത്തരം നൽകപ്പെടുന്ന ഒരു പ്രാർത്ഥനയുണ്ട്. ഓരോ നബിമാരും തങ്ങളുടെ പ്രാർത്ഥന പെട്ടെന്ന് പ്രയോഗിച്ചു കളഞ്ഞു. എന്റെ സമുദായത്തിനു വേണ്ടി ശഫാഅത്ത് ചെയ്യാൻ വിധി നാളിലേക്ക് എന്റെ പ്രാർത്ഥന ഞാൻ സൂക്ഷിച്ചുവെച്ചു. എന്റെ സമുദായത്തിൽ അല്ലാഹുവിന് ഒന്നിനെയും പങ്കു ചേർക്കാതെ മരിച്ചവർക്ക് അത് ലഭിക്കുന്നതാണ്; ഇൻശാഅല്ലാഹ്!." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَنَا أَوَّلُ شَفِيعٍ فِي الْجَنَّةِ لَمْ يُصَدَّقْ نَبِيٌّ مِنَ الْأَنْبِيَاءِ مَا صُدِّقْتُ، وَإِنَّ مِنَ الْأَنْبِيَاءِ نَبِيًّا مَا يُصَدِّقُهُ مِنْ أُمَّتِهِ إِلَّا رَجُلٌ وَاحِدٌ". (م)', 'അനസ്: നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗത്തിൽ ആദ്യമായി ശഫാഅത്ത് സ്വീകരിക്കപ്പെടുന്നവൻ ഞാനാണ്. എന്നിൽ വിശ്വസിച്ച പോലെ ഒരു പ്രവാചകനെയും (ജനങ്ങൾ) വിശ്വസിച്ചിട്ടില്ല. തന്റെ സമുദായത്തിൽ നിന്ന് ഒരാളെ മാത്രം അനുയായിയായിക്കിട്ടിയ പ്രവാചകൻ പോലും നബിമാരിലുണ്ടായിട്ടുണ്ട്." (മു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്', '⁹. സിറിയയിലെ ഒരു പൗരാണിക നഗരം.', null, array['م']::text[], array['മു']::text[], null, null, 140, 140, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ تَلَا قَوْلَ اللهِ عَزَّ وَجَلَّ فِي إِبْرَاهِيمَ: {رَبِّ إِنَّهُنَّ أَضْلَلْنَ كَثِيرًا مِنَ النَّاسِ فَمَنْ تَبِعَنِي فَإِنَّهُ مِنِّي} الْآيَةَ وَقَالَ عِيسَى عَلَيْهِ السَّلَامُ: {إِنْ تُعَذِّبْهُمْ فَإِنَّهُمْ عِبَادُكَ وَإِنْ تَغْفِرْ لَهُمْ فَإِنَّكَ أَنْتَ الْعَزِيزُ الْحَكِيمُ} فَرَفَعَ يَدَيْهِ وَقَالَ: "اللَّهُمَّ أُمَّتِي أُمَّتِي" وَبَكَى فَقَالَ اللهُ عَزَّ وَجَلَّ: يَا جِبْرِيلُ، اذْهَبْ إِلَى مُحَمَّدٍ – وَرَبُّكَ أَعْلَمُ – فَسَلْهُ مَا يُبْكِيكَ، فَأَتَاهُ جِبْرِيلُ عَلَيْهِ السَّلَامُ فَسَأَلَهُ فَأَخْبَرَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِمَا قَالَ وَهُوَ أَعْلَمُ، فَقَالَ اللهُ: يَا جِبْرِيلُ، اذْهَبْ إِلَى مُحَمَّدٍ فَقُلْ إِنَّا سَنُرْضِيكَ فِي أُمَّتِكَ وَلَا نَسُوءُكَ". (م)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നു ആസ്(റ): ഇബ്രാഹീം നബി(അ) അല്ലാഹുവിനോട് പറയുന്ന വാക്യം "നാഥാ! ഇവർ ഒരുപാട് ജനങ്ങളെ വഴിപിഴപ്പിച്ചു. അതിനാൽ ആരെങ്കിലും എന്നെ പിൻപറ്റിയാൽ അവൻ എന്നിൽ പെടുന്നവനാണ്'' എന്ന വചനം നബി(സ) പാരായണം ചെയ്തു. ഈസാ നബി(അ)യുടെന്റെ പ്രാർത്ഥനയും, "നാഥാ! നീ അവരെ ശിക്ഷിക്കുകയാണെങ്കിൽ നിശ്ചയം അവർ നിന്റെ അടിമകളത്രെ! എന്നാൽ അവർക്ക് പൊറുത്തു കൊടുക്കുകയാണെങ്കിൽ നീ തന്നെയാണല്ലോ മഹായോഗ്യനും വിധികർത്താവും." തുടർന്ന് നബി(സ) രണ്ട് കൈകളും ഉയർത്തി പ്രാർത്ഥിച്ചു. "അല്ലാഹുവേ! എന്റെ സമുദായം! എന്റെ സമുദായം!" അവിടന്ന് കരഞ്ഞു. അല്ലാഹു വിളിക്കും: "ജിബ്രീൽ!, മുഹമ്മദി(സ)ന്റെ അടുത്തുചെന്ന് ''എന്തേ കരയുന്നതെ''ന്ന് അന്വേഷിക്കൂ! നിന്റെ നാഥൻ എല്ലാം അറിയും. ജിബ്രീൽ(അ) നബിയുടെ അടുക്കൽ ചെന്ന് വിവരങ്ങൾ ചോദിച്ചറിഞ്ഞു. നബി(സ) താൻ പ്രാർത്ഥിച്ചതിനെക്കുറിച്ച് പറഞ്ഞു. അല്ലാഹു പറഞ്ഞു: നീ മുഹമ്മദി(സ)ന്റെ അടുക്കൽ പോയി താങ്കളുടെ സമുദായത്തിന്റെ കാര്യത്തിൽ താങ്കളെ നാം വേണ്ടത്ര തൃപ്തിപ്പെടുത്തുമെന്നും വിഷമിപ്പിക്കുകയില്ലെന്നും അറിയിക്കുക." (മു)', 'عَبْدِ اللهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നു ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 140, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ الطُّفَيْلَ بْنَ عَمْرٍو الدَّوْسِيَّ أَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللهِ، هَلْ لَكَ فِي حِصْنٍ حَصِينٍ وَمَنْعَةٍ، قَالَ: حِصْنٌ كَانَ لِدَوْسٍ فِي الْجَاهِلِيَّةِ، فَأَبَى ذَلِكَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِلَّذِي ذَخَرَ اللهُ لِلْأَنْصَارِ، فَلَمَّا هَاجَرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَدِينَةِ هَاجَرَ إِلَيْهِ الطُّفَيْلُ بْنُ عَمْرٍو وَهَاجَرَ مَعَهُ رَجُلٌ مِنْ قَوْمِهِ فَاجْتَوَوُا الْمَدِينَةَ فَمَرِضَ فَجَزِعَ، فَأَخَذَ مَشَاقِصَ لَهُ فَقَطَعَ بِهَا بَرَاجِمَهُ، فَشَخَبَتْ يَدَاهُ حَتَّى مَاتَ، فَرَآهُ الطُّفَيْلُ بْنُ عَمْرٍو فِي مَنَامِهِ، فَرَآهُ وَهَيْئَتُهُ حَسَنَةٌ، وَرَآهُ مُغَطِّيًا يَدَيْهِ، فَقَالَ لَهُ: مَا صَنَعَ بِكَ رَبُّكَ؟ فَقَالَ: غَفَرَ لِي بِهِجْرَتِي إِلَى نَبِيِّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَا لِي أَرَاكَ مُغَطِّيًا يَدَيْكَ؟ قَالَ: قِيلَ لِي: لَنْ نُصْلِحَ مِنْكَ مَا أَفْسَدْتَ، فَقَصَّهَا الطُّفَيْلُ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اللَّهُمَّ وَلِيَدَيْهِ فَاغْفِرْ". (م)', 'ജാബിർ(റ): ത്വുഫൈലുബ്നു അംറുദ്ദൗസി നബി(സ)യോട് ചോദിച്ചു: നബിയേ! താങ്കൾക്കു വേണ്ടി സുരക്ഷിതമായ ഒരു കോട്ടയും ഒരു പ്രതിരോധ സേനയും ഉണ്ടാക്കുന്നതിന് വിരോധമുണ്ടോ? (റിപ്പോർട്ടർ പറയുന്നു) ദൗസ് ഗോത്രക്കാർക്ക് ജാഹിലിയ്യാ കാലത്ത് ഇത്തരമൊരു കോട്ടയുണ്ടായിരുന്നു. തന്നെ അൻസാരികൾക്ക് വേണ്ടി ഒരു സൂക്ഷിപ്പ് സ്വത്തായി അല്ലാഹു തീരുമാനിച്ചിരിക്കുകയാണ്. നബി(സ) അത് നിരസിച്ചു. നബി(സ) മദീനയിലേക്ക് ഹിജ്റ പോയപ്പോൾ ത്വുഫൈലുബ്നുഅംറും ഹിജ്റ പോയി. അദ്ദേഹത്തിന്റെ ജനതയിൽ പെട്ട മറ്റൊരാളും കൂടെ ഹിജ്റ പോയി. മദീനയിലെ (കാലാവസ്ഥ) അവർക്ക് പിടിച്ചില്ല. രോഗബാധിതനായ അയാൾ (കൂടെ പോയ ആൾ) അക്ഷമനായി തന്റെ അമ്പ് കൊണ്ട് വിരൽ കെണുപ്പുകൾ അറുത്തു. രണ്ട് കൈയ്യിൽ നിന്നും രക്തം വാർന്നൊഴുകി അയാൾ മരണപ്പെട്ടു. ത്വുഫൈൽ അയാളെ സ്വപ്നം കണ്ടു. കാണാൻ നല്ലചേലുണ്ട്; പക്ഷെ കൈ മൂടിക്കെട്ടിയിരിക്കുന്നു; ത്വുഫൈൽ ചോദിച്ചു: നിന്റെ നാഥൻ നിന്നെയെന്ത് ചെയ്തു? നബി(സ) യുടെ അടുത്തേക്ക് ഹിജ്റ: പോയതിന്റെ പേരിൽ അല്ലാഹു എനിക്ക് പൊറുത്തുതന്നു. ത്വഫൈൽ ചോദിച്ചു: കൈ മൂടിക്കെട്ടിയിരിക്കുന്നതെന്തേ? അദ്ദേഹം പറഞ്ഞു: നീ നശിപ്പിച്ചത് നാം നന്നാക്കിത്തരില്ലെന്നാണ് എന്നോട് പറയപ്പെട്ടത്. സംഭവം ത്വുഫൈൽ(റ) നബി(സ)ക്ക് വിവരിച്ചു കൊടുത്തു.അവിടുന്ന് പ്രാർത്ഥിച്ചു: നാഥാ! അവന്റെ കൈകൾക്കും നീ പൊറുത്തു കൊടുക്കണേ! (മു)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 141, 141, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي هُرَيْرَةَ قَالَ: لَمَّا أُنْزِلَتْ هَذِهِ الْآيَةُ: {وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ} دَعَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قُرَيْشًا فَاجْتَمَعُوا، فَعَمَّ وَخَصَّ، فَقَالَ: "يَا بَنِي كَعْبِ بْنِ لُؤَيٍّ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ، يَا بَنِي مُرَّةَ بْنِ كَعْبٍ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ، يَا بَنِي عَبْدِ شَمْسٍ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ، يَا بَنِي عَبْدِ مَنَافٍ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ، يَا بَنِي هَاشِمٍ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ، يَا بَنِي عَبْدِ الْمُطَّلِبِ، أَنْقِذُوا أَنْفُسَكُمْ مِنَ النَّارِ، يَا فَاطِمَةُ أَنْقِذِي نَفْسَكِ مِنَ النَّارِ، فَإِنِّي لَا أَمْلِكُ لَكُمْ مِنَ اللهِ شَيْئًا غَيْرَ أَنَّ لَكُمْ رَحِمًا سَأَبُلُّهَا بِبَلَالِهَا". (م)', 'അബൂഹുറൈറ(റ): "അടുത്ത ബന്ധുക്കൾക്ക് മുന്നറിയിപ്പ് നൽകുക" എന്ന സൂക്തം അവതരിച്ചപ്പോൾ നബി(സ) പൊതുവായും പ്രത്യേകമായും ഖുറൈശികളെ ഒരുമിച്ചുകൂട്ടി. നബി(സ) പറഞ്ഞു: "കഅ്ബുബ്നു ലുഅയ്യിന്റെ സന്തതികളേ! നിങ്ങളുടെ ശരീരം നരകത്തിൽ നിന്ന് സൂക്ഷിക്കുക, മുർറതുബ്നു കഅ്ബിന്റെ സന്തതികളേ! നിങ്ങളുടെ ശരീരം നരകത്തിൽ നിന്ന് മോചിപ്പിക്കുക, അബ്ദുശ്ശംസിന്റെ സന്തതികളേ! നിങ്ങളുടെ ശരീരം നരകത്തിൽനിന്ന് രക്ഷിക്കുക. അബ്ദുൽ മുത്തലിബിന്റെ സന്തതികളേ! നിങ്ങളുടെ ശരീരം നരകാഗ്നിയിൽ നിന്ന് സൂക്ഷിക്കുക. ഫാത്വിമാ, നിന്റെ ശരീരം നരകത്തിൽനിന്ന് മോചിപ്പിക്കുക, അല്ലാഹുവുമായുള്ള കാര്യത്തിൽ നിങ്ങൾക്കായി ഒന്നും ചെയ്യാൻ എനിക്കാവില്ല. എന്നാൽ കുടുംബബന്ധത്തിന്റെ ഈർപ്പംകൊണ്ട് ഞാൻ നിങ്ങളുമായുള്ള ബന്ധത്തെ നനക്കും.¹¹" (നിങ്ങളോട് കുടുംബബന്ധം പുലർത്തും)" (മു)', 'أَبِي هُرَيْرَةَ قَالَ', 'അബൂഹുറൈറ(റ)', '¹¹. അല്ലാഹുവിന്റെ അനുവാദമില്ലാതെ ശഫാഅത്തോ മറ്റോ ലഭിക്കുകയില്ലെന്നും സ്വർഗ്ഗ പ്രവേശമോ നരകമുക്തിയോ ലഭിക്കാനുള്ള യോഗ്യത ഓരോരുത്തരും ഇഹലോകത്ത് വെച്ചു തന്നെ ചെയ്യുന്ന സ്വന്തം അമലുകളിലൂടെ തന്നെ ആർജ്ജിക്കണമെന്നും സാരം.', null, array['م']::text[], array['മു']::text[], null, null, 141, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: يَا رَسُولَ اللهِ، هَلْ نَفَعْتَ أَبَا طَالِبٍ بِشَيْءٍ؟ فَإِنَّهُ كَانَ يَحُوطُكَ وَيَغْضَبُ لَكَ، قَالَ: "نَعَمْ، هُوَ فِي ضَحْضَاحٍ مِنْ نَارٍ، وَلَوْلَا أَنَا لَكَانَ فِي الدَّرْكِ الْأَسْفَلِ مِنَ النَّارِ". (م)', 'അബ്ബാസ്(റ): അദ്ദേഹം ചോദിച്ചു: നബിയെ, അബൂത്വാലിബിന് അങ്ങെന്തെങ്കിലും ഉപകാരം ചെയ്തുവോ? അദ്ദേഹം നിങ്ങളെ സംരക്ഷിക്കുകയും നിങ്ങൾക്ക് വേണ്ടി ദേഷ്യപ്പെടുകയും ചെയ്തിരുന്നുവല്ലോ? നബി(സ) പറഞ്ഞു: "അതെ, ഉപകാരം ചെയ്തു. അദ്ദേഹം നരകത്തിൽ ഏറ്റവും ആഴം കുറഞ്ഞ സ്ഥലത്താണ്; ഞാനില്ലായിരുന്നുവെങ്കിൽ നരകത്തിലെ ഏറ്റവും അടിയിലെ തട്ടിലാകുമായിരുന്നേനേ!" (മു)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 142, 142, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=9 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
